ALTER TABLE public.films ADD COLUMN IF NOT EXISTS posters_i18n JSONB DEFAULT '{}'::jsonb;


UPDATE public.films SET tmdb_id = 639, titoli_i18n = '{"it":"Harry, ti presento Sally... (When Harry Met Sally...)","fr":"Quand Harry rencontre Sally…","es":"Cuando Harry encontró a Sally","de":"Harry und Sally","en":"When Harry Met Sally..."}'::jsonb, trame_i18n = '{"it":"Harry Burns e Sally Albright si incontrano per la prima volta nel 1977 durante un viaggio in auto da Chicago a New York. Nel corso di dodici anni si ritrovano casualmente più volte, sviluppando una profonda amicizia che mette alla prova la teoria di Harry secondo cui un uomo e una donna non possono essere amici senza che il sesso si metta di mezzo.","fr":"Lorsqu''ils se rencontrent pour la première fois dans les années 70, Harry et Sally ne s''apprécient pas, mais alors pas du tout. Ils se quittent, jurant de ne plus se revoir. Cinq ans plus tard, ils se retrouvent mais rien n''a changé : leurs avis sur les relations hommes-femmes divergent du tout au tout. Cinq autres années passent, et Harry rencontre Sally à nouveau. Ils se racontent leurs expériences, leurs déceptions et se rendent compte que leur vie amoureuse est un désastre. Mais l''amitié entre Harry et Sally est-elle possible ?","es":"Harry Burns y Sally Albright se conocen fortuitamente cuando ella se ofrece para llevarle en su coche hasta la ciudad, entablan una conversación sobre la amistad entre personas de diferente sexo; la conversación acaba en discusión, pero entre ellos nace algo muy especial. Son un hombre y una mujer que se han pasado mucho tiempo intentando averiguar cómo seguir siendo amigos. Sin embargo, Harry tiene una firme creencia: que dos personas de sexo opuesto no pueden ser simplemente amigos, la relación siempre acaba en la cama o en el altar.","de":"Harry nervt Sally und Sally nervt Harry. Das war während ihrer gemeinsamen unfreiwilligen 18-Stunden-Fahrt nach New York so, und bleibt auch so fünf Jahre später, als sie sich zufällig im Flugzeug treffen. Weitere fünf Jahre später – beide im Beziehungsfrust – tritt das ungleiche Paar mehr aus Not den Gegenbeweis für Harrys Lieblingsthese an: „Männer und Frauen können nie Freunde sein – der Sex kommt ihnen immer in die Quere.“ Und wie in jeder guten Komödie merken die beiden als allerletzte, dass sie im Grunde füreinander geschaffen sind.","en":"Sex always gets in the way of friendships between men and women. At least, that''s what Harry Burns believes. So when Harry meets Sally Albright and a deep friendship blossoms between them, Harry''s determined not to let his attraction to Sally destroy it. But when a night of weakness ends in a morning of panic, can the pair avoid succumbing to Harry''s fears by remaining friends and admitting they just might be the perfect match for each other?"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/9FntiimMchiZBjuklFfMuIinRnC.jpg","fr":"https://image.tmdb.org/t/p/w500/ghvbClWDXje0ksaL6ad2k7IZHCc.jpg","es":"https://image.tmdb.org/t/p/w500/dHUhjAPViRGTU9CFBt4JoANWHiK.jpg","de":"https://image.tmdb.org/t/p/w500/i6L2FanSxToy4OxGDUYxzST4FwR.jpg","en":"https://image.tmdb.org/t/p/w500/rFOiFUhTMtDetqCGClC9PIgnC1P.jpg"}'::jsonb WHERE id = 189;
UPDATE public.films SET tmdb_id = 166, titoli_i18n = '{"en":"The Party","fr":"La Boum","de":"La Boum - Die Fete","it":"Il tempo delle mele (La Boum)","es":"La fiesta"}'::jsonb, trame_i18n = '{"en":"A thirteen-year-old French girl deals with moving to a new city and school in Paris, while at the same time her parents are getting a divorce.","fr":"Vic, treize ans, inscrite au lycée Henri-IV, est à l''âge des premières sorties et des premiers émois. Vic n''a guère l''occasion de parler avec ses parents, trop occupés par leur carrière respective, et dont le couple subit les assauts classiques du temps. Elle se confie donc à son arrière-grand-mère, la pétillante Poupette, ou à sa meilleure amie, Pénélope. Elle partagera donc avec elles son amour pour le beau Mathieu. Mais cet amour-là aussi connaîtra quelques difficultés...","de":"Die 13-jährige Vic zieht mit ihren Eltern, einem Zahnarzt und einer Comiczeichnerin, nach Paris. Dort findet Vic schnell Freunde, unter anderem Pénélope, die im Gegensatz zu Vic schon Erfahrungen mit Jungs hat, und deren kleine Schwester Samantha. Auf einer Fete findet Vic ihre erste große Liebe, Mathieu, mit dem sie schon nach kurzer Zeit ausgeht. Die Familienidylle zerbricht, als herauskommt, dass Vics Vater eine Affäre mit einer Parfumhändlerin hatte. Wütend trennt sich Vics Mutter vorübergehend von ihm und demoliert aus Rache das Geschäft der Geliebten. Wenig später beginnt sie eine Affäre mit Vics Lehrer.","it":"La quattordicenne Vic affronta i primi amori, le prime feste e le difficoltà dell''adolescenza nella Parigi degli anni ''80, mentre i suoi genitori attraversano una profonda crisi coniugale.","es":"Vic tiene 13 años y es nueva en el instituto, pero pronto se hace amiga de Penélope. Las dos están ansiosas por encontrar un chico del que enamorarse; el problema es que los padres de Vic no la dejan todavía ir a fiestas."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/usGV1Q7KWR0Uq4dOIppGZ0ba8kz.jpg","fr":"https://image.tmdb.org/t/p/w500/s2d4P7XZUA4rwNK4il7gMptxd7M.jpg","de":"https://image.tmdb.org/t/p/w500/5FC0Js9guGK8MPxDhWcxvSiv0Iw.jpg","it":"https://image.tmdb.org/t/p/w500/lDxr4hi1El5SLIArgGAhjyOzREk.jpg","es":"https://image.tmdb.org/t/p/w500/rZwEKic3lnftp9M7TjAsTW2pDEh.jpg"}'::jsonb WHERE id = 190;
UPDATE public.films SET tmdb_id = 171, titoli_i18n = '{"en":"The Party 2","it":"Il tempo delle mele 2 (La Boum 2)","fr":"La Boum 2","de":"La Boum 2 - Die Fete geht weiter","es":"La Boum 2"}'::jsonb, trame_i18n = '{"en":"After moving to a new city, a young French teenage girl falls in love with a boy and thinks of having sex with him, since her girl friends have already done it.","it":"Vic ha ormai sedici anni e, di ritorno da un viaggio, incontra il giovane Philippe. Tra i due nasce una romantica storia d''amore che la porterà a confrontarsi con nuove gelosie e le prime vere scelte della maturità.","fr":"Deux ans ont passé, Vic, maintenant âgée de 15 ans (et 3 mois) entre en classe de seconde au lycée Henri-IV. Ses amis aussi ont grandi. Cela fait maintenant un an qu''elle n''est pas \"sortie\" avec un garçon. Dans le train, en rentrant d''Autriche avec Poupette, lors du contrôle des Douanes, ce n''est pas son passeport qui lui est rendu, mais celui d''un certain Philippe Berthier, un jeune homme de 18 ans dont elle va vite devenir amoureuse. Dans le même temps, ses parents François et Françoise évoluent dans leurs carrières respectives et des choix devront être faits...","de":"Vic Beretton ist inzwischen 15; während ihre Freundin Pénélope jede Woche mit einem anderen Jungen geht und auch schon die Pille nimmt, ist Vic noch immer Jungfrau und führt ein relativ entspanntes Leben ohne Freund. Eines Tages jedoch trifft sie Philippe im Zug und vertauscht versehentlich seinen Pass mit ihrem. Später sucht sie ihn, um ihm seinen Pass zurückzugeben. Die beiden werden Freunde und gehen miteinander aus. Doch Vic ist sich nicht sicher, ob Philippe der richtige für das „erste Mal“ ist, zumal sie Philippes Beziehung zu dessen Exfreundin Catherine mit Misstrauen betrachtet. Währenddessen bändelt Pénélope, nachdem sie von Thibaut (mit dem sie geschlafen hat) verlassen wurde, mit dem Neffen des Schwagers des neuen Freundes ihrer Mutter an, wechselt jedoch später auf Didier und schließlich auf Philippes Freund Frédo. Ihre Schwester Samantha vernachlässigt inzwischen die Schule und konzentriert sich ganz auf ihr Training als Balletttänzerin."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/pbkccDoxH1H1VdqWcQYycZxHTIK.jpg","it":"https://image.tmdb.org/t/p/w500/ixRF6arqUqSHqvruUxbLFaSkK2L.jpg","fr":"https://image.tmdb.org/t/p/w500/eN2xx8aRd4sjelfunSLmtZXCKfd.jpg","de":"https://image.tmdb.org/t/p/w500/AkZfQry3QngGZbQ3RmrNF4XTs2M.jpg","es":"https://image.tmdb.org/t/p/w500/eN2xx8aRd4sjelfunSLmtZXCKfd.jpg"}'::jsonb WHERE id = 191;
UPDATE public.films SET tmdb_id = 52286, titoli_i18n = '{"it":"Il tempo delle mele 3 (L''étudiante)","fr":"L''Étudiante","es":"La estudiante","de":"Die Studentin","en":"The Student"}'::jsonb, trame_i18n = '{"it":"Valentine è una studentessa universitaria determinata a superare i suoi esami di abilitazione all''insegnamento. La sua vita rigorosa viene sconvolta dall''incontro con Ned, un musicista jazz con ritmi di vita opposti ai suoi.","fr":"Valentine prépare avec acharnement son agrégation, l''aboutissement de 5 années d''études difficiles. Elle ne dispose donc pas de loisirs et doit beaucoup travailler. Elle va cependant tomber amoureuse d''Édouard, un jeune musicien…","es":"Tres meses antes de sus exámenes finales, la ambiciosa Valentine se concentra totalmente en sus estudios. Cuando el músico de jazz Edouard la corteja, ella está de acuerdo, aunque sólo para una noche de diversión. Pero cuando llega a conocerlo mejor, se da cuenta de que no es tan superficial como ella pensaba ... y el deseo se convierte en amor. Sin embargo, entre los preparativos de su examen y los de una gira con una banda de jazz de Edouard casi no les queda tiempo para estar juntos.","de":"Die Lehramtskandidatin Valentine läßt sich kurz vor dem Examen auf einen Flirt mit dem Musiker Eduard ein. Nach der gemeinsam verbrachten Nacht zieht sie sich zum Büffeln zuirück, während Eduard mit seiner Band auf Frankreich-Tournee geht. Die Liebe führt die beiden unterschiedlichen Charaktere trotz Stress und Terminschwierigkeiten wieder zusammen, und am Ende schafft die Studentin ihre Abschlußprüfung trotz aller Hindernisse.","en":"An ambitious teaching student''s finals studies are interrupted by a passionate affair with a jazz musician."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/wGx196d9fMsWwItWTK3WpUkzY1T.jpg","fr":"https://image.tmdb.org/t/p/w500/jR8L6MtUwuv9ZI0KyOUhoeCvUVd.jpg","es":"https://image.tmdb.org/t/p/w500/jR8L6MtUwuv9ZI0KyOUhoeCvUVd.jpg","de":"https://image.tmdb.org/t/p/w500/reGOKVmhkdueUQUBDUU57JcyE35.jpg","en":"https://image.tmdb.org/t/p/w500/tDx9zW0Edb83qh9PAGrgP3Zh9RP.jpg"}'::jsonb WHERE id = 192;
UPDATE public.films SET tmdb_id = 295385, titoli_i18n = '{"en":"The Devil''s Advocate","es":"El abogado del diablo","it":"L''avvocato del diavolo (Des Teufels Advokat)","de":"Des Teufels Advokat","fr":"L''Avocat du diable"}'::jsonb, trame_i18n = '{"en":"A dying priest is commissioned to investigate the deeds of Giacomo Nerone, a dead wartime partisan, and find out if he truly is worthy of being canonized.","es":"Un sacerdote de alto rango RC descubre que tiene cáncer terminal. Su fe se pone a prueba cuando se enfrenta a una muerte inminente. Al mismo tiempo, se le pide que viaje a un remoto pueblo en el sur de Italia para investigar a un misterioso individuo, Giacomo Nerone, quien ha sido nombrado como un posible \"santo\", porque se dice que ha hecho milagros. Antes de que la Iglesia proclame su RC a ser un santo, alguien tiene que hacer de \"abogado del diablo\": investigar su vida y ver por qué no debería ser un santo. El sacerdote comienza sus investigaciones al hablar con un número de personas que le conocen. Él descubre que su verdadero nombre era \"James Black\". Él era un soldado británico que se había desprendido del ejército británico (durante la 2 ª Guerra Mundial) y que se escondió en este pueblo durante la guerra en Italia. Él comenzó una relación con una mujer local...","de":"Ende der 50er Jahre erhält der todkranke Priester Meredith einen letzten Auftrag vom Vatikan: In einem kalabrischen Bergdorf soll er den Heiligenkult um Nerone klären. Der englische Deserteur kam im Zweiten Weltkreig in das Dorf und hat dort angeblich Wunder vollbracht. Die Aufgabe stellt den Glauben Merediths auf den Prüfstand.","fr":"En 1958, un prélat anglais reçoit mission d''enquêter sur le culte qui entoure la mémoire d''un homme exécuté dans un village des Abruzzes à la fin de la guerre.","it":"Un sacerdote affetto da un male incurabile viene inviato in un piccolo paese della Calabria per indagare sulla vita e sui presunti miracoli di un uomo giustiziato nel 1944."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/AbPgcdruJ9ZfNOMWOf1kpyjCUKE.jpg","es":"https://image.tmdb.org/t/p/w500/zUhr0pBVSE8hAsBC1txCJayYhmv.jpg","it":"https://image.tmdb.org/t/p/w500/zUhr0pBVSE8hAsBC1txCJayYhmv.jpg","de":"https://image.tmdb.org/t/p/w500/zUhr0pBVSE8hAsBC1txCJayYhmv.jpg","fr":"https://image.tmdb.org/t/p/w500/zUhr0pBVSE8hAsBC1txCJayYhmv.jpg"}'::jsonb WHERE id = 193;
UPDATE public.films SET tmdb_id = 1813, titoli_i18n = '{"it":"L''avvocato del diavolo (The Devil''s Advocate)","en":"The Devil''s Advocate","fr":"L''Associé du diable","de":"Im Auftrag des Teufels","es":"Pactar con el diablo"}'::jsonb, trame_i18n = '{"it":"Un giovane e imbattuto avvocato della Florida viene ingaggiato da un imponente studio legale di New York. L''uomo si rende presto conto che il suo carismatico capo, John Milton, e la societa stessa nascondono un''oscura origine demoniaca.","en":"Aspiring Florida defense lawyer Kevin Lomax accepts a job at a New York law firm. With the stakes getting higher every case, Kevin quickly learns that his boss has something far more evil planned.","fr":"Kevin Lomax, jeune et brillant avocat, est approché par l''un des plus puissants cabinets New-Yorkais dirigé par l''étrange John Milton. Assoiffé de pouvoir et d''argent, poussé par une ambition dévorante, prêt à tout pour réussir, il accepte l''offre et gravit les marches de la réussite de façon fulgurante. Mais l''ambition a un prix : sans le savoir, Kevin vient de vendre son âme au diable...","de":"Der junge Staatsanwalt Kevin Lomax bekommt die Chance seines Lebens: Die größte und mächtigste Kanzlei des Landes holt ihn nach New York. Und damit nicht genug: Sein neuer Boß, der geheimnisvolle John Milton, nimmt ihn persönlich unter seine Fittiche. Unaufhaltsam verfällt Kevin dem Rausch von Macht, Ruhm, Sex und dem ganz großen Geld. Doch nach einer Serie unheimlicher Vorfälle wird Kevin klar, daß ihn der Leibhaftige persönlich unter Vertrag genommen hat.","es":"Kevin Lomax (Keanu Reeves) es un joven y brillante abogado que nunca ha perdido un caso. Vive en Florida y parece feliz con su esposa, Mary Ann (Charlize Theron). Un día, recibe la visita de un abogado de Nueva York, que representa a un poderoso bufete que tiene la intención de contratarlo. Al frente de la prestigiosa empresa se encuentra John Milton (Al Pacino), un hombre mundano, brillante y carismático, que alberga planes muy oscuros con respecto a Lomax."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/6wq4owkyGkdXqehBsgcPOfeVVOE.jpg","en":"https://image.tmdb.org/t/p/w500/5ZzBGpxy55OQzHxKVY11IpY6a0o.jpg","fr":"https://image.tmdb.org/t/p/w500/dwRco8u0IrVfiWzSH8HLUjgRdNR.jpg","de":"https://image.tmdb.org/t/p/w500/9deaag4AgDAgo6sG2pBfeV8BOgG.jpg","es":"https://image.tmdb.org/t/p/w500/rOXciqRgEXqRvvYS6Dk2im3NF7H.jpg"}'::jsonb WHERE id = 194;
UPDATE public.films SET tmdb_id = 9659, titoli_i18n = '{"it":"Interceptor (Mad Max)","en":"Mad Max","fr":"Mad Max","de":"Mad Max","es":"Mad Max. Salvajes de la autopista"}'::jsonb, trame_i18n = '{"it":"In un''Australia distopica e violenta al collasso sociale, il poliziotto Max Rockatansky cerca vendetta contro una spietata banda di motociclisti che ha sterminato la sua famiglia.","en":"In the ravaged near-future, a savage motorcycle gang rules the road. Terrorizing innocent civilians while tearing up the streets, the ruthless gang laughs in the face of a police force hell-bent on stopping them.","fr":"Sur les autoroutes désertées d''une Australie méconnaissable, une guerre sans merci oppose motards hors-la-loi et policiers Interceptor, qui tentent de triompher de la vermine au volant de voitures aux moteurs surgonflés. Dans ce monde en pleine décadence, les bons, les méchants, le manichéisme disparaissent…","de":"Die Erde ist wüst, die Ordnung zerfallen, und auf den Highways liefern sich Banden und Polizei wilde Rennen. Den grausamen Motorradrockern \"Glory Riders\" stehen schwerstbewaffnete Cops mit 600 PS-starken Karossen gegenüber. Einer der letzten aufrechten Gesetzeshüter ist Max. Als bei einer Jagd auf die Rocker sein bester Freund stirbt, quittiert Max den Dienst. Mit seiner Frau Jessie und seinem Sohn zieht er durchs Land, kann dem Endzeitkrieg jedoch nicht entkommen. Der sadistische Toecutter tötet Max'' Kind und schlägt Jessie zum Krüppel. Aus Max wird \"Mad Max\" und bis an die Zähne bewaffnet startet er seinen Rachefeldzug...","es":"En las autopistas desiertas de una Australia desconocida, tiene lugar una guerra sin merced entre motoristas forajidos y policías Interceptor, que intentan triunfar sobre la gentuza al volante de coches con motores trucados. En un mundo en plena decadencia, la moral se difuminará en el escenario post apocalíptico donde lo único que tiene valor es el bien más preciado: la gasolina. La depravación, crueldad y salvajismo reinan en las bandas que no dudarán en perseguir y acabar con cualquiera que se ponga entre ellos y su ansia destruir y ser los amos de la carretera. Max se cruzará en su camino y lo que empieza como un acto de justicia no tardará en tornarse una lucha personal para acabar con ellos."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/4vkHxaW8mGTQuhl6BAkUu2WnxfR.jpg","en":"https://image.tmdb.org/t/p/w500/5LrI4GiCSrChgkdskVZiwv643Kg.jpg","fr":"https://image.tmdb.org/t/p/w500/nv5DtpzgjrILNusr3JiTE3O4tlL.jpg","de":"https://image.tmdb.org/t/p/w500/nlyVSuwvacjEDdnDZVqsJaTdeJU.jpg","es":"https://image.tmdb.org/t/p/w500/vWa1DEwV5RbAOiuAm0WNXD3Aydw.jpg"}'::jsonb WHERE id = 195;
UPDATE public.films SET tmdb_id = 8810, titoli_i18n = '{"it":"Interceptor - Il guerriero della strada (Mad Max 2)","fr":"Mad Max 2 : Le Défi","de":"Mad Max II - Der Vollstrecker","es":"Mad Max II. El guerrero de la carretera","en":"Mad Max 2"}'::jsonb, trame_i18n = '{"it":"Divenuto un vagabondo solitario nelle desolate terre post-apocalittiche, Max accetta di difendere una comunità assediata che gestisce una preziosa raffineria di petrolio da un gruppo di predoni sanguinari.","fr":"Dans un futur non défini, les réserves de pétrole sont épuisées et la violence règne sur le monde. Max, un ancien de la sécurité routière, se porte aux secours d''une communauté de fuyards aux prises avec des pirates de la route. La bataille se concentre autour d''une citerne de raffinerie.","de":"Das Ende der Zivilisation steht bevor. Brutale Motorrad-Gangs diktieren das Geschehen. Für einen Tropfen Benzin, sind sie bereit zu töten. Auch die Familie des Ex-Polizisten Max wurde ermordet. Auf der Suche nach Benzin gelangt er zu einer heiß umkämpften Raffinerie, zu der er sich Zugang verschafft. Die Leute dort planen den Ausbruch mit einem riesigen Benzintank, um irgendwo ein neues Leben zu beginnen. Max soll dafür einen Sattelschlepper besorgen und ihn samt Tank steuern. Als sich die Tore öffnen, beginnt eine höllische Jagd auf Leben und Tod.","es":"Tras el holocausto nuclear, la gasolina se ha convertido en un bien escaso y muy codiciado. Mad Max, héroe solitario, inicia una lucha sin cuartel para ayudar a una colonia de supervivientes constantemente atacada por un grupo de violentos guerreros que intenta arrebatarle un tanque de gasolina. Max decide ayudar a los defensores del tanque utilizando un enorme camión como trampa. La banda de guerreros persigue al camión, pensando que transporta miles de litros de gasolina.","en":"Max Rockatansky returns as the heroic loner who drives the dusty roads of a postapocalyptic Australian Outback in an unending search for gasoline. Arrayed against him and the other scraggly defendants of a fuel-depot encampment are the bizarre warriors commanded by the charismatic Lord Humungus, a violent leader whose scruples are as barren as the surrounding landscape."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/i313vatvaMM67gi1B3YqJtl295Q.jpg","fr":"https://image.tmdb.org/t/p/w500/oNI8l7GL3fvDIP9mtBSMku4gQde.jpg","de":"https://image.tmdb.org/t/p/w500/c0LcCMUcMMImdYYbfHchfTUF29j.jpg","es":"https://image.tmdb.org/t/p/w500/udpVgRB3xz5ZN553apthn4TyT6G.jpg","en":"https://image.tmdb.org/t/p/w500/l1KVEhkGDpWRzQ0VqIhZqDDuOim.jpg"}'::jsonb WHERE id = 196;
UPDATE public.films SET tmdb_id = 9355, titoli_i18n = '{"en":"Mad Max Beyond Thunderdome","de":"Mad Max - Jenseits der Donnerkuppel","it":"Mad Max oltre la sfera del tuono (Mad Max Beyond Thunderdome)","es":"Mad Max III. Más allá de la cúpula del trueno","fr":"Mad Max :  Au-delà du dôme du tonnerre"}'::jsonb, trame_i18n = '{"en":"Mad Max becomes a pawn in a decadent oasis of a technological society, and when exiled, becomes the deliverer of a colony of children.","de":"Mad Max, der letzte wahre Kämpfer nach der barbarischen Apokalypse, gelangt auf der Suche nach seinem gestohlenen Dromedargespann an den Wüstenhandelsplatz Bartertown. Hier herrscht Aunty Entity mit Strenge und Gewalt. Sie schlägt Max einen Handel vor: wenn er den riesenhaften Blaster im Zweikampf unter der Donnerkuppel besiegt, soll er seine Ausrüstung zurückerhalten. Max gewinnt die erbarmungslose Auseinandersetzung, bei der alle Waffen erlaubt sind, doch er schenkt Blaster und seinem Herrn Master, einem Gnom, das Leben. Wütend läßt Aunty ihn fesseln und in die Wüste jagen. Aber Mad Max kehrt zurück nach Bartertown. Härter und unerbittlicher als je zuvor. Bei einer rasanten Verfolgungsjagd durch die unendliche Wüste kommt es zur spektakulären Entscheidung...","it":"Esiliato dall''avida dominatrice della città di Bartertown dopo essersi rifiutato di uccidere un gladiatore, Max viene salvato da una tribù di bambini sopravvissuti a un incidente aereo che lo credono il loro salvatore.","es":"Tras la catástrofe nuclear, Mad Max cruza un desierto donde pierde su caravana de camellos. Llega a una ciudad donde le proponen cambiárselos a cambio de que ataque al tirano de la ciudad subterránea, un enano que fabrica gas metano con excrementos de cerdo.","fr":"Max, de retour, s''est fait dépouiller de son maigre bien. Suivant le voleur, il arrive à la Ville du Troc, où règne Entity. Celle-ci l''engage pour qu''il la débarrasse de Master et Blaster, rois du Monde souterrain. N''ayant voulu tuer Blaster, Max est abandonné en plein désert, d''où il ressurgit à la tête d''une troupe d''enfants pour faire exploser la Ville du Troc."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/jJlxcEVVUHnrUeEkQ0077VeHQpb.jpg","de":"https://image.tmdb.org/t/p/w500/n3TM8ZHG4R6aZSbt3GhSTigRzaD.jpg","it":"https://image.tmdb.org/t/p/w500/zEFrGhYPkE0taW1cGgmfMoOWQ4t.jpg","es":"https://image.tmdb.org/t/p/w500/u9gVwCajHkJpVAaVRau2xSOeHcl.jpg","fr":"https://image.tmdb.org/t/p/w500/fHo2AJ9brsXKWbYJ2LA087UDBwZ.jpg"}'::jsonb WHERE id = 197;
UPDATE public.films SET tmdb_id = 76341, titoli_i18n = '{"it":"Mad Max: Fury Road","fr":"Mad Max : Fury Road","en":"Mad Max: Fury Road","es":"Mad Max: Furia en la carretera","de":"Mad Max: Fury Road"}'::jsonb, trame_i18n = '{"it":"In fuga attraverso le distese desertiche controllate dal tiranno Immortan Joe, Max unisce le forze con l''Imperatrice Furiosa per scortare cinque donne verso la libertà a bordo di una potente autocisterna.","fr":"Hanté par un lourd passé, Mad Max estime que le meilleur moyen de survivre est de rester seul. Cependant, il se retrouve embarqué par une bande qui parcourt le désert à bord d’un véhicule militaire piloté par l’Impératrice Furiosa. Ils fuient la Citadelle où sévit le terrible Immortan Joe qui s’est fait voler un objet irremplaçable. Enragé, ce Seigneur de guerre envoie ses hommes pour traquer les rebelles impitoyablement…","en":"An apocalyptic story set in the furthest reaches of our planet, in a stark desert landscape where humanity is broken, and most everyone is crazed fighting for the necessities of life. Within this world exist two rebels on the run who just might be able to restore order.","es":"Perseguido por su turbulento pasado, Mad Max cree que la mejor forma de sobrevivir es ir solo por el mundo. Sin embargo, se ve arrastrado a formar parte de un grupo que huye a través del desierto en un War Rig conducido por una Emperatriz de élite: Furiosa. Escapan de una Ciudadela tiranizada por Immortan Joe, a quien han arrebatado algo irreemplazable. Enfurecido, el Señor de la Guerra moviliza a todas sus bandas y persigue implacablemente a los rebeldes en una ''guerra de la carretera'' de altas revoluciones.","de":"Bei seinen Reisen durch die postapokalyptische Ödnis der Zukunft wird Max von den Schergen des Warlords Immortan Joe gefangen genommen und als lebende Blutkonserve für den schwerkranken Krieger Nux verwendet. Als Imperator Furiosa, eine wichtige Handlangerin Joes, den Herrscher hintergeht, indem sie seine fünf Frauen befreit und während einer Handelsmission mit ihnen an Bord ihres Kriegslasters flieht, ruft der Warlord sein Heer zur Verfolgung auf. Zu den Kriegern gehört auch Nux, der Max zur Blutversorgung an seinen Wagen schnallt. Doch während des ersten Gefechts zwischen Joes Leuten und Furiosa kann sich Max befreien und bildet von da eine Zweckgemeinschaft mit Furiosa und den Frauen, während sie weiter unerbittlich von den Truppen Joes gejagt werden …"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/5gbm8m1gYvOmVGRcxteiplDLWdg.jpg","fr":"https://image.tmdb.org/t/p/w500/oLy2V6AWSEfdPgKOtrSGnwB3Q2R.jpg","en":"https://image.tmdb.org/t/p/w500/ulcAi4dKpAjHwYGS08vNyx9H6I9.jpg","es":"https://image.tmdb.org/t/p/w500/fnY0VRsb31A5RLVCBjuR6EFUlo2.jpg","de":"https://image.tmdb.org/t/p/w500/6zI7lI5Usf5z6wXH9KPWvGWvKS7.jpg"}'::jsonb WHERE id = 198;
UPDATE public.films SET tmdb_id = 786892, titoli_i18n = '{"it":"Furiosa: A Mad Max Saga","en":"Furiosa: A Mad Max Saga","de":"Furiosa: A Mad Max Saga","fr":"Furiosa — Une saga Mad Max","es":"Furiosa: De la saga Mad Max"}'::jsonb, trame_i18n = '{"it":"Rapita da bambina dal Luogo Verde delle Molte Madri e finita nelle mani della brutale Orda di Motociclisti guidata dal Signore della Guerra Dementus, la giovane Furiosa combatte per anni per sopravvivere e trovare la via di casa.","en":"As the world falls, young Furiosa is snatched from the Green Place of Many Mothers into the hands of a great biker horde led by the warlord Dementus. Sweeping through the wasteland, they encounter the citadel presided over by Immortan Joe. The two tyrants wage war for dominance, and Furiosa must survive many trials as she puts together the means to find her way home.","de":"Als die Welt untergeht, wird die junge Furiosa vom Grünen Ort der vielen Mütter entführt und fällt in die Hände einer großen Bikerhorde unter der Führung des Warlords Dementus. Bei ihrem Streifzug durch das Ödland stoßen sie auf die Zitadelle, die vom Immortan Joe beherrscht wird. Während die beiden Tyrannen um die Vorherrschaft kämpfen, muss Furiosa viele Prüfungen überstehen, während sie die Mittel zusammenstellt, um ihren Weg nach Hause zu finden.","fr":"Alors que le monde s''écroule, la jeune Furiosa tombe entre les mains d''une horde de motards dirigée par le seigneur de la guerre Dementus. En traversant le Wasteland, ils tombent sur la Citadelle présidée par l''Immortan Joe. Alors que les deux tyrans se battent pour la domination, Furiosa doit survivre à de nombreuses épreuves pour trouver le moyen de rentrer chez elle.","es":"En un mundo postapocalíptico donde todo ha perdido su valor, los pocos supervivientes se guían por la ley del más fuerte. Sin aprecio por la vida, lo único que despierta un brutal interés es la gasolina, sinónimo de poder y objetivo de bandas armadas hasta los dientes y sin escrúpulos. En este contexto conoceremos la  historia de la arrebatadoramente despiadada, salvaje y joven Furiosa, quien cae en manos de una horda de motoristas y debe sobrevivir a muchas pruebas mientras reúne los medios para encontrar el camino de vuelta a casa. Precuela de ''Mad Max: Furia en la carretera'' (2015)."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/fMG7ALVMYT8mVY9zQyVPIFCzQnN.jpg","en":"https://image.tmdb.org/t/p/w500/iADOJ8Zymht2JPMoy3R7xceZprc.jpg","de":"https://image.tmdb.org/t/p/w500/jhq0IGZLeWwJbj2gCAevaT8MlSS.jpg","fr":"https://image.tmdb.org/t/p/w500/hbxqFdWXHeLIJfagMMhVG5SV5tb.jpg","es":"https://image.tmdb.org/t/p/w500/tGHUlykWn9V2IIQ4ZaATIAq9VLB.jpg"}'::jsonb WHERE id = 199;
UPDATE public.films SET tmdb_id = 968, titoli_i18n = '{"it":"Quel pomeriggio di un giorno da cani (Dog Day Afternoon)","en":"Dog Day Afternoon","fr":"Un après-midi de chien","es":"Tarde de perros","de":"Hundstage"}'::jsonb, trame_i18n = '{"it":"A New York, tre rapinatori poco esperti tentano di svaligiare una filiale bancaria in un torrido pomeriggio estivo. Quando il colpo fallisce, la situazione si trasforma in un lungo assedio con ostaggi che cattura l''attenzione della polizia e dei media dell''intera nazione.","en":"Based on the true story of would-be Brooklyn bank robbers John Wojtowicz and Salvatore Naturile. Sonny and Sal attempt a bank heist which quickly turns sour and escalates into a hostage situation and stand-off with the police. As Sonny''s motives for the robbery are slowly revealed and things become more complicated, the heist turns into a media circus.","fr":"Des gangsters débutants braquent une banque et se retrouvent cernés par la police et les médias. Ils prennent en otage les employés de la banque. Débute alors un cauchemar qui va durer des heures…","es":"Unos delincuentes de poca monta deciden atracar la sucursal de un banco de Brooklyn. Sin embargo, debido a su inexperiencia, el robo, que había sido planeado para ser ejecutado en apenas diez minutos, se convierte en una trampa para los atracadores y en un espectáculo para la televisión en directo.","de":"An einem heißen Sommertag will der arbeitslose New Yorker Sonny gemeinsam mit zwei Freunden eine Bank überfallen, um die Geschlechtsumwandlung seines Geliebten finanzieren zu können. Was als Ex-und-Hopp-Aktion geplant war, läuft gründlich schief: Sonny findet sich mit seinem Komplizen Sal, einem Haufen Geiseln und minimaler Beute in der Bank wieder, während draußen Polizei und Fernsehteams Stellung beziehen. Nervenaufreibende Verhandlungen über einen Abzug beginnen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/kxVjqcrWGoysfBsrXPQHVLRf1o2.jpg","en":"https://image.tmdb.org/t/p/w500/mavrhr0ig2aCRR8d48yaxtD5aMQ.jpg","fr":"https://image.tmdb.org/t/p/w500/wx54osROfinN2F522AD8ppFwR77.jpg","es":"https://image.tmdb.org/t/p/w500/ctcUXNlnddo9ndUK0w7w6CZQpig.jpg","de":"https://image.tmdb.org/t/p/w500/x4D5hmh2QKzZfCeUH4cmGNisR03.jpg"}'::jsonb WHERE id = 200;
UPDATE public.films SET tmdb_id = 14384, titoli_i18n = '{"it":"Soldato blu (Soldier Blue)","en":"Soldier Blue","es":"Soldado azul","fr":"Soldat bleu","de":"Das Wiegenlied vom Totschlag"}'::jsonb, trame_i18n = '{"it":"Dopo un massacro compiuto dai Cheyenne, gli unici due sopravvissuti, una giovane donna bianca che ha vissuto a lungo con i nativi e un giovane soldato idealista, intraprendono un difficile viaggio per raggiungere la salvezza. Lungo il cammino, si scontreranno con le rispettive visioni del mondo, fino ad assistere al brutale e tragico massacro di un villaggio indiano inerme da parte dell''esercito statunitense.","en":"After a cavalry group is massacred by the Cheyenne, only two survivors remain: Honus, a naive private devoted to his duty, and Cresta, a young woman who had lived with the Cheyenne two years and whose sympathies lie more with them than with the US government. Together, they must try to reach the cavalry''s main base camp. As they travel onward, Honus is torn between his growing affection for Cresta.","es":"Un grupo de soldados de la caballería es atacado por los Cheyennes. Tan sólo Honus, un soldado raso completamente entregado a su deber, y Cresta, una jovencita que había vivido anteriormente con los indios durante dos años y que simpatiza más con ellos que con el ejército americano consiguen sobrevivir a la masacre. Juntos, deberán encontrar el campamento base de la caballería.","fr":"Le 29 Novembre 1864, une unité de volontaires de la Cavalerie du Colorado, comprenant 900 hommes, attaque un paisible village Cheyenne à Sand Creek. Les indiens levèrent un drapeau blanc et un drapeau américain. La cavalerie attaqua néanmoins, massacrant sept cents indiens - dont plus de 350 femmes et enfants. Plus de cent scalps indiens furent pris, des corps furent démembrés et il y eu de nombreux viols…","de":"Der junge Yankee-Soldat Honus Gran und die schöne Cresta Lee sind die einzigen Überlebenden eines Überfalls der Cheyenne-Indianer auf einen Geldtransporter. Honus hasst die Indianer und hat für Cresta, die einst mit dem Häuptling der Cheyenne verheiratet war, nur Verachtung übrig. Cresta sieht das kriegstreiberische Verhalten der US-Kavallerie sehr kritisch und bringt dies offen zum Ausdruck. Als Honus verletzt wird, lässt Cresta ihn zurück, um Hilfe zu holen. Honus schlägt sich allein bis zum Fort durch und wird zum Feldzug gegen die Cheyenne eingesetzt. Er muss miterleben, wie seine geliebte Kavallerie sich des Völkermordes schuldig macht. Obwohl Häuptling Gefleckter Wolf den Soldaten mit einer weißen Fahne entgegenreitet, wird sein Stamm brutal niedergemetzelt."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/gk71DcCAhdoNux7Zt5vovmJyCRB.jpg","en":"https://image.tmdb.org/t/p/w500/2fRfVQpdrjAhvxwytG0scOqdQOJ.jpg","es":"https://image.tmdb.org/t/p/w500/6vqJyrOleRoP716Sl2n7xog6w4i.jpg","fr":"https://image.tmdb.org/t/p/w500/uIXhFUi5wPeRl8emnXH9KOVWwpj.jpg","de":"https://image.tmdb.org/t/p/w500/x6R24XtcDN3aIcfgXoSRT7Mj99I.jpg"}'::jsonb WHERE id = 201;
UPDATE public.films SET tmdb_id = 70160, titoli_i18n = '{"it":"Hunger Games (The Hunger Games)","fr":"Hunger Games","es":"Los Juegos del Hambre","de":"Die Tribute von Panem – The Hunger Games","en":"The Hunger Games"}'::jsonb, trame_i18n = '{"it":"In un futuro distopico, la sedicenne Katniss Everdeen si offre volontaria al posto della sorella minore per partecipare agli Hunger Games, un brutale reality show televisivo in cui ventiquattro adolescenti combattono all''ultimo sangue.","fr":"Dans un proche futur, les États‐Unis sont devenus un gouvernement fédéral dystopique dans lequel chacun des 12 districts doit envoyer un garçon et une fille combattre lors d’un événement annuel télévisé, « Les Hunger Games ». La seule issue à ces jeux pour les « Tributs » est de tuer ou d’être tué. Lorsque la petite sœur de Katniss est tirée au sort pour y participer, celle‐ci décide de prendre sa place.","es":"Lo que en el pasado fueron los Estados Unidos, ahora es una nación llamada Panem; un imponente Capitolio ejerce un control riguroso sobre los 12 distritos que lo rodean y que están aislados entre sí. Cada distrito se ve obligado a enviar anualmente un chico y una chica entre los doce y los dieciocho años para que participen en los Hunger Games, unos juegos que son transmitidos en directo por la televisión. Se trata de una lucha a muerte, en la que sólo puede haber un superviviente. Katniss Everdeen, una joven de dieciséis años, decide sustituir a su hermana en los juegos; pero para ella, que ya ha visto la muerte de cerca, la lucha por la supervivencia es su segunda naturaleza.","de":"Die Tribute von Panem bringt uns in eine ferne Zukunft. Die Vereinigten Staaten sind schon lange im Staub der Geschichte versunken. Das Volk leidet unter schrecklichen Hungersnöten, da Jahrhunderte von Kriegen und Naturkatstrophen nur Staub und Verzweiflung zurückgelassen haben. Um die Bevölkerung an die blutigen Folgen eines früheren Aufstandes zu erinnern, inszeniert die Regierung eine grausame Show: Jedes Jahr werden in jedem Distrikt ein Junge und ein Mädchen zwischen 13 und 18 Jahren ausgelost, welche als Tribute von Panem an den Hunger-Games teilnehmen müssen. Dort müssen die 24 Kandidaten mehrere Tage lang auf Leben und Tod gegeneinander kämpfen, bis es am Ende nur noch einen Überlebenden gibt. Um ihre Schwester aus ihrer Tributspflicht zu lösen, meldet sich die 16jährige Katniss freiwillig für die Hunger Games.","en":"In a dystopian society where the Capitol forces each district to send two young tributes to fight to the death in a televised spectacle, a girl volunteers to take her sister’s place, setting the stage for a struggle of survival and defiance."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/azsm2nqX2eMJQ2eI6FjCIk17ncx.jpg","fr":"https://image.tmdb.org/t/p/w500/fWG9Jqqintc8jQj4XzWNMPjIxzf.jpg","es":"https://image.tmdb.org/t/p/w500/nmwpp0ykPbddqGW8WmOdBEYFImC.jpg","de":"https://image.tmdb.org/t/p/w500/8o3MlFkqI9O8PXRXDApyoN4HNPc.jpg","en":"https://image.tmdb.org/t/p/w500/apa5G43Hha7kH7wJG0gkkHT7FA9.jpg"}'::jsonb WHERE id = 202;
UPDATE public.films SET tmdb_id = 101299, titoli_i18n = '{"it":"Hunger Games: La ragazza di fuoco (The Hunger Games: Catching Fire)","en":"The Hunger Games: Catching Fire","fr":"Hunger Games : L''Embrasement","es":"Los Juegos del Hambre: En llamas","de":"Die Tribute von Panem – Catching Fire"}'::jsonb, trame_i18n = '{"it":"Dopo aver vinto i settantaquattresimi Hunger Games, Katniss e Peeta diventano il simbolo della ribellione contro Capitol City e vengono costretti a partecipare all''Edizione della Memoria degli Hunger Games.","en":"After surviving the Hunger Games, Katniss and Peeta struggle with the consequences of their victory as unrest spreads across Panem. Forced back into the spotlight, they become symbols of hope and resistance while the Capitol prepares a new and deadly challenge that will change the future of the nation forever.","fr":"Après les premiers Hunger Games, Katniss est devenue le symbole de la rébellion. Le peuple de Panem est impatient de la retrouver pour la grande Tournée de la victoire. Mais Katniss va devoir prouver au Capitole et au Président Snow que ses sentiments envers Peeta étaient sincères afin de sauver ceux qu’elle aime…","es":"Tras vencer en los 74º Juegos del Hambre anuales, la joven Katniss Everdeen y su compañero Peeta Mellark regresan a casa. Atrás dejaron a sus amigos y su familia, teniendo ambos que participar en la ''gira de la victoria'' por todos los distritos. Durante ese largo viaje, Katniss se da cuenta de que se está gestando una rebelión, pero en el Capitolio todo sigue igual y bajo estricto control del Presidente Snow, que está organizando los 75º Juegos del Hambre, denominados ''El Vasallaje de los Veinticinco'': una competición especial con una inesperada novedad que cambiará Panem para siempre.","de":"Katniss Everdeen hat nach den Ereignissen des ersten Teils den Zorn von Präsident Snow auf sich gezogen. Um sie endgültig auszuschalten wird sie gemeinsam mit Peeta Mellark anlässlich der 75. Hungerspiele (auch Quarter Quell genannt) gezwungen, abermals gegeneinander anzutreten. Sie müssen dabei gegen andere ehemalige Gewinner der Hungerspiele um ihr Überleben kämpfen. Katniss weiß, dass diesmal nicht nur ihr Leben, sondern auch die Sicherheit ihrer Familie auf dem Spiel steht, denn eine erneute Blamage wird Präsident Snow nicht dulden. Auch außerhalb der Arena hat Katniss Aufbegehren gegen die blutigen Regeln dieses Turniers Wirkung gezeigt. Immer mehr Menschen verweigern sich den Befehlen der totalitären Regierung und erblicken in Katniss das Symbol ihres gemeinsamen Widerstandes. Der Keim der Revolution ist gesät und Katniss’ Mocking Jay ist ihr gemeinsames Erkennungszeichen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/oFQj7SBn9pGGc6ZuadhmQoSYWaD.jpg","en":"https://image.tmdb.org/t/p/w500/vrQHDXjVmbYzadOXQ0UaObunoy2.jpg","fr":"https://image.tmdb.org/t/p/w500/lHdbNb8GEuMXCwar9wENzVu5eQI.jpg","es":"https://image.tmdb.org/t/p/w500/oxnKI1qiHz7xC0mNthC7dSqTcot.jpg","de":"https://image.tmdb.org/t/p/w500/goLUaKDwTip1fikpCHDA6oCIfkV.jpg"}'::jsonb WHERE id = 203;
UPDATE public.films SET tmdb_id = 131631, titoli_i18n = '{"it":"Hunger Games: Il canto della rivolta - Parte 1 (The Hunger Games: Mockingjay - Part 1)","es":"Los Juegos del Hambre: Sinsajo - Parte 1","en":"The Hunger Games: Mockingjay - Part 1","fr":"Hunger Games : La Révolte, partie 1","de":"Die Tribute von Panem – Mockingjay Teil 1"}'::jsonb, trame_i18n = '{"it":"Katniss si ritrova nel Distretto 13 dopo aver distrutto l''arena. Guidata dalla Presidente Coin, accetta di diventare la Ghiandaia Imitatrice, simbolo della rivoluzione contro Panem.","es":"Katniss Everdeen se encuentra en el Distrito 13 después de destrozar los Juegos para siempre. Bajo el liderazgo de la comandante Coin y el consejo de sus amigos más leales, Katniss extiende sus alas mientras lucha por salvar a Peeta Mellark y a una nación alentada por su valentía...","en":"After surviving the Quarter Quell, Katniss finds herself in the hidden stronghold of District 13, where the rebellion against the Capitol is gaining momentum. Struggling with the weight of becoming the symbol of resistance, she must navigate fragile alliances while trying to protect those she loves. As propaganda battles rage and Panem moves closer to full-scale war, Katniss is forced to confront the true cost of revolution.","fr":"Katniss Everdeen s’est réfugiée dans le District 13 après avoir détruit à jamais l’arène et les Jeux. Sous le commandement de la Présidente Coin, chef du district, et suivant les conseils de ses amis en qui elle a toute confiance, Katniss déploie ses ailes pour devenir le symbole de la rébellion. Elle va se battre pour sauver Peeta et libérer le pays tout entier, à qui son courage a redonné espoir.","de":"Katniss erwacht nach dem zweiten Hunger-Games-Turnier im Schiff der Rebellen. Da District 12 von der Regierung zerstört wurde, wird sie im unterirdischen District 13 versteckt. Sie erfährt, dass der District 13 entgegen der offiziellen Geschichtsschreibung noch immer existiert und jetzt die Anführer der Revolution stellt. Auch wenn Katniss zögert, sich der Truppe anzuschließen, erkennt sie, dass sie kaum andere Möglichkeiten hat. Die Rebellen wollen Katniss’ Popularität für ihre Zwecke ausnutzen und sie zum ‘Mockingjay’ aufbauen, dem Propagandaidol der Opposition gegen das Capitol. Gleichzeitig wird Peeta, der nicht aus der Arena gerettet werden konnte, von der Regierung gefangen gehalten. Er wird gezwungen, sich vor Kameras von Katniss und den Rebellen loszusagen und einen Waffenstillstand zu fordern. In einer letzten Mission begibt sich Katniss ins Capitol, um Präsident Snow zu töten."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/9LZSYohDOJkLU2TyRvPM1zIo62e.jpg","es":"https://image.tmdb.org/t/p/w500/wfLsciidZamFPeOb4FD8ywk1Q9c.jpg","en":"https://image.tmdb.org/t/p/w500/meSGXQ8MXqiC8bXxkKu7lPqnu0L.jpg","fr":"https://image.tmdb.org/t/p/w500/xWQfZgnjaH2fmjGSCWFYicTPwwv.jpg","de":"https://image.tmdb.org/t/p/w500/uK1ZjmrwugzDBSRMx8pi9ZEQDEV.jpg"}'::jsonb WHERE id = 204;
UPDATE public.films SET tmdb_id = 131634, titoli_i18n = '{"en":"The Hunger Games: Mockingjay - Part 2","it":"Hunger Games: Il canto della rivolta - Parte 2 (The Hunger Games: Mockingjay - Part 2)","es":"Los Juegos del Hambre: Sinsajo - Parte 2","fr":"Hunger Games : La Révolte, partie 2","de":"Die Tribute von Panem – Mockingjay Teil 2"}'::jsonb, trame_i18n = '{"en":"As the war between the Capitol and the districts reaches its peak, Katniss Everdeen embarks on a perilous mission to liberate Panem and confront President Snow. Joined by a team of trusted allies, she navigates deadly traps, shifting loyalties, and the heavy cost of rebellion, determined to bring freedom to her people and end the Hunger Games once and for all.","it":"Con Panem in guerra totale, Katniss guida la squadra d''assalto verso Capitol City per affrontare direttamente il Presidente Snow e porre fine alla tirannia.","es":"La última entrega de ''Los Juegos del Hambre'' nos muestra a una nación en guerra, en la que Katniss se enfrenta con uñas y dientes al presidente Snow. Con la ayuda de algunos amigos, entre ellos Gale, Finnick y Peeta, arriesgará la vida para salir del Distrito 13 y eliminar al presidente Snow.","fr":"Alors que Panem est ravagé par une guerre désormais totale, Katniss et le Président Snow vont s’affronter pour la dernière fois. Katniss et ses plus proches amis – Gale, Finnick, et Peeta – sont envoyés en mission pour le District 13 : ils vont risquer leur vie pour tenter d’assassiner le Président Snow, qui s’est juré de détruire Katniss. Les pièges mortels, les ennemis et les choix déchirants qui attendent Katniss seront des épreuves bien pires que tout ce qu’elle a déjà pu affronter dans l’arène…","de":"Katniss, die sich im 13. Distrikt versteckt hält, wird von den Revolutionsführern gegen das Capitol als Propagandainstrument ausgenutzt. Sie erwacht in einem Krankenhaus und erfährt, dass Peeta das Opfer einer Gedankenmanipulation des Capitols war. Doch die eigentliche Bedrohung geht nicht vom Capitol aus, sondern auch in den eigenen Reihen wird schon für die Zeit nach dem Krieg geplant, in der die Revolutionsikone Katniss für viele, die selbst auf die Macht hoffen, zu beliebt bei der Bevölkerung geworden ist. Katniss gelingt es nur schwer, Peeta zumindest ansatzweise wieder zu heilen. Trotzdem begibt sie sich mit ihm und einer kleinen Einheit in einer letzten geheimen Mission ins Capitol, um Präsident Snow zu töten. Seine Hinrichtung soll live im Fernsehen zu sehen sein, da die Anführer der Revolution glauben, die werde den Krieg beenden. Doch gerade ihren Anführern kann Katniss schon lange nicht mehr trauen. Alles was ihr bleibt, ist das Vertrauen auf ihren Instinkt."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/lImKHDfExAulp16grYm8zD5eONE.jpg","it":"https://image.tmdb.org/t/p/w500/aQvME1wpAZpjdyg5Xfe35lINmwt.jpg","es":"https://image.tmdb.org/t/p/w500/3qQPBc7JVGXJGo0Av5jrqndcdTm.jpg","fr":"https://image.tmdb.org/t/p/w500/hsHLkjIs3RKcUAOuJbvb19Q4ZiZ.jpg","de":"https://image.tmdb.org/t/p/w500/gGkGiNZ98aztaHtKxuvtWpNOwoD.jpg"}'::jsonb WHERE id = 205;
UPDATE public.films SET tmdb_id = 695721, titoli_i18n = '{"it":"Hunger Games - La ballata dell''usignolo e del serpente (The Hunger Games: The Ballad of Songbirds & Snakes)","en":"The Hunger Games: The Ballad of Songbirds & Snakes","fr":"Hunger Games : La Ballade du serpent et de l''oiseau chanteur","de":"Die Tribute von Panem – The Ballad of Songbirds and Snakes","es":"Los Juegos del Hambre: Balada de pájaros cantores y serpientes"}'::jsonb, trame_i18n = '{"it":"Decenni prima di diventare il tirannico presidente di Panem, il diciottenne Coriolanus Snow viene assegnato come mentore a Lucy Gray Baird, il tributo del Distretto 12 per i decimi Hunger Games.","en":"64 years before he becomes the tyrannical president of Panem, Coriolanus Snow sees a chance for a change in fortunes when he mentors Lucy Gray Baird, the female tribute from District 12.","fr":"Le jeune Coriolanus est le dernier espoir de sa lignée, la famille Snow autrefois riche et fière est aujourd’hui tombée en disgrâce dans un Capitole d''après-guerre. À l’approche des 10e Hunger Games, il est assigné à contrecœur à être le mentor de Lucy Gray Baird, un tribut originaire du District 12, le plus pauvre et le plus méprisé de Panem. Le charme de Lucy Gray ayant captivé le public, Snow y voit l’opportunité de changer son destin, et va s’allier à elle pour faire pencher le sort en sa faveur. Luttant contre ses instincts, déchiré entre le bien et le mal, Snow se lance dans une course contre la montre pour survivre et découvrir s’il deviendra finalement un oiseau chanteur ou un serpent.","de":"Jahre bevor er der tyrannische Präsident von Panem werden würde, ist der 18-jährige Coriolanus Snow die letzte Hoffnung für seine verblassende Abstammung, eine einst stolze Familie, die in einem Nachkriegskapitol in Ungnade gefallen ist. Da die 10. jährlichen Hungerspiele immer näher rücken, ist der junge Snow alarmiert, als er als Mentor für Lucy Gray Baird eingesetzt wird, die Mädchenehrung aus dem verarmten Distrikt 12. Aber nachdem Lucy Gray die ganze Aufmerksamkeit von Panem auf sich gezogen hat, indem sie während der Erntezeremonie trotzig singt, glaubt Snow, dass er in der Lage sein könnte, die Chancen zu ihren Gunsten zu wenden. Snow und Lucy vereinen ihren Instinkt für Selbstdarstellung und ihr neu entdecktes politisches Geschick. Ihr Überlebensrennen gegen die Zeit beginnt, um letztendlich zu enthüllen, wer ein Singvogel und wer eine Schlange ist.","es":"Ambientada en un Panem postapocalíptico, nos traslada varias décadas antes del comienzo de las aventuras de Katniss Everdeen. El joven Coriolanus Snow será el mentor de Lucy Gray Baird, la chica elegida para ser homenajeada del empobrecido Distrito 12. La joven sorprenderá a todos cantando en la ceremonia de apertura de los Décimos Juegos del Hambre en los que Snow intentará aprovecharse de su talento y encanto para sobrevivir."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/bk2Bh5mD3uvyKDaXKTAOGfoCTq5.jpg","en":"https://image.tmdb.org/t/p/w500/mBaXZ95R2OxueZhvQbcEWy2DqyO.jpg","fr":"https://image.tmdb.org/t/p/w500/q4EDvPcf956FgakWwcXiWdQEgxU.jpg","de":"https://image.tmdb.org/t/p/w500/itogxOvIcuF1pUQbfAaRTC74nCE.jpg","es":"https://image.tmdb.org/t/p/w500/2vIK81ikjvdewSLmrwIg7AMoJIv.jpg"}'::jsonb WHERE id = 206;
UPDATE public.films SET tmdb_id = 20352, titoli_i18n = '{"es":"Gru Mi villano favorito","it":"Cattivissimo me (Despicable Me)","fr":"Moi, moche et méchant","de":"Ich - Einfach unverbesserlich","en":"Despicable Me"}'::jsonb, trame_i18n = '{"es":"En una alegre urbanización con cuidados jardines rodeados por verjas de madera pintadas de blanco y llenos de rosales, sobresale una casa negra con el césped amarillento. Los vecinos ignoran que debajo de la vivienda hay un enorme escondite secreto. Allí está Gru, rodeado por un pequeño ejército de lacayos, planeando el mayor robo de toda la historia. ¡Va a hacerse con la luna!","it":"Il supercattivo Gru pianifica di rubare la Luna con l''aiuto dei suoi piccoli assistenti gialli, i Minions, ma il suo piano viene scompaginato dall''incontro con tre bambine orfane.","fr":"Dans un charmant quartier résidentiel délimité par des clôtures de bois blanc et orné de rosiers fleurissants se dresse une bâtisse noire entourée d’une pelouse en friche. Cette façade sinistre cache un secret : Gru, un méchant vilain, entouré d’une myriade de sous‐fifres et armé jusqu’aux dents, qui, à l’insu du voisinage, complote le plus gros casse de tous les temps : voler la lune (Oui, la lune !)… Gru affectionne toutes sortes de sales joujoux. Il possède une multitude de véhicules de combat aérien et terrestre et un arsenal de rayons immobilisants et rétrécissants avec lesquels il anéantit tous ceux qui osent lui barrer la route… jusqu’au jour où il tombe nez à nez avec trois petites orphelines qui voient en lui quelqu’un de tout à fait différent : un papa. Le plus grand vilain de tous les temps se retrouve confronté à sa plus dure épreuve : trois fillettes prénommées Margo, Édith et Agnès.","de":"Der verschrobene Gru führt ein zurückgezogenes Leben – unscheinbar lebt er in einer kleinen Nachbarschaft irgendeines Vorortes. Aber was seine Nachbarn nicht wissen: Er plant das größte Verbrechen der Menschheitsgeschichte und will den Mond klauen. Auf dem Vormarsch mit technisch raffinierten Waffen und von der Polizei nicht zu stoppen, findet er aber dann doch – vielleicht – seine Bezwinger. Drei Waisenmädchen entdecken in ihm einen potentiellen Vater. Ist es nun mit seinem Verbrecherleben vorbei … oder stiehlt er doch noch den Mond?","en":"Determined to prove he''s the world''s greatest supervillain, Gru hatches an audacious plan to steal the Moon. To pull it off, he adopts three orphaned girls—Margo, Edith, and Agnes—intending to use them as pawns in his scheme. But the unexpected bond they form forces him to question the criminal life he''s always known."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/AsaaPLSfisdFDeasEd9r0GiZVss.jpg","it":"https://image.tmdb.org/t/p/w500/t6hBb0Iz8TkY6JNxaUCE30es3iT.jpg","fr":"https://image.tmdb.org/t/p/w500/wuhJx9bTbxHfJHeeR3L8uRjAZ7C.jpg","de":"https://image.tmdb.org/t/p/w500/tgQAiavJYM1vGcNVeKZHr35F4WB.jpg","en":"https://image.tmdb.org/t/p/w500/b1BT309QWjtFUlJPLmXmrcHOWEL.jpg"}'::jsonb WHERE id = 207;
UPDATE public.films SET tmdb_id = 93456, titoli_i18n = '{"it":"Cattivissimo me 2 (Despicable Me 2)","es":"Gru 2. Mi villano favorito","fr":"Moi, moche et méchant 2","de":"Ich - Einfach unverbesserlich 2","en":"Despicable Me 2"}'::jsonb, trame_i18n = '{"it":"Gru viene reclutato dalla Lega Anti-Cattivi per indagare sulla scomparsa di un laboratorio segreto e sulla trasformazione dei suoi Minions in mostri viola indistruttibili.","es":"La película de animación de los estudios Universal, giraba en torno a una apacible y colorida población en la que vivía el malvado Gru. Ayudado por su batallón de Minions, unos pequeños seres de color amarillo, intentaron robar la Luna, aunque no todo acabó como esperaban. Tres niñas curiosas y algo traviesas se cruzaron en su camino, entorpeciéndole todos sus planes y conviertiendo su objetivo en una alocada hazaña interestelar.  Ahora, ''Gru, mi villano favorito 2'', narra una nueva aventura en la que Gru volverá a estar acompañado de simpáticos humanoides.","fr":"Ayant abandonné la super‐criminalité et mis de côté ses activités funestes pour se consacrer à la paternité et élever Margo, Édith et Agnès, Gru, et avec lui, le Professeur Néfario et les Minions, doivent se trouver de nouvelles occupations. Alors qu’il commence à peine à s’adapter à sa nouvelle vie tranquille de père de famille, une organisation ultrasecrète, menant une lutte acharnée contre le Mal à l’échelle planétaire, vient frapper à sa porte. Soudain, c’est à Gru, et à sa nouvelle coéquipière Lucy, que revient la responsabilité de résoudre une série de méfaits spectaculaires. Après tout, qui mieux que l’ex plus méchant de tous les temps, pourrait attraper celui qui rivalise pour lui voler la place qu’il occupait encore récemment…","de":"Nachdem der Superschurke Gru die drei Waisenkinder Margo, Edith und Agnes adoptiert hat, hat sich in seinem Leben viel geändert. Anstatt als Griesgram Verbrechen zu begehen, dreht sich sein Leben nun um Gute-Nacht-Geschichten, Kindergeburtstage und erste Verehrer der Mädchen. Sein neues Leben wird plötzlich gestört, als Lucy, eine Agentin der geheimen Anti-Villain League, Gru gegen seinen Willen zu deren Zentrale führt. Dort bekommt Gru den Auftrag, die Welt vor einem neuen Bösewicht zu retten. Eifrig macht sich Gru ans Werk und bekommt dabei erneut Hilfe von Dr. Nefario  und seinen meist sehr tollpatschigen Minions. Doch seine neue Aufgabe mit der Erziehung seiner Adoptivtöchter in Einklang zu bringen ist nicht leicht und auch mit der Situation, dass Lucy auch außerhalb der Arbeit sehr von Gru angetan ist, überfordert den ehemaligen Einzelgänger.","en":"Gru is recruited by the Anti-Villain League to help deal with a powerful new super criminal."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/cAHjd4n5dmBnKf6eHcXbqi4CSrJ.jpg","es":"https://image.tmdb.org/t/p/w500/hhksXOBVJ6Mu2BwAFgPJwZxNisd.jpg","fr":"https://image.tmdb.org/t/p/w500/PCd21fTyaJN9ge1MpYUfF5Zcmb.jpg","de":"https://image.tmdb.org/t/p/w500/e9uMneUxEN8vb3lS2wU9Pie597B.jpg","en":"https://image.tmdb.org/t/p/w500/5Fh4NdoEnCjCK9wLjdJ9DJNFl2b.jpg"}'::jsonb WHERE id = 208;
UPDATE public.films SET tmdb_id = 211672, titoli_i18n = '{"en":"Minions","es":"Los minions","it":"Minions","fr":"Les Minions","de":"Minions"}'::jsonb, trame_i18n = '{"en":"Minions Stuart, Kevin and Bob are recruited by Scarlet Overkill, a super-villain who, alongside her inventor husband Herb, hatches a plot to take over the world.","es":"Los minions empezaron siendo organismos amarillos unicelulares que evolucionaron a través del tiempo, poniéndose siempre al servicio de los amos más despreciables. Ante su incapacidad para mantener a esos amos – desde el T. Rex a Napoleón –, los minions acaban encontrándose solos y caen en una profunda depresión. Sin embargo, uno de ellos, tiene un plan. Emprende un emocionante viaje para conseguir una jefa a quien servir, la terrible Scarlet Overkill. Pasarán de la helada Antártida, a la ciudad de Nueva York (Estados Unidos) en la década de 1960 para acabar en Londres (Reino Unido), donde deberán enfrentarse al mayor reto hasta la fecha: salvar a la raza ninion de la aniquilación.","it":"Evolutisi da organismi unicellulari gialli, i Minions cercano disperatamente un padrone malvagio da servire. Nel 1968, Kevin, Stuart e Bob partono per una missione che li condurrà da Scarlet Sterminator.","fr":"À la nuit des temps des temps. À l’origine, de simples organismes monocellulaires de couleur jaune, les Minions ont évolué au cours des âges au service de maîtres plus abjects les uns que les autres. Les disparitions répétitives de ceux‐ci, des tyrannosaures à Napoléon, ont plongé nos mignons personnages dans une profonde dépression. Mais l’un d’eux, prénommé Kevin, a une idée. Flanqué de Stuart, l’adolescent rebelle et de l’adorable petit Bob, Kevin part à la recherche d’un nouveau patron malfaisant pour guider les siens. Nos trois Minions se lancent dans un palpitant voyage qui va les conduire à leur nouveau maître… qui s’avère être une maîtresse : Scarlet Overkill, la première super‐vilaine de l’histoire. De l’Antarctique au New York des années 60, nos trois compères arrivent finalement à Londres, à l’apogée des mods, où ils vont devoir faire face à la plus terrible menace de leur existence : l’annihilation de leur espèce.","de":"Seit dem Anfang des Anfang gab es die Minions schon: kleine, gelbe Helferlein, deren einziger Existenzgrund ist, einem Bösewicht zu Diensten zu stehen. Als all ihre Meister jedoch zerstört wurden, zogen sie sich in die Antarktis zurück und verharrten dort viele, viele Jahre in Depression - bis schließlich in den Sechziger Jahren der mutigste Minion und zwei Gefährten den Entschluss fassen, einen neuen Meister finden zu gehen. Und so machen sie sich auf zu einer Bösewicht-Convention. Dort laufen sie der verrückten Super-Bösewichtin Scarlett Overkill und ihrem Ehemann, dem Wissenschaftler Herb Overkill in die Arme. Sie will die erste weibliche Oberbösewichtin werden und die kleinen gelben Helferlein für ihre finsteren Pläne missbrauchen."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/dr02BdCNAUPVU07aOodwPYv6HCf.jpg","es":"https://image.tmdb.org/t/p/w500/nmqLwaTfgyWLQWbYd82w159cAqJ.jpg","it":"https://image.tmdb.org/t/p/w500/bQ92zNRkeD7SL2awyHPsC5PCjkF.jpg","fr":"https://image.tmdb.org/t/p/w500/sGuZHYvu0mXeQCwvJ5yzk2Yoytq.jpg","de":"https://image.tmdb.org/t/p/w500/4WdMdylQUwF534UU5FXHocCbw6e.jpg"}'::jsonb WHERE id = 209;
UPDATE public.films SET tmdb_id = 324852, titoli_i18n = '{"it":"Cattivissimo me 3 (Despicable Me 3)","en":"Despicable Me 3","fr":"Moi, moche et méchant 3","es":"Gru 3. Mi villano favorito","de":"Ich - Einfach unverbesserlich 3"}'::jsonb, trame_i18n = '{"it":"Dopo essere stato licenziato dalla Lega Anti-Cattivi, Gru scopre di avere un fratello gemello ricco e stravagante di nome Dru, mentre i Minions affrontano una breve ribellione.","en":"Gru and his wife Lucy must stop former ''80s child star Balthazar Bratt from achieving world domination.","fr":"Après avoir été licencié de la Ligue Anti‐Villain pour avoir échoué à capturer le dernier méchant capable de menacer l’humanité, Gru se trouve confronté à une crise d’identité majeure. Mais quand se présente un étranger mystérieux qui l’informe du décès de son père mais aussi de l’existence d’un frère jumeau – un frère qui veut désespérément suivre les traces méprisables de son jumeau – un ancien super‐méchant va redécouvrir à quel point c’est bon d’être mauvais.","es":"A Gru lo han despedido. Se ha quedado sin trabajo porque ha dejado escapar al supervillano Balthazar Bratt, estrella infantil de los años 80 que con la llegada de la pubertad lo perdió todo y ha estado creando el caos en todo el planeta.  Además, Gru va a conocer a su hermano gemelo Dru y tendrá que decidir si está listo para continuar la tradición familiar de dedicarse al crimen, y unirse a el para llevar a cabo un último golpe. Aunque ha dejado esa vida atrás… ¿volverá a convertirse Gru en un villano?","de":"Der einstmals finstere Gru hat sich im zweiten Teil in Agentin Lucy Wilde verguckt und aus Liebe zu ihr und seinen drei Adoptivtöchtern Margo, Edith und Agnes die Seiten gewechselt: Gemeinsam mit seiner Angetrauten bekämpft er nun Bösewichte. Zu diesen gehört auch Balthazar Bratt, ein Super-Bösewicht und 80er-Jahre-Fan mit Schulterpolstern und Vokuhila, der hinter einem riesigen rosa Diamanten her ist. Während Gru mit der Jagd auf Bratt beschäftigt ist, bekommt er Besuch von seinem Zwillingsbruder Dru. Dieser hat nicht nur volles Haar, sondern ist auch noch erfolgreicher und selbstbewusster als Gru, der nicht mal seine Minions unter Kontrolle hat – und das nervt diesen gewaltig! Doch dann holt Balthazar Bratt zu einem teuflischen Schlag aus und die ungleichen Brüder müssen sich zusammenraufen, um die Welt zu retten."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/w5UQOIVconX1rmmGgUch9a1SMuG.jpg","en":"https://image.tmdb.org/t/p/w500/e72KCMHNkbZ6USRJmABeqwmaJ5n.jpg","fr":"https://image.tmdb.org/t/p/w500/sXRCdFPzlQeRGPO6wWhCOnVI0wR.jpg","es":"https://image.tmdb.org/t/p/w500/mz3zTmsnySgFWGc3ZsBbCQbalut.jpg","de":"https://image.tmdb.org/t/p/w500/f2QpHiuMjQ5J9olQVIJBDLV8Hr4.jpg"}'::jsonb WHERE id = 210;
UPDATE public.films SET tmdb_id = 438148, titoli_i18n = '{"en":"Minions: The Rise of Gru","it":"Minions 2 - Come Gru diventa cattivissimo (Minions: The Rise of Gru)","de":"Minions - Auf der Suche nach dem Mini-Boss","es":"Minions: El origen de Gru","fr":"Les Minions 2 : Il était une fois Gru"}'::jsonb, trame_i18n = '{"en":"A fanboy of a supervillain supergroup known as the Vicious 6, Gru hatches a plan to become evil enough to join them, with the backup of his followers, the Minions.","it":"Negli anni ''70, il dodicenne Gru tenta di entrare a far parte di un gruppo di supercattivi chiamato I Malefici 6. Quando il suo colloquio va male, i Minions intervengono per aiutarlo.","de":"In den 70er-Jahren, lange bevor er zu einem Meister des Bösen aufsteigt, ist Gru einfach ein zwölfjähriger Vorstadtjunge, der in seinem Keller von der Weltherrschaft träumt. Als die berüchtigte Schurkenbande \"Die fiesen 6\" ihren Anführer rauswirft, bewirbt Gru sich um dessen Nachfolge, endet alsbald jedoch als Todfeind der Bande. Während Gru fliehen muss, lernen die Minions Kampfsport, um ihn zu retten, und Gru findet heraus, dass selbst Schurken manchmal ein bisschen Hilfe von ihren Freunden gebrauchen können.","es":"En la década de 1970, Gru crece siendo un gran admirador de \"Los salvajes seis\", un supergrupo de villanos. Para demostrarles que puede ser malvado, diseña un plan con la esperanza de formar parte de la banda.","fr":"Alors que les années 70 battent leur plein, Gru qui grandit en banlieue au milieu des jeans à pattes d’éléphants et des chevelures en fleur, met sur pied un plan machiavélique à souhait pour réussir à intégrer un groupe célèbre de super méchants, connu sous le nom de Vicious 6, dont il est le plus grand fan. Il est secondé dans sa tâche par les Minions, ses petits compagnons aussi turbulents que fidèles. Avec l’aide de Kevin, Stuart, Bob et Otto – un nouveau Minion arborant un magnifique appareil dentaire et un besoin désespéré de plaire – ils vont déployer ensemble des trésors d’ingéniosité afin de construire leur premier repaire, expérimenter leurs premières armes, et lancer leur première mission. Gru passe l’audition pour intégrer l’équipe. Le moins qu’on puisse dire c’est que l’entrevue tourne mal, et soudain court quand Gru leur démontre sa supériorité et se retrouve soudain leur ennemi juré."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/4dBDk1LPdvdhcZdjQBmdXwiVKUA.jpg","it":"https://image.tmdb.org/t/p/w500/qfJeCjOVYYfy8uYqF711qV8Usqe.jpg","de":"https://image.tmdb.org/t/p/w500/nHJDZsad536CYI6RK9n97rNjqUN.jpg","es":"https://image.tmdb.org/t/p/w500/fzwG3cukayxKpCK0lqS1jkSBqJk.jpg","fr":"https://image.tmdb.org/t/p/w500/pA05WmBZLEu32peDDh3I4VuVPsu.jpg"}'::jsonb WHERE id = 211;
UPDATE public.films SET tmdb_id = 519182, titoli_i18n = '{"es":"Gru 4. Mi villano favorito","it":"Cattivissimo me 4 (Despicable Me 4)","de":"Ich - Einfach unverbesserlich 4","fr":"Moi, moche et méchant 4","en":"Despicable Me 4"}'::jsonb, trame_i18n = '{"es":"Gru, Lucy y las niñas -Margo, Edith y Agnes- dan la bienvenida a un nuevo miembro en la familia: Gru Junior, que parece llegar con el propósito de ser un suplicio para su padre. Gru tendrá que enfrentarse en esta ocasión a su nueva némesis Maxime Le Mal y su sofisticada y malévola novia Valentina, lo que obligará a la familia a tener que darse a la fuga. Cuarta entrega de ''Gru, mi villano favorito''.","it":"Gru, Lucy e le loro figlie accolgono un nuovo membro in famiglia, Gru Jr., ma sono costretti alla fuga quando il supercriminale Maxime Le Mal evade di prigione per vendicarsi.","de":"Ein ehemaliger Erzschurke verwandelt sich in einen Vorstadtvater – eine Veränderung, die Gru widerfährt, nachdem er bei einem Klassentreffen auf seinen größten Widersacher stößt, ein Konflikt ausbricht und er sich gezwungen sieht, unterzutauchen. Doch die ungestörte Idylle findet ein jähes Ende, als Baby Gru Junior entführt wird. Zusammen mit seiner Familie begibt sich Gru auf eine abenteuerliche und verrückte Rettungsmission. Im Team sind auch die Minions, die durch ein Superserum in fünf Mega Minions mit einzigartigen Kräften verwandelt wurden und für noch mehr Chaos sorgen!","fr":"Gru, Lucy et les filles, Margo, Édith et Agnès accueillent le petit dernier de la famille, Gru Junior, qui semble n’avoir qu’une passion : faire tourner son père en bourrique. Mais Gru est confronté à un nouvel ennemi, Maxime Le Mal, qui avec l’aide de sa petite amie, la fatale Valentina, va obliger toute la famille à fuir.","en":"Gru and Lucy and their girls—Margo, Edith and Agnes—welcome a new member to the Gru family, Gru Jr., who is intent on tormenting his dad. Gru also faces a new nemesis in Maxime Le Mal and his femme fatale girlfriend Valentina, forcing the family to go on the run."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/b6JX0fBne5yPFNBtdp4Imi3CpiE.jpg","it":"https://image.tmdb.org/t/p/w500/gIV7DbvWUwPN4lxSk3dMNkXzgX7.jpg","de":"https://image.tmdb.org/t/p/w500/t8fh33Rx3YithmYJ2xqAjdVsBUh.jpg","fr":"https://image.tmdb.org/t/p/w500/bYovCvLV1RxB0zAR5cXu699P9P7.jpg","en":"https://image.tmdb.org/t/p/w500/wWba3TaojhK7NdycRhoQpsG0FaH.jpg"}'::jsonb WHERE id = 212;
UPDATE public.films SET tmdb_id = 205775, titoli_i18n = '{"it":"Heart of the Sea - Le origini di Moby Dick (In the Heart of the Sea)","en":"In the Heart of the Sea","es":"En el corazón del mar","fr":"Au cœur de l''Océan","de":"Im Herzen der See"}'::jsonb, trame_i18n = '{"it":"Nel inverno del 1820, la baleniera del New England Essex viene assalita da una creatura incredibile: una balena dalle dimensioni e dalla forza mastodontiche, con un senso quasi umano di vendetta. Il disastro marittimo realmente accaduto avrebbe ispirato Herman Melville a scrivere Moby Dick.","en":"In the winter of 1820, the New England whaling ship Essex is assaulted by something no one could believe—a whale of mammoth size and will, and an almost human sense of vengeance.","es":"En el invierno de 1820, el ballenero de Nueva Inglaterra Essex fue agredido por algo a lo que nadie podía dar crédito: una ballena de tamaño y voluntad descomunal, con un sentido de la venganza casi humano. Este hecho real que supuso un desastre marítimo fue la inspiración para Moby-Dick de Melville. Pero la novela solo contó la mitad de la historia. “En el corazón del mar” revela las horribles consecuencias del encuentro, cuando los supervivientes de la tripulación fueron forzados hasta el límite y se vieron obligados a hacer lo impensable para mantenerse vivos. Enfrentándose a las tormentas, el hambre, el pánico, y la desesperación, los hombres llegan a dudar hasta de sus creencias más profundas, desde el valor de sus vidas a la moralidad de su oficio, mientras el capitán intenta orientarse en el mar abierto y su primer oficial sigue empeñado en conquistar a la gran ballena.","fr":"À l''hiver 1820, le baleinier Essex, originaire de Nouvelle-Angleterre, est attaqué par une créature redoutable : une baleine aux dimensions hors normes et à la volonté de fer qui semble animée par une terrible soif de vengeance.  Cette catastrophe maritime inspirera \"Moby Dick\" d''Herman Melville. Mais cet ouvrage n''a pas relaté l''intégralité des événements. \"Au cœur de l''océan\" s''attache aux conséquences épouvantables de ce désastre, alors que les survivants de l''équipage sont acculés et contraints de commettre l''impensable pour rester en vie. Affrontant les tempêtes, la faim, la panique et le désespoir, ces hommes remettent en question leurs convictions les plus profondes et leurs valeurs morales, tandis que le capitaine du navire cherche à retrouver le cap et que son second croit encore pouvoir mater l''énorme mammifère qui les a pris pour cible…","de":"1820 wird ein Walfängerschiff, die Essex, von einem riesigen Wal angegriffen. Das Ungewöhnliche daran ist, dass das Tier aus einem bisher nur Menschen zugeschriebenen Vergeltungsdrang angetrieben zu sein scheint. Die Essex entgeht nur knapp dem Untergang und ein großer Teil der Besatzung kommt ums Leben. Doch damit ist der Alptraum noch nicht vorbei, denn nun muss es das Schiff erst einmal wieder ans sichere Ufer schaffen. Die Besatzung, zerrüttet durch den Verlust der Kameraden, steht vor einer schwierigen Aufgabe: Der unerfahrene Kapitän George Pollard  versucht, in den tobenden Gewässern einen sicheren Kurs in die Heimat zu bestimmen, während der abgebrühte erste Offizier Owen Chase nur auf Rache gegen den Wal sinnt. 30 Jahre nach den Ereignissen recherchiert Autor Herman Melville das Schicksal der Essex und schreibt ein Buch darüber - den Klassiker \"Moby Dick\"..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/wAN0GViqoyT1616y1fBq0hNB2HR.jpg","en":"https://image.tmdb.org/t/p/w500/weVvNPfk6FM9vBg3BXtRtNAmiYM.jpg","es":"https://image.tmdb.org/t/p/w500/ajcrkYTl8p55LGXYfGzx4d5XIco.jpg","fr":"https://image.tmdb.org/t/p/w500/dRQPhD7RUMa290dzQtmu0NFobvR.jpg","de":"https://image.tmdb.org/t/p/w500/rvT4BXWwq2ReNmCNuOo1tBit3VX.jpg"}'::jsonb WHERE id = 213;
UPDATE public.films SET tmdb_id = 146233, titoli_i18n = '{"it":"Prisoners","es":"Prisioneros","en":"Prisoners","fr":"Prisoners","de":"Prisoners"}'::jsonb, trame_i18n = '{"it":"Dopo la scomparsa della figlia di sei anni e della sua amica durante il Giorno del Ringraziamento, Keller Dover affronta il peggior incubo di ogni genitore. Il detective Loki guida le indagini e arresta l''unico sospettato, ma è costretto a rilasciarlo per mancanza di prove. Preso dalla disperazione e vedendo la polizia brancolare nel buio, Keller decide di farsi giustizia da solo, spingendosi oltre ogni limite pur di salvare le bambine.","es":"Keller Dover se enfrenta a la peor de las pesadillas: Anna, su hija de seis años, ha desaparecido con su amiga Joy y, a medida que pasa el tiempo, el pánico lo va dominando. Desesperado, decide ocuparse personalmente del asunto. Pero, ¿hasta dónde está dispuesto a llegar para averiguar el paradero de su hija?","en":"After his six-year-old daughter is abducted, a desperate father takes justice into his own hands when he loses faith in the detective leading the investigation, setting both men on a collision course as the search descends into obsession and moral compromise.","fr":"Dans la banlieue de Boston, deux fillettes de 6 ans, Anna et Joy, ont disparu. Le détective Loki privilégie la thèse du kidnapping suite au témoignage de Keller, le père d’Anna. Le suspect numéro 1 est rapidement arrêté mais est relâché quelques jours plus tard faute de preuve, entrainant la fureur de Keller. Aveuglé par sa douleur, le père dévasté se lance alors dans une course contre la montre pour retrouver les enfants disparus. De son côté, Loki essaie de trouver des indices pour arrêter le coupable avant que Keller ne commette l’irréparable… Les jours passent et les chances de retrouver les fillettes s’amenuisent…","de":"Keller Dover ist ein bibeltreuer Kriegsveteran. Der harte Kerl steht mit beiden Beinen fest im Leben. Dovers Welt gerät jedoch aus den Fugen, als seine sechsjährige Tochter Anna und deren Freundin Joy an Thanksgiving entführt werden. Es beginnt eine fieberhafte Suche, die von dem jungen und ambitionierten Detektiv Loki angeführt wird, dessen primäres Ziel es jedoch ist, endlich der Kleinstadt zu entfliehen und in eine Großstadt versetzt zu werden. Alle Spuren zu der Entführung verlaufen im Nichts. Auch den einzigen Verdächtigen, den geistig zurückgebliebenen Alex Jones, muss Loki aus Mangel an Beweisen wieder laufen lassen. Familienvater Dover fasst daraufhin einen folgenschweren Entschluss: Er will die Wahrheit auf eigene Faust herausfinden und begibt sich auf einen verhängnisvollen und gnadenlosen Weg der Selbstjustiz um die beiden kleinen Mädchen vielleicht doch noch zu finden."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/h1rj4wTATjxeqFMtEOuZyk1czis.jpg","es":"https://image.tmdb.org/t/p/w500/i6CcmOvJxBFH3mfhCHa3Njtelix.jpg","en":"https://image.tmdb.org/t/p/w500/uhviyknTT5cEQXbn6vWIqfM4vGm.jpg","fr":"https://image.tmdb.org/t/p/w500/fUk1f0iOAezl5PZ7gQW6nrguOXk.jpg","de":"https://image.tmdb.org/t/p/w500/d7DS20nwYT6WzbN2IvTvXvKPWjT.jpg"}'::jsonb WHERE id = 214;
UPDATE public.films SET tmdb_id = 10376, titoli_i18n = '{"it":"La leggenda del pianista sull''oceano (The Legend of 1900)","en":"The Legend of 1900","fr":"La Légende du pianiste sur l''océan","es":"La leyenda del pianista en el océano","de":"Die Legende vom Ozeanpianisten"}'::jsonb, trame_i18n = '{"it":"La storia di Danny Boodmann T.D. Lemon Novecento, un pianista straordinario nato e cresciuto a bordo del transatlantico Virginian, senza mai mettere piede sulla terraferma. La sua vita e il suo incredibile talento vengono raccontati dal suo grande amico, il trombettista Max Tooney.","en":"Musician Max Tooney goes to sell his prized Conn trumpet to a music shop, where he plays the instrument one last time. The shopkeeper recognises the song as one on a record matrix he found and asks who the piece is by. Tooney tells the story of an infant found abandoned in the first class dining room of the four-stacker ocean-liner SS Virginian on 1 January 1900. Danny Boodman, a coal-man from the boiler room, names the boy Danny Boodman T. D. Lemon 1900, after himself, the fruit crate the boy was found in, and the year, and raises him as his own.","fr":"À bord du \"Virginian\", paquebot de croisière, Danny, un mécanicien, découvre un nouveau-né abandonné dans la salle de bal désertée. Il décide de l''élever et le baptise du nom de 1900.  À la mort de Danny, l''enfant, adopté par l''équipage, grandit sur le navire, voguant d''un continent à l''autre. Un jour, 1900 s''assoit au piano et révèle un don extraordinaire pour la musique. Adulte, il devient un pianiste virtuose. Les plus grands jazzmen lui rendent visite. 1900 refuse de quitter le navire.\r Jusqu''au jour où celui-ci est promis à la démolition.","es":"Historia de un niño que fue abandonado sobre el piano del Virginia, un enorme trasatlántico. El niño es adoptado por un maquinista y le pone por nombre \"Novecento\", ya que lo encuentra justo en el cambio de siglo. Novecento se convertirá en un fabuloso pianista y amenizará las noches del Virginia. Pero nunca pisará tierra firme, ni tan sólo tras las súplicas de su amigo Max.","de":"Im Jahre 1900 findet der Seemann Danny Boodmann eine Kiste mit der Aufschrift \"T.D. Lemon\" in der sich ein Baby befindet, das er folglich Danny Boodmann T.D. Lemon 1900 nennt. Der kleine Junge wird im Heizraum des Schiffes grossgezogen und entwickelt sich zu einem der besten Pianisten."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/8rttNpb83qdHFMPMgFlcspVGaio.jpg","en":"https://image.tmdb.org/t/p/w500/iOcbJ5pxokOPDRgieVDbsFMrCc6.jpg","fr":"https://image.tmdb.org/t/p/w500/tamGferK68ppVyOrM8jiqF5vbjJ.jpg","es":"https://image.tmdb.org/t/p/w500/8rttNpb83qdHFMPMgFlcspVGaio.jpg","de":"https://image.tmdb.org/t/p/w500/kYFOxIiEvxJxI8BMO1oNghKjSPw.jpg"}'::jsonb WHERE id = 216;
UPDATE public.films SET tmdb_id = 115036, titoli_i18n = '{"es":"El libro de Boba Fett","it":"The Book of Boba Fett","en":"The Book of Boba Fett","fr":"Le Livre de Boba Fett","de":"Das Buch von Boba Fett"}'::jsonb, trame_i18n = '{"es":"El legendario cazarrecompensas Boba Fett y la mercenaria Fennec Shand deben navegar por el inframundo de la galaxia cuando regresen a las arenas de Tatooine para reclamar el territorio que una vez gobernó Jabba el Hutt y su sindicato del crimen.","it":"Il leggendario cacciatore di taglie Boba Fett e la mercenaria Fennec Shand tornano sulle sabbie di Tatooine per rivendicare il territorio un tempo controllato da Jabba the Hutt e dal suo sindacato criminale.","en":"Legendary bounty hunter Boba Fett and mercenary Fennec Shand must navigate the galaxy’s underworld when they return to the sands of Tatooine to stake their claim on the territory once ruled by Jabba the Hutt and his crime syndicate.","fr":"Après s’être hasardés dans les bas-fonds de la galaxie, le légendaire chasseur de primes et la mercenaire Fennec Shand reviennent au milieu des dunes de Tatooine pour y revendiquer le territoire autrefois dirigé par Jabba le Hutt et son syndicat du crime.","de":"Der Kopfgeldjäger Boba Fett und der Söldner Fennec Shand reisen durch die Unterwelt der Galaxis."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/4bffB2YV4UxNfEifp4HxdhfJulK.jpg","it":"https://image.tmdb.org/t/p/w500/lQqbnWsGt9RBGBWrmUKUOXZkl7N.jpg","en":"https://image.tmdb.org/t/p/w500/gNbdjDi1HamTCrfvM9JeA94bNi2.jpg","fr":"https://image.tmdb.org/t/p/w500/bumvJZvV3p98VOvdkGIkGVz6utk.jpg","de":"https://image.tmdb.org/t/p/w500/fz9fn1Aa4PkAEH6eSe39mBPQEqF.jpg"}'::jsonb WHERE id = 217;
UPDATE public.films SET tmdb_id = 114166, titoli_i18n = '{"en":"Quo Vadis?","it":"Quo Vadis?","fr":"Quo Vadis?","de":"Quo Vadis?","es":"Quo Vadis?"}'::jsonb, trame_i18n = '{"en":"During the latter years of the reign of the tyrannical Roman emperor Nero, Marcus Vinicius, one of Nero''s officers, falls in love with a young Christian named Lygia, attempting to enslave her. Lygia''s protector, the noble and  burly Ursus, works to save her from Vinicius'' clutches. Pursuing Lygia, Vinicius finds himself at a catacomb prayer meeting led by the apostle Peter and finds his conscience stirring-- just as Nero orders Rome burned. A landmark in epic film, Enrico Guazzoni’s grand-scale masterpiece laid the foundations for what colossal Italian spectacles would become. The film had tremendous influence on Giovanni Pastrone’s Cabiria (1914) and D.W. Griffith’s Intolerance (1916).","it":"Nella Roma dell''imperatore Nerone, il giovane tribuno Marco Vinicio si innamora della cristiana Licia. Tra intrighi di corte, l''incendio della città e il martirio dei primi cristiani, il loro amore affronterà terribili prove."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/xbA8ljsXMgOnbkN3X5li9UzFSvf.jpg","it":"https://image.tmdb.org/t/p/w500/xbA8ljsXMgOnbkN3X5li9UzFSvf.jpg","fr":"https://image.tmdb.org/t/p/w500/xbA8ljsXMgOnbkN3X5li9UzFSvf.jpg","de":"https://image.tmdb.org/t/p/w500/xbA8ljsXMgOnbkN3X5li9UzFSvf.jpg","es":"https://image.tmdb.org/t/p/w500/xbA8ljsXMgOnbkN3X5li9UzFSvf.jpg"}'::jsonb WHERE id = 219;
UPDATE public.films SET tmdb_id = 184499, titoli_i18n = '{"fr":"Quo Vadis?","de":"Quo Vadis?","en":"Quo Vadis?","it":"Quo Vadis?","es":"Quo Vadis?"}'::jsonb, trame_i18n = '{"en":"\"The Roman Banquet, the golden glories, the unrivaled luxuries, the wine, the dance, the song, the beautiful women, the sumptuous splendors that taxed a barbaric world for a night of feasting and revel-- Re-created for your entertainment in the most colossal drama produced\", reads an ad in the Daily Argus of New York. Unione Cinematografica Italiana''s lavish production of the oft-told tale stars Emil Jannings as Nero.","it":"Imponente kolossal muto che mette in scena la follia dell''imperatore Nerone e il tragico destino dei primi cristiani a Roma, intrecciato con la storia d''amore tra Marco Vinicio e la giovane Licia."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/9XznF1gIXfgqzEs6La7vXMW46sM.jpg","de":"https://image.tmdb.org/t/p/w500/9XznF1gIXfgqzEs6La7vXMW46sM.jpg","en":"https://image.tmdb.org/t/p/w500/9XznF1gIXfgqzEs6La7vXMW46sM.jpg","it":"https://image.tmdb.org/t/p/w500/9XznF1gIXfgqzEs6La7vXMW46sM.jpg","es":"https://image.tmdb.org/t/p/w500/9XznF1gIXfgqzEs6La7vXMW46sM.jpg"}'::jsonb WHERE id = 220;
UPDATE public.films SET tmdb_id = 11620, titoli_i18n = '{"it":"Quo Vadis","fr":"Quo Vadis","es":"Quo Vadis","de":"Quo Vadis","en":"Quo Vadis"}'::jsonb, trame_i18n = '{"it":"Di ritorno dalle campagne militari, il comandante romano Marco Vinicio si innamora della cristiana Licia. Quando l''imperatore Nerone incendia Roma e accusa i cristiani, la coppia viene travolta dalle persecuzioni.","fr":"À Rome, le général Marcus Vinicius rencontre Lygia, une esclave, dont il tombe amoureux. Mais elle est chrétienne et ne veut rien avoir à faire avec un homme de guerre. Marcus la rachète pourtant à l''empereur Néron, mais elle s''échappe avec l''aide d''un ami. En la retrouvant, Marcus va apprendre à connaître les Chrétiens.","es":"Cuando regresa a Roma, después de tres años en el campo de batalla, el general Marco Vinicio se enamora de Lygia. Pero ella es cristiana y sus creencias le impiden enamorarse de un guerrero. Aunque fue adoptada por un general retirado, jurídicamente es una esclava de Roma. Pero Marco consigue que el emperador Nerón se la ceda en pago por sus servicios.","de":"Rom brennt. Nero spielt dazu auf der Leier. Das Christentum strebt empor.. Robert Taylor spielt den Kommandanten einer Legion, dessen Liebe zu einer christlichen Sklavin die Kluft zwischen Römischem Reich und der zutiefst im Glauben verwurzelten Religionsgemeinschaft überbrückt. Und über allem waltet Nero . Er ist Caesar, Verrückter, Mörder ein kaiserlicher Gebieter über die spektakuläre, dem Untergang geweihte Pracht, die Rom einst war.","en":"After fierce Roman commander Marcus Vinicius becomes infatuated with beautiful Christian hostage Lygia, he begins to question the tyrannical leadership of the despotic emperor Nero."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/5fU3X1zTK5fL5rfAHWfzi06STVN.jpg","fr":"https://image.tmdb.org/t/p/w500/gBDK3a9krq7iDJzFzq1g3avK4n8.jpg","es":"https://image.tmdb.org/t/p/w500/4O7Jb5jtoAttqzhZCSwicjAWrQw.jpg","de":"https://image.tmdb.org/t/p/w500/hMNtH77NvAAMtlEInbuxJ7OJO7m.jpg","en":"https://image.tmdb.org/t/p/w500/dqF1dattMNiwGjPSphu2VSi558Q.jpg"}'::jsonb WHERE id = 221;
UPDATE public.films SET tmdb_id = 77204, titoli_i18n = '{"fr":"Quo Vadis?","it":"Quo Vadis?","de":"Quo Vadis?","es":"Quo Vadis?","en":"Quo Vadis?"}'::jsonb, trame_i18n = '{"de":"Gelegen im Rom des Kaisers Nero, im Jahr 63 v. Chr., Gegen das römische Forum während der ersten Verfolgungen der ersten Christen. Die Geschichte dreht sich um den jungen Tribun Marcus Vinicius und seine Liebe zu Lygia, einem Bekehrten zum neuen Glauben.","es":"Primera versión televisiva, después de las cinco versiones cinematográficas, de la novela de Henryk Sienkiewicz.","en":"Drama about love and intrigues in ancient Rome during the times of Nero.","it":"Adattamento televisivo del capolavoro di Henryk Sienkiewicz che racconta l''ascesa del cristianesimo nella Roma imperiale e la deriva tirannica e folle di Nerone."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/4AD9VxrSItAjOUIdAkDwSD4xXDu.jpg","it":"https://image.tmdb.org/t/p/w500/4AD9VxrSItAjOUIdAkDwSD4xXDu.jpg","de":"https://image.tmdb.org/t/p/w500/4AD9VxrSItAjOUIdAkDwSD4xXDu.jpg","es":"https://image.tmdb.org/t/p/w500/4AD9VxrSItAjOUIdAkDwSD4xXDu.jpg","en":"https://image.tmdb.org/t/p/w500/4AD9VxrSItAjOUIdAkDwSD4xXDu.jpg"}'::jsonb WHERE id = 222;
UPDATE public.films SET tmdb_id = 59219, titoli_i18n = '{"es":"Quo Vadis","en":"Quo Vadis","it":"Quo Vadis","fr":"Quo Vadis","de":"Quo Vadis"}'::jsonb, trame_i18n = '{"es":"Siglo I d.C.. El oficial romano Marco Vinicio regresa de la guerra en Asia Menor y visita a su tío Petronio, amigo del emperador Nerón. Vinicio le confiesa que se ha enamorado de una joven misteriosa, Ligia, a quien ha conocido en la casa del general Aulus Plaucius. En una fiesta, Vinicio trata de aprovecharse de Ligia, pero su protector, el gigantesco Ursus, la saca de palacio y la lleva al lugar donde se reúnen los cristianos. Cuando Ligia es acusada de haber asesinado a la hija de Nerón, Vinicio la busca en las catacumbas. Pero la vida de los cristianos peligra al ser acusados de haber provocado el incendio de Roma, ordenado en realidad por el emperador.","en":"Ancient Rome, during the time of Emperor Nero. Vinicius, a young patrician, falls in love with the beautiful Lygia, the daughter of a Barbarian commander who was killed in battle, and wants her for his concubine. For Lygia, a Christian, being a pagan''s concubine is a severe sin and disgrace. However, when Vinicius is wounded, Lygia cares for him, and starts to reciprocate his feelings. Vinicius, in return, becomes interested in Christian learning and asks Apostle Peter to teach him. In the meantime, Emperor Nero accuses Christians of having started a great fire in Rome. He encourages the imprisonment, torture and murder of his Christian subjects.","fr":"Marcus Vinicius rencontre Lygia à Rome et en tombe amoureux. Mais Ligia est chrétienne et ne veut rien avoir à faire avec lui. Il décide de la kidnapper mais Ursus, son garde du corps l''en empêche. Lygia, l''apprenant, tombe à son tour sous le charme de Marcus mais celui-ci doit voir Néron. Après leur entretien, Marcus rentre chez. Mais il apprend que Néron est en train de brûler Rome et décide d''y retourner et de sauver Lygia.","de":"Im Zentrum der Handlung steht die sich entwickelnde Liebe eines römischen Patriziers zu einer christlichen Jungfrau vom Volk der Lygier (Gebiet des späteren Polen), die im Kontext grausamer Christenverfolgungen unter Kaiser Nero zur inneren Bekehrung und zur Taufe führt.","it":"Produzione polacca ad alto budget altamente fedele al romanzo originale, centrata sul contrasto tra la decadenza edonistica della Roma di Nerone e la nascente fede dei primi cristiani."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/rzePNmvU9Kczxu60TUoyzVED5xy.jpg","en":"https://image.tmdb.org/t/p/w500/rzePNmvU9Kczxu60TUoyzVED5xy.jpg","it":"https://image.tmdb.org/t/p/w500/rzePNmvU9Kczxu60TUoyzVED5xy.jpg","fr":"https://image.tmdb.org/t/p/w500/rzePNmvU9Kczxu60TUoyzVED5xy.jpg","de":"https://image.tmdb.org/t/p/w500/pDFO2YF2xetOd8bhmBrMpcDnbMK.jpg"}'::jsonb WHERE id = 223;
UPDATE public.films SET tmdb_id = 967, titoli_i18n = '{"en":"Spartacus","es":"Espartaco","de":"Spartacus","it":"Spartacus","fr":"Spartacus"}'::jsonb, trame_i18n = '{"en":"The rebellious Thracian Spartacus, born and raised a slave, is sold to Gladiator trainer Batiatus. After weeks of being trained to kill for the arena, Spartacus turns on his owners and leads the other slaves in rebellion. As the rebels move from town to town, their numbers swell as escaped slaves join their ranks. Under the leadership of Spartacus, they make their way to southern Italy, where they will cross the sea and return to their homes.","es":"Hacia el año 75 antes de Cristo, un esclavo llamado Espartaco es vendido a una escuela de gladiadores donde le adiestran para combatir en la arena de los circos romanos. Pronto, Espartaco lidera una rebelión por el maltrato sufrido.","de":"Die Gladiatoren von Capua kämpfen in der Arena auf Leben und Tod zur reinen Belustigung der römischen Herrscher. Die Exekutierung eines der Sklaven durch Prätor Crassus ist für den unerschrockenen Gladiator Spartacus das Zeichen zur Rebellion. Er fasst den wahnwitzigen Entschluss, mit der ihn liebenden Sklavin Varinia  und den Sklaven des Landes in ihre Heimatländer zurückzukehren. Spartacus formiert ein ganzes Heer, um in die Freiheit zu ziehen. Aber der machthungrige Crassus, der das Römische Imperium bedroht sieht, schickt seine Legionen gegen den Rebellen und seine Armee aus. Eine blutige Schlacht beginnt.","it":"Nel I secolo a.C., il gladiatore trace Spartaco guida una vasta ribellione di schiavi contro la Repubblica romana. Dopo aver sconfitto diverse legioni e radunato migliaia di seguaci in cerca di libertà, l''esercito dei ribelli si scontra con le ambizioni politiche del patrizio Marco Licinio Crasso, determinato a schiacciare la rivolta per consolidare il proprio potere su Roma.","fr":"Italie, 73 av. J.C. Esclave devenu gladiateur, Spartacus est épargné par un de ses compagnons d''infortune dans un combat à mort. Ce répit soulève en lui plus que jamais le souffle de la révolte, et après avoir brisé ses chaînes, il enjoint les autres esclaves à faire de même. Rapidement à la tête d''une colossale armée, Spartacus entend rejoindre le port de Brides au sud du pays pour prendre la mer à bord des navires ciliciens. Mais l''Empire romain ne l''entend pas de cette oreille et lance ses légions à la poursuite des esclaves révoltés…"}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/xLPpQlFWE12cbqNJQ5Vf4eJU8ij.jpg","es":"https://image.tmdb.org/t/p/w500/azXoEA108BvWjeKxIW9tfYlxY2I.jpg","de":"https://image.tmdb.org/t/p/w500/lCtMmNvW4VYIohi7UuVM30rl3xN.jpg","it":"https://image.tmdb.org/t/p/w500/lHxOu8Gp1urxHgtS4o0AywrniG1.jpg","fr":"https://image.tmdb.org/t/p/w500/7jIkNQenhZdiGRcwMk8w9KhwFi6.jpg"}'::jsonb WHERE id = 224;
UPDATE public.films SET tmdb_id = 616, titoli_i18n = '{"it":"L''ultimo samurai (The Last Samurai)","es":"El último samurái","en":"The Last Samurai","de":"Last Samurai","fr":"Le Dernier Samouraï"}'::jsonb, trame_i18n = '{"it":"Nel 1876 il veterano della guerra civile americana Nathan Algren viene assoldato dall''imperatore giapponese per addestrare il nuovo esercito secondo i metodi occidentali e sedare la ribellione guidata dal samurai Katsumoto. Catturato dai ribelli, Algren scopre il loro stile di vita e il codice d''onore dei samurai, finendo per abbracciare la loro causa contro la modernizzazione forzata e spietata del Paese.","es":"1870. El capitán Nathan Algren es un hombre a la deriva. Las batallas que libró en otro tiempo parecen ahora lejanas e inútiles. Una vez arriesgó su vida por el honor y por la patria, pero, en los años transcurridos desde la Guerra de Secesión estadounidense, el mundo ha cambiado. El pragmatismo ha reemplazado al valor, el interés personal ha ocupado el lugar del sacrificio y el honor no se encuentra en ninguna parte, especialmente en el Oeste, donde su papel en las campañas contra los indios acabó en desilusión y tristeza. En algún lugar de las implacables llanuras junto a la ribera del río Washita, Algren perdió su alma. En un mundo completamente distinto, otro soldado ve como su modo de vida está a punto de desintegrarse.","en":"Nathan Algren is an American hired to instruct the Japanese army in the ways of modern warfare, which finds him learning to respect the samurai and the honorable principles that rule them. Pressed to destroy the samurai''s way of life in the name of modernization and open trade, Algren decides to become an ultimate warrior himself and to fight for their right to exist.","de":"Der abgehalfterte US-Militär Captain Nathan Algren nimmt im Jahr 1875 den Auftrag an, die Armee des japanischen Kaisers auszubilden. Er soll die Truppe auf den Kampf gegen die alten Krieger des japanischen Kaiserreichs vorbereiten: den Kampf gegen die Samurai. Doch bereits im ersten Gefecht werden die Soldaten vernichtend geschlagen und Algren wird gefangen genommen. Schwer verletzt wird er in das Dorf des Anführers der Samurai Katsumoto gebracht. Er wird gesund gepflegt und lernt die Lebensweise der Samurai kennen. Wieder zurück in Tokio muss er sich entscheiden, auf welcher Seite er steht. Wird er mit den von Amerikanern geführten japanischen Soldaten kämpfen oder sich für die Seite der Samurai entscheiden?","fr":"En 1876, le capitaine Nathan Algren vit avec les souvenirs des batailles sanglantes menées contre les Sioux. Fort de son expérience au combat, il devient conseiller militaire pour le compte de l''empereur japonais soucieux d''ouvrir son pays aux traditions et au commerce occidentaux et d''éradiquer l''ancienne caste guerrière des samouraïs. Mais ceux-ci influent sur le capitaine Algren, qui se trouve bientôt pris entre deux feux, au cœur d''une confrontation entre deux époques et deux mondes avec, pour le guider, son sens de l''honneur."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/hHYbOZVogfOIVg4FEF2Hs2UUNHs.jpg","es":"https://image.tmdb.org/t/p/w500/DfwutbQodAsYxdqJu7Cme5jifC.jpg","en":"https://image.tmdb.org/t/p/w500/a8jmJPs5eZBARmnuEEvZwbjwyz4.jpg","de":"https://image.tmdb.org/t/p/w500/zxUiSv7gK4VLfCyU7quE9r5S0Qt.jpg","fr":"https://image.tmdb.org/t/p/w500/dJDLjVmBNMb13wZ6lXYwe6uscel.jpg"}'::jsonb WHERE id = 225;
UPDATE public.films SET tmdb_id = 70385, titoli_i18n = '{"de":"狼よ落日を斬れ","en":"The Last Samurai","es":"狼よ落日を斬れ","it":"L''ultimo samurai (Ôkami yo rakujitsu o)","fr":"Les derniers samouraïs"}'::jsonb, trame_i18n = '{"en":"The film follows the story of Sugi Toranosuke, a ronin, who returns to his home town of Edo many years after his attempted suicide as a sickly child. Rescued and adopted by a master swordsman, he has grown into a master swordsman and a very kind gentleman. The time is around 1868 the year that the nails were finally put into the coffin containing the feudal system that nurtured and sustained the samurai. Sugi is confused and unsure about what is happening but his teacher wants him out of the chaos of the multiple power struggles between the various clans.","fr":"A la fin du 19ème siècle, un samourai (Sugi Toranosuke), déchiré entre son dévouement pour un Shogun vieillissant et les conseils de son ancien professeur, entre finalement en guerre pour venger la mort de ce dernier.","it":"Durante il periodo del Bakumatsu e il declino dello shogunato Tokugawa, un maestro di spada fedele alla tradizione samurai si trova diviso tra amicizia, dovere e il turbine dei conflitti sanguinosi che segnano la nascita del Giappone moderno."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/o4WHApeJWxu3QVYRbDzg1cEtGfd.jpg","en":"https://image.tmdb.org/t/p/w500/wvLCXdOMbSRdxZErYvWYxLVZnAe.jpg","es":"https://image.tmdb.org/t/p/w500/o4WHApeJWxu3QVYRbDzg1cEtGfd.jpg","it":"https://image.tmdb.org/t/p/w500/o4WHApeJWxu3QVYRbDzg1cEtGfd.jpg","fr":"https://image.tmdb.org/t/p/w500/8NQRenOrzboAi0fPVACgAyVTPLg.jpg"}'::jsonb WHERE id = 226;
UPDATE public.films SET tmdb_id = 771, titoli_i18n = '{"en":"Home Alone","fr":"Maman, j''ai raté l''avion !","es":"Solo en casa","de":"Kevin - Allein zu Haus","it":"Mamma, ho perso l''aereo (Home Alone)"}'::jsonb, trame_i18n = '{"en":"Eight-year-old Kevin McCallister makes the most of the situation after his family unwittingly leaves him behind when they go on Christmas vacation. When thieves try to break into his home, he puts up a fight like no other.","fr":"La famille McCallister a décidé de passer les fêtes de Noël à Paris. Seulement Kate et Peter McCallister s''aperçoivent dans l''avion qu''il leur manque le plus jeune de leurs enfants, Kevin, âgé de 9 ans. D''abord désespéré, Kevin reprend vite les choses en main et s''organise pour vivre le mieux possible. Quand deux cambrioleurs choisissent sa maison pour commettre leurs méfaits.","es":"Kevin McAllister es un niño de ocho años, miembro de una familia numerosa, que accidentalmente se queda abandonado en su casa cuando toda la familia se marcha a pasar las vacaciones a Francia. Kevin aprende a valerse por sí mismo e incluso a protegerse de Harry y Marv, dos bribones que se proponen asaltar todas las casas cerradas de su vecindario. Cuando su madre Kate lo hecha en falta, realiza un pintoresco viaje de vuelta contra reloj a Chicago para recuperar a su hijo.","de":"Schon lange hat die Familie McCallister den Urlaub in Europa geplant, und alle sind bereit, am nächsten Morgen endlich loszufliegen. Doch leider verschlafen alle, und alles wird sehr hektisch und unübersichtlich, weil sie das Flugzeug nicht verpassen wollen. Irgendwo über dem Atlantik stellen sie fest, dass sie Kevin, den jüngsten Sohn der Familie, zu Hause vergessen haben. Und der muss nun alleine klar kommen, und das Haus gegen Einbrecher und böse Nachbarn verteidigen.","it":"Il piccolo Kevin McCallister viene sbadatamente dimenticato a casa dalla famiglia in partenza per le vacanze di Natale a Parigi. Rimasto solo, deve difendere la propria abitazione da due maldestri ladri d''appartamento usando ingegnose trappole."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/onTSipZ8R3bliBdKfPtsDuHTdlL.jpg","fr":"https://image.tmdb.org/t/p/w500/7hvfmQ5zgwoxZZOHQ9uGMdIk43t.jpg","es":"https://image.tmdb.org/t/p/w500/rjc2a9N5pro1xGsSvvnJ1JDXRGm.jpg","de":"https://image.tmdb.org/t/p/w500/8PuMnVXP1l0mDh5b7CeHESodMjT.jpg","it":"https://image.tmdb.org/t/p/w500/aQdJ8Q4CEUq55DTcBjItOyqMhTd.jpg"}'::jsonb WHERE id = 227;
UPDATE public.films SET tmdb_id = 772, titoli_i18n = '{"it":"Mamma, ho riperso l''aereo - Mi sono smarrito a New York (Home Alone 2: Lost in New York)","en":"Home Alone 2: Lost in New York","fr":"Maman, j''ai encore raté l''avion !","de":"Kevin - Allein in New York","es":"Solo en casa 2: Perdido en Nueva York"}'::jsonb, trame_i18n = '{"it":"Durante la confusione dell''imbarco per le vacanze natalizie in Florida, Kevin si imbarca per errore su un volo diretto a New York. Nella grande mela si ritroverà ad affrontare nuovamente i ladri Harry e Marv, evasi nel frattempo dal carcere.","en":"Instead of flying to Florida with his folks, Kevin ends up alone in New York, where he gets a hotel room with his dad''s credit card—despite problems from a clerk and meddling bellboy. But when Kevin runs into his old nemeses, the Wet Bandits, he''s determined to foil their plans to rob a toy store on Christmas Eve.","fr":"Après Paris, c''est à Miami que la tribu McCallister décide de passer les fêtes de Noël. À l''aube du jour J, toute la famille est sur le pied de guerre et file a l''aéroport en prenant bien garde de ne pas oublier Kevin. Mais celui-ci s''éclipse pour acheter des piles pour son walkman, il ne retrouve plus les siens et s''embarque par mégarde pour New York...","de":"Und wieder ist Weihnachten bei der Familie McCallister, wieder ist Ferienstimmung angesagt – diesmal soll’s ins sonnige Florida gehen. Aus den Erfahrungen des chaotischen letzten Jahres hat man gelernt; diesmal kann alles verlorengehen – wenn nur Kevin mit am Flughafen ist. Doch es kommt, wie es kommen muß: Die Familie sitzt in der Maschine nach Florida und Kevin gerät auf den Flieger in die Stadt mit der Statue. Das ist ein Heidenspaß für den liebenswerten frechen Bengel, denn New York ist eben immer noch DIE Stadt überhaupt. Eine schöne Bescherung für den kleinen Kevin – wenn da nicht die “nassen Banditen” wären, die ausgerechnet zur gleichen Zeit ihr unfreiwilliges Zuhause verlassen haben, um in der Stadt der Städte ihr neues, fieses Glück zu suchen. Und die beiden sind noch immer mächtig sauer auf den gewitzten Jungen aus Chicago.","es":"En plenas fiestas navideñas, el pequeño Kevin y su familia están a punto de coger un avión para disfrutar de unas pequeñas vacaciones, pero Kevin se equivoca y embarca en un avión que lo lleva a Nueva York, donde vuelve a encontrarse solo y desprotegido."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/eYKQJmrEyANdUcE7nJ7PQ6XARaO.jpg","en":"https://image.tmdb.org/t/p/w500/uuitWHpJwxD1wruFl2nZHIb4UGN.jpg","fr":"https://image.tmdb.org/t/p/w500/gFhf8NwvEKCbNIOQZxLqj1i5DMy.jpg","de":"https://image.tmdb.org/t/p/w500/y9smOLUhE5JOBjbmnESm6orPrf5.jpg","es":"https://image.tmdb.org/t/p/w500/7sdiRUyc0ANHJptPhsgb1KL6hoq.jpg"}'::jsonb WHERE id = 228;
UPDATE public.films SET tmdb_id = 9714, titoli_i18n = '{"es":"Solo en casa 3","it":"Mamma, ho preso il morbillo (Home Alone 3)","de":"Wieder allein zu Haus","en":"Home Alone 3","fr":"Maman, je m''occupe des méchants !"}'::jsonb, trame_i18n = '{"es":"Cuatro espías de alta tecnología industrial roban un microchip ultrasecreto y confiadamente lo ocultan en un coche de juguete de control remoto. Por causa de una confusión de equipajes en el aeropuerto, la anciana señora Hess recoge el juguete y se lo regala a su vecino de ocho años Alex. Los espías desearán recuperar el valioso chip a toda costa, pero Alex está preparado para darles una cálida bienvenida.","it":"Il piccolo Alex è costretto a rimanere a casa con il morbillo. Si troverà a dover affrontare quattro pericolosi criminali internazionali intenzionati a recuperare un prezioso microchip militare nascosto all''interno di un''auto radiocomandata finita per sbaglio nelle sue mani.","de":"Vier High-Tech-Industrie-Spione schmieden einen scheinbar brillanten Plan: Beaupre, Alice, Jernigan und Unger stehlen einen neuartigen und streng geheimen Mikrochip, den ein Unternehmen aus dem Silicon Valley entworfen hat, um eine für den Radar nicht sichtbare Rakete zu steuern. Um an den Sicherheitskontrollen am Flughafen vorbeizukommen, verstecken die Ganoven den Chip in einem Spielzeugauto. Doch natürlich läuft nicht alles nach Plan. Durch eine Verwechslung an der Gepäckausgabe kommt Mrs. Hess in den Besitz des Autos. Die ältere Dame verschenkt das Spielzeug an den Nachbarsjungen Alex. Der hütet gerade das Bett: Windpocken! Während seine Eltern in der Arbeit und seine Geschwister in der Schule sind, ist der Achtjährige also ganz allein zu Haus. Einfaches Spiel für Beaupre und seine Bande, die nur in das Haus einbrechen und das Spielzeugauto an sich nehmen müssen. Oder vielleicht auch nicht. Denn Alex ist gut gerüstet für den unliebsamen Besuch…","en":"9-year-old Alex Pruitt is home alone with the chicken pox. Turns out, due to a mix-up among nefarious spies, Alex was given a toy car concealing a top-secret microchip. Now Alex must fend off the spies as they try to break into his house to get it back.","fr":"De dangereux trafiquants prennent livraison à Hong Kong d''un microprocesseur à usage militaire et le dissimulent dans un jouet électronique. À l''aéroport, Mrs Hess prend par erreur le sac contenant le jouet. Les malfrats retrouvent sa trace dans la banlieue de Chicago, mais faute de connaître son nom, s''installent dans sa rue et visitent chaque maison. Mrs Hess a offert le jouet à son petit voisin, Alex, précoce et déluré, qui ne tarde pas à remarquer le manège des gangsters."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/720eeviFT6G8SStX2lEgFsYzqAp.jpg","it":"https://image.tmdb.org/t/p/w500/s1PwvbnNicaxT6wdlMZJqrW0yQt.jpg","de":"https://image.tmdb.org/t/p/w500/eTSyZeH2TEIkqxuozZmf0KPNqCt.jpg","en":"https://image.tmdb.org/t/p/w500/6uOadrCfle0n2LOOxHbgWEdnrm2.jpg","fr":"https://image.tmdb.org/t/p/w500/jFlRBtxKgogQso43nC7t65gJeNS.jpg"}'::jsonb WHERE id = 229;
UPDATE public.films SET tmdb_id = 12536, titoli_i18n = '{"it":"Mamma, ho allagato la casa (Home Alone 4: Taking Back the House)","en":"Home Alone 4","fr":"Maman, je suis seul contre tous","es":"Solo en casa 4","de":"Kevin - Allein gegen alle"}'::jsonb, trame_i18n = '{"it":"Kevin McCallister trascorre il Natale nella villa super tecnologica della nuova fidanzata del padre. Lì dovrà impedire il rapimento di un giovane principe da parte del suo vecchio nemico Marv e della sua nuova complice.","en":"Kevin McCallister''s parents have split up. Now living with his mom, he decides to spend Christmas with his dad at the mansion of his father''s rich girlfriend, Natalie. Meanwhile robber Marv Merchants, one of the villains from the first two movies, partners up with a new criminal named Vera to hit Natalie''s mansion.","fr":"Maintenant que ses parents sont séparés, Kevin doit passer ses vacances avec son père chez la petite amie de celui-ci qui vit dans un véritable palace bourré d''une tonne de gadgets derniers cris. Mais il est loin de se douter qu''il devra mener une véritable guerre éclair pour déjouer le plan de dangereux malfaiteurs !","es":"Después del reciente divorcio de sus padres, Kevin decide pasar la Navidad en casa de Natalie, la nueva novia de su padre, una casa equipada con la más moderna tecnología. Con la ayuda de esta tecnología y haciendo uso de su habitual ingenio, Kevin deberá hacer frente a unos ladrones, además de intentar conseguir que sus progenitores se reconcilien. Nueva entrega de la popular saga de \"Solo en casa\", que en esta ocasión, y tras perder progresivamente calidad y taquilla en las anteriores, ya se hizo directamente para la televisión y el mercado de video.","de":"Kevin will das Weihnachtsfest bei seinem Vater verbringen, der seit der Trennung von Kevins Mutter Kate mit der deutlich jüngeren Nathalie zusammenlebt. Deswegen macht sich Kevin auf den Weg und kommt dabei prompt dem Gaunerpärchen Marv und Vera auf die Schliche, das die Entführung zweier Kinder aus wohlhabendem Hause plant. Das Verbrechen soll bei Nathalie über die Bühne gehen. Natürlich kann der clevere Kevin das nicht zulassen und er heckt einen ausgefeilten Plan aus, wie er in Nathalies High-Tech-Haus, die beiden Gangster vertreiben kann. Da Marv und Vera nicht mit dem Einfallsreichtum und der Sturheit eines Kindes wie Kevin gerechnet haben, beginnt eine abenteuerliche Nacht, in der sich ein Kind gegen Kriminelle behaupten muss…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/zfm0UYbIpOpL8ak9tf655h3GWS2.jpg","en":"https://image.tmdb.org/t/p/w500/qRktvMOO2QaCL7gvNyvZDoxPOZj.jpg","fr":"https://image.tmdb.org/t/p/w500/5Qyhmdw7qv19J81C3mjsIb74HaR.jpg","es":"https://image.tmdb.org/t/p/w500/q9BAc2Q37oQWcRlMKUkuRilJ90E.jpg","de":"https://image.tmdb.org/t/p/w500/rno49zdgQzQWK6AhrwWfrhX1vAT.jpg"}'::jsonb WHERE id = 230;
UPDATE public.films SET tmdb_id = 134375, titoli_i18n = '{"it":"Mamma, ho visto i fantasmi! (Home Alone: The Holiday Heist)","fr":"Maman, la maison est hantée !","en":"Home Alone: The Holiday Heist","es":"Solo en casa 5","de":"Allein zu Haus: Der Weihnachts-Coup"}'::jsonb, trame_i18n = '{"it":"Finn si trasferisce con la famiglia in una nuova casa nel Maine che crede infestata dai fantasmi. Quando i genitori rimangono bloccati fuori città, Finn deve proteggere la dimora da una banda di tre ladri d''arte a caccia di un dipinto dal valore inestimabile.","fr":"Les Baxter ont quitté la Californie pour s''installer dans le Maine. Alors que Finn, 10 ans, apprend à composer avec le rude climat local, il se persuade que sa nouvelle maison est hantée par le fantôme d''un gangster. Déterminé à le capturer, il truffe la demeure de dispositifs divers.","en":"10-year-old Finn is terrified to learn his family is relocating from sunny California to Maine in the scariest house he has ever seen! Convinced that his new house is haunted, Finn sets up a series of elaborate traps to catch the “ghost” in action. Left home alone with his sister while their parents are stranded across town, Finn’s traps catch a new target – a group of thieves who have targeted Finn’s house.","es":"Finn Baxter y su familia se mudan de California a Maine a su nueva casa. Finn está aterrorizado y cree que la casa está embrujada. Mientras que instala trampas para coger al \"fantasma\", sus padres se quedan varados en la ciudad y Finn se quedá solo en casa con su hermana. Lo que no esperaban, es que su casa se convierte en el objetivo de tres ladrones en busca de un botín especial. (FILMAFFINITY)","de":"Nach dem Umzug seiner Familie aus dem sonnigen Kalifornien in ein altes Haus in Maine ist der 8-jährige Finn (Christian Martyn) überzeugt, dass es in dem Haus spukt. Deshalb baut er einige Fallen für die Gespenster. Die erweisen sich als äußerst hilfreich, als an Weihnachten ein paar Diebe in das Haus eindringen, während Finns Eltern am anderen Ende der Stadt festhängen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/nsRl6M33UjKNpHDIRoGW81WX89H.jpg","fr":"https://image.tmdb.org/t/p/w500/88gvFNRRBiAeD9CeOBnVbbdjcXJ.jpg","en":"https://image.tmdb.org/t/p/w500/aP6NPJeiv30d82lZF1baZ3qRBcZ.jpg","es":"https://image.tmdb.org/t/p/w500/nxxcHTbqNrEkrJvtCzxzm3TDtU.jpg","de":"https://image.tmdb.org/t/p/w500/ggMiHskombbsOiUJGY9E2KrNsw1.jpg"}'::jsonb WHERE id = 231;
UPDATE public.films SET tmdb_id = 654974, titoli_i18n = '{"it":"Home Sweet Home Alone - Mamma, ho perso l''aereo (Home Sweet Home Alone)","fr":"Maman, j’ai raté l’avion ! (Ça recommence)","en":"Home Sweet Home Alone","es":"Por fin solo en casa","de":"Nicht schon wieder allein zu Haus"}'::jsonb, trame_i18n = '{"it":"Il giovanissimo Max Mercer viene accidentalmente lasciato a casa da solo quando la sua famiglia parte per il Giappone. Deve proteggere la sua abitazione da una coppia di coniugi in difficoltà finanziarie che tenta di recuperare un prezioso cimelio di famiglia.","fr":"Max Mercer, dix ans, se retrouve tout seul chez lui quand sa famille part en vacances au Japon en l''oubliant. Alors qu''un couple obsédé par un précieux héritage a sa maison dans le collimateur, Max doit la protéger contre ces intrus… et il ne reculera devant rien pour leur en interdire l''entrée.","en":"After being left at home by himself for the holidays, 10-year-old Max Mercer must work to defend his home from a married couple who tries to steal back a valuable heirloom.","es":"Max Mercer tiene 10 años. Su familia se ha ido a Japón a pasar las Navidades y se ha olvidado de él en casa. Cuando una pareja que quiere recuperar un valioso tesoro familiar decide meterse en su casa, Max tiene que protegerla de los intrusos. Y hará lo que sea para que no entren.","de":"Der 10-jährige Max Mercer bleibt aus Versehen zurück, als seine Familie über Weihnachten nach Japan in den Urlaub fliegt. Als ein Ehepaar, das ein kostbares Erbstück sucht, sein Zuhause ins Visier nimmt, liegt es an Max, es vor den Eindringlingen zu schützen... Und er wird alles tun, was nötig ist, damit sie auf keinen Fall hineinkommen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/jdMU0YJC5jTEI95iALzGm6qPis0.jpg","fr":"https://image.tmdb.org/t/p/w500/pm9IBLHOClAjlPi8O1bvpU9lUtO.jpg","en":"https://image.tmdb.org/t/p/w500/fP3VvqUjEBjawxZHL4sYCq2ZdJD.jpg","es":"https://image.tmdb.org/t/p/w500/5K7qxX77PJXWuzkZD8rOBduCEKo.jpg","de":"https://image.tmdb.org/t/p/w500/2q4w8c7q0lyTGU8omBiFWnM9pny.jpg"}'::jsonb WHERE id = 232;
UPDATE public.films SET tmdb_id = 576845, titoli_i18n = '{"it":"Ultima notte a Soho","en":"Last Night in Soho","fr":"Last Night in Soho","de":"Last Night in Soho","es":"Última noche en el Soho"}'::jsonb, trame_i18n = '{"it":"Eloise, ventenne cresciuta con la nonna dopo il suicidio della madre, arriva a Londra con il sogno di diventare stilista. Ha il mito della Swingin'' London e della musica anni ''60, che ascolta continuamente su vecchi 33 giri portatili. Dopo un''infelice esperienza nello studentato della scuola di moda in cui è stata ammessa, si trasferisce in un appartamento di Soho affittato da un''anziana signora. Qui, durante lunghe notti agitate, Eloise sogna di tornare nel passato, nella Londra che ama di più, dove incontra Sandie, un''aspirante cantante che vive il glamour di una città colorata ed esaltante. Poco alla volta, però, Eloise confonde la propria personalità con quella di Sandie e ne scopre la vita in realtà miserabile, scivolando tra realtà e incubo in un''esperienza spaventosa.","en":"A young girl, passionate about fashion design, is mysteriously able to enter the 1960s where she encounters her idol, a dazzling wannabe singer. But 1960s London is not what it seems, and time seems to be falling apart with shady consequences.","fr":"L’histoire d’une jeune femme passionnée de mode et de design qui parvient mystérieusement à retourner dans les années 60 où elle rencontre son idole, une éblouissante jeune star montante. Mais le Londres des années 60 n’est pas ce qu’il paraît, et le temps semble se désagréger entraînant de sombres répercussions.","de":"Die behütete Eloise zieht nach London, um Mode zu studieren. Dort träumt sie sich immer öfter in den glitzernden Szenebezirk Soho der Swinging Sixties, wobei Traum und Realität verschwimmen. Doch der Schein trügt und die Zeit scheint aus den Fugen zu geraten - mit düsteren Folgen.","es":"Thriller psicológico sobre una joven apasionada por la moda que misteriosamente puede entrar en la década de 1960, donde se encuentra con su ídolo, un atractivo aspirante a cantante. Pero el Londres de los sesenta no es lo que parece, y el tiempo comenzará a desmoronarse con sombrías consecuencias."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/mNuXKuiywifooo8LnAzMy0W4ZiK.jpg","en":"https://image.tmdb.org/t/p/w500/n1ZRmjlk1BJTY7aASqACfPAaLn2.jpg","fr":"https://image.tmdb.org/t/p/w500/v6qAIxWYIUiid71YPWjnVOZ4U6K.jpg","de":"https://image.tmdb.org/t/p/w500/azdy7STEzLAyrhzeKZfl15jZYMN.jpg","es":"https://image.tmdb.org/t/p/w500/4eSJJsBZ00qMyoWLe98ulNGvGbC.jpg"}'::jsonb WHERE id = 234;
UPDATE public.films SET tmdb_id = 16699, titoli_i18n = '{"it":"Mamma ho perso il lavoro","en":"Smother","fr":"Smother","es":"La madre de él","de":"Das Muttersöhnchen"}'::jsonb, trame_i18n = '{"en":"After he''s fired from his job, an everyday guy faces pressure from his wife to have a baby and from his mom, who has decided to move in with the young couple.","es":"Cuando lo despiden de su trabajo como fisioterapeuta, Noah Cooper piensa que no puede ocurrirle nada peor. Pero se equivoca. Al llegar a casa, su ya abarrotado hogar se vuelve aún más caótico con la presencia de Marilyn, su dominante madre, que busca un lugar donde refugiarse y que, además, trae consigo a sus cinco perros. A partir de ese momento, Noah deberá aprender a soportar la presión que implica buscar trabajo, que su mujer busque desesperadamente un hijo; y lo que es peor: que su madre no quiera pasar ni un minuto lejos de él.","de":"Chaotische Verwirrungen sind vorprogrammiert: Noah verliert seinen Job, seine Frau Clare will endlich ein Kind und hat gerade ihre fruchtbaren Tage und Noahs Mutter Marilyn verdächtigt ihren Gatten der Untreue - woraufhin sie kurzerhand bei Noah und Clare einzieht. Eine Mischung, die schnell zur Explosion führt...","it":"After he''s fired from his job, an everyday guy faces pressure from his wife to have a baby and from his mom, who has decided to move in with the young couple."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/2vLLJG71kmrCcTbnIztn13NHKZF.jpg","en":"https://image.tmdb.org/t/p/w500/2vLLJG71kmrCcTbnIztn13NHKZF.jpg","fr":"https://image.tmdb.org/t/p/w500/2vLLJG71kmrCcTbnIztn13NHKZF.jpg","es":"https://image.tmdb.org/t/p/w500/czM99MpudQceBxcowaTGbvlhUtm.jpg","de":"https://image.tmdb.org/t/p/w500/2vLLJG71kmrCcTbnIztn13NHKZF.jpg"}'::jsonb WHERE id = 235;
UPDATE public.films SET tmdb_id = 63, titoli_i18n = '{"it":"L''esercito delle 12 scimmie","en":"Twelve Monkeys","es":"12 monos","fr":"L''Armée des 12 singes","de":"12 Monkeys"}'::jsonb, trame_i18n = '{"it":"L''Esercito delle 12 scimmie è un piccolo gioiellino fantascientifico del 1995 che si focalizza sulla disperazione di un singolo uomo, condannato a essere il prescelto per trovare un rimedio alla situazione disastrosa dell''umanità, in un futuro ormai abitato da una razza umana rassegnata. Nel 2035 gli esseri umani vivono nel sottosuolo, terrorizzati dall''ambiente esterno, portatore di un virus mortale che li ha decimati, rendendo il pianeta Terra un luogo dove i prigionieri sono diventati loro stessi. Anche se solo in modo approssimativo, gli scienziati di quel terribile futuro hanno reso possibile il viaggio nel tempo, unica possibilità per poter mettere le mani sul virus e crearne una cura.","en":"In the year 2035, convict James Cole reluctantly volunteers to be sent back in time to discover the origin of a deadly virus that wiped out nearly all of the earth''s population and forced the survivors into underground communities. But when Cole is mistakenly sent to 1990 instead of 1996, he''s arrested and locked up in a mental hospital. There he meets psychiatrist Dr. Kathryn Railly and the son of a famous virus expert who may hold the key to the Army of the 12 Monkeys; thought to be responsible for unleashing the killer disease.","es":"En el año 2035, un virus mortal ha arrasado la humanidad y los supervivientes viven bajo tierra. Un convicto llamado James Cole se ofrece como voluntario para viajar al pasado y averiguar el origen de la plaga. Su misión es encontrar al ''Ejército de los Doce Monos'', una organización terrorista que se cree que liberó el virus. Sin embargo, su viaje se complica por los errores temporales, las visiones recurrentes y la duda sobre su propia cordura. Con la ayuda de una psiquiatra llamada Kathryn Railly y un loco llamado Jeffrey Goines, Cole intenta salvar el futuro antes de que sea demasiado tarde.","fr":"Nous sommes en l’an 2035. Les quelques milliers d’habitants qui restent sur notre planète sont contraints de vivre sous terre. La surface du globe est devenue inhabitable à la suite d’un virus ayant décimé 99 % de la population. Les survivants mettent tous leurs espoirs dans un voyage à travers le temps pour découvrir les causes de la catastrophe et la prévenir. C’est James Cole, hanté depuis des années par une image incompréhensible, qui est désigné pour cette mission.","de":"Das Jahr 2035: Die Erdoberfläche ist entvölkert, seit eine Virenepidemie die Menschheit 1996 fast gänzlich vernichtet hat. Die wenigen Überlebenden existieren in einem Unterwelt-System. Mit der Hoffnung auf ein besseres Leben schickt man den Sträfling Cole als Zeitboten ins Jahr der Katastrophe zurück, um den Ursprung der Apokalypse herauszufinden. Versehentlich gerät er zunächst ins Jahr 1990 und in eine Irrenanstalt. Dort warnt ihn der verwirrte Jeffrey vor den \"12 Monkeys\". Haben sie mit den Viren zu tun? Endlich im Jahr 1996, spürt Cole mit der Psychiaterin Kathryn diese Vereinigung auf und macht eine verblüffende Entdeckung..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/9WfkdEGHO8K0AF8ahbc34zMzM4e.jpg","en":"https://image.tmdb.org/t/p/w500/gt3iyguaCIw8DpQZI1LIN5TohM2.jpg","es":"https://image.tmdb.org/t/p/w500/bXLwKCCMS2NCNlxAhSwn9HCymRl.jpg","fr":"https://image.tmdb.org/t/p/w500/pJ0EtnTbJyHf9XCqeiuAy3HK9Ij.jpg","de":"https://image.tmdb.org/t/p/w500/l872D4V4sl13A8UOZRUk5TMSRV6.jpg"}'::jsonb WHERE id = 236;
UPDATE public.films SET tmdb_id = 9552, titoli_i18n = '{"en":"The Exorcist","es":"El exorcista","it":"L''esorcista","de":"Der Exorzist","fr":"L''Exorciste"}'::jsonb, trame_i18n = '{"en":"When a mysterious entity possesses a young girl, her mother seeks the help of two Catholic priests to save her life.","es":"Regan es una niña de doce años víctima de fenómenos paranormales como la levitación o la manifestación de una fuerza sobrehumana. Su madre, aterrorizada, tras someter a su hija a múltiples análisis médicos que no ofrecen ningún resultado, acude a un sacerdote con estudios de psiquiatría. Éste está convencido de que el mal no es físico sino espiritual, es decir, que la niña es víctima de una posesión diabólica. Por eso, con la ayuda de otro sacerdote decide practicar un exorcismo.","it":"In un quartiere tranquillo, in una casa dotata di tutti i moderni comfort, una ragazzina modello cade ammalata. La madre non può aiutarla. I medici non riescono ad elaborare una diagnosi. Temendo che le crisi di cui soffre la figlia non riguardino solo la sfera fisica, ma anche quella spirituale, la donna si rivolge a un sacerdote. L''uomo però dubita della presenza del diavolo in quella casa, in quel corpo e la debolezza delle sue convinzioni non farà altro che rendere più forte il maligno.","de":"Regan MacNeill, zwölfjährige Tochter der berühmten Filmschauspielerin Chris MacNeill, leidet seit kurzem unter hysterischen, von heftigen Krämpfen begleiteten Wutausbrüchen. Als die versammelte, hochdotierte Ärzteschar Hilflosigkeit demonstriert und die Anfälle eskalieren, sucht Mutter MacNeill die Hilfe katholischer Geistlicher. Zwei herbeieilende Jesuitenpater diagnostizieren teuflische Besessenheit und verschreiben dem Teenager einen klassischen Exorzismus. Der alte Kampf zwischen Gut und Böse entbricht.","fr":"Regan, une adolescente, présente depuis quelque temps d’étranges symptômes. Après avoir épuisé les solutions médicales, la mère de Regan consulte un prêtre-psychiatre qui est rapidement convaincu que Regan est possédée et que seul un exorcisme pourra la \"guérir\"."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/5x0CeVHJI8tcDx8tUUwYHQSNILq.jpg","es":"https://image.tmdb.org/t/p/w500/hwJvgHQ4tf9eRQec1ouAgg33dPV.jpg","it":"https://image.tmdb.org/t/p/w500/49uIBJqG4ugL7KC2yBhz0nCLeHG.jpg","de":"https://image.tmdb.org/t/p/w500/x7pwEqdrKJ7dO5qIk9bdihubC0I.jpg","fr":"https://image.tmdb.org/t/p/w500/zApG4BHUfOsCbNcPfyHk6cKDboI.jpg"}'::jsonb WHERE id = 238;
UPDATE public.films SET tmdb_id = 948, titoli_i18n = '{"it":"Halloween - La notte delle streghe","en":"Halloween","fr":"La Nuit des masques","es":"La noche de Halloween","de":"Halloween - Die Nacht des Grauens"}'::jsonb, trame_i18n = '{"it":"Micheal, a soli 6 anni ammazza la sorella e viene internato ma dopo 15 anni fugge per recarsi al suo paese. E'' il 31 Ottobre, e secondo l''antica tradizione americana è la notte in cui si esorcizzano le streghe, grazie a questa concomitanza Micheal può mietere altre vittime.","en":"Fifteen years after murdering his sister on Halloween Night 1963, Michael Myers escapes from a mental hospital and returns to the small town of Haddonfield, Illinois to kill again.","fr":"Il y a 15 ans, dans une petite ville des États-Unis, le soir d’Halloween, au cours de laquelle les enfants ont l’habitude de se déguiser, un petit garçon, Michael, épie sa sœur et son ami qui flirtent. Michael les suit et, armé d’un couteau de cuisine, assassine la jeune fille. Quinze ans plus tard, un psychiatre, le docteur Loomis qui étudie le cas du jeune meurtrier apprend que le criminel s’est échappé : il est revenu sur les lieux de son crime pour continuer son œuvre…","es":"Durante la noche de Halloween, Michael, un niño de seis años, asesina a su familia con un cuchillo de cocina. Es internado en un psiquiátrico del que huye quince años más tarde, precisamente la víspera de Halloween. El psicópata vuelve a su pueblo y comete una serie de asesinatos. Mientras, uno de los médicos del psiquiátrico le sigue la pista.","de":"1963, Halloween-Nacht im Kaff Haddonfield: Die Teenagerin Judith Myers wird in ihrem Elternhaus von ihrem sechsjährigen Bruder brutal erstochen - Michael Myers hat das erste Mal zugeschlagen! Der Junge kommt daraufhin in das Smith’s Grove Warren County Sanatorium in die Obhut von Psychiater Sam Loomis. Schon bald ist dieser davon überzeugt, dass sich in der Gestalt des Kindes das absolut Böse verbirgt. 15 Jahre danach, am Vorabend von Halloween, gelingt Michael die Flucht aus der Heilanstalt. Der maskierte Killer macht sich auf den Weg nach Haddonfield, wo sich arglose Teenager wie Laurie Strode auf ein bisschen Horrorspaß freuen..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/uxLqrN38fSQEUVpM4S1suhnW3X.jpg","en":"https://image.tmdb.org/t/p/w500/wijlZ3HaYMvlDTPqJoTCWKFkCPU.jpg","fr":"https://image.tmdb.org/t/p/w500/r1ME6ZFxmZ6vFYqt9PHepiIb1t.jpg","es":"https://image.tmdb.org/t/p/w500/6bsDpDL312h6vEGPOPWoweaZWUG.jpg","de":"https://image.tmdb.org/t/p/w500/mWm1FkerRpBFyaYtvcAMMTjz38o.jpg"}'::jsonb WHERE id = 239;
UPDATE public.films SET tmdb_id = 346364, titoli_i18n = '{"en":"It","es":"It (Eso)","fr":"Ça","de":"Es","it":"It - Capitolo uno"}'::jsonb, trame_i18n = '{"en":"In a small town in Maine, seven children known as The Losers Club come face to face with life problems, bullies and a monster that takes the shape of a clown called Pennywise.","es":"Remake del clásico de Stephen King en el que un payaso aterroriza a los niños de un vecindario. En un pequeño pueblo de Maine, siete niños conocidos como el Club de los Perdedores se encuentran cara a cara con problemas de la vida, matones y un monstruo que toma la forma de un payaso llamado Pennywise.","fr":"À Derry, dans le Maine, aux États-Unis, 7 gamins, ayant du mal à s’intégrer, se sont regroupés au sein du Club des Ratés. Rejetés par leurs camarades, ils sont les cibles favorites des gros durs de l’école. Ils ont aussi en commun d’avoir éprouvé leur plus grande terreur face à un terrible prédateur métamorphe qu’ils appellent Ça…","de":"Die Freunde Stanley Uris, Richie Tozier, Mike Hanlon, Bill Denbrough Beverly Marsh, Eddie Kaspbrak und Ben Hanscom leben in einer Stadt namens Derry, in der immer wieder Menschen verschwinden – sowohl Erwachsene als auch vor allem Minderjährige. Schließlich erfahren die Kinder, die sich selbst auch den „Klub der Verlierer“ nennen, von einer interdimensionalen Kreatur, die Jagd auf Menschen macht und sich in die schlimmsten Alpträume ihrer Opfer verwandeln kann. Meistens tritt das Biest jedoch in Form des sadistischen Clowns Pennywise  auf. Die Kinder schwören die Kreatur zu vernichten und kehren als Erwachsene in ihre Heimatstadt zurück, in der Pennywise erneut aufgetaucht ist.","it":"Ottobre 1988, nella cittadina di Derry. Il piccolo Georgie esce di casa nella pioggia per far navigare la barchetta di carta preparatagli dal fratello maggiore Billy, costretto a casa dall''influenza. La barchetta scorre per i rivoli lungo i marciapiedi, ma finisce in uno scolo che conduce alla rete fognaria. Georgie, contrariato, si china a guardare nella feritoia e incontra lo sguardo del bizzarro clown che abita nelle fogne, Pennywise. Per quanto strano sia trovare un clown in quel luogo, Georgie si intrattiene con lui sin quando il clown non lo addenta e lo cattura portandolo giù con sé. Giugno 1989. A Derry vige il coprifuoco a causa delle numerose sparizioni di persone, soprattutto bambini."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/9E2y5Q7WlCVNEhP5GiVTjhEhx1o.jpg","es":"https://image.tmdb.org/t/p/w500/sSrj4lnhrb113DOPEPTaO2jaDk3.jpg","fr":"https://image.tmdb.org/t/p/w500/3SUz0F0I2Bodcj9Ev2pYSWnE9zp.jpg","de":"https://image.tmdb.org/t/p/w500/xrqfuDX1Ei4gdjcpYPufTWjBcVN.jpg","it":"https://image.tmdb.org/t/p/w500/ru0gDnxKzBjzrPxfRyZIuse9hfu.jpg"}'::jsonb WHERE id = 240;
UPDATE public.films SET tmdb_id = 601, titoli_i18n = '{"it":"E.T. l''extra-terrestre","en":"E.T. the Extra-Terrestrial","fr":"E.T. l''extra-terrestre","de":"E.T. – Der Außerirdische","es":"E.T., el extraterrestre"}'::jsonb, trame_i18n = '{"it":"Durante un sopralluogo sulla Terra per raccogliere vegetali, un gruppo di alieni viene sorpreso e uno di loro viene lasciato erroneamente al suolo per l''affrettato decollo. L''alieno, solo e smarrito, viene trovato ed ospitato da Elliott, con la complicità della sorellina Gertie e il fratello maggiore Michael. Tra i due si instaura un profondo rapporto di amicizia che li lega anche a livello emotivo. Desideroso di tornare a casa, l''alieno costruisce un rudimentale dispositivo di comunicazione per chiedere aiuto ai suoi. Gradualmente, la salute di ET peggiora, e la situazione è aggravata dall''irruzione nell''universo dei ragazzi da parte del mondo degli adulti, che vuole impossessarsi dell''alieno.","en":"An alien is left behind on Earth and saved by the 10-year-old Elliott who decides to keep him hidden in his home. While a task force hunts for the extra-terrestrial, Elliott, his brother, and his little sister Gertie form an emotional bond with their new friend, and try to help him find his way home.","fr":"Une soucoupe volante atterrit en pleine nuit près de Los Angeles. Quelques extraterrestres, envoyés sur Terre en mission d’exploration botanique, sortent de l’engin, mais un des leurs s’aventure au-delà de la clairière où se trouve la navette. Celui-ci se dirige alors vers la ville. C’est sa première découverte de la civilisation humaine. Bientôt traquée par des militaires et abandonnée par les siens, cette petite créature apeurée se nommant E.T. se réfugie dans une résidence de banlieue. Elliot, un garçon de dix ans, le découvre et lui construit un abri dans son armoire. Rapprochés par un échange télépathique, les deux êtres ne tardent pas à devenir amis. Aidé par sa sœur Gertie et son frère aîné Michael, Elliot va alors tenter de garder la présence d''E.T. secrète.","de":"Der junge Elliott traut seinen Augen kaum, als er in einem Schuppen einen kleinen Ausserirdischen findet. Der schrumpelige Kobold musste bei einem Erkundungsflug von seinen Kollegen auf der Erde zurückgelassen werden, weil sie in Gefahr gerieten, von Menschen entdeckt zu werden. Elliot versucht, seinen neuen Freund vor den Wissenschaftlern der Regierung zu verstecken, denn der will seine weit entfernten Verwandten anfunken. Doch E.T. wird vor Heimweh immer schwächer.","es":"Un pequeño ser de otro planeta se queda abandonado en la Tierra cuando su nave se marcha olvidándose de él. Tiene miedo. Está completamente solo, pero se hará amigo de un niño, que lo esconde en su casa. El niño y sus hermanos intentarán encontrar la forma de que el pequeño extraterrestre regrese a su planeta antes de que los científicos y la policía lo encuentren."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/3DIwTC2A58WDtsgjaXjo2FYA1pW.jpg","en":"https://image.tmdb.org/t/p/w500/an0nD6uq6byfxXCfk6lQBzdL2J1.jpg","fr":"https://image.tmdb.org/t/p/w500/5jl5sfhTeAlp60rM9GxoDA2dmX9.jpg","de":"https://image.tmdb.org/t/p/w500/mNbBxa6pNxr4tmOQTGzj9eBuivZ.jpg","es":"https://image.tmdb.org/t/p/w500/ojvKem8WUzRK5PLvO7wTuAFinnz.jpg"}'::jsonb WHERE id = 241;
UPDATE public.films SET tmdb_id = 497, titoli_i18n = '{"it":"Il miglio verde","en":"The Green Mile","es":"La milla verde","de":"The Green Mile","fr":"La Ligne verte"}'::jsonb, trame_i18n = '{"it":"E'' il racconto che Paul Edgecomb fa all''amica Elaine Connelly in una casa di riposo. Sono passati circa sessanta anni da quando lavorava come capo delle guardie del braccio della morte nel penitenziario di Could Mountain. Durante la grande depressione, nel carcere del sud degli Usa, Edgecomb si occupava di quattro assassini che attendevano di compiere la loro ultima passeggiata lungo il ''Miglio verde'', il corridoio rivestito di linoleum verde che li avrebbe condotti nella stanza della sedia elettrica. Fra questi c''era anche John Coffrey, un ragazzone nero condannato per l''omicidio di due gemelline di nove anni. Nonostante avesse le dimensioni e la forza per uccidere chiunque, Coffrey aveva un carattere semplice e ingenuo: era davvero lui il colpevole?","en":"A supernatural tale set on death row in a Southern prison, where gentle giant John Coffey possesses the mysterious power to heal people''s ailments. When the cell block''s head guard, Paul Edgecomb, recognizes Coffey''s miraculous gift, he tries desperately to help stave off the condemned man''s execution.","es":"En el sur de los Estados Unidos, en plena Depresión, Paul Edgecomb es un vigilante penitenciario a cargo de la Milla Verde, un pasillo que separa las celdas de los reclusos condenados a la silla eléctrica. Esperando su ejecución está John Coffey, un gigantesco negro acusado de asesinar brutalmente a dos hermanas de nueve años. Tras una personalidad ingenua, Coffey esconde un don sobrenatural prodigioso. A medida que transcurre la historia, Paul Edgecomb aprende que los milagros ocurren... incluso en los lugares más insospechados.","de":"Paul Edgecomb und seine Kollegen sind Wärter im Todestrakt eines Gefängnisses in den 30ern. Paul versieht seinen Job zwar immer noch mit der größtmöglichen Menschlichkeit, doch er wird zunehmend zynischer, da er ständig Menschen sterben sieht. Außerdem ist er krank. Da kommt ein neuer Delinquent in den Trakt: John Coffey, ein farbiger Riese von friedlichster Bauart, der im Dunkeln Angst hat. Wie sich herausstellt, hat Coffey heilende Fähigkeiten, die auch Paul kennenlernt. Zunehmend gerät er in Zweifel, ob dieser Gigant sterben soll, vor allem da er die Morde, wegen der er verurteilt ist, nicht begangen zu haben scheint. Doch der Stuhl wartet und Coffeys Gabe droht für immer zu verschwinden ...","fr":"Paul Edgecomb, pensionnaire centenaire d’une maison de retraite, est hanté par ses souvenirs. Gardien-chef du pénitencier de Cold Mountain en 1935, il était chargé de veiller au bon déroulement des exécutions des peines capitales, en s’efforçant d’adoucir les derniers moments des condamnés. Parmi eux, se trouvait un colosse du nom de John Coffey, accusé du viol et du meurtre de deux fillettes. Intrigué par cet homme candide et timide, aux dons magiques, Edgecomb va tisser avec lui des liens très forts."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/kptqTcldosy8JPf75JT16oTYUMB.jpg","en":"https://image.tmdb.org/t/p/w500/8VG8fDNiy50H4FedGwdSVUPoaJe.jpg","es":"https://image.tmdb.org/t/p/w500/aBQiJRxGRrX0mXFMjxyzWYFtEnf.jpg","de":"https://image.tmdb.org/t/p/w500/frsZNikjMbp1gfidAl3zm1PAMHk.jpg","fr":"https://image.tmdb.org/t/p/w500/cRBUYC02CPsVa1GqBq6rfHn5a8g.jpg"}'::jsonb WHERE id = 256;
UPDATE public.films SET tmdb_id = 1368337, titoli_i18n = '{"en":"The Odyssey","es":"La Odisea","it":"Odissea","de":"Die Odyssee","fr":"L''Odyssée"}'::jsonb, trame_i18n = '{"en":"Odysseus, the legendary King of Ithaca, embarks on a long and perilous journey home following the Trojan War. Throughout his voyage, he is forced to confront the whims of gods, mythological monsters, and trials that stretch both his cunning and his humanity to the breaking point.","es":"Tras la caída de Troya, el legendario rey de Ítaca, Odiseo a.k.a. Ulises, emprende un largo y peligroso viaje para regresar junto a su esposa Penélope y su hijo Telémaco. En el camino deberá enfrentarse a criaturas mitológicas, dioses caprichosos y pruebas que pondrán a prueba su ingenio, su resistencia y su humanidad. Mientras tanto, en Ítaca, el futuro de su reino pende de un hilo ante la creciente amenaza de quienes creen que jamás volverá.","it":"Ogni leggenda ha un prezzo. Ogni ritorno richiede un sacrificio. Mentre il mare diventa il suo più grande nemico, Ulisse affronta un cammino fatto di illusioni, battaglie e prove impossibili. Un''epica odissea che mette alla prova il coraggio di un uomo contro il volere degli dèi.","de":"Folgt Odysseus, dem legendären griechischen König von Ithaka, auf seiner langen und gefährlichen Heimreise nach dem Trojanischen Krieg und schildert seine Begegnungen mit mythischen Wesen wie dem Zyklopen Polyphem, den Sirenen und der Hexengöttin Circe, während er versucht, wieder mit seiner Frau Penelope zusammenzukommen.","fr":"Ulysse, roi d''Ithaque, entreprend un périple périlleux pour regagner son royaume après la guerre de Troie. Alors qu''ils traversent la Méditerranée avec ses soldats, ils se retrouvent bientôt à lutter non seulement contre les éléments, mais aussi contre une multitude d''obstacles mortels et de créatures mythiques."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/5rhTDKUhPYvpdQIijFIs5VoWsON.jpg","es":"https://image.tmdb.org/t/p/w500/sf2ke1nwFOLLcwLZiXu9VaMMv8e.jpg","it":"https://image.tmdb.org/t/p/w500/qQhInj9fw3S2bMbiEujVldthgKe.jpg","de":"https://image.tmdb.org/t/p/w500/4E8Ji8jTcWNncl9PdUCauoj2qh9.jpg","fr":"https://image.tmdb.org/t/p/w500/kP8jJIkmX0vWEYiqQ9c5zU0dvcn.jpg"}'::jsonb WHERE id = 257;
UPDATE public.films SET tmdb_id = 408, titoli_i18n = '{"es":"Blancanieves y los siete enanitos","it":"Biancaneve e i sette nani","de":"Schneewittchen und die sieben Zwerge","fr":"Blanche-Neige et les Sept Nains","en":"Snow White and the Seven Dwarfs"}'::jsonb, trame_i18n = '{"es":"La malvada madrastra de la princesa Blancanieves decide deshacerse de ella porque no puede soportar que la belleza de la joven sea superior a la de ella. Sin embargo, Blancanieves consigue salvarse y se refugia en la cabaña de los siete enanitos. A pesar de todo, su cruel madrastra consigue encontrarla y la envenena con una manzana. Pero la princesa no está muerta, sólo dormida, a la espera de que un príncipe azul la rescate.","it":"La perfida regina ordina al suo cacciatore di uccidere Biancaneve che lo specchio parlante ha definito la più bella del reame. La ragazza fugge. Guidata dagli animaletti del bosco, arriva alla casa dei sette nani. Eolo, Mammolo, Pisolo, Brontolo, Dotto, Gongolo e Cucciolo la accolgono e la proteggono. Quando la regina, trasformatasi in strega, arriva per ucciderla, i nanetti inseguono la cattiva che precipita da un burrone. Biancaneve, vegliata dai suoi amici come morta, torna in vita quando viene baciata dal giovane principe innamorato.","de":"Schneewittchen ist eine kleine Prinzessin, deren böse Stiefmutter sie in Lumpen hüllen und als Magd schuften ließ. Warum? Weil sie Angst hatte, dass das Mädchen eines Tages schöner sein könnte als sie selbst. Als diese Befürchtung der eitlen Königin durch ihren magischen Spiegel als wahr bestätigt wird, beauftragt sie einen Jäger, Schneewittchen im Wald zu töten. Doch der bringt den Mord nicht übers Herz und lässt das Mädchen entkommen. Schneewittchen entdeckt auf einer Lichtung ein leer stehendes Haus, in dem sie gemeinsam mit den Tieren des Waldes für Ordnung und Sauberkeit sorgt. Als die sieben Zwerge von der Arbeit heimkehren, sind sie von ihrem Hausgast schnell entzückt und nehmen Schneewittchen bei sich auf. Als die Königin erfährt, dass ihre Stieftochter noch lebt, ist sie außer sich: Mit Zauberkräften verwandelt sie sich in eine Hexe und macht sich auf den Weg in den Wald, um die böse Tat mit Hilfe eines giftigen Apfels selbst zu vollenden...","fr":"Blanche-Neige est une princesse d’une très grande beauté, ce qui rend jalouse sa belle‐mère. Celle‐ci demande quotidiennement à son miroir magique de lui dire qu’elle est la plus belle, mais un jour, le miroir affirme que la plus belle femme du royaume est Blanche-Neige. La reine décide alors de la tuer, mais le garde chargé de cette tâche ne trouve pas le courage et abandonne Blanche-Neige dans la forêt. Perdue, à bout de force, elle échoue dans une maison où habitent sept nains.","en":"A beautiful girl, Snow White, takes refuge in the forest in the house of seven dwarfs to hide from her stepmother, the wicked Queen. The Queen is jealous because she wants to be known as \"the fairest in the land,\" and Snow White''s beauty surpasses her own."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/b2ZPP3bZqDOzqTHr1TlFIFPWP48.jpg","it":"https://image.tmdb.org/t/p/w500/pXji7b98MIliRsylaBeCBaRbcmA.jpg","de":"https://image.tmdb.org/t/p/w500/9WIyHiEYjVAAXc6m0yg2J4upT8V.jpg","fr":"https://image.tmdb.org/t/p/w500/pf2dhaGRYNtBgjkw24ot3AAXfPi.jpg","en":"https://image.tmdb.org/t/p/w500/3VAHfuNb6Z7UiW12iYKANSPBl8m.jpg"}'::jsonb WHERE id = 258;
UPDATE public.films SET tmdb_id = 787699, titoli_i18n = '{"it":"Wonka","en":"Wonka","es":"Wonka","de":"Wonka","fr":"Wonka"}'::jsonb, trame_i18n = '{"it":"Basato sullo straordinario protagonista de La Fabbrica di Cioccolato, il romanzo per bambini più iconico dell’autore Roald Dahl nonché uno dei libri per bambini più venduti di tutti i tempi, Wonka racconta la meravigliosa storia di come il più grande inventore, mago e cioccolataio del mondo sia diventato l''amato Willy Wonka che conosciamo oggi.","en":"Willy Wonka – chock-full of ideas and determined to change the world one delectable bite at a time – is proof that the best things in life begin with a dream, and if you’re lucky enough to meet Willy Wonka, anything is possible.","es":"Basada en el personaje que protagoniza \"Charlie y la fábrica de chocolate\", el libro infantil más emblemático de Roald Dahl y uno de los más vendidos de todos los tiempos, \"Wonka\" cuenta la historia de cómo el mayor inventor, mago y chocolatero del mundo se convirtió en el querido Willy Wonka que conocemos hoy en día.","de":"Bereits in jungen Jahren träumt Willy Wonka von seinem eigenen Schokoladengeschäft. Doch Schaum wie so manch anderer Traum ist das nicht. Mit dem Laden ist es ihm sehr ernst. Deshalb hat er auch viel Zeit damit verbracht, um die Welt zu reisen und an verschiedensten Orten seine Techniken zu verbessern. Doch bevor alles überhaupt richtig in Gang kommen kann, ist es schon fast wieder aus mit dem Traum vom eigenen Laden. Denn das mächtige Schokoladenkartell legt dem exzentrischen Wonka jede Menge Steine in den Weg. Aber ohne die Erlaubnis des Kartells geht nun mal leider gar nichts, die Ladentür muss verschlossen bleiben. Aber Wonka lässt sich auch davon nicht unterkriegen. Er sprudelt regelrecht vor Ideen, wie er seine schokoladigen Leckereien trotzdem unters Volk bringen kann. Alleine ist er dabei auch nicht. Die kleine Noodle ist ebenfalls mit dabei. Außerdem kann Wonka auf die Unterstützung der skurrilen Oompa Loompas setzen.","fr":"Inspiré du personnage principal hors du commun de Charlie et la Chocolaterie, le best-seller de Roald Dahl qui est aujourd''hui l''un des livres pour enfants les plus vendus de tous les temps, « Wonka » est une histoire merveilleuse retraçant la jeunesse de Willy Wonka, et comment il est devenu ce grand inventeur, magicien et chocolatier que nous connaissons aujourd''hui. Dans ce spectacle saisissant et d''une créativité sans limites, les spectateurs découvriront un Willy Wonka jeune, la tête débordant d''idées et bien décidé à changer le monde à coups de délicieuses chocolateries. Il vous montrera que les meilleures choses de la vie commencent par un rêve, et qu''en rencontrant Willy Wonka, tout devient possible."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/7y2M1w0nWW0Z5Ph1XzED07OYUsa.jpg","en":"https://image.tmdb.org/t/p/w500/qhb1qOilapbapxWQn9jtRCMwXJF.jpg","es":"https://image.tmdb.org/t/p/w500/6eHcR7zwvNSvkOl9jbctU0lvZQ1.jpg","de":"https://image.tmdb.org/t/p/w500/5ZQDRv6hw3JaNvcnhrNeaeXnQMG.jpg","fr":"https://image.tmdb.org/t/p/w500/aKK2C3SErXIhNdT9gI93as2b8GV.jpg"}'::jsonb WHERE id = 259;
UPDATE public.films SET tmdb_id = 615457, titoli_i18n = '{"fr":"Nobody","es":"Nadie","de":"Nobody","it":"Io sono nessuno","en":"Nobody"}'::jsonb, trame_i18n = '{"fr":"Hutch Mansell, un père et un mari frustré, totalement déconsidéré par sa famille, se contente d’encaisser les coups, sans jamais les rendre. Il n’est rien. Une nuit, alors que deux cambrioleurs pénètrent chez lui, il fait le choix de ne pas intervenir, plutôt que de risquer une escalade sanglante. Une décision qui le discrédite définitivement aux yeux de son fils Blake, et qui semble l’éloigner encore plus de sa femme Becca. Cet incident réveille chez cet homme blessé des instincts larvés qui vont le propulser sur une voie violente, révélant des zones d’ombres et des compétences létales insoupçonnées. Dans une avalanche de coups de poings, de fusillades et de crissements de pneus, il va tout faire pour tirer sa famille des griffes d’un redoutable ennemi et s’assurer que, plus jamais, personne ne le prenne pour un moins que rien.","es":"Hutch Mansell, un padre de familia que aguanta con resignación y sin defenderse los golpes de la vida. Un don nadie.  Una noche, cuando dos ladrones entran en su casa, Hutch decide no actuar y no trata de defenderse ni al él mismo ni a su familia, convencido de que solo así evitará una escalada de violencia. Tras el ataque, su hija adolescente Blake no oculta su decepción, y su esposa Becca se aleja todavía más.","de":"Familienvater Hutch ist ein Niemand. Der Vorstadt-Familienvater wird von den meisten Leuten einfach ignoriert und zieht auch niemals die Aufmerksamkeit auf sich. Als zwei Verbrecher eines Nachts in sein Haus einsteigen, sieht er sich außerstande, sich oder seine Familie zu verteidigen. Schließlich will er Gewalt um jeden Preis verhindern. Sein Sohn Brady wendet sich daraufhin enttäuscht von seinem Vater ab. Seine Frau Becca tut es ihm gleich und zieht sich noch mehr zurück. Doch der Einbruch löst bei Hutch etwas aus. Er sieht plötzlich rot und enthüllt eine dunkle Seite, die ihn auf einen Pfad der Gewalt schickt …","it":"Hutch Mansell, padre e marito sottostimato e trascurato, è abituato a non reagire a nessuna umiliazione. Quando una notte due ladri irrompono nella sua abitazione in periferia, rifiuta di difendere se stesso o la sua famiglia, sperando di prevenire violenze maggiori. Il figlio adolescente Blake è deluso dal suo comportamento e la moglie Becca comincia ad allontanarsi maggiormente da lui. All''indomani dell''accaduto, la rabbia che Hutch cova esplode spingendolo a manifestare tutta la violenza di cui è capace. Si ritroverà allora a dover difendere come meglio può la sua famiglia da un pericoloso avversario e ad assicurarsi di non essere mai più sottovalutato da nessuno.","en":"Hutch Mansell, a suburban dad, overlooked husband, nothing neighbor — a \"nobody.\" When two thieves break into his home one night, Hutch''s unknown long-simmering rage is ignited and propels him on a brutal path that will uncover dark secrets he fought to leave behind."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/jKRzh9y5YjYNISbeh55FQwetsSu.jpg","es":"https://image.tmdb.org/t/p/w500/ddO5a3tMPpQutSDQO1bESgLWadB.jpg","de":"https://image.tmdb.org/t/p/w500/p64aYHMicQjIHUC5WczBHgIiWcM.jpg","it":"https://image.tmdb.org/t/p/w500/iECT5xNf72P7cx9LDMrEwhGYD5O.jpg","en":"https://image.tmdb.org/t/p/w500/oBgWY00bEFeZ9N25wWVyuQddbAo.jpg"}'::jsonb WHERE id = 260;
UPDATE public.films SET tmdb_id = 1007734, titoli_i18n = '{"it":"Io sono nessuno 2","en":"Nobody 2","fr":"Nobody 2","es":"Nadie 2","de":"Nobody 2"}'::jsonb, trame_i18n = '{"it":"Il padre di periferia Hutch Mansell, un ex assassino letale, viene riportato nel suo passato violento dopo aver sventato un''invasione domestica, innescando una catena di eventi che svela i segreti sul passato di sua moglie Becca e sul suo.","en":"Former assassin Hutch Mansell takes his family on a nostalgic vacation to a small-town theme park, only to be pulled back into violence when they clash with a corrupt operator, a crooked sheriff, and a ruthless crime boss.","fr":"Quatre ans après sa malencontreuse altercation avec la mafia russe, Hutch doit toujours 30 millions de dollars à la redoutable organisation et s''efforce de la rembourser en enchaînant sans répit les contrats d''une liste de criminels à abattre aussi interminable qu''internationale. Bien qu''il apprécie le caractère intense de son travail, Hutch se retrouve vite surmené, tout comme sa femme Becca, et ils s''éloignent inexorablement l''un de l''autre.","es":"Cuatro años después de enfrentarse involuntariamente a la mafia rusa, Hutch Mansell sigue intentando saldar una deuda de 30 millones de dólares con golpes a criminales internacionales. Agotado y distanciado de su familia, organiza unas vacaciones con su esposa e hijos en Plummerville, el lugar donde solía ir con su hermano de niño. Pero un pequeño altercado los convierte en el objetivo de un peligroso mafioso local y de su corrupto sheriff, poniendo en riesgo toda la familia.","de":"Vier Jahre nachdem er sich versehentlich mit der russischen Mafia angelegt hatte, arbeitet Hutch noch immer seinen Schuldenberg von 30 Millionen Dollar ab. Unzählige dreckige Jobs erledigt, zahllose Auftragsmorde vor sich: Ein Ende ist für den gestressten Killer nicht absehbar. Zunehmend leidet die Ehe mit seiner Frau Becca unter seinem zeitintensiven Job. Um mehr Zeit miteinander zu verbringen, machen sie einen Kurzurlaub mit ihren Kindern im Wild Bill’s Majestic Midway Wasserpark, wo Hutch schon als Kind glückliche Ferien verbrachte. Mit Hutchs Vater freuen sie sich auf eine entspannte Zeit in Plummerville. Doch eine Begegnung mit Vorstadtschlägern weckt die Aufmerksamkeit des korrupten Wasserparkbesitzers und seines zwielichtigen Sheriffs. Hutch steckt plötzlich in neuen Schwierigkeiten und trifft auf den härtesten Gangsterboss, dem er je gegenüberstand."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/8RXDbeVG9Tb0z8FWPph77uJsTkd.jpg","en":"https://image.tmdb.org/t/p/w500/svXVRoRSu6zzFtCzkRsjZS7Lqpd.jpg","fr":"https://image.tmdb.org/t/p/w500/gmyEMJqpScyALufAMspejI6qGQx.jpg","es":"https://image.tmdb.org/t/p/w500/qwdBh0102NX5fslXv3L9MSlXqKc.jpg","de":"https://image.tmdb.org/t/p/w500/3szAYIIftJgBMkYJXmb3jA23ctl.jpg"}'::jsonb WHERE id = 261;
UPDATE public.films SET tmdb_id = 687163, titoli_i18n = '{"es":"Proyecto Salvación","de":"Der Astronaut – Project Hail Mary","fr":"Projet Dernière Chance","it":"L''ultima missione: Project Hail Mary","en":"Project Hail Mary"}'::jsonb, trame_i18n = '{"es":"El profesor de ciencias Ryland Grace se despierta en una nave espacial a años luz de casa sin recordar quién es ni cómo ha llegado hasta allí. A medida que recupera la memoria, empieza a descubrir su misión: resolver el enigma de la misteriosa sustancia que provoca la extinción del sol. Deberá recurrir a sus conocimientos científicos y a sus ideas poco ortodoxas para salvar todo lo que hay en la Tierra de la extinción... pero una amistad inesperada significa que quizá no tenga que hacerlo solo.","de":"Als Ryland Grace erwacht, muss er feststellen, dass er ganz allein ist. Er ist anscheinend der einzige Überlebende einer Raumfahrtmission, Millionen Kilometer von zu Hause entfernt, auf einem Flug ins Tau-Ceti-Sternsystem. Aber was erwartet ihn dort? Und warum sind alle anderen Besatzungsmitglieder tot? Nach und nach dämmert es Grace, dass von seinem Überleben nicht nur die Mission, sondern die Zukunft der gesamten Erdbevölkerung abhängt.","fr":"Le professeur de sciences Ryland Grace se réveille à bord d’un vaisseau spatial, à des années-lumière de la Terre, sans aucun souvenir de qui il est ni de la façon dont il est arrivé là. À mesure que sa mémoire lui revient, il commence à découvrir sa mission : résoudre l’énigme d’une mystérieuse substance qui provoque l’extinction du Soleil. Il doit faire appel à ses connaissances scientifiques et ses idées peu orthodoxes pour sauver toute vie sur Terre mais une amitié inattendue pourrait signifier qu’il n’aura pas à accomplir cette tâche seul.","it":"L’insegnante di scienze Ryland Grace si sveglia su un’astronave lontano anni luce da casa senza alcun ricordo di chi sia o di come sia arrivato lì. Con il riaffiorare della sua memoria, torna alla luce lo scopo della sua missione: risolvere l’enigma della misteriosa sostanza che sta causando il collasso del Sole. Dovrà fare affidamento sulle sue conoscenze scientifiche e sulle sue capacità di pensare fuori dagli schemi per salvare dall’estinzione la vita sulla Terra, mentre un''inaspettata amicizia gli farà capire che non è solo in questa impresa.","en":"Science teacher Ryland Grace wakes up on a spaceship light years from home with no recollection of who he is or how he got there. As his memory returns, he begins to uncover his mission: solve the riddle of the mysterious substance causing the sun to die out. He must call on his scientific knowledge and unorthodox ideas to save everything on Earth from extinction."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/7lwOTxajURKEWO6gI370NTrVdBO.jpg","de":"https://image.tmdb.org/t/p/w500/qUraey7aJVaqx6NhlXl5Q7Z1rEX.jpg","fr":"https://image.tmdb.org/t/p/w500/wzyy8ZrsuHfAt4iz4iH3rT0tdoT.jpg","it":"https://image.tmdb.org/t/p/w500/gPC1X3mwqwX50Ye3qwwPt7iW3Ma.jpg","en":"https://image.tmdb.org/t/p/w500/iOb2fjXLbpJgyQXe46n1WtGCnaa.jpg"}'::jsonb WHERE id = 262;
UPDATE public.films SET tmdb_id = 1284465, titoli_i18n = '{"it":"Robin Hood - Il prezzo del sangue","es":"La muerte de Robin Hood","en":"The Death of Robin Hood","fr":"On l''appelait Robin des Bois","de":"The Death of Robin Hood"}'::jsonb, trame_i18n = '{"it":"Il principe dei ladri, il difensore degli oppressi, l’eroe che ruba ai ricchi per dare ai poveri. Sono tutte bugie: Robin Hood non è mai stato un paladino della giustizia, ma solo un efferato bandito, e le sue “allegre scorribande” erano vere e proprie carneficine. Ma quando dedichi la tua vita al crimine, alla violenza e alla menzogna, devi essere pronto a pagarne il prezzo…","es":"Robin Hood intenta lidiar con sus demonios tras una larga vida de crímenes y asesinatos. Cuando en una sangrienta batalla resulta herido de gravedad, es enviado a un misterioso castillo para que curen sus heridas. Allí conocerá a una mujer que le ofrecerá una última oportunidad de redención.","en":"Grappling with his past after a life of crime and murder, Robin Hood finds himself gravely injured after a battle he thought would be his last. In the hands of a mysterious woman, he is offered a chance at salvation.","fr":"Hanté par son passé après une vie de crimes et de violence, Robin des Bois est laissé pour mort à l’issue d’un combat qu’il pensait être le dernier. Recueilli par une femme mystérieuse, il se voit offrir une ultime chance de rédemption…","de":"Während er nach einem Leben voller Verbrechen und Mord mit seiner Vergangenheit ringt, findet sich Robin Hood schwer verwundet nach einer Schlacht wieder, die er für seine letzte hielt. In den Händen einer geheimnisvollen Frau bietet sich ihm eine Chance auf Erlösung."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/knUCsVWsLv5583lsvs2cP1VRrGx.jpg","es":"https://image.tmdb.org/t/p/w500/pC2hVl4J522GcMVc5OghRHSs0tq.jpg","en":"https://image.tmdb.org/t/p/w500/13MmRwmG5NmaMfU8qNrtgGXisiD.jpg","fr":"https://image.tmdb.org/t/p/w500/7MEcMhm889D8zIDINnBKOYNiSg1.jpg","de":"https://image.tmdb.org/t/p/w500/oR8ZW1CVADJCwCsIYPEowUI1RAU.jpg"}'::jsonb WHERE id = 263;
UPDATE public.films SET tmdb_id = 1275779, titoli_i18n = '{"it":"Disclosure Day","en":"Disclosure Day","es":"El día de la revelación","fr":"Disclosure Day","de":"Disclosure Day – Der Tag der Wahrheit"}'::jsonb, trame_i18n = '{"it":"Se scoprissi che non siamo soli, se qualcuno te lo mostrasse, te lo dimostrasse, questo ti spaventerebbe?","en":"A cybersecurity expert becomes a whistleblower after uncovering secrets about aliens, putting him on the run from a corporation. Meanwhile, a meteorologist experiencing strange phenomena joins forces with him to prove there''s life beyond our understanding.","es":"Entre conspiraciones gubernamentales y avances tecnológicos, toda la humanidad está a punto de conocer la verdad sobre la existencia extraterrestre y su devenir.","fr":"Si vous découvriez que nous ne sommes pas seuls, si quelqu''un vous le montrait, vous le prouvait, cela vous effraierait-il ?","de":"Die Fernsehmeteorologin Margaret Fairchild wird live während eines TV-Auftritts plötzlich von einem unerklärlichen Phänomen heimgesucht. Während die Behörden zu vertuschen versuchen, dass Außerirdische dahinter stecken könnten, will der Aktivist Daniel Kellner mit allen Mitteln die Weltöffentlichkeit über die Wahrheit informieren."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/72Yx1uisLLJy5k2P5OzBkRdEIjp.jpg","en":"https://image.tmdb.org/t/p/w500/AnJ8IQJI23hNpYXVNaythu061Ru.jpg","es":"https://image.tmdb.org/t/p/w500/dPTa7jSIeaDhie2d9JSZr7qI0Tf.jpg","fr":"https://image.tmdb.org/t/p/w500/8GRMeKaDFnuzXBzqGiDMzCFDnwQ.jpg","de":"https://image.tmdb.org/t/p/w500/8aaV365bjSxPMZdT18RybAYGqSp.jpg"}'::jsonb WHERE id = 264;
UPDATE public.films SET tmdb_id = 546554, titoli_i18n = '{"en":"Knives Out","es":"Puñales por la espalda","fr":"À couteaux tirés","de":"Knives Out - Mord ist Familiensache","it":"Cena con delitto - Knives Out"}'::jsonb, trame_i18n = '{"en":"When renowned crime novelist Harlan Thrombey is found dead at his estate just after his 85th birthday, the inquisitive and debonair Detective Benoit Blanc is mysteriously enlisted to investigate. From Harlan''s dysfunctional family to his devoted staff, Blanc sifts through a web of red herrings and self-serving lies to uncover the truth behind Harlan''s untimely death.","es":"Cuando el renombrado novelista de misterio Harlan Thrombey es encontrado muerto en su mansión justo después de su 85 cumpleaños, el inquisitivo y cortés detective Benoit Blanc es misteriosamente reclutado para investigar. Se moverá entre una red de pistas falsas y mentiras interesadas para tratar de descubrir la verdad tras la prematura muerte del escritor.","fr":"Célèbre auteur de polars, Harlan Thrombey est retrouvé mort dans sa somptueuse propriété, le soir de ses 85 ans. L’esprit affûté et la mine débonnaire, le détective Benoit Blanc est alors engagé par un commanditaire anonyme afin d’élucider l’affaire. Mais entre la famille d’Harlan qui s''entre-déchire et son personnel qui lui reste dévoué, Blanc plonge dans les méandres d’une enquête mouvementée, mêlant mensonges et fausses pistes, où les rebondissements s''enchaînent à un rythme effréné jusqu''à la toute dernière minute…","de":"Harlan Thrombey ist tot! Und nicht nur das – der renommierte Krimiautor und Familienpatriarch wurde auf der Feier zu seinem 85. Geburtstag umgebracht. Doch natürlich wollen weder die versammelte exzentrische Verwandtschaft noch das treu ergebene Hauspersonal etwas gesehen haben. Ein Fall für Benoit Blanc! Der lässig-elegante Kommissar beginnt seine Ermittlungen und während sich sämtliche anwesenden Gäste alles andere als kooperativ zeigen, spitzt sich die Lage zu und das Misstrauen untereinander wächst. Ein komplexes Netz aus Lügen, falschen Fährten und Ablenkungsmanövern muss durchkämmt werden, um die Wahrheit hinter Thrombeys vorzeitigem Tod zu enthüllen.","it":"Quando il noto scrittore di gialli Harlan Thrombey viene trovato morto nella sua tenuta poco dopo il suo 85° compleanno, il detective Benoit Blanc, curioso e disinvolto, viene misteriosamente reclutato per investigare sull''accaduto. Dalla disfunzionale famiglia della vittima al suo devoto entourage, Blanc si muove attraverso una fitta rete di bugie, segreti e non detti, per scoprire quale sia la verità dietro la prematura morte dell''autore."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/pThyQovXQrw2m0s9x82twj48Jq4.jpg","es":"https://image.tmdb.org/t/p/w500/7scJ3fVmwdSpGG87wvxH3kk0RPc.jpg","fr":"https://image.tmdb.org/t/p/w500/4kxVUW4hMurLs7ascwahF7blEUs.jpg","de":"https://image.tmdb.org/t/p/w500/ftCASOlSQ6QtjS3TIJB7xXHW5H9.jpg","it":"https://image.tmdb.org/t/p/w500/q2sh3RJ3rhRDYlJV4ZrMzzZ9Ye7.jpg"}'::jsonb WHERE id = 265;
UPDATE public.films SET tmdb_id = 661374, titoli_i18n = '{"it":"Glass Onion - Knives Out","es":"Puñales por la espalda: El misterio de Glass Onion","fr":"Glass Onion : Une histoire à couteaux tirés","en":"Glass Onion: A Knives Out Mystery","de":"Glass Onion: A Knives Out Mystery"}'::jsonb, trame_i18n = '{"it":"L''egocentrico multimilardiario Miles Bron, proprietario della Alpha Industries, invita i suoi amici a una fuga sulla sua isola greca privata. Quando qualcuno viene trovato morto, l''investigatore Benoit Blanc si occupa del caso.","es":"Cuando el multimillonario Miles Bron invita a algunos de sus allegados a una escapada a su isla griega privada, pronto queda claro que no todo es perfecto en el paraíso. Y cuando alguien aparece muerto, ¿quién mejor que Benoit Blanc para desentrañar todas las capas del misterio?","fr":"Direction la Grèce pour le célèbre détective Benoit Blanc, qui doit élucider un mystère entourant un milliardaire de la technologie et son groupe d''amis hauts en couleur.","en":"World-famous detective Benoit Blanc heads to Greece to peel back the layers of a mystery surrounding a tech billionaire and his eclectic crew of friends.","de":"Der weltberühmte Detektiv Benoit Blanc reist nach Griechenland, um das Rätsel um einen Tech-Milliardär und dessen facettenreiche Entourage zu lösen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/yhCxL5ebwiBwkmYrjL8gqJBZKNS.jpg","es":"https://image.tmdb.org/t/p/w500/yXGsWQURm614onIpb3iBcp1iLz8.jpg","fr":"https://image.tmdb.org/t/p/w500/j8mGH7DzwUD9soODpUI64PWNumg.jpg","en":"https://image.tmdb.org/t/p/w500/vDGr1YdrlfbU9wxTOdpf3zChmv9.jpg","de":"https://image.tmdb.org/t/p/w500/oprUVNuV1aLeB7fffHqCNcrs1uT.jpg"}'::jsonb WHERE id = 266;
UPDATE public.films SET tmdb_id = 812583, titoli_i18n = '{"it":"Wake Up Dead Man - Knives Out","en":"Wake Up Dead Man: A Knives Out Mystery","fr":"Wake Up Dead Man : Une histoire à couteaux tirés","de":"Wake Up Dead Man: A Knives Out Mystery","es":"Puñales por la espalda III. De entre los muertos"}'::jsonb, trame_i18n = '{"it":"Il detective Benoit Blanc fa squadra con un giovane prete zelante per indagare su un crimine perfettamente impossibile nella chiesa di una piccola città dal passato oscuro.","en":"When young priest Jud Duplenticy is sent to assist charismatic firebrand Monsignor Jefferson Wicks, it’s clear that all is not well in the pews. After a sudden and seemingly impossible murder rocks the town, the lack of an obvious suspect prompts local police chief Geraldine Scott to join forces with renowned detective Benoit Blanc to unravel a mystery that defies all logic.","fr":"Le détective Benoit Blanc collabore avec un jeune prêtre pour enquêter sur un crime totalement inexplicable perpétré dans l''église d''une petite ville au sombre passé.","de":"Der Detektiv Benoit Blanc arbeitet mit einem jungen Priester zusammen, um ein absolut unmögliches Verbrechen in einer Kirche mit dunkler Vergangenheit zu lösen.","es":"El detective Benoit Blanc se une a un joven y honesto sacerdote para investigar un crimen totalmente imposible en la iglesia de un pequeño pueblo con una oscura historia."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/db8j0xU82lzWKX0SXrPY5tFrzwA.jpg","en":"https://image.tmdb.org/t/p/w500/iV9LM8aUb83BjCCx2RUnKE5sSQg.jpg","fr":"https://image.tmdb.org/t/p/w500/qlUqHz8M1x3a2gZSggXY2t1qhNo.jpg","de":"https://image.tmdb.org/t/p/w500/bIeHhOqCQysfed98TKjZhRWRc7x.jpg","es":"https://image.tmdb.org/t/p/w500/trGWfaYTkzkalkosXfxidpLum50.jpg"}'::jsonb WHERE id = 267;
UPDATE public.films SET tmdb_id = 1054867, titoli_i18n = '{"it":"Una battaglia dopo l’altra","es":"Una batalla tras otra","fr":"Une Bataille après l''autre","en":"One Battle After Another","de":"One Battle After Another"}'::jsonb, trame_i18n = '{"it":"Un gruppo di ex rivoluzionari si riunisce quando un loro perfido nemico riemerge dal loro passato, dopo sedici anni di silenzio. Il gruppo avrà il duro compito di salvare la figlia di uno di loro, prima che accada l''inevitabile.","es":"Un ex revolucionario, tras años apartado de la lucha, se ve obligado a volver a la acción para enfrentar a viejos enemigos en un ambiente cargado de tensión política, racismo y violencia militar... Adaptación modernizada de la novela ''Vineland'', de Thomas Pynchon (1990), sobre los movimientos radicales de los años sesenta.","fr":"Bob Ferguson est un ancien révolutionnaire paranoïaque et désabusé, qui a jadis œuvré avec son ex, Perfidia, au sein du French 75, un groupe militant voué au renversement du gouvernement américain. Seize ans plus tard, Bob vit seul avec sa fille, Willa, quand celle-ci disparaît soudainement. Bob soupçonne son vieil ennemi d’antan, le Colonel Steven J. Lockjaw, d’être responsable de sa disparition. Il décide alors de renouer avec ses anciens frères d’armes pour retrouver sa fille, quitte à confronter les fantômes de son passé.","en":"Washed-up revolutionary Bob exists in a state of stoned paranoia, surviving off-grid with his spirited, self-reliant daughter, Willa. When his evil nemesis resurfaces after 16 years and she goes missing, the former radical scrambles to find her, father and daughter both battling the consequences of his past.","de":"Vor 16 Jahren hat die Widerstandsgruppe namens „French 75“ auf einen Schlag 200 Häftlinge aus den Fängen des skrupellosen United States Immigration and Customs Enforcement – kurz: ICE – befreit. Danach verschwanden die Widerständler, darunter auch der von allen nur Ghetto Pat genannte Bob Ferguson, von der Bildfläche. Heute ist Bob getrieben von Paranoia, denn er fürchtet, dass es der damalige ICE-Colonel Steven J. Lockjaw immer noch auf ihn abgesehen hat."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/3TjxuSfBSkhB8OvBov7Dk4L0Bcd.jpg","es":"https://image.tmdb.org/t/p/w500/iZ1499F6hYxDxiqioy8oSUaxipG.jpg","fr":"https://image.tmdb.org/t/p/w500/vfoxYHHpSOadhOFCmNbtLG2WcUy.jpg","en":"https://image.tmdb.org/t/p/w500/lbBWwxBht4JFP5PsuJ5onpMqugW.jpg","de":"https://image.tmdb.org/t/p/w500/5k2WV1i6jcnbPmRhoXSEQWQGT9u.jpg"}'::jsonb WHERE id = 268;
UPDATE public.films SET tmdb_id = 38286, titoli_i18n = '{"it":"Tre uomini e una gamba","en":"Three Men and a Leg","de":"Tre uomini e una gamba","es":"Tres hombres y una pierna","fr":"Tre uomini e una gamba"}'::jsonb, trame_i18n = '{"it":"I tre amici Aldo, Giovanni e Giacomo si mettono in viaggio verso il sud Italia per il matrimonio di uno di loro con la futura moglie. Durante il tragitto il terzetto affronta varie peripezie, tra le quali l''incontro con una ragazza di cui Giacomo si innamora e il trasporto di una gamba di legno al suocero.","en":"Friends Aldo, Giovanni, and Giacomo cross Italy from north to south for Giacomo''s wedding: the father of the bride, a despotic magnate who is both their boss and father-in-law—since Aldo and Giovanni have also married into the family not for love but for money, a fate now awaiting Giacomo—has entrusted them with a priceless piece of modern art, one that looks just like a rather unremarkable wooden leg.","es":"Aldo, Giovanni y Giacomo se dirigen a la boda de éste último cuya prometida es hermana de las dos esposas de los primeros. Aunque entre ellos no existe una buena relación su amistad se va forjando durante el viaje, en el que transportan una costosa pierna de madera obra de un famoso escultor americano llamado Michel Garpez. (FILMAFFINITY)","fr":"Trois amis - Aldo, Giovanni et Giacomo - doivent se rendre de Milan à Gallipoli, dans les Pouilles, pour le mariage de Giacomo. Le père de la mariée, qui est aussi l''employeur et le beau-père d''Aldo et de Giovanni, est un homme d''affaires riche et vulgaire qui maltraite ses gendres et leur a confié la tâche de lui apporter une jambe de bois, œuvre d''un artiste célèbre."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/aUQhhVkB1XXUZ9MPGborY6MFYI8.jpg","en":"https://image.tmdb.org/t/p/w500/yhgfM1WTHu4Uiwa47FAGmBk4V7x.jpg","de":"https://image.tmdb.org/t/p/w500/aUQhhVkB1XXUZ9MPGborY6MFYI8.jpg","es":"https://image.tmdb.org/t/p/w500/lASu78osxKRP34a4Ln1ar7VNGhZ.jpg","fr":"https://image.tmdb.org/t/p/w500/aUQhhVkB1XXUZ9MPGborY6MFYI8.jpg"}'::jsonb WHERE id = 269;
UPDATE public.films SET tmdb_id = 38397, titoli_i18n = '{"it":"La leggenda di Al, John e Jack","en":"The Legend of Al, John and Jack","es":"La leggenda di Al, John e Jack","fr":"La leggenda di Al, John e Jack","de":"La leggenda di Al, John e Jack"}'::jsonb, trame_i18n = '{"it":"New York 1959. I tre gangster Al, John e Jack hanno il compito di uccidere Frankie per conto del boss. Sbagliano bersaglio e il boss da a loro un''altra possibilità: tenere d''occhio una persona a lui cara. Ma la fortuna non è dalla loro parte....","en":"Hapless Depression-era gangsters Al, John and Jack find out their boss wants to get rid of them and come up with a plan to sell him to the FBI, but Al''s short-term memory loss could make it difficult.","es":"Al Caruso, John Gresco y Jack Amoruso son tres gángsters que trabajan para la familia Genovese. Sin embargo, sus esfuerzos no provocan más que dolores de cabeza a la mafia, y cuando les dan la última oportunidad, encargándoles la protección de la tía de su jefe, se meterán en el mayor lío que jamás habían imaginado."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/t7Xb04P1uCUJ1LADWD5RfqWGyDu.jpg","en":"https://image.tmdb.org/t/p/w500/t7Xb04P1uCUJ1LADWD5RfqWGyDu.jpg","es":"https://image.tmdb.org/t/p/w500/t7Xb04P1uCUJ1LADWD5RfqWGyDu.jpg","fr":"https://image.tmdb.org/t/p/w500/t7Xb04P1uCUJ1LADWD5RfqWGyDu.jpg","de":"https://image.tmdb.org/t/p/w500/t7Xb04P1uCUJ1LADWD5RfqWGyDu.jpg"}'::jsonb WHERE id = 270;
UPDATE public.films SET tmdb_id = 38396, titoli_i18n = '{"en":"That''s Life","fr":"Così è la vita","es":"Così è la vita","de":"Così è la vita","it":"Così è la vita"}'::jsonb, trame_i18n = '{"en":"While on the run from the police, an unlikely companionship blossoms between a funny con man who just broke out of jail, the bumbling cop whose car he seized at gunpoint, and a nitpicking civilian he unwittingly took hostage.","es":"Aldo cumple condena por fraude con tarjetas de crédito. Cuando es llevado al juzgado en el coche de policía, se encuentra con una pistola en la guantera y obliga al agente a cambiar el rumbo. Por el camino se encuentran a Giovanni, que detiene el vehículo para denunciar el robo de su coche ignorando la situación, y también es tomado como rehén por Aldo.","it":"Soprannominato Bancomat per le sue imprese di falsificatore di carte di credito, Aldo sequestra in auto a Milano prima Giacomo, poliziotto di debole professionalità, e poi Giovanni, inventore di giocattoli. I tre se ne vanno in giro per mezza Italia (i monti dell''Abruzzo, in realtà), prima braccati dalla polizia e poi creduti morti. Diventano amici fino all''epilogo a sorpresa in chiave surrealista..."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/zcZxzcl79S3gaWWDGGHcFkjT9m2.jpg","fr":"https://image.tmdb.org/t/p/w500/zcZxzcl79S3gaWWDGGHcFkjT9m2.jpg","es":"https://image.tmdb.org/t/p/w500/zcZxzcl79S3gaWWDGGHcFkjT9m2.jpg","de":"https://image.tmdb.org/t/p/w500/zcZxzcl79S3gaWWDGGHcFkjT9m2.jpg","it":"https://image.tmdb.org/t/p/w500/zcZxzcl79S3gaWWDGGHcFkjT9m2.jpg"}'::jsonb WHERE id = 271;
UPDATE public.films SET tmdb_id = 50531, titoli_i18n = '{"en":"Ask Me If I''m Happy","it":"Chiedimi se sono felice","de":"Chiedimi se sono felice","fr":"Demandez-moi si je suis heureux","es":"Pregúntame si soy feliz"}'::jsonb, trame_i18n = '{"en":"Aspiring thespians Aldo, Giovanni and Giacomo work dead-end jobs while nurturing their dream production of Cyrano de Bergerac, until love for the same woman tears their friendship apart. Three years later, Giovanni and Giacomo reunite after learning that Aldo is dying.","it":"Aldo, Giovanni e Giacomo, tre grandi amici, sbarcano il lunario lavorando rispettivamente come comparsa nelle opere liriche, statua vivente ai Grandi Magazzini, doppiatore di ruoli irrelevanti. Ma sono anche tre aspiranti attori di teatro con un sogno nel cassetto: mettere in scena una loro particolare versione di \"Cyrano de Bergerac\".","fr":"James rencontre John, un ami proche de son, avec qui il avait disputé il y a trois ans et le persuade d''aller visiter leur troisième ami Aldo, qui est en train de mourir en Sicile. À travers des flashbacks, nous apprenons leur histoire: Aldo était le fantôme dans les opéras, James a été le doublage des films où il avait seulement de faire du bruit sans même parler et John vivants mannequin les Grands magasins. Insatisfait de leur carrière, ils tentent de réaliser leur rêve de mettre en scène un spectacle de leur propre. Les femmes du mal cependant les séparer ...","es":"Giovanni y Giacomo, después de tres años sin hablarse, viajan juntos en tren con la mujer causante de su enemistad. Viajan para ver al tercer amigo en discordia, Aldo, enfermo de gravedad. Los tres eran grandes amigos que preparaban representar una versión teatral de Cyrano de Bergerac. Grandes amigos que se ayudaban mtuamente en todo, incluído sus líos con las mujeres. Pero ellas también pueden romper grandes amistades..."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/7DtDnWwmZAI3dYUKNPsRy24SxV3.jpg","it":"https://image.tmdb.org/t/p/w500/7DtDnWwmZAI3dYUKNPsRy24SxV3.jpg","de":"https://image.tmdb.org/t/p/w500/7DtDnWwmZAI3dYUKNPsRy24SxV3.jpg","fr":"https://image.tmdb.org/t/p/w500/7DtDnWwmZAI3dYUKNPsRy24SxV3.jpg","es":"https://image.tmdb.org/t/p/w500/7DtDnWwmZAI3dYUKNPsRy24SxV3.jpg"}'::jsonb WHERE id = 272;
UPDATE public.films SET tmdb_id = 57112, titoli_i18n = '{"en":"Have You Met Claudia?","it":"Tu la conosci Claudia?","de":"Tu la conosci Claudia?","es":"Tu la conosci Claudia?","fr":"Tu la conosci Claudia?"}'::jsonb, trame_i18n = '{"en":"Claudia is married with Giovanni, a rather dull type. Meek Giacomo is happily divorced, until he meets her. Aldo is a colorful cabbie with whom she had an affair. Who''ll win her heart?","it":"Giovanni, un uomo abitudinario la cui massima aspirazione è vedere \"Passaparola\" sul divano, magari con accanto la moglie Claudia.  Aldo, un tassista innamorato, innamoratissimo di Claudia.  Giacomo, un uomo solo, separato dalla moglie, rimasto un po'' troppo adolescente. Un giorno conosce Claudia e la sua vita cambia.  E'' la stessa Claudia a raccontarci di loro a partire da un prologo che non va perso per nessun motivo."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/4MbovTjSHv2AvcK39qUaEYeNuyl.jpg","it":"https://image.tmdb.org/t/p/w500/4MbovTjSHv2AvcK39qUaEYeNuyl.jpg","de":"https://image.tmdb.org/t/p/w500/4MbovTjSHv2AvcK39qUaEYeNuyl.jpg","es":"https://image.tmdb.org/t/p/w500/4MbovTjSHv2AvcK39qUaEYeNuyl.jpg","fr":"https://image.tmdb.org/t/p/w500/4MbovTjSHv2AvcK39qUaEYeNuyl.jpg"}'::jsonb WHERE id = 273;
UPDATE public.films SET tmdb_id = 88, titoli_i18n = '{"en":"Dirty Dancing","es":"Dirty Dancing","it":"Dirty Dancing - Balli proibiti","de":"Dirty Dancing","fr":"Dirty Dancing"}'::jsonb, trame_i18n = '{"en":"Expecting the usual tedium that accompanies a summer in the Catskills with her family, 17-year-old Frances ''Baby'' Houseman is surprised to find herself stepping into the shoes of a professional hoofer—and unexpectedly falling in love.","es":"Johnny Castle es un experto profesor de baile y un amante consumado. Por su parte, Baby Houseman es una aburrida e inocente adolescente de 17 años. Durante el transcurso de un verano, en un balneario para clases acomodadas, el encuentro entre ambos causará más de un recelo, a causa de sus distintos orígenes sociales. Entre ambos media un abismo pero, cuando la música suena, sus cuerpos se abrazan al ritmo del dirty dancing y todos esos detalles desaparecen de repente...","it":"Aspettandosi la solita noia che accompagna un''estate nelle Catskills con la sua famiglia, la diciassettenne Frances \"Baby\" Houseman si ritrova nei panni di una ballerina professionista con l''amore che bussa inaspettatamente.","de":"Francis „Baby“ Houseman ist ein Mädchen aus reichem Hause. Sie und ihre Familie verbringen die Sommerferien 1963 in Max Kellermans Hotel, wo Baby dem feschen Tanzlehrer Johnny Castle begegnet - seine Show lässt auch in ihr die Lust steigen, zu tanzen. Doch der Mambogott hat nichts übrig für verwöhnte Mädels aus der Oberschicht. Dann aber fällt seine Tanzpartnerin Penny wegen einer ungewollten Schwangerschaft aus und Baby bietet ihre Hilfe an. Nun soll sie im Schnelldurchgang die komplizierten Figuren des Mambos lernen. Das Paar kommt sich auch emotional schnell näher, muss auf seinem Weg aber diversen Problemen trotzen: eine Reihe von Diebstählen und die goldene Hotelregel, dass Personal und Gäste durch eine unsichtbare Linie voneinander getrennt bleiben müssen, machen Baby und Johnny zu schaffen...","fr":"En 1963. Bébé – de son vrai prénom Frédérique – fille d’une riche famille, passe ses vacances avec ses parents et sa sœur à la pension de la famille Kellerman dans l’État de l’Oregon. Elle va être confrontée à un monde qui lui est complètement étranger, celui de la danse, et vivre une histoire d’amour avec Johnny, l’un des professeurs de danse de l’établissement, issu d’un milieu social très différent. Film à petit budget d’Émile Ardolino, il deviendra l’un des plus grand succès des années 80."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/9Jw6jys7q9gjzVX5zm1z0gC8gY9.jpg","es":"https://image.tmdb.org/t/p/w500/4uGWtDrtPLoMiEjotQaqZTDnqUn.jpg","it":"https://image.tmdb.org/t/p/w500/4wj0T7FSD2FohE1IHAXU3brpL4U.jpg","de":"https://image.tmdb.org/t/p/w500/m9T9x2EXIyPssM6hFq5okkeeAk4.jpg","fr":"https://image.tmdb.org/t/p/w500/osfBQ18P0y3pwT5qVuhdPk8btbj.jpg"}'::jsonb WHERE id = 274;
UPDATE public.films SET tmdb_id = 2898, titoli_i18n = '{"it":"Qualcosa è cambiato","en":"As Good as It Gets","es":"Mejor... imposible","fr":"Pour le pire et pour le meilleur","de":"Besser geht''s nicht"}'::jsonb, trame_i18n = '{"it":"Lui è un misantropo razzista, villano, paranoico, ossessionato da tic e complessi. Ma nella sua eccentrica vita stanno per entrare un pittore omosessuale con il suo delizioso cagnolino e una ragazza-madre che fa la cameriera.","en":"A misanthropic author, a single mother and waitress, and a gay artist form an unlikely friendship after the artist is assaulted in a robbery.","es":"Melvin Udall, un escritor obsesivo y maniático, es uno de los seres más desagradables y desagradecidos que uno pueda tener como vecino. Pero, un buen día, tiene que hacerse cargo de un perro al que odia a muerte. La presencia en su vida del animal ablandará su corazón.","fr":"Melvin Udall, un écrivain misanthrope, écrit à la chaîne des romans sentimentaux qui comblent son sens pervers de l''autodérision et lui permettent de vivre confortablement. Sa vie est réglée comme du papier à musique, il évite le contact humain hormis celui de Carol Connelly, une jeune mère célibataire, serveuse dans un restaurant où il prend ses repas. Un jour, Simon Bishop, son voisin, artiste gay, est défiguré par deux voyous, le fils de Carol tombe malade et Melvin hérite du chien de Simon pendant son séjour à l''hôpital. Sa vie en est toute bouleversée.","de":"Melvin Udall ist ein brillanter Autor von Liebesromanen in New York. Gleichzeitig ist er aber auch ein Misanthrop, ein Grobian und ein Neurotiker, versehen mit einer ganzen Reihe seltsamer Ticks und Vorurteilen und ungeübt im Umgang mit anderen Menschen. Sein einziger menschlicher Kontakt ist seine Stammkellnerin in seinem Stammrestaurant, die jedoch andere Sorgen als ihn hat. Auch seinem schwulen Nachbarn Simon Bishop gegenüber ist er äußerst unfreundlich, muss aber eines Tages den verhassten Hund des Nachbarn zur Pflege aufnehmen. Und der Hund schafft, was niemand für möglich gehalten hat: Melvins Panzer beginnt zu bröckeln; er fängt an, Simon zu helfen, als dieser in Not gerät und bemüht sich, seine Gefühle für die Kellnerin Carol zu formulieren. Natürlich hat er da noch eine Menge aufzuholen, doch er bemüht sich, so gut es geht."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/tmwubiSQ4IwJbRqSoyNFb7tMAVg.jpg","en":"https://image.tmdb.org/t/p/w500/xXxuJPNUDZ0vjsAXca0O5p3leVB.jpg","es":"https://image.tmdb.org/t/p/w500/zr9FWAFnjeBugw725udOypnXXMY.jpg","fr":"https://image.tmdb.org/t/p/w500/7DnNgfY9l8flUtqdF21sJCt84S6.jpg","de":"https://image.tmdb.org/t/p/w500/nUVlD7hfxTWsYD4eTb8JDwjngTS.jpg"}'::jsonb WHERE id = 275;
UPDATE public.films SET tmdb_id = 516043, titoli_i18n = '{"it":"Arrivano i prof","es":"Llegan los profes","de":"Arrivano i prof","fr":"Arrivano i prof","en":"Here Come the Teachers"}'::jsonb, trame_i18n = '{"it":"Mentre (quasi) tutti festeggiano le promozioni all''esame di maturità, al liceo Alessandro Manzoni c''è grande preoccupazione: solo il 12% degli studenti è riuscito a conseguire il diploma. Il Manzoni ha un primato assoluto: è il peggior liceo d''Italia. Non sapendo più che soluzioni adottare, il Preside accoglie la proposta del Provveditore e decide di fare un ultimo, estremo, rischioso tentativo: reclutare i peggiori insegnanti in circolazione selezionati dall''algoritmo ministeriale nella speranza che dove hanno fallito i migliori, possano riuscire i peggiori. Obiettivo: avere almeno il 50% di promossi.","es":"Mientras (casi) todos festejan el aprobado del examen de madurez, en el instituto Alessandro Manzoni hay una gran preocupación: solo el 12% de los estudiantes ha logrado obtener el diploma. El Manzoni tiene un récord absoluto: es el peor instituto de Italia. No sabiendo ya que medidas adoptar, el Director escucha la propuesta del Superintendente y decide llevar a cabo un último, extremo y arriesgado intento: reclutar a los peores profesores en activo seleccionados por un algoritmo del ministerio con la esperanza que donde han fracasado los mejores, puedan triunfar los peores. Objetivo: tener al menos un 50% de aprobados.","en":"The Manzoni High School in Milan is the worst in Italy. When the percentage of those promoted falls to 12%, it''s time for the last resort: to entrust the classes to the worst of the available teachers."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/mBc8UOa5VxdgLfY5qYWZvuboJKq.jpg","es":"https://image.tmdb.org/t/p/w500/mBc8UOa5VxdgLfY5qYWZvuboJKq.jpg","de":"https://image.tmdb.org/t/p/w500/mBc8UOa5VxdgLfY5qYWZvuboJKq.jpg","fr":"https://image.tmdb.org/t/p/w500/mBc8UOa5VxdgLfY5qYWZvuboJKq.jpg","en":"https://image.tmdb.org/t/p/w500/mBc8UOa5VxdgLfY5qYWZvuboJKq.jpg"}'::jsonb WHERE id = 276;
UPDATE public.films SET tmdb_id = 9802, titoli_i18n = '{"it":"The Rock","fr":"Rock","en":"The Rock","es":"La roca","de":"The Rock - Fels der Entscheidung"}'::jsonb, trame_i18n = '{"it":"The Rock veniva chiamata la prigione di Alcatraz, chiusa nel 1963. La leggenda racconta che mai un solo detenuto sia riuscito a evadere da quella \"rocca\" situata proprio nel mezzo della baia di San Francisco. È proprio in quella prigione, divenuta meta turistica, che un generale dei marines nasconde tre missili con testate di gas nervino: vuole protestare per come il governo ha trattato i reduci del Vietnam. Se non gli daranno un centinaio di milioni di dollari farà esplodere i missili su San Francisco. A risolvere la situazione vengono chiamati un chimico e un ex agente inglese, l''unico detenuto che sia riuscito, trent''anni prima, a evadere da Alcatraz. Complice un certo pentimento del generale, i due riescono nell''impresa.","fr":"Excédé par l’injustice de son gouvernement, le Général Hummel se rend maître de l’île d’Alcatraz et menace de lancer un gaz mortel sur San Francisco. Deux hommes sont chargés de le contrer : un expert en armes chimiques, Stanley Goodspeed, et John Patrick Mason, l’unique prisonnier à s’être évadé d’Alcatraz… Ils se rendent ensemble sur l’île afin de stopper les projets destructeurs du Général.","en":"When vengeful General Francis X. Hummel seizes control of Alcatraz Island and threatens to launch missiles loaded with deadly chemical weapons into San Francisco, only a young FBI chemical weapons expert and notorious Federal prisoner have the skills to penetrate the impregnable island fortress and take him down.","es":"Un grupo de soldados renegados roba un arma química y toma la antigua cárcel de Alcatraz con 81 turistas como rehenes. Su líder, un general del ejército muy condecorado, pide 100 millones de dólares para entregárselos a las familias de los soldados muertos en operaciones secretas llevadas a cabo por el ejército. Un equipo de élite y un recluso, que en su día pudo huir de Alcatraz, y que conoce los pasadizos que pueblan la prisión, tratarán de evitar que una gran catástrofe se produzca.","de":"Der Beatles-Fan und FBI-Bombenexperte Stanley Goodspeed wird zu einem Notfalleinsatz auf Alacatraz gerufen. Auf der Gefängnisinsel hat sich General Hummel mit einer Hand voll Söldnern verschanzt, um mit Geiseln und Giftgasraketen 100 Millionen Dollar für die Hinterbliebenen gefallener Golfkriegs-Soldaten zu erpressen. Goodspeed soll die Raketen entschärfen, doch nur der Ex-Agent Patrick Mason kennt den Weg in die Festung…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/leBDsXawQQ6ue7xlB6fIjXEZMZz.jpg","fr":"https://image.tmdb.org/t/p/w500/5TU2NRk8aP40o7IDck0RF24TCyj.jpg","en":"https://image.tmdb.org/t/p/w500/eBcoxveWzzXQrCrwWMGAROcqgpP.jpg","es":"https://image.tmdb.org/t/p/w500/l6PuNPsNFx1UFWfQwjk1McPce4y.jpg","de":"https://image.tmdb.org/t/p/w500/n75Zv7O1S7acu306Njb56GoI0Fz.jpg"}'::jsonb WHERE id = 277;
UPDATE public.films SET tmdb_id = 118, titoli_i18n = '{"it":"La fabbrica di cioccolato","es":"Charlie y la fábrica de chocolate","fr":"Charlie et la Chocolaterie","de":"Charlie und die Schokoladenfabrik","en":"Charlie and the Chocolate Factory"}'::jsonb, trame_i18n = '{"it":"Charlie Bucket, proviene da una famiglia povera, e spende la maggior parte del suo tempo a sognare la cioccolata che adora, ma che di rado può permettersela. La sua vita cambia quando Willy Wonka, proprietario di una famosissima fabbrica di cioccolato, mette in palio cinque biglietti, nascosti in cinque barrette di cioccolato. I bambini che troveranno uno di questi biglietti potranno fare un tour nella fantastica fabbrica di cioccolato. Charlie trova miracolosamente un biglietto vincente...","es":"Charlie Bucket (Freddie Highmore), un niño muy bueno de una familia muy pobre, gana un concurso, junto a otros cuatro niños de diferentes partes del mundo, para disfrutar de una visita durante todo un día a la gigantesca fábrica de chocolate dirigida por el excéntrico Willy Wonka (Johnny Depp) y su equipo de Oompa-Loompas. La fábrica se parece a un mundo fantástico y mágico lleno de diferentes sabores, todos muy dulces.","fr":"Charlie est un enfant issu d''une famille pauvre. Travaillant pour subvenir aux besoins des siens, il doit économiser chaque penny, et ne peut s''offrir les friandises dont raffolent les enfants de son âge. Pour obtenir son comptant de sucreries, il participe à un concours organisé par l''inquiétant Willy Wonka, le propriétaire de la fabrique de chocolat de la ville. Celui qui découvrira l''un des cinq tickets d''or que Wonka a caché dans les barres de chocolat de sa fabrication gagnera une vie de sucreries.","de":"Seit langem hat niemand mehr den exzentrischen Schokoladenhersteller Willy Wonka gesehen. Eines Tages gewährt der bizarr ausstaffierte Fabrikbesitzer fünf Kindern samt Begleitperson freien Eintritt in seine Fabrik - vorausgesetzt, sie besitzen eines der goldenen Tickets, die nach dem Zufallsprinzip in den Wonka-Schokoladentafeln verteilt wurden. Gegen jede Wahrscheinlichkeit findet der bettelarme Charlie das letzte Ticket und schon am nächsten Tag geht''s los mit der abenteuerlichsten Sightseeingtour der Schokoladengeschichte.","en":"A young boy wins a tour through the most magnificent chocolate factory in the world, led by the world''s most unusual candy maker."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/w2Q8Zx1RCM0aAuG36nOXXJ6pV0u.jpg","es":"https://image.tmdb.org/t/p/w500/voJEk0WNtrcawz2hN9AwdNbvhrp.jpg","fr":"https://image.tmdb.org/t/p/w500/tR4PU2wRPzGKmF665lE5wULGb3X.jpg","de":"https://image.tmdb.org/t/p/w500/wdxuboDikf0srdcQ0nf2uAwbKpR.jpg","en":"https://image.tmdb.org/t/p/w500/iKP6wg3c6COUe8gYutoGG7qcPnO.jpg"}'::jsonb WHERE id = 278;
UPDATE public.films SET tmdb_id = 105, titoli_i18n = '{"en":"Back to the Future","it":"Ritorno al futuro","es":"Regreso al futuro","fr":"Retour vers le futur","de":"Zurück in die Zukunft"}'::jsonb, trame_i18n = '{"en":"Eighties teenager Marty McFly is accidentally sent back in time to 1955, inadvertently disrupting his parents'' first meeting and attracting his mother''s romantic interest. Marty must repair the damage to history by rekindling his parents'' romance and - with the help of his eccentric inventor friend Doc Brown - return to 1985.","it":"Marty McFly è stato catapultato per errore nel 1955, grazie alla macchina del tempo ideata dal suo amico scienziato Doc. Non avendo più \"carburante\" per poter tornare nel futuro si rivolge alla versione più giovane di Doc, che nonostante l''incredulità iniziale si farà in quattro per aiutarlo. Ma nel 1955 non è solo Doc ad essere più giovane, Marty infatti si imbatte casualmente nei suoi genitori, all''epoca teenager, ma l''incontro aggiungerà altri problemi.","es":"El adolescente Marty McFly es amigo de Doc, un científico al que todos toman por loco. Cuando Doc crea una máquina para viajar en el tiempo, un error fortuito hace que Marty llegue a 1955, año en el que sus futuros padres aún no se habían conocido. Después de impedir su primer encuentro, deberá conseguir que se conozcan y se casen; de lo contrario, su existencia no sería posible.","fr":"En 1985, Marty, un adolescent comme les autres, mène une existence morne et ennuyeuse. Heureusement, il est épris de la jolie Jennifer et entretient une profonde amitié avec Doc, un savant fou qui prétend avoir inventé une machine à explorer le temps. Un jour, Doc invite Marty à l''essayer…","de":"Der Teenager Marty McFly wird mit der Zeitmaschine seines Freundes, dem skurrilen Wissenschaftler Dr. Emmett Brown, versehentlich ins Jahr 1955 geschleudert. Dort verhindert er zunächst unabsichtlich, dass sich seine zukünftigen Eltern kennen lernen und in einander verlieben, womit er seine eigene Zeugung gefährdet. Zu allem Überfluss verguckt sich seine Mutter auch noch in ihn. Ihm bleibt nun eine Woche Zeit, seinen tollpatschigen Vater mit seiner Mutter zu verkuppeln und gemeinsam mit Docs dreißig Jahre jüngerem alter Ego einen Plan zu entwickeln, wie sie das bevorstehende große Gewitter nutzen können, um ihn in die Gegenwart zurück zu schicken."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/vN5B5WgYscRGcQpVhHl6p9DDTP0.jpg","it":"https://image.tmdb.org/t/p/w500/isqoi7kuUsR5Drlqdh4ZfMULgox.jpg","es":"https://image.tmdb.org/t/p/w500/owk40tn1sFJmC7bhamEpmhdZPKa.jpg","fr":"https://image.tmdb.org/t/p/w500/iCgFtDUZxN8iUzNBCisjUrBmg2q.jpg","de":"https://image.tmdb.org/t/p/w500/i9cmMivQ8cgTYUjfrzznsFJ0GYg.jpg"}'::jsonb WHERE id = 279;
UPDATE public.films SET tmdb_id = 165, titoli_i18n = '{"it":"Ritorno al futuro - Parte II","en":"Back to the Future Part II","fr":"Retour vers le futur II","es":"Regreso al futuro II","de":"Zurück in die Zukunft II"}'::jsonb, trame_i18n = '{"it":"Il film comincia dove terminava il primo capitolo, ovvero con Marty e Jennifer che partono insieme allo scienziato Doc, inventore della macchina del tempo, per il 2015 allo scopo di evitare che il futuro dei loro figli possa essere in pericolo. Ma la situazione precipita e ad essere in pericolo non è più il futuro, ma il passato. Marty dovrà tornare nuovamente nel 1955 e...","en":"Marty and Doc are at it again as the time-traveling duo head to 2015 to nip some McFly family woes in the bud. But things go awry thanks to bully Biff Tannen and a pesky sports almanac. In a last-ditch attempt to set things straight, Marty finds himself bound for 1955 and face to face with his teenage parents -- again.","fr":"En 1985, Marty McFly a retrouvé sa famille et sa petite amie après un voyage mouvementé dans le passé. Surgit alors Doc Brown, au volant de sa machine à explorer le temps. Il lui enjoint de le suivre dans le futur, en l''an 2015, pour secourir son fils tombé sous la coupe du sinistre Biff Tannen.","es":"Aunque a Marty McFly todavía le falta tiempo para asimilar el hecho de estar viviendo dentro de la familia perfecta gracias a su anterior viaje en el tiempo, no le queda ni espacio para respirar cuando su amigo Doc aparece de improviso con la máquina del tiempo (mucho más modernizada), e insta a que le acompañen él y su novia a viajar al futuro para solucionar un problema con la ley que tendrá uno de sus futuros hijos. En la tremenda vorágine futurista, con todo lo que ello conlleva, del Hill Valley de 2015, la presencia de tales viajeros temporales causará un efecto mayor que el que iban a arreglar. Un almanaque deportivo y la posesión del secreto de la existencia de la máquina del tiempo por parte del siempre villano Biff Tannen, serán los ingredientes que conjugarán una causa-efecto en el pasado, en el presente y en el propio futuro, que hará que Marty y Doc se tengan que emplear a fondo para poner fin a la catástrofe a la que les lleva el destino.","de":"Nachdem Doc Brown am Ende des ersten Teiles Marty mit in die Zukunft genommen hat, sieht er nun selbst, was aus ihm werden wird - ein abgehalfterter Angestellter, der am Ende der Karriereleiter steht.Marty und Doc Brown versuchen, der Zukunft einen kleinen Schubser in die richtige Richtung zu geben. Doch Biff gibt seiner eigenen Zukunft durch einen Fehler Martys eine neue Wendung - und dieser Fehler muß nun ausgebügelt werden..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/AbwX5BzdmfA0WFBxBF909Gf4Sop.jpg","en":"https://image.tmdb.org/t/p/w500/hQq8xZe5uLjFzSBt4LanNP7SQjl.jpg","fr":"https://image.tmdb.org/t/p/w500/pvSf95zo0GZNp83QCtmK1GFLHtT.jpg","es":"https://image.tmdb.org/t/p/w500/oTiQdzBOP5biNvzvrSPAvPxiSKH.jpg","de":"https://image.tmdb.org/t/p/w500/9m396LRrW2PwIKAogU19pnGpJCI.jpg"}'::jsonb WHERE id = 280;
UPDATE public.films SET tmdb_id = 196, titoli_i18n = '{"it":"Ritorno al futuro - Parte III","en":"Back to the Future Part III","es":"Regreso al futuro III","fr":"Retour vers le futur III","de":"Zurück in die Zukunft III"}'::jsonb, trame_i18n = '{"it":"Per questa terza, conclusiva, puntata della trilogia, Marty McFly è costretto a tornare indietro nel tempo fino al 1885 per salvare Doc, che vi era stato catapultato al termine del secondo capitolo. Questa volta tornare nel futuro sarà ancora più difficile.","en":"The final installment finds Marty digging the trusty DeLorean out of a mineshaft and looking for Doc in the Wild West of 1885. But when their time machine breaks down, the travelers are stranded in a land of spurs. More problems arise when Doc falls for pretty schoolteacher Clara Clayton, and Marty tangles with Buford Tannen.","es":"Marty McFly sigue en 1955 y su amigo Doc ha retrocedido al año 1885, la época del salvaje oeste. Éste le envía una carta donde comenta que la máquina del tiempo está averiada, y que es imposible repararla. Sin embargo no le preocupa estar atrapado en el pasado, pues allí es muy feliz trabajando de herrero aunque convive con malhechores. Pero Marty descubre una vieja tumba en la que lee que Doc murió en 1885 y, sin pensárselo dos veces, irá a rescatar a su amigo.","fr":"Ce troisième épisode propulse Marty sur une toute nouvelle mission… en l''an 1885, en plein Far West ! Il n''a que cinq jours pour sauver son ami Doc des griffes du terrible Buford \"Molosse\" Tannen et ainsi lui éviter la mort. Cependant, bon nombre d''embûches vont empêcher nos deux voyageurs de rentrer rapidement vers le futur : ils devront faire face à une panne de la DeLorean, leur très célèbre machine à remonter le temps, affronter une bande de hors-la-loi et croiser sur leur route une maîtresse d''école dont le charme ne laissera pas insensible ce bon vieux Doc…","de":"Als Dr. Emmett Brown im Jahre 1955 bei einem Landeversuch mit dem DeLorean vom Blitz getroffen wird, katapultiert ihn die Zeitmaschine in das Jahr 1885. Sofort schreibt er Marty McFly einen Brief, in dem er seinen Freund darüber unterrichtet, dass es ihm gut gehe und er seinen Lebensabend gern in dieser Epoche verbringen würde. Dank des zuverlässigen Postsystems erreicht der Brief Marty 70 Jahre später, direkt nachdem dieser mit ansehen musste, wie die Zeitmaschine im bewölkten Nachthimmel von Hill Valley verschwand. Kurz darauf findet Marty allerdings heraus, dass der schrullige Wissenschaftler eine Woche nach seiner Ankunft im Wilden Westen erschossen wird. Um dies zu vereiteln, begibt er sich kurzerhand selbst auf die Reise in das Jahr 1885."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/iBfwdp2Sp4aWH9QaHUqFq25sxIU.jpg","en":"https://image.tmdb.org/t/p/w500/crzoVQnMzIrRfHtQw0tLBirNfVg.jpg","es":"https://image.tmdb.org/t/p/w500/yamBr3ihlWFF9jh3oOODSvjDY2e.jpg","fr":"https://image.tmdb.org/t/p/w500/xormrixo6PYdjyh31JWT2LCBmjO.jpg","de":"https://image.tmdb.org/t/p/w500/9VCSpNGyHBwwZRFF8zwgzcoA7tC.jpg"}'::jsonb WHERE id = 281;
UPDATE public.films SET tmdb_id = 278, titoli_i18n = '{"it":"Le ali della libertà","en":"The Shawshank Redemption","es":"Cadena perpetua","fr":"Les Évadés","de":"Die Verurteilten"}'::jsonb, trame_i18n = '{"it":"Siamo nel 1946. Processato per l''omicidio della moglie e del suo amante, Andy, un bancario del New England, viene condannato a un doppio ergastolo e recluso nel penitenziario di Shawshank. All''inizio è vittima delle violenze dei reclusi, poi però diventa il consulente finanziario delle guardie. Scopre così che il direttore falsifica i libri contabili intestando i conti a un fittizio Randall Stevens. Fuggito di prigione attraverso un tunnel costruito negli anni, Andy assume l''identità di Randall Stevens, denuncia il direttore e va in Messico.","en":"Imprisoned in the 1940s for the double murder of his wife and her lover, upstanding banker Andy Dufresne begins a new life at the Shawshank prison, where he puts his accounting skills to work for an amoral warden. During his long stretch in prison, Dufresne comes to be admired by the other inmates -- including an older prisoner named Red -- for his integrity and unquenchable sense of hope.","es":"Acusado del asesinato de su mujer, Andrew Dufresne, tras ser condenado a cadena perpetua, es enviado a la prisión de Shawshank. Con el paso de los años conseguirá ganarse la confianza del director del centro y el respeto de sus compañeros presidiarios, especialmente de Red, el jefe de la mafia de los sobornos.","fr":"En 1947, Andy Dufresne, un jeune banquier, est condamné à la prison à vie pour le meurtre de sa femme et de son amant. Ayant beau clamer son innocence, il est emprisonné à Shawshank, le pénitencier le plus sévère de l''État du Maine. Il y fait la rencontre de Red, un noir désabusé, détenu depuis vingt ans. Commence alors une grande histoire d''amitié entre les deux hommes…","de":"Das Shawshank Gefängnis in den 30ern: der wegen Mordes an seiner Frau verurteilte Andy Dufresne kommt als Neuling lebenslänglich hinter Gittern. Zurückhaltend wie er ist, ist er ständig das Ziel sexueller Angriffe, doch als er als Banker durchblicken läßt, daß er finanziell für den Direktor und die Wärter eine Menge tun kann, ist für seine Sicherheit gesorgt. Langsam aber sicher freundet er sich mit dem Langzeitinsassen Red an, baut die Gefängnisbibliothek auf und rückt nie von seiner Überzeugung ab, unschuldig zu sein. Viele Jahre vergehen, bis etwas geschieht, was sogar Reds Leben für immer verändern wird..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/9OxcvTJwZDjQTFvY2NxiwnSrQS6.jpg","en":"https://image.tmdb.org/t/p/w500/9cqNxx0GxF0bflZmeSMuL5tnGzr.jpg","es":"https://image.tmdb.org/t/p/w500/uRRTV7p6l2ivtODWJVVAMRrwTn2.jpg","fr":"https://image.tmdb.org/t/p/w500/t30GjttOdb5At1sYy8b3TOwFgWV.jpg","de":"https://image.tmdb.org/t/p/w500/78Pb6FMLMfpm1jUOKTniwREYgAN.jpg"}'::jsonb WHERE id = 282;
UPDATE public.films SET tmdb_id = 510, titoli_i18n = '{"es":"Alguien voló sobre el nido del cuco","en":"One Flew Over the Cuckoo''s Nest","it":"Qualcuno volò sul nido del cuculo","de":"Einer flog über das Kuckucksnest","fr":"Vol au-dessus d''un nid de coucou"}'::jsonb, trame_i18n = '{"es":"Randle McMurphy (Jack Nicholson), un violador de espíritu libre, que vive contracorriente, es recluido en un hospital psiquiátrico. La inflexible disciplina del centro acentúa su contagiosa tendencia al desorden, que acabará desencadenando una guerra entre los pacientes y el personal de la clínica con la fría y severa enfermera Ratched (Louise Fletcher) a la cabeza. La suerte de cada paciente del pabellón está en juego.","en":"A petty criminal fakes insanity to serve his sentence in a mental ward rather than prison. He soon finds himself as a leader to the other patients—and an enemy to the cruel, domineering nurse who runs the ward.","it":"Candle McMurphy, arrestato per piccoli reati, viene portato in una clinica psichiatrica: tenta di fingersi pazzo per sfuggire al carcere. Qui viene a contatto con gli altri pazienti dei quali diventa ben presto il beniamino: si prende gioco delle sedute di psicoanalisi, si improvvisa telecronista, organizza una piccola gita in barca. L''ospedale è diretto dalla ferrea capoinfermiera, la signorina Ratched che ha organizzato la vita dei pazienti secondo regole di intransigente disciplina.","de":"McMurphy ist ein krimineller gesellschaftlicher Außenseiter. Mitte dreißig, ehemaliger Korea-Kämpfer, wegen Ungehorsam aus der Armee entlassen, wird er wegen Schlägereien, Notzucht und Trunksucht in eine Strafanstalt eingeliefert. Von dort aus lässt er sich mit einem Trick zur Beobachtung in eine psychiatrische Anstalt überweisen. In die graue Welt einer anonymen Heilanstalt wird McMurphy eines Tages eingeliefert. Er findet dort ein unmenschliches System vor, das seine hilf- und willenlosen Patienten in „Chronische“ (schwere Fälle) und „Akute“ (leichte Fälle) aufteilt. Eine despotische Oberschwester unterdrückt mit einer Schar brutaler Wärter jede individualistische Regung. Der Zustand der Kranken wird mit pharmazeutischen Mitteln oder Elektroschock-Therapie „behandelt“ und dadurch noch weiter verschlechtert. In diesem System muss McMurphy wie ein Katalysator wirken … er stellt das System der Irrenanstalt in Frage und wiegelt die Insassen auf.","fr":"Randle P. McMurphy se fait interner pour échapper à la prison. Il va être touché par la détresse et la solitude des patients. Très rapidement, il comprend que l’infirmière en chef, Mlle Ratched, a imposé des règles strictes et entend bien les faire respecter. Il décide alors de révolutionner ce petit monde, plutôt au départ par jeu."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/lBYmCynNEPt7HVaJvuXgfHvLhbJ.jpg","en":"https://image.tmdb.org/t/p/w500/kjWsMh72V6d8KRLV4EOoSJLT1H7.jpg","it":"https://image.tmdb.org/t/p/w500/hpg2j8FhnnmbiRpoOU09M0sffJu.jpg","de":"https://image.tmdb.org/t/p/w500/8ifFMKq21P0A2xV4q7K5VfuR4Cp.jpg","fr":"https://image.tmdb.org/t/p/w500/r5b2ub7GMawCWDP5vHR1MXpV7vU.jpg"}'::jsonb WHERE id = 283;
UPDATE public.films SET tmdb_id = 642, titoli_i18n = '{"de":"Zwei Banditen","es":"Dos hombres y un destino","fr":"Butch Cassidy et le Kid","it":"Butch Cassidy","en":"Butch Cassidy and the Sundance Kid"}'::jsonb, trame_i18n = '{"de":"Um die Jahrhundertwende planen die beiden berühmt-berüchtigten Desperados Butch Cassidy  und Sundance Kid  den Zug der Union Pacific gleich zweimal zu überfallen: nämlich auf der Hin- und auf der Rückfahrt. Doch diese Dreistigkeit lässt sich die Regierung nicht gefallen: Von einer Elitetruppe werden die beiden bis zur Erschöpfung gejagt","es":"Un grupo de jóvenes pistoleros se dedica a asaltar los bancos del estado de Wyoming y el tren-correo de la Union Pacific. El jefe de la banda es el carismático Butch Cassidy, y Sundance Kid es su inseparable compañero. Un día, después de un atraco, el grupo se disuelve. Será entonces cuando Butch, Sundance y una joven maestra de Denver formen un trío de románticos forajidos que, huyendo de la ley, llegan hasta Bolivia.","fr":"Au début du XXème siècle, Butch Cassidy et son ami Sundance Kid pillent les trains et les banques. Les deux malfrats élaborent un plan ingénieux qui leur permet de dévaliser deux fois le même convoi, mais les autorités sont sur leur piste. Le Kid retrouve son amie, Etta Place, une jeune institutrice, et Butch Cassidy improvise avec elle un brillant numéro à bicyclette. La seconde attaque de l''Union Pacific oblige les deux complices et Etta à abandonner leurs amis et à fuir en Bolivie. Là, ils poursuivent leurs exploits criminels et ce, malgré la défection de la jeune femme, effrayée par la tournure que prennent les événements.","it":"Butch e Sundance sono due rapinatori che dopo ogni colpo, si rifugiano da una maestra innamorata di Sundance e corteggiata da Butch. Ma un giorno la Union Pacific, bersaglio di una loro rapina assolda un gruppo di guardie private ed allora i due rapinatori sono costretti a cambiare aria...","en":"As the west rapidly becomes civilized, a pair of outlaws in 1890s Wyoming find themselves pursued by a posse and decide to flee to South America in hopes of evading the law."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/wHF7wueTLjb7dqt1MCfLeLDuUP.jpg","es":"https://image.tmdb.org/t/p/w500/2w6Ik8P1E20KOH5ykQlfTjawAIf.jpg","fr":"https://image.tmdb.org/t/p/w500/okSvpbn4OBEHfjKeaN8ccZAvLAS.jpg","it":"https://image.tmdb.org/t/p/w500/7T9YNd236L9JXLeNTayHZgTrSHJ.jpg","en":"https://image.tmdb.org/t/p/w500/gFmmykF1Ym3OGzENo50nZQaD1dx.jpg"}'::jsonb WHERE id = 284;
UPDATE public.films SET tmdb_id = 9277, titoli_i18n = '{"en":"The Sting","de":"Der Clou","fr":"L''Arnaque","es":"El golpe","it":"La stangata"}'::jsonb, trame_i18n = '{"en":"A novice con man teams up with an acknowledged master to avenge the murder of a mutual friend by pulling off the ultimate big con and swindling a fortune from a big-time mobster.","de":"Chicago um 1930. Kleingauner Johnny Hooker und sein schwarzer Partner erleichtern unwissentlich den Geldkurier des mächtigen Unterweltbosses Lonnegan. Der lässt Johnnys Partner ermorden. Johnny wendet sich an den abgehalfterten Gauner Gondorff. Sie fädeln einen raffinierten Racheplan ein, setzen auf Lonnegans Wettleidenschaft. Mit Kollegen, die von Lonnegan reingelegt worden sind, errichten sie ein falsches Wettbüro. Johnny wird zum Schein von Gondorff erschossen, Lonnegans Millionen wandern in ihre Hände.","fr":"À Chicago, en 1936, Johnny Hooker et son acolyte Coleman volent sans le savoir le convoyeur de fonds de Doyle Lonnegan, un dangereux gangster de New York. Coleman est aussitôt abattu par le gang de ce dernier et Hooker se réfugie chez Henry Gondorff, un spécialiste de l''arnaque. Ceux-ci décident alors de venger la mort de Coleman en montant une vaste escroquerie destinée à mettre Lonnegan sur la paille. Pour cela, Hooker fait croire au gangster qu''il est capable d''obtenir les résultats des courses avant qu''ils ne soient officiellement connus.","es":"En Illinois, en 1936, dos ladrones dan un golpe a un hombre de confianza de un gángster y se embolsan un montón de dinero. El gángster decide vengarse y mata a uno de los que dieron el golpe, mientras que el otro logra escapar y entra en contacto con un ex compinche. Los dos deciden intentar un gran timo que hará temblar las finanzas del jefe de la mafia.","it":"Johnny Hooker e il suo amico Luther Coleman sono due truffatori di strada. Dopo aver raggirato il corriere del potente gangster Doyle Lonnegan, Luther viene ucciso per ritorsione e Hooker è costretto a fuggire e a nascondersi. Desiderando vendicare Luther, il giovane chiede aiuto ad un vecchio amico del defunto, Henry Gondorff, uno dei più bravi ed esperti truffatori degli Stati Uniti. Insieme organizzano una \"stangata\" ai danni di Lonnegan, creando una finta agenzia di scommesse in cui il boss crede di poter vincere facilmente delle ingenti somme di denaro, grazie a informazioni riservate."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/ckmYng37zey8INYf6d10cVgIG93.jpg","de":"https://image.tmdb.org/t/p/w500/nFTKS7mPP22a0V2YSj4aE38nhg.jpg","fr":"https://image.tmdb.org/t/p/w500/hUhnNuPZHjGDUDaLLnDVIiARLYN.jpg","es":"https://image.tmdb.org/t/p/w500/cnCv2NhtymMwq5oWSzoz6tXcjQf.jpg","it":"https://image.tmdb.org/t/p/w500/jnD4EA8uULiNGxk96jfheznoEwz.jpg"}'::jsonb WHERE id = 285;
UPDATE public.films SET tmdb_id = 539, titoli_i18n = '{"es":"Psicosis","en":"Psycho","it":"Psyco","de":"Psycho","fr":"Psychose"}'::jsonb, trame_i18n = '{"es":"Una joven secretaria, tras cometer un robo, se marcha de la ciudad y conduce durante horas, parando para descansar en un pequeño motel de carretera regentado por un joven llamado Norman. Todo parece normal y tranquilo en el apartado motel y en la casa de al lado en la que viven Norman y su madre pero, mientras está en la ducha, la joven es asesinada salvajemente a cuchilladas.","en":"When larcenous real estate clerk Marion Crane goes on the lam with a wad of cash and hopes of starting a new life, she ends up at the notorious Bates Motel, where manager Norman Bates cares for his housebound mother.","it":"Marion Crane, impiegata in una società immobiliare, scappa con 40.000$ rubati dalle casse della ditta. Durante la fuga verso casa del fidanzato però, decide di fermarsi nel Motel gestito dal giovane Norman Bates e dalla madre, che però vive rintanata nella casa attigua al Motel stesso.  Il capolavoro di Alfred Hitchcock.","de":"Die Sekretärin Marion Crane unterschlägt 40.000 Dollar und macht auf ihrer Flucht in einem abgelegenen Motel Station, das der eigentümliche Norman Bates leitet, der mit seiner Mutter im Haus neben dem Motel lebt. Als Marion sich frisch machen will, wird sie während des Duschens erstochen. Nachdem ein Privatdetektiv, der ihre Spur gefunden hatte, ebenfalls verschwindet, begeben sich Marions Freund Sam und ihre Schwester Lila auf die Suche. Im Bates Motel machen sie eine grausige Entdeckung.","fr":"Marion Crane en a assez de ne pouvoir mener sa vie comme elle l''entend. Son travail ne la passionne plus, son amant ne peut l''épouser car il doit verser une énorme pension alimentaire le laissant sans le sou… Mais un beau jour, son patron lui demande de déposer 40 000 dollars à la banque. La tentation est trop grande, et Marion s''enfuit avec l''argent. Très vite la panique commence à se faire sentir. Partagée entre l''angoisse de se faire prendre et l''excitation de mener une nouvelle vie, Marion roule vers une destination qu''elle n''atteindra jamais. La pluie est battante, la jeune femme s''arrête près d''un motel, tenu par un sympathique gérant nommé Norman Bates, mais qui doit supporter le caractère possessif de sa mère. Après un copieux repas avec Norman, Marion prend toutes ses précautions afin de dissimuler l''argent. Pour se délasser de cette journée, elle prend une douche…"}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/xFbnc2QPG5H5gYWsGbZT4q8Akya.jpg","en":"https://image.tmdb.org/t/p/w500/yz4QVqPx3h1hD1DfqqQkCq3rmxW.jpg","it":"https://image.tmdb.org/t/p/w500/tdqX0MWaFHuGwUygYn7j6eluOdP.jpg","de":"https://image.tmdb.org/t/p/w500/p6ST4wHG90PfHRDMhcA5WsLeh39.jpg","fr":"https://image.tmdb.org/t/p/w500/lzF8b44dAvXFagQnB1UZa2AF87q.jpg"}'::jsonb WHERE id = 286;
UPDATE public.films SET tmdb_id = 521, titoli_i18n = '{"de":"Bei Anruf Mord","es":"Crimen perfecto","it":"Il delitto perfetto","en":"Dial M for Murder","fr":"Le crime était presque parfait"}'::jsonb, trame_i18n = '{"de":"Margot ist die reiche Ehefrau des windigen Ex-Profi-Tennisspielers und Playboys Tony Wendice. Tony fürchtet den Verlust des Geldes, weil Margots Liaison mit dem Kriminalroman-Autor Mark zu einer Scheidung führen könnte. Er zwingt einen ehemaligen Schulkameraden, der in Schwierigkeiten steckt, zum Mord an seiner Frau. Der bis ins kleinste Detail minutiös ausgefeilte Plan droht zu scheitern, als Margot es mit letzter Kraft schafft, ihren vermeintlichen Mörder mit einer Schere zu erstechen. Doch Tony schaltet schnell: Mit eiskalter Berechnung liefert er der Polizei Hinweise, die seine Frau nicht nur ins Gefängnis, sondern sogar die Todesstrafe bringen könnten …","es":"Tony Wendice maquina un plan para deshacerse de Margot, su esposa infiel. Pero la casualidad hará que sea a ella a quien finalmente acusen de asesinato. La inestimable ayuda de un inspector de policía ayudará a resolver el misterioso crimen.","it":"Margot è sposata con Tony, ma i loro rapporti non sono certo idilliaci: lui vive alle spalle di lei perché è benestante e perché è un fannullone, ed inoltre lei è innamorata di uno scrittore americano e medita il divorzio, che sarebbe la rovina per suo marito. Così Tony medita di uccidere Margot per intascare i suoi soldi e vivere di rendita.","en":"When her American lover visits London, a wealthy woman’s jealous husband hatches a plan to murder her and inherit her fortune.","fr":"Tony Wendice, une ancienne gloire du tennis, s''est marié avec Margot pour sa richesse. Mais celle-ci le trompe depuis peu avec Mark Halliday, un jeune auteur de romans policiers. Craignant que sa femme le quitte et le laisse sans le sou, Tony fait appel au capitaine Lesgate et le charge d''assassiner Margot en échange d''une grosse somme d''argent."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/sPXTBbmgqdeUJyMpPuprPOzkako.jpg","es":"https://image.tmdb.org/t/p/w500/mRJO5slKZ2kUsTtzAeT0AJHryaY.jpg","it":"https://image.tmdb.org/t/p/w500/feVfUSdS9k39GSqJjeMLlafV8M6.jpg","en":"https://image.tmdb.org/t/p/w500/2gDCAgl2iBQNuJuk6p2xtuS1ewg.jpg","fr":"https://image.tmdb.org/t/p/w500/2ikfaqVUxyPq726S8TYihSczkFF.jpg"}'::jsonb WHERE id = 287;
UPDATE public.films SET tmdb_id = 571, titoli_i18n = '{"en":"The Birds","es":"Los pájaros","it":"Gli uccelli","de":"Die Vögel","fr":"Les Oiseaux"}'::jsonb, trame_i18n = '{"en":"Thousands of birds flock into a seaside town and terrorize the residents in a series of deadly attacks.","es":"Melanie, una joven rica y snob de la alta sociedad de San Francisco, conoce casualmente en una pajarería al abogado Mitch Brenner, que ha ido a comprar un regalo de cumpleaños para Kathy, su hermana pequeña. Mitch, que conoce por la prensa la alocada vida de Melanie, la trata despectivamente y se va de la tienda dejándola bastante irritada. Ella, que no está acostumbrada a que la traten así, encarga unos periquitos y los lleva a casa del abogado, pero Mitch se ha ido a pasar el fin de semana a casa de su madre. Entonces, Melanie decide ir a Bodega Bay y presentarse en casa de los Brenner con el pretexto de regalar los periquitos a Kathy. En cuanto ella llega, los pájaros, enloquecidos, empiezan a atacar salvajemente a los habitantes del lugar. La situación se agrava a medida que avanzan las horas.","it":"Melanie Daniels incontra Mitch Brenner in un negozio di animali di San Francisco. Lui vorrebbe comprare una coppia di inseparabili per regalarli a sua sorella per il suo compleanno, lei finge di essere una commessa del negozio, lui non le crede, ma sta al gioco. Melanie decide poi di comprare una coppia di inseparabili e di andare a Bodega Bay, un tranquillo paesino costiero, dove Mitch passa i suoi fine settimana con la sorellina e la madre, per fargli una sorpresa. Al suo arrivo viene attaccata da un gabbiano, e sarà il primo di una lunga, inspiegabile serie di attacchi da parte degli uccelli...","de":"Melanie Daniels, gelangweilte Tochter eines Pressezaren, verliebt sich beim Einkaufen in der Stadt in den Anwalt Mitch Brenner und folgt ihm in dessen kleines Heimatnest an der Pazifikküste. Dort macht sie nicht nur unangenehme Bekanntschaft mit Mitchs reservierter Mutter, sondern auch mit den Vögeln der Umgebung, die sich just an diesem Tag ganz besonders unnatürlich geben. Was zunächst niemanden weiter besorgt, erwächst zum echten Problem, als die Vögel in militärisch anmutenden Formationen zu lebensgefährlichen Attacken auf die Menschen übergehen.","fr":"Melanie, jeune femme quelque peu superficielle, rencontre chez un marchand d''oiseaux un brillant et séduisant avocat qui recherche des inséparables. Par jeu, Melanie achète les oiseaux et les apporte à Bodega Bay. Dès son arrivée, elle est blessée au front par une mouette..."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/ADoJaT1s9Jlcfx3Tw2MIZ1BMxo.jpg","es":"https://image.tmdb.org/t/p/w500/aqMiK53QEC5UyGePN5KmgL7DLNg.jpg","it":"https://image.tmdb.org/t/p/w500/omnOJCmTGJoxCRJorWIEweu1JTN.jpg","de":"https://image.tmdb.org/t/p/w500/9rDGUfzKVAlUNVP2otDsnyfwMIF.jpg","fr":"https://image.tmdb.org/t/p/w500/pIc5nX1neiJ38R7b4e8PKqvxbkD.jpg"}'::jsonb WHERE id = 288;
UPDATE public.films SET tmdb_id = 16515, titoli_i18n = '{"it":"Capitani coraggiosi","en":"Captains Courageous","fr":"Capitaines courageux","es":"Capitanes intrépidos","de":"Manuel"}'::jsonb, trame_i18n = '{"it":"Frank Burton Cheyne, un ricco industriale trascura il figlio adolescente Harvey, al punto da trasformarlo in un ribelle arrogante e raccontafrottole. Harvey per i suoi modi arroganti, a scuola viene evitato da tutti, finché un giorno nella tipografia dell''istituto è coinvolto in una zuffa con un suo coetaneo, e ha la peggio. Il Direttore e il Maestro di Harvey fanno visita al padre, comunicandogli la decisione di sospenderlo per tre mesi, raccontandogli la verità sul comportamento di suo figlio, Frank capisce che è ora di riprendere in mano la situazione, prima che sia troppo tardi. Frank porta con se il figlio Harvey in una crociera su una delle sue navi, ma anche li per fare lo sbruffone con due ragazzini ruzzola in mare. Per sua fortuna viene ripescato da Manuel Fidello, un pescatore di professione che lo tira a bordo della sua barca, lo rianima e lo porta sul peschereccio da cui è partito.","en":"Harvey, the arrogant and spoiled son of an indulgent absentee-father, falls overboard from a transatlantic steamship and is rescued by a fishing vessel on the Grand Banks. Harvey fails to persuade them to take him ashore, nor convince the crew of his wealth. The captain offers him a low-paid job, until they return to port, as part of the crew that turns him into a mature, considerate young man.","fr":"Le jeune Harvey Cheyne est le fils d''un très riche entrepreneur américain. Il pense pouvoir tout obtenir et tout se permettre grâce à l''argent de son père. Renvoyé temporairement de son école pour avoir tenté de corrompre un professeur, il entreprend une croisière avec son père. Mais il tombe à la mer et se retrouve mousse sur le bateau de pêcheurs qui l''a recueilli. Là sa condition sociale ne lui sera pas d''une grande utilité... Il y fera son éducation d''homme notamment grâce au pêcheur Manuel (Spencer Tracy) qui le prend sous son aile. Il retrouvera finalement son père à la fin de cette aventure initiatique.","es":"Harvey, el hijo arrogante y malcriado de un padre poco cariñoso, cae por la borda de un barco de vapor transatlántico y es rescatado por un barco de pesca en el Gran Banco de Terranova. Harvey trata de convencerles para que lo lleven a tierra alardeando de su riqueza ante la tripulación, aunque nadie le toma en serio. El capitán le ofrece un trabajo mal pagado hasta que regresen a puerto. El duro trabajo como uno más de la tripulación convierte al joven en un hombre maduro y considerado.","de":"Nachdem er von der Schule geflogen ist, will der schwerreiche Vater des verzogenen, zehnjährigen Harvey Versäumtes nachholen und ihn in erzieherischer Absicht auf eine Schiffsreise nach Europa mitnehmen. Dummerweise fällt Harvey auf See über Bord, hat aber Glück im Unglück und wird von dem portugiesischen Fischer Manuel gerettet. Da dessen Schiff für die nächsten Monate keinen Hafen ansteuern wird, sieht sich Harvey gezwungen, sich unter Anleitung Manuels nützlich zu machen, was seiner charakterlichen Entwicklung nur zuträglich ist."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/xez8YMw0BhIS7bY0f1rxfdzQcX9.jpg","en":"https://image.tmdb.org/t/p/w500/qhJNHLwIcMqDKBwsr9uMDOumO33.jpg","fr":"https://image.tmdb.org/t/p/w500/ua7U0VMBrK3g5xI4lExx2q1Rxg9.jpg","es":"https://image.tmdb.org/t/p/w500/rsXZmQjSZyZQgETa2AYYQEbBnj8.jpg","de":"https://image.tmdb.org/t/p/w500/vazg1O2ExJCh8uDVQUKkB0zPDkX.jpg"}'::jsonb WHERE id = 289;
UPDATE public.films SET tmdb_id = 1214931, titoli_i18n = '{"it":"Norimberga","en":"Nuremberg","es":"Núremberg","fr":"Nuremberg","de":"Nürnberg"}'::jsonb, trame_i18n = '{"it":"All’indomani della Seconda guerra mondiale, mentre il mondo è ancora sconvolto dagli orrori dell’Olocausto, al tenente colonnello Douglas Kelley, psichiatra dell’esercito americano, viene affidato un incarico senza precedenti: valutare la sanità mentale di Hermann Göring, il famigerato ex braccio destro di Hitler, e di altri alti gerarchi nazisti. Allo stesso tempo, gli Alleati — guidati dal giudice Robert H. Jackson — affrontano l’impresa titanica di istituire un tribunale internazionale, per far sì che il regime nazista risponda dei propri crimini di fronte alla storia. Nel silenzio delle celle, Kelley ingaggia un intenso duello psicologico con Göring, uomo carismatico e manipolatore. Da quello scontro emerge una domanda che ancora oggi tormenta la coscienza del mondo:stavano eseguendo ordini, erano pazzi… o semplicemente malvagi? Sul palcoscenico della storia si apre così il processo di Norimberga, un evento che ha cambiato per sempre la storia e l’umanità.","en":"In postwar Germany, an American psychiatrist must determine whether Nazi prisoners are fit to go on trial for war crimes, and finds himself in a complex battle of intellect and ethics with Hermann Göring, Hitler''s right-hand man.","es":"Tras el fin de la II Guerra Mundial, con ocasión de los cruciales e inminentes juicios de Nuremberg contra el derrotado régimen Nazi, el psiquiatra estadounidense Douglas Kelley (Malek), encargado de determinar si los oficiales nazis prisioneros son aptos para ser juzgados por sus crímenes de guerra, se ve inmerso en una compleja batalla de ingenio dialéctico con Hermann Göring (Crowe), mano derecha de Hitler. Basada en el libro \"El nazi y el psiquiatra\", de Jack El-Hai.","fr":"Washington, 1945. Hitler s''est suicidé, l''Allemagne a capitulé et les Alliés détiennent 22 officiers nazis, dont Hermann Göring, plus haut gradé du Troisième Reich. Contrairement à ses collègues, qui préconisent leur exécution, Robert H. Jackson, juge à la Cour suprême des États-Unis, obtient que ceux-ci soient traduits devant une cour internationale. Un an avant l''ouverture du procès à Nuremberg, Jackson confie à un psychiatre de l''armée américaine, Douglas Kelley, le mandat d''évaluer les accusés. Secondé par son traducteur, Kelley se met à la tâche, en privilégiant le cas du Reichsmarschall Göring, un pervers narcissique, qui s''engage avec lui dans un jeu du chat et de la souris.","de":"Hermann Göring wird von den Alliierten verhaftet und soll als ranghöchster noch verbliebener Nazi für die unfassbaren Taten des NS-Regimes zur Rechenschaft gezogen werden. Der Psychiater Dr. Kelley wird beauftragt, alle Angeklagten auf ihre Prozessfähigkeit hin zu untersuchen. Schnell ist er von Görings Scharfsinn und Charisma eingenommen und obwohl er dessen Machtspiele durchschaut, kann sich Dr. Kelley der manipulativen Stärke und Faszination des Bösen nur schwer entziehen. Um Görings Vertrauen zu gewinnen, überschreitet Dr. Kelley moralische Grenzen und gefährdet sogar den Nürnberger Prozess.  Das bis in die Nebenrollen hochkarätig besetzte Justizdrama erzählt vom folgenreichsten Prozess des 20. Jahrhunderts, der zudem die Geburtsstunde des Völkerrechts markiert."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/ucZHG8KD2A9Czl1aZz1f4bIvbLR.jpg","en":"https://image.tmdb.org/t/p/w500/xthXNYltOOm80vW5Kxjzxx5gvQ6.jpg","es":"https://image.tmdb.org/t/p/w500/7OOQRx9SmkMC3UQfdzj4QsQHtA1.jpg","fr":"https://image.tmdb.org/t/p/w500/6iYLH0TjqCyEkCYadpLUMHr9S8J.jpg","de":"https://image.tmdb.org/t/p/w500/2yVfXfnROnZfPPrArz2MMWfzOSr.jpg"}'::jsonb WHERE id = 290;
UPDATE public.films SET tmdb_id = 872585, titoli_i18n = '{"en":"Oppenheimer","de":"Oppenheimer","es":"Oppenheimer","fr":"Oppenheimer","it":"Oppenheimer"}'::jsonb, trame_i18n = '{"en":"The story of J. Robert Oppenheimer''s role in the development of the atomic bomb during World War II.","de":"Als dem Physiker Julius Robert Oppenheimer während des Zweiten Weltkriegs die wissenschaftliche Leitung des Manhattan-Projekts übertragen wird, können er und seine Ehefrau Kitty sich nicht vorstellen, welche Auswirkungen Oppenheimers Arbeit nicht nur auf ihr Leben, sondern auf die ganze Welt haben wird. Im Los Alamos National Laboratory in New Mexico sollen er und sein Team unter der Aufsicht von Lt. Leslie Groves eine Nuklearwaffe entwickeln – was ihnen auch gelingt. Oppenheimer wird zum „Vater der Atombombe“ ausgerufen, doch dass seine tödliche Erfindung bald folgenschwer in Hiroshima und Nagasaki eingesetzt wird, lässt Oppenheimer Abstand von dem Projekt nehmen. Als der Krieg zu Ende geht, setzt sich Robert Oppenheimer als Berater der US-amerikanischen Atomenergiebehörde, die von Lewis Strauss mitbegründet wurde, für eine internationale Kontrolle von Kernenergie und gegen ein nukleares Wettrüsten ein – und gerät ins Visier des FBI.","es":"Película sobre el físico J. Robert Oppenheimer y su papel como desarrollador de la bomba atómica. Basada en el libro ''American Prometheus: The Triumph and Tragedy of J. Robert Oppenheimer'' de Kai Bird y Martin J. Sherwin.","fr":"En 1942, convaincus que l''Allemagne hitlérienne est en train de développer une arme nucléaire, les États-Unis initient, dans le plus grand secret, le  « Projet Manhattan » destiné à mettre au point la première bombe atomique de l’histoire. Pour piloter ce dispositif, le gouvernement engage J. Robert Oppenheimer, brillant physicien, qui sera bientôt surnommé « le père de la bombe atomique ». C''est dans le laboratoire ultra-secret de Los Alamos, au cœur du désert du Nouveau-Mexique, que le scientifique et son équipe mettent au point une arme révolutionnaire dont les conséquences, vertigineuses, continuent de peser sur le monde actuel…","it":"La storia del ruolo di J. Robert Oppenheimer, i cui studi condussero alle scoperte legate alla bomba atomica, con il conseguente utilizzo durante le stragi di Hiroshima e Nagasaki durante la Seconda Guerra Mondiale."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/8Gxv8gSFCU0XGDykEGv7zR1n2ua.jpg","de":"https://image.tmdb.org/t/p/w500/9AiHV08v8RyyuHcO5wuTaTXBxfe.jpg","es":"https://image.tmdb.org/t/p/w500/mJRUREPjTqqMEKwEiM2sdmIGngz.jpg","fr":"https://image.tmdb.org/t/p/w500/boAUuJBeID7VNp4L7LNMQs8mfQS.jpg","it":"https://image.tmdb.org/t/p/w500/fRtaxfyynWMJI6DhejyA6JOzVTB.jpg"}'::jsonb WHERE id = 291;
UPDATE public.films SET tmdb_id = 515001, titoli_i18n = '{"it":"Jojo Rabbit","en":"Jojo Rabbit","es":"Jojo Rabbit","fr":"Jojo Rabbit","de":"Jojo Rabbit"}'::jsonb, trame_i18n = '{"it":"Jojo, un bambino cresciuto dalla sola madre, ha come unico alleato il suo amico immaginario Adolf Hitler. Il suo ingenuo patriottismo viene però messo alla prova quando incontra una ragazzina che stravolge le sue convinzioni sul mondo, costringendolo ad affrontare le sue paure più grandi.","en":"Jojo, a lonely German boy during World War II has his world shaken when he learns that his single mother is hiding a Jewish girl in their home. Influenced by a buffoonish imaginary version of Adolf Hitler, he begins to question his beliefs and confront the conflict between propaganda and his own humanity.","es":"Jojo Rabbit es un niño viviendo en plena 2ª Guerra Mundial. Su única vía de escape es su amigo imaginario, una versión de Hitler étnicamente incorrecta que incita los ciegos ideales patrióticos del niño. Todo esto cambia cuando descubre que su madre Rosie está escondiendo a una joven judía en su ático.","fr":"Jojo est un petit allemand solitaire. Sa vision du monde est mise à l’épreuve quand il découvre que sa mère cache une jeune fille juive dans leur grenier. Avec la seule aide de son ami aussi grotesque qu''imaginaire, Adolf Hitler, Jojo va devoir faire face à son nationalisme aveugle.","de":"Jojo Rabbit handelt von einem kleinen Jungen, der während des Zweiten Weltkriegs lebt. Er kann der rauen Wirklichkeit nur durch seinen imaginären Freund entkommen, eine ethnisch ungenaue Version von Adolf Hitler, der die naiven patriotischen Überzeugungen des kleinen Jungen vorantreibt. Das ändert sich jedoch alles, als ein junges Mädchen diese Ansichten hinterfragt und Jojo dazu bringt, sich seinen eigenen Problemen zu stellen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/2vv0tEFH10YG3hMRCOhiWsw7bOk.jpg","en":"https://image.tmdb.org/t/p/w500/1mqL7VG4Ix8wmxwypmCA1HTHBky.jpg","es":"https://image.tmdb.org/t/p/w500/5KRPe0XObWOVGVzDaGSAxG2w8bd.jpg","fr":"https://image.tmdb.org/t/p/w500/t4JPW6GxKOiwqtsursgGynmPffu.jpg","de":"https://image.tmdb.org/t/p/w500/mqE5oPqmT1WU1WxuOloDUIsEKto.jpg"}'::jsonb WHERE id = 292;
UPDATE public.films SET tmdb_id = 475557, titoli_i18n = '{"it":"Joker","es":"Joker","fr":"Joker","en":"Joker","de":"Joker"}'::jsonb, trame_i18n = '{"it":"Arthur Fleck vive con l''anziana madre in un palazzone fatiscente e sbarca il lunario facendo pubblicità per la strada travestito da clown, in attesa di avere il giusto materiale per realizzare il desiderio di fare il comico. La sua vita, però, è una tragedia: ignorato, calpestato, bullizzato, preso in giro da da chiunque, ha sviluppato un tic nervoso che lo fa ridere a sproposito incontrollabilmente, rendendolo inquietante e allontanando ulteriormente da lui ogni possibile relazione sociale. Ma un giorno Arthur non ce la fa più e reagisce violentemente, pistola alla mano. Mentre la polizia di Gotham City dà la caccia al clown killer, la popolazione lo elegge a eroe metropolitano, simbolo della rivolta degli oppressi contro l''arroganza dei ricchi.","es":"Arthur Fleck es un hombre ignorado por la sociedad, cuya motivación en la vida es hacer reír. Pero una serie de trágicos acontecimientos le llevarán a ver el mundo de otra forma. Película basada en Joker, el popular personaje de DC Comics y archivillano de Batman, pero que en este film toma un cariz más realista y oscuro.","fr":"Dans les années 1980, à Gotham City, Arthur Fleck, un humoriste de stand‐up raté, bascule dans la folie et devient le Joker.","en":"During the 1980s, a failed stand-up comedian is driven insane and turns to a life of crime and chaos in Gotham City while becoming an infamous psychopathic crime figure.","de":"Gotham City im Jahr 1981: Der mental instabile Arthur Fleck führt wahrlich nicht das Leben, von dem man träumt: Vollgepumpt mit Medikamenten geht er seiner Arbeit als kostümierter Werbeschildträger nach und wird nicht selten das Ziel von Spott und Attacken. Abends zieht es ihn in sein heruntergekommenes Apartment, wo er sich um seine kranke Mutter kümmern muss. Gemeinsam hoffen sie auf ein besseres Leben, das Arthur als Stand-Up-Komiker realisieren will. Als plötzlich die Förderung für seine psychologische Betreuung gestrichen wird, nimmt das Unheil seinen Lauf. Die Schusswaffe eines Kollegen, die Suche nach seinem echten Vater und plötzlicher Ruhm sorgen dafür, dass der einstmals harmlose Exzentriker die ganze Stadt in Angst und Schrecken versetzt …"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/y1AthYH1r2j4N4cYn2HdrEGgrnJ.jpg","es":"https://image.tmdb.org/t/p/w500/v0eQLbzT6sWelfApuYsEkYpzufl.jpg","fr":"https://image.tmdb.org/t/p/w500/tWjJ3ILjsbTwKgXxEv48QAbYZ19.jpg","en":"https://image.tmdb.org/t/p/w500/udDclJoHjfjb8Ekgsd4FDteOkCU.jpg","de":"https://image.tmdb.org/t/p/w500/t3ZtGpIqoQgMY5hMHSLJSD8aguU.jpg"}'::jsonb WHERE id = 293;
UPDATE public.films SET tmdb_id = 496243, titoli_i18n = '{"en":"Parasite","es":"Parásitos","fr":"Parasite","de":"Parasite","it":"Parasite"}'::jsonb, trame_i18n = '{"en":"All unemployed, Ki-taek''s family takes peculiar interest in the wealthy and glamorous Parks for their livelihood until they get entangled in an unexpected incident.","es":"Tanto Gi Taek (Song Kang-ho) como su familia están sin trabajo. Cuando su hijo mayor, Gi Woo (Choi Woo-sik), empieza a dar clases particulares en casa de Park (Lee Seon-gyun), las dos familias, que tienen mucho en común pese a pertenecer a dos mundos totalmente distintos, comienzan una interrelación de resultados imprevisibles.","fr":"Toute la famille de Ki-taek est au chômage. Elle s’intéresse particulièrement au train de vie de la richissime famille Park. Mais un incident se produit et les deux familles se retrouvent mêlées, sans le savoir, à une bien étrange histoire…","de":"Familie Kim ist ganz unten angekommen: Vater, Mutter, Sohn und Tochter hausen in einem grünlich-schummrigen Keller und sind sich für keinen Aushilfsjob zu schade. Erst als der Jüngste eine Anstellung als Nachhilfelehrer in der todschicken Villa der Familie Park antritt, steigen die Kims ein ins Karussell der Klassenkämpfe. Mit findigen Tricksereien, bemerkenswertem Talent und großem Mannschaftsgeist gelingt es ihnen, die bisherigen Bediensteten der Familie Park nach und nach loszuwerden. Bald schon sind die Kims unverzichtbar für ihre neuen Herrschaften. Doch dann löst ein unerwarteter Zwischenfall eine Kette von Ereignissen aus, die so unvorhersehbar wie unfassbar sind.","it":"Tutta la famiglia di Ki-taek è senza lavoro. Ki-taek è particolarmente interessata allo stile di vita della ricchissima famiglia Park. Un giorno, suo figlio riesce a farsi assumere dai Park e le due famiglie si ritrovano così intrecciate da una serie di eventi incontrollabili."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/7IiTTgloJzvGI1TAYymCfbfl3vT.jpg","es":"https://image.tmdb.org/t/p/w500/4N55tgxDW0RRATyrZHbx0q9HUKv.jpg","fr":"https://image.tmdb.org/t/p/w500/7hLSzZX2jROmEXz2aEoh6JKUFy2.jpg","de":"https://image.tmdb.org/t/p/w500/hoqe3leVhHBgboB6G1bv1kB8K4p.jpg","it":"https://image.tmdb.org/t/p/w500/mMM8kcfspicib7AmPTvf97Rarwn.jpg"}'::jsonb WHERE id = 294;
UPDATE public.films SET tmdb_id = 354912, titoli_i18n = '{"it":"Coco","en":"Coco","es":"Coco","fr":"Coco","de":"Coco - Lebendiger als das Leben!"}'::jsonb, trame_i18n = '{"it":"Nonostante il divieto di musica che dura da generazioni nella sua famiglia, Miguel sogna di diventare un musicista affermato come il suo idolo, Ernesto de la Cruz. Disperato di dimostrare il suo talento, Miguel si ritrova nella splendida e colorata Terra dei Morti, seguendo una misteriosa catena di eventi. Lungo il cammino incontra il fascinante imbroglione Hector e insieme partono per un viaggio straordinario per svelare la vera storia della famiglia di Miguel.","en":"Despite his family’s baffling generations-old ban on music, Miguel dreams of becoming an accomplished musician like his idol, Ernesto de la Cruz. Desperate to prove his talent, Miguel finds himself in the stunning and colorful Land of the Dead following a mysterious chain of events. Along the way, he meets charming trickster Hector, and together, they set off on an extraordinary journey to unlock the real story behind Miguel''s family history.","es":"Un joven aspirante a músico llamado Miguel se embarca en un viaje extraordinario a la mágica tierra de sus ancestros. Allí, el encantador embaucador Héctor se convierte en su inesperado amigo y le ayuda a descubrir los misterios detrás de las historias y tradiciones de su familia.","fr":"Depuis déjà plusieurs générations, la musique est bannie dans la famille de Miguel. Un vrai déchirement pour le jeune garçon dont le rêve ultime est de devenir un musicien aussi accompli que son idole, Ernesto de la Cruz. Bien décidé à prouver son talent, Miguel, par un étrange concours de circonstances, se retrouve propulsé dans un monde étonnant et coloré lié aux célébrations des ancêtres. Là, il se lie d’amitié avec Hector, un gentil garçon mais un peu filou sur les bords. Ensemble, ils vont accomplir un voyage extraordinaire qui leur révèlera la véritable histoire qui se cache derrière celle de la famille de Miguel…","de":"Miguel ist zwölf Jahre alt und ein großer Fan von Musik – aber leider hasst seine Schusterfamilie alles, was mit Tönen und Instrumenten zu tun hat. Miguels Ururgroßvater verließ damals seine Frau und Tochter, um Musiker zu werden, seitdem fühlen sich die Riveras durch Musik verflucht. Doch Familie hin oder her – Miguel will seinem Idol, dem Sänger Ernesto de la Cruz, trotzdem nacheifern. Aus Versehen kommt er dabei ins Reich der Toten und betritt dadurch einen wunderschönen Ort, an dem er die Seelen seiner toten Verwandten trifft. Miguels Ururgroßmutter Imelda ist darunter, und das nette Schwindler-Skelett Hector. Zusammen suchen Skelett und Junge im Totenreich nach de la Cruz, wobei allerdings die Zeit drängt: Zu lange darf Miguel nicht in der Unterwelt bleiben…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/l5qUox5uroubMi8sihD9RGPbcwO.jpg","en":"https://image.tmdb.org/t/p/w500/6Ryitt95xrO8KXuqRGm1fUuNwqF.jpg","es":"https://image.tmdb.org/t/p/w500/vwsFGblLYxWBNjg9pdWN1Mm5YfW.jpg","fr":"https://image.tmdb.org/t/p/w500/sZqcEV3KhDITHlUBmyj1a3RRvT9.jpg","de":"https://image.tmdb.org/t/p/w500/x7YxGQGItXaLzl5eQNqGo0837fs.jpg"}'::jsonb WHERE id = 295;
UPDATE public.films SET tmdb_id = 290250, titoli_i18n = '{"it":"The Nice Guys","en":"The Nice Guys","es":"Dos buenos tipos","de":"The Nice Guys","fr":"The Nice Guys"}'::jsonb, trame_i18n = '{"it":"Nella Los Angeles degli anni ‘70, libertina, stravagante e decisamente trendy, un investigatore privato, Holland March (Ryan Gosling), e un detective senza scrupoli, Jackson Healy (Russell Crowe), si alleano per risolvere il caso di una ragazza scomparsa e la morte di una porno star che apparentemente non sembrerebbero correlate: scopriranno che un semplice omicidio nasconde il caso del secolo!","en":"A private eye investigates the apparent suicide of a fading porn star in 1970s Los Angeles and uncovers a conspiracy.","es":"Ambientada en Los Ángeles durante los años 70. El detective Holland March y el matón a sueldo Jackson Healy se ven obligados a colaborar para resolver varios casos: la desaparición de una joven, la muerte de una estrella porno y una conspiración criminal que llega hasta las altas esferas.","de":"Holland March, ein abgehalfterter Privatdetektiv, und Jackson Healy, der als Mann fürs Grobe angeheuert wird, haben nicht viel gemeinsam. Doch dann werden beide in den Fall der vermissten Amelia verstrickt. Widerwillig zur Zusammenarbeit gezwungen, streifen sie gemeinsam mit Marchs pubertierender Tochter Holly durch Los Angeles, um verworrenen Hinweisen auf den Grund zu gehen. Bis Amelias Spur sie zu einer Multi-Milliarden-Dollar-Verschwörung führt, die bis in die höchsten Kreise reicht und sie zum Ziel skrupelloser Profikiller macht...","fr":"Los Angeles. Années 70. Deux détectives privés enquêtent sur le prétendu suicide d’une starlette. Malgré des méthodes pour le moins « originales », leurs investigations vont mettre à jour une conspiration impliquant des personnalités très haut placées…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/clq4So9spa9cXk3MZy2iMdqkxP2.jpg","en":"https://image.tmdb.org/t/p/w500/clq4So9spa9cXk3MZy2iMdqkxP2.jpg","es":"https://image.tmdb.org/t/p/w500/kgMpKQMKyS7oYmPffKyyOv0VqyT.jpg","de":"https://image.tmdb.org/t/p/w500/n3CP3VtCoFuB7Wnh8Zyhx8erlnZ.jpg","fr":"https://image.tmdb.org/t/p/w500/p94BXHeJQagD3M8p4LuAB87RMQv.jpg"}'::jsonb WHERE id = 296;
UPDATE public.films SET tmdb_id = 395834, titoli_i18n = '{"it":"I segreti di Wind River","en":"Wind River","fr":"Wind River","de":"Wind River","es":"Wind River"}'::jsonb, trame_i18n = '{"it":"Cory Lambert, esperto inseguitore e cacciatore, scopre il corpo congelato di una ragazza adolescente. Fa allora squadra con Jane Banner, nuova agente dell''Fbi, per capire cosa sia accaduto alla giovane e chi sia il responsabile di un così macabro crimine. Man mano che l''indagine si approfondisce, la vita dei due investigatori è sempre più a rischio.","en":"An FBI agent teams with the town''s veteran game tracker to investigate a murder that occurred on a Native American reservation.","fr":"Cory Lambert est pisteur dans la réserve indienne de Wind River, perdue dans l’immensité sauvage du Wyoming. Lorsqu’il découvre le corps d’une femme en pleine nature, le FBI envoie une jeune recrue élucider ce meurtre. Fortement lié à la communauté amérindienne, il va l’aider à mener l’enquête dans ce milieu hostile, ravagé par la violence et l’isolement, où la loi des hommes s’estompe face à celle impitoyable de la nature…","de":"Cory Lambert arbeitet für den United States Fish and Wildlife Service und macht vor allem Jagd auf Kojoten und andere Raubtiere im Indianer-Reservat Wind River. Den kürzlichen Tod seiner Teenager-Tochter hat er noch nicht überwunden, da stolpert er in der Wildnis über die Leiche einer vergewaltigten und erfrorenen Jugendlichen. Um den Täter zu fassen, wird die noch sehr junge FBI-Agentin Jane Banner auf den Fall angesetzt. Weil sie sich in dem rauen Gelände und mit den schwierigen Wetterverhältnissen vor Ort allerdings nicht auskennt, bittet sie Cory um Hilfe bei ihren Ermittlungen und gemeinsam brechen sie auf ins Ungewisse.","es":"Una joven agente del FBI se alía con un veterano rastreador local para investigar el asesinato de una joven ocurrido en una reserva de nativos americanos..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/5OI9QQ24lrrS1IGB6RVuPL5GcZl.jpg","en":"https://image.tmdb.org/t/p/w500/pySivdR845Hom4u4T2WNkJxe6Ad.jpg","fr":"https://image.tmdb.org/t/p/w500/yp7ogTlvEvgUIvNXdbfwH68S3i4.jpg","de":"https://image.tmdb.org/t/p/w500/itiigTVSRWuRN5r72SN5vZNTxTm.jpg","es":"https://image.tmdb.org/t/p/w500/8YQzSkPbJB5PJMTvTccDNo3z9K7.jpg"}'::jsonb WHERE id = 297;
UPDATE public.films SET tmdb_id = 281957, titoli_i18n = '{"it":"Revenant - Redivivo","es":"El renacido","en":"The Revenant","fr":"The Revenant","de":"The Revenant - Der Rückkehrer"}'::jsonb, trame_i18n = '{"it":"Sono gli anni Venti del diciannovesimo secolo. Soldati, esploratori, cacciatori di pelli, mercenari solcano i territori ancora sconosciuti d''America per trarne profitto. Glass è l''uomo che meglio di tutti i suoi compagni di spedizione conosce la terra impervia in cui si sono inoltrati. Il suo compito è riportare la compagnia al forte e tutto ciò che lo preoccupa è proteggere suo figlio, un ragazzo indiano. Lo scontro con un grizzly lo lascia in condizioni prossime alla fine. Il più arrogante della compagnia, Fitzgerald, si offre di restare per dargli sepoltura, ma lo tradisce orribilmente. La volontà di vendicarsi rimetterà in piedi Glass e darà inizio ad un''odissea leggendaria.","es":"Durante una expedición en las tierras salvajes americanas, el legendario explorador Hugh Glass es brutalmente atacado por un oso y dado por muerto por los miembros de su propia partida de caza. En su cruzada por sobrevivir, Glass supera inimaginables tribulaciones, además de la traición de su confidente John Fitzgerald. Guiado por la pura determinación y el amor de su familia, Glass deberá superar un duro invierno mientras busca sin descanso un motivo para seguir adelante y encontrar la redención.","en":"In the 1820s, a frontiersman, Hugh Glass, sets out on a path of vengeance against those who left him for dead after a bear mauling.","fr":"Dans une Amérique profondément sauvage, le trappeur Hugh Glass est sévèrement blessé et laissé pour mort par un traître de son équipe, John Fitzgerald. Avec sa seule volonté pour unique arme, Glass doit affronter un environnement hostile, un hiver brutal et des tribus guerrières, dans une inexorable lutte pour sa survie, portée par un intense désir de vengeance.","de":"In den 1820ern zieht der legendäre Trapper Hugh Glass durch die Weiten der USA, wo er mit einer von Captain Andrew Henry angeführten Expedition dabei ist, den Missouri River zu erforschen. Am Fluss hat er einen unachtsamen Moment – den ein Grizzly ausnutzt, ihn übel zuzurichten. Glass schwebt in Lebensgefahr. Seine Begleiter, unter ihnen der raubeinige John Fitzgerald und der junge Jim Bridger, glauben nicht, dass er den Vorfall überleben wird und als sie dann Ureinwohner in der Nähe ihres Lagers erspähen, fackeln sie nicht lange. Sie nehmen dem Schwerverwundeten Gewehr, Messer und seine weitere Ausrüstung ab und überlassen ihn sich selbst. Aber überraschend überlebt Glass doch – und schwört allen Begleitern Rache, die ihn zurückgelassen haben. Auf der Suche nach ihnen schleppt sich der verletzte Abenteurer durch die eisige Bergwelt …"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/cw8HPomOzNql3l4xdaJJ8HGIZds.jpg","es":"https://image.tmdb.org/t/p/w500/k3Jh7J5GGMx1lmr7qmynRxOvOK5.jpg","en":"https://image.tmdb.org/t/p/w500/ji3ecJphATlVgWNY0B0RVXZizdf.jpg","fr":"https://image.tmdb.org/t/p/w500/AsDto68FNWNXD15Ov0yMXASJiSB.jpg","de":"https://image.tmdb.org/t/p/w500/fv9H7m73DKbwjowHSl1raTTwQ0d.jpg"}'::jsonb WHERE id = 298;
UPDATE public.films SET tmdb_id = 190859, titoli_i18n = '{"en":"American Sniper","fr":"American Sniper","es":"El francotirador","it":"American Sniper","de":"American Sniper"}'::jsonb, trame_i18n = '{"en":"U.S. Navy SEAL Chris Kyle takes his sole mission—protect his comrades—to heart and becomes one of the most lethal snipers in American history. His pinpoint accuracy not only saves countless lives but also makes him a prime target of insurgents. Despite grave danger and his struggle to be a good husband and father to his family back in the States, Kyle serves four tours of duty in Iraq. However, when he finally returns home, he finds that he cannot leave the war behind.","fr":"Tireur d’élite des Navy SEAL, Chris Kyle est envoyé en Irak dans un seul but : protéger ses camarades. Sa précision chirurgicale sauve d’innombrables vies humaines sur le champ de bataille et, tandis que les récits de ses exploits se multiplient, il décroche le surnom de « La Légende ». Cependant, sa réputation se propage au-delà des lignes ennemies, si bien que sa tête est mise à prix et qu’il devient une cible privilégiée des insurgés. Malgré le danger, et l’angoisse dans laquelle vit sa famille, Chris participe à quatre batailles décisives parmi les plus terribles de la guerre en Irak, s’imposant ainsi comme l’incarnation vivante de la devise des SEAL : « Pas de quartier ! ». Mais en rentrant au pays, Chris prend conscience qu’il ne parvient pas à retrouver une vie normale.","es":"El marine del grupo de operaciones especiales de la Marina de Estados Unidos Chris Kyle es enviado a Irak con una sola misión: proteger a sus compañeros de ejército. Su precisión milimétrica salva incontables vidas en el campo de batalla y, a medida que se extienden sus valientes hazañas, se gana el apodo de ''Leyenda''. Sin embargo, su reputación también crece detrás de las líneas enemigas, de manera que ponen precio a su cabeza y se convierte en objetivo prioritario de los insurgentes. Al mismo tiempo también se está enfrentando a otra batalla en casa: ser un buen marido y padre desde el otro lado del mundo.","it":"Il cecchino Chris Kyle viene inviato in Iraq con una sola missione: proteggere i propri compagni. Grazie alla sua precisione millimetrica e alla sue gesta eroiche salverà innumerevoli vite guadagnandosi il soprannome di \"Legend\". Tuttavia, la sua reputazione cresce anche dietro le linee nemiche facendolo diventare uno degli obiettivi primari. Nonostante ciò, riuscirà a far ritorno a casa scoprendo che la guerra è qualcosa che difficilmente riuscirà a lasciarsi alle spalle.","de":"US-Navy-SEAL und Scharfschütze Chris Kyle wird mit nur einem einzigen Auftrag in den Irak geschickt, er soll seine Waffenbrüder beschützen. Seine punktgenauen Schüsse retten unzählige Leben auf dem Schlachtfeld. Als sich die Geschichten seiner mutigen Heldentaten und der unvergleichlichen Treffsicherheit verbreiten, bekommt er den Spitznamen „Legend“. Doch sein Ruf eilt ihm auch hinter die feindlichen Linien voraus und die Gegner setzen ein Kopfgeld auf ihn aus. Doch der Krieg ist nicht sein einziger Kampf: Der Scharfschütze versucht auch, ein guter Ehemann und Vater für seine Liebsten am anderen Ende der Welt zu sein. Trotz der lauernden Gefahr und seiner daheim wartenden Familie absolviert Kyle vier Einsätze im Irak – ganz nach dem Motto „lass niemanden zurück“. Aber als er dann wieder bei seiner Frau Taya Renae Kyle und seinen Kinder ist, erkennt er, dass er den Krieg nicht hinter sich lassen kann."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/i1U46OwMc6vlm7OoSUKfqUH615e.jpg","fr":"https://image.tmdb.org/t/p/w500/9BEN7zRpoLBaBU3t97kPJkHUgnv.jpg","es":"https://image.tmdb.org/t/p/w500/ntso1nvAVIEdzjc4Tc9nB7MPSKu.jpg","it":"https://image.tmdb.org/t/p/w500/AdYOjcPT5PHyDsyxBgjCLtIepQR.jpg","de":"https://image.tmdb.org/t/p/w500/vvujeQGFdTqVo63VXYTVsHuNGCl.jpg"}'::jsonb WHERE id = 299;
UPDATE public.films SET tmdb_id = 137113, titoli_i18n = '{"en":"Edge of Tomorrow","fr":"Edge of Tomorrow","it":"Edge of Tomorrow - Senza domani","es":"Al filo del mañana","de":"Edge of Tomorrow"}'::jsonb, trame_i18n = '{"en":"Major Bill Cage is an officer who has never seen a day of combat when he is unceremoniously demoted and dropped into combat. Cage is killed within minutes, managing to take an alpha alien down with him. He awakens back at the beginning of the same day and is forced to fight and die again... and again - as physical contact with the alien has thrown him into a time loop.","fr":"Dans un futur proche, des hordes d’extraterrestres ont livré une bataille acharnée contre la Terre et semblent désormais invincibles : aucune armée au monde n’a réussi à les vaincre. Le commandant William Cage, qui n’a jamais combattu de sa vie, est envoyé, sans la moindre explication, dans ce qui ressemble à une mission‐suicide. Il meurt en l’espace de quelques minutes et se retrouve projeté dans une boucle temporelle, condamné à revivre le même combat et à mourir de nouveau indéfiniment…","it":"La storia di “Edge of Tomorrow” si svolge in un futuro prossimo in cui una razza aliena ha colpito la Terra con un implacabile assalto che nessuno esercito al mondo riesce a respingere. Il tenente William Cage è un ufficiale che non ha mai partecipato neppure a un giorno di combattimento quando viene inviato senza tanti complimenti a compiere una missione suicida. Ucciso in pochi minuti, incredibilmente Cage si risveglia ed è costretto a combattere e a morire ancora e ancora, in un continuo loop temporale. Ma a ogni scontro Cage diventa sempre più abile nell’affrontare il nemico, insieme alla combattente delle Forze Speciali Rita Vrataski. Mentre Cage e Rita continuano la lotta contro gli alieni, la ripetizione di ogni battaglia li fa avvicinare sempre più alla soluzione per annientare il nemico.","es":"En un futuro no muy lejano, invade la Tierra una raza de extraterrestres invencibles. Al comandante William Cage, un oficial que nunca ha entrado en combate, le encargan una misión casi suicida y resulta muerto. Entra entonces en un bucle temporal, en el que se ve obligado a luchar y morir una y otra vez. Pero las múltiples batallas que libra lo hacen cada vez más hábil y eficaz en su lucha contra los alienígenas. Su compañera de combate es Rita Vrataski, una guerrera de las Fuerzas Especiales. Adaptación del manga de Hiroshi Sakurazaka.","de":"In naher Zukunft beginnt eine insektenartige Alienrasse – die sogenannten Mimics, mit einer Invasion der Erde. Mit ihrer überlegenen Technologie zerstören die Mimics unerbittlich Städte und ganze Länder, das menschliche Militär ist so gut wie machtlos. Doch noch ist nicht alle Hoffnung verloren, denn die militärischen Kräfte der ganzen Welt haben sich verbündet, um in einer letzten Offensive gegen das übermächtige Alienheer in die Schlacht zu ziehen. In diesem gigantischen Selbstmordkommando findet sich auch der degradierte Lt. Col. Bill Cage wieder. Er stirbt während der Schlacht, aber unglaublicherweise erwacht er daraufhin wieder am Morgen desselben Tages."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/nBM9MMa2WCwvMG4IJ3eiGUdbPe6.jpg","fr":"https://image.tmdb.org/t/p/w500/mZgaULvOfCMc2MVKm0DzDLvi5ZU.jpg","it":"https://image.tmdb.org/t/p/w500/AbzpU4ookiyWFmiq1bTZwjNl7Y1.jpg","es":"https://image.tmdb.org/t/p/w500/vNjwi0STOwzmwE9laZSMYYh2JPE.jpg","de":"https://image.tmdb.org/t/p/w500/1ajE3sEyuEvfuqTTwK4XLKO8ROe.jpg"}'::jsonb WHERE id = 300;
UPDATE public.films SET tmdb_id = 152747, titoli_i18n = '{"it":"All is lost - Tutto è perduto","en":"All Is Lost","de":"All Is Lost","fr":"All Is Lost","es":"Cuando todo está perdido"}'::jsonb, trame_i18n = '{"it":"Perso in mezzo all’Oceano Indiano, il viaggiatore solitario senza identità (Redford) si accorge che il suo yacht di 14 metri inizia ad imbarcare acqua dopo aver urtato contro un container che galleggiava in alto mare. Con il navigatore e la radio fuori uso, l’uomo si ritrova nel mezzo di una violenta tempesta. Nonostante la riparazione dei danni allo scafo e la sua intuizione da esperto marinaio unita ad una forza che smentisce la sua età, l’uomo riesce a malapena a sopravvivere alla tempesta. Avendo a disposizione un sestante ed alcune carte nautiche, per tracciare una rotta verso la salvezza, è costretto ad affidarsi unicamente alle correnti oceaniche nella speranza di incrociare delle barche di passaggio. Sotto un sole battente, accerchiato dagli squali e con le riserve alimentari che iniziavano a scarseggiare, l’ intraprendente marinaio si è trovato molto spesso faccia a faccia con la morte.","en":"During a solo voyage in the Indian Ocean, a veteran mariner awakes to find his vessel taking on water after a collision with a stray shipping container. With his radio and navigation equipment disabled, he sails unknowingly into a violent storm and barely escapes with his life. With any luck, the ocean currents may carry him into a shipping lane -- but, with supplies dwindling and the sharks circling, the sailor is forced to face his own mortality.","de":"Mitten auf dem indischen Ozean wird ein Mann jäh aus dem Schlaf gerissen. Seine zwölf Meter lange Segelyacht hat einen im offenen Meer treibenden Schiffscontainer gerammt. Sein Navigations-Equipment und sein Funkgerät versagen in der Folge den Dienst und er treibt mitten in einen gewaltigen Sturm hinein. In letzter Minute gelingt es dem Mann, das Leck in seinem Boot notdürftig zu flicken. Er überlebt den Sturm dank seiner seemännischen Intuition und Erfahrung mit knapper Not. Praktisch manövrierunfähig treibt der Mann auf offener See. Seine letzte Hoffnung ist es, von der Strömung in eine der großen Schifffahrtsstrecken getrieben zu werden. Unter der unerbittlich sengenden Sonne, sieht sich der sonst so selbstbewusste und erfahrene Segler mit seiner eigenen Sterblichkeit konfrontiert und kämpft einen verzweifelten Kampf ums Überleben.","fr":"Au cours d''un voyage en solitaire à travers l''Océan Indien, un homme découvre à son réveil que la coque de son voilier de 12 mètres a été percée lors d''une collision avec un container flottant à la dérive. Privé de sa radio et de son matériel de navigation, l''homme se laisse prendre dans une violente tempête. Malgré ses réparations, son génie marin et une force physique défiant les années, il y survit de justesse. Avec un simple sextant et quelques cartes marines pour établir sa position, il doit s''en remettre aux courants pour espérer se rapprocher d''une voie de navigation et héler un navire de passage. Mais le soleil implacable, la menace des requins et l''épuisement de ses maigres réserves forcent ce marin forcené à regarder la mort en face.","es":"En el transcurso de un viaje en solitario a través del Océano Índico, un hombre descubre al despertar que el casco de su velero de 12 metros se ha agrietado tras una colisión con un contenedor que flotaba a la deriva. A pesar de las reparaciones, su intuición de marinero y una fuerza física que desafía su edad, a duras penas logra sobrevivir a la tormenta. Pero el sol implacable, la amenaza de los tiburones y el agotamiento de sus escasas reservas obligan a este marinero sin rumbo a mirar a la muerte a los ojos."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/phZLbxYVfE98S0d1G3HdUCc7fqc.jpg","en":"https://image.tmdb.org/t/p/w500/9cVA4oX2xHgiglv6hemxwAaofsq.jpg","de":"https://image.tmdb.org/t/p/w500/9tnNyCdASD4zbKyxVKfjtdNeQfU.jpg","fr":"https://image.tmdb.org/t/p/w500/7yPNj5Xdj1Vl3Edyl3mzWYZMzgE.jpg","es":"https://image.tmdb.org/t/p/w500/f6sWgXefZXMm0fv37wgsKi4Rx4q.jpg"}'::jsonb WHERE id = 301;
UPDATE public.films SET tmdb_id = 68718, titoli_i18n = '{"it":"Django Unchained","en":"Django Unchained","es":"Django desencadenado","de":"Django Unchained","fr":"Django Unchained"}'::jsonb, trame_i18n = '{"it":"Stati Uniti del Sud, alla vigilia della guerra civile. Il cacciatore di taglie di origine tedesca dottor King Schultz, su un carretto da dentista, è alla ricerca dei fratelli Brittle, per consegnarli alle autorità piuttosto morti che vivi e incassare la ricompensa. Per scovarli, libera dalle catene lo schiavo Django, promettendogli la libertà a missione completata. Tra i due uomini nasce così un sodalizio umano e professionale che li conduce attraverso l''America delle piantagioni e degli orrori razzisti alla ricerca dei criminali in fuga e della moglie di Django, Broomhilda, venduta come schiava a qualche possidente negriero.","en":"With the help of a German bounty hunter, a freed slave sets out to rescue his wife from a brutal Mississippi plantation owner.","es":"Dos años antes de estallar la Guerra Civil (1861-1865), Schultz, un cazarrecompensas alemán que le sigue la pista a unos asesinos, le promete al esclavo Django dejarlo en libertad si le ayuda a atraparlos. Terminado con éxito el trabajo, Django prefiere seguir al lado del alemán y ayudarle a capturar a los delincuentes más buscados del Sur. Se convierte así en un experto cazador de recompensas, pero su único objetivo es rescatar a su esposa Broomhilda, a la que perdió por culpa del tráfico de esclavos. La búsqueda llevará a Django y a Schultz hasta Calvin Candie, el malvado propietario de la plantación \"Candyland\". La presencia de ambos en los alrededores de la propiedad, despierta las sospechas de Stephen, el esclavo de confianza de Candie.","de":"Als das Sklavenpaar Django und seine Frau Broomhilda bei einer Auktion getrennt werden, hat Django nur noch ein Ziel vor Augen: seine Frau wiederzufinden. Die Gelegenheit ergibt sich für den in Fesseln Geschlagenen schneller als erwartet, als er vom früheren Zahnarzt und jetzigen Kopfgeldjäger Dr. Schultz befreit wird, damit er ihm bei der Identifikation steckbrieflich gesuchter Verbrecher behilflich sei. Zum Dank will Dr. Schultz ihn zum Kopfgeldjäger ausbilden und ihm helfen, seine Frau ausfindig zu machen. Schließlich führt Django und Dr. Schultz die Spur nach Candyland, wo Broomhilda in den Besitz des charismatischen und überaus gefährlichen Calvin Candie übergegangen ist. Sie erschleichen sich erfolgreich das Vertrauen von Candie. Doch der Haussklave Stephen durchschaut ihr Spiel…","fr":"Dans le sud des États‐Unis, deux ans avant la guerre de Sécession, le Dr King Schultz, un chasseur de primes allemand, fait l’acquisition de Django, un esclave qui peut l’aider à traquer les frères Brittle, les meurtriers qu’il recherche. Schultz promet à Django de lui rendre sa liberté lorsqu’il aura capturé les Brittle – morts ou vifs. Alors que les deux hommes pistent les dangereux criminels, Django n’oublie pas que son seul but est de retrouver Broomhilda, sa femme, dont il fut séparé à cause du commerce des esclaves… Lorsque Django et Schultz arrivent dans l’immense plantation du puissant Calvin Candie, ils éveillent les soupçons de Stephen, un esclave qui sert Candie et a toute sa confiance. Le moindre de leurs mouvements est désormais épié par une dangereuse organisation de plus en plus proche… Si Django et Schultz veulent espérer s’enfuir avec Broomhilda, ils vont devoir choisir entre l’indépendance et la solidarité, entre le sacrifice et la survie…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/igYptikalrjsMueMx6rz15lE4Ts.jpg","en":"https://image.tmdb.org/t/p/w500/7oWY8VDWW7thTzWh3OKYRkWUlD5.jpg","es":"https://image.tmdb.org/t/p/w500/fIxAE6BKfAzhPRYm7DdldBaYu5T.jpg","de":"https://image.tmdb.org/t/p/w500/yK0qrQhi3BbOXvTNOBWHgpcbckZ.jpg","fr":"https://image.tmdb.org/t/p/w500/vRXUnWrXUgXRoX0BaEcuNMfyeQt.jpg"}'::jsonb WHERE id = 302;
UPDATE public.films SET tmdb_id = 87827, titoli_i18n = '{"it":"Vita di Pi","es":"La vida de Pi","de":"Life of Pi - Schiffbruch mit Tiger","fr":"L''Odyssée de Pi","en":"Life of Pi"}'::jsonb, trame_i18n = '{"it":"Il giovane Piscine Molitor Patel, detto Pi, è cresciuto con la famiglia a contatto con lo zoo paterno, mescolando fin dall''infanzia sogno e realtà. Quando il padre ha esigenze di denaro e sceglie di trasferirsi in Canada per vendere lo zoo, Pi ancora non può intuire cosa lo attenderà nelle vastità oceaniche. Di fronte a una tempesta terrificante, la nave affonda, lasciando in breve tempo Pi con un''unica compagna di viaggio: la tigre Richard Parker, l''animale più temuto dello zoo paterno. Pi potrà solo fare affidamento alla propria intelligenza per poter sopravvivere e convivere con la tigre.","es":"Pi Patel es un muchacho cuyo padre es el dueño del zoológico de la ciudad de la India en la que viven. Su familia decide marcharse a Canadá, pero una tormenta hace naufragar el barco en el que viajan. Pi consigue salvarse gracias a una barcaza en la que también hay otro \"pasajero\", un tigre de Bengala al que el joven intentará domar para poder sobrevivir.","de":"Wie man 227 Tage auf hoher See mit einem Bengalischen Tiger unbeschadet überstehen kann, das zeigt Schiffbruch mit Tiger. Piscine Molitor Patel, kurz Pi, ist ein junger Inder, der mit seiner Familie in Pondicherry lebt, wo sein Vater einen Zoo besitzt. Als sie aus politischen Gründen nach Kanada auswandern müssen, wird der Zoo verkauft und mit ihm ein Großteil der Tiere. Den Rest nimmt die Familie mit an Bord eines Frachters, der sie in die neue Heimat bringen soll. Doch auf der Überfahrt kommt es zu einer Havarie und nur Pi kann sich als einziger Überlebender in ein Beiboot retten. Mit vier nicht-menschlichen Ausnahmen: Weitere „Passagiere“ im Rettungsboot sind eine Hyäne, ein am Bein verletztes Zebra, ein Orang-Utan und ein ausgewachsener Tiger namens Richard Parker. Wie und unter welchen Opfern Pi diese entbehrungsreiche Odyssee überlebt, davon berichtet der mittlerweile erwachsene Pi.","fr":"Après une enfance passée à Pondichéry en Inde, Pi Patel, 17 ans, embarque avec sa famille pour le Canada où l’attend une nouvelle vie. Mais son destin est bouleversé par le naufrage spectaculaire du cargo en pleine mer. Il se retrouve seul survivant à bord d''un canot de sauvetage. Seul, ou presque… Richard Parker, splendide et féroce tigre du Bengale est aussi du voyage. L’instinct de survie des deux naufragés leur fera vivre une odyssée hors du commun au cours de laquelle Pi devra développer son ingéniosité et faire preuve d’un courage insoupçonné pour survivre à cette aventure incroyable.","en":"The story of an Indian boy named Pi, a zookeeper''s son who finds himself in the company of a hyena, zebra, orangutan, and a Bengal tiger after a shipwreck sets them adrift in the Pacific Ocean."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/hQc6NHCshzZmi7cR6ggQMKlf17i.jpg","es":"https://image.tmdb.org/t/p/w500/9jpQ6BRScQmTULj10mUkjEKelhX.jpg","de":"https://image.tmdb.org/t/p/w500/eeLve6g5O99vIPXhhAxY6QE2v6r.jpg","fr":"https://image.tmdb.org/t/p/w500/bDfZiMQxm6YQxShym38sPWVm2yL.jpg","en":"https://image.tmdb.org/t/p/w500/iLgRu4hhSr6V1uManX6ukDriiSc.jpg"}'::jsonb WHERE id = 303;
UPDATE public.films SET tmdb_id = 59436, titoli_i18n = '{"it":"Midnight in Paris","fr":"Minuit à Paris","en":"Midnight in Paris","de":"Midnight in Paris","es":"Midnight in Paris"}'::jsonb, trame_i18n = '{"it":"Una storia romantica ambientata a Parigi, nella quale s''intrecciano le vicende di una famiglia, in Francia per affari, e di due giovani fidanzati prossimi alle nozze; tutti alle prese con esperienze che cambieranno per sempre le loro vite. Il film è anche la storia del grande amore di un giovane uomo per una città, Parigi, e dell''illusione di tutti coloro che pensano che se avessero avuto una vita diversa sarebbero stati molto più felici.","fr":"Un jeune couple d’américains dont le mariage est prévu à l’automne se rend pour quelques jours à Paris. La magie de la capitale ne tarde pas à opérer, tout particulièrement sur le jeune homme amoureux de la Ville-lumière et qui aspire à une autre vie que la sienne.","en":"While on a trip to Paris with his fiancée''s family, a nostalgic screenwriter finds himself mysteriously going back to the 1920s every day at midnight.","de":"Ein Wunschtraum geht für den Amerikaner Gil in Erfüllung, als er mit seiner Verlobten Inez, ein Mädchen aus wohlhabendem Hause, seinen Urlaub in Paris verbringen kann. Seit seiner Jugend schwärmt Gil von der dortigen Künstlerszene der Zwanzigerjahre. Wenn er nur damals hätte leben können! Hemingway, Fitzgerald, Gertrude Stein – das sind die Idole des erfolgreichen Hollywood-Drehbuchautoren, der sich sehnlichst wünscht, als ernst zu nehmender Schriftsteller zu reüssieren. Inez hat kein Verständnis für seine Schwärmerei. Eines Abends bricht Gil alleine auf und verirrt sich bei seinem Streifzug durch die Straßen der Stadt der Liebe. Punkt Mitternacht geschieht etwas Wundersames: Gil wird von einer Limousine aufgelesen, die ihn geradewegs in die Roaring Twenties transportiert, zu all den legendären Künstlern, die er immer schon bewundert hat! Mit einem Mal ist nichts mehr so, wie es vorher war …","es":"Un escritor norteamericano algo bohemio llega con su prometida Inez y los padres de ésta a París. Mientras vaga por las calles soñando con los felices años 20, cae bajo una especie de hechizo que hace que, a medianoche, en algún lugar del barrio Latino, se vea transportado a otro universo donde va a conocer a personajes que jamás imaginaría iba a conocer..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/hfdsTXO6wIJ9uywIgnqzNYDWYQK.jpg","fr":"https://image.tmdb.org/t/p/w500/d8OE6ZHyisBXLs2cGzP1gqG52Cf.jpg","en":"https://image.tmdb.org/t/p/w500/4wBG5kbfagTQclETblPRRGihk0I.jpg","de":"https://image.tmdb.org/t/p/w500/ocOl71FjnYi0CNEzaLeY6ByKTRR.jpg","es":"https://image.tmdb.org/t/p/w500/paDvLnSZyrDoUVRrUZPjB19zJQZ.jpg"}'::jsonb WHERE id = 304;
UPDATE public.films SET tmdb_id = 44214, titoli_i18n = '{"it":"Il cigno nero","en":"Black Swan","es":"Cisne negro","de":"Black Swan","fr":"Black Swan"}'::jsonb, trame_i18n = '{"it":"Nina è una ballerina del New York City Ballet che sogna il \"ruolo\" e un amore che spezzi l''adolescenza mai finita. Incalzata dalla madre, si sottopone ad un allenamento sotto lo sguardo di Thomas Leroy. Coreografo appassionato e deciso a farne una stella, Leroy le assegna la parte della protagonista nella sua versione del \"Lago dei cigni\". Sul palcoscenico Nina sarà Odette. Eterea e piena di grazia Nina incarna alla perfezione il candore del cigno bianco e con difficoltà il suo doppio nero e tenebroso, che in una superba variazione ingannerà il suo principe e la voterà al suicidio. La ricerca del suo lato oscuro e della consapevolezza della propria sessualità la condurranno verso una tempesta emozionale e all''incontro con Lily, insidiosa rivale in nero. Dietro le quinte Nina si strugge e si predispone a ''doppiare'' il suo cigno bianco.","en":"A committed dancer struggles to maintain her sanity after winning the lead role in a production of Tchaikovsky''s \"Swan Lake.\"","es":"Nina, una brillante bailarina que forma parte de una compañía de ballet de Nueva York, vive completamente absorbida por la danza. La presión de su controladora madre, la rivalidad con su compañera Lily y las exigencias del severo director se irán incrementando a medida que se acerca el día del estreno. Esta tensión provoca en Nina un agotamiento nervioso y una confusión mental que la incapacitan para distinguir entre realidad y ficción.","de":"Nina ist eine ehrgeizige und leidenschaftliche Ballett-Tänzerin, die ihr Leben ausnahmslos ihrer Arbeit an der New Yorker Ballet Company widmet. Dabei wird sie energisch von ihrer Mutter, selbst eine ehemalige Tänzerin, gefördert. Als die Rolle der Primaballerina für die Produktion des Klassikers Schwanensee neu besetzt werden soll, wird Nina von Regisseur Thomas Leroy favorisiert. Sie bekommt jedoch schnell Konkurrenz durch die jüngere Lily, die zwar technisch schwächer ist, aber eine Leichtigkeit besitzt, die sich nicht mit Übung erreichen lässt. Zwischen den beiden entsteht eine außergewöhnliche Beziehung, die zur Zerreißprobe für Nina wird. Immer intensiver lernt sie die düstere Seite ihres Selbst kennen, das ihr bedrohlicherweise immer ähnlicher wird.","fr":"Rivalités dans la troupe du New York City Ballet. Nina est prête à tout pour obtenir le rôle principal du Lac des cygnes que dirige l’ambigu Thomas. Mais elle se trouve bientôt confrontée à la belle et sensuelle nouvelle recrue, Lily…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/dywocnQY2FhEpDeV56Vl3yHw0oy.jpg","en":"https://image.tmdb.org/t/p/w500/viWheBd44bouiLCHgNMvahLThqx.jpg","es":"https://image.tmdb.org/t/p/w500/dZucAEc4JNsO6z4fvvunXgLe3b8.jpg","de":"https://image.tmdb.org/t/p/w500/f5yFgSs9wMCP9lNnRGUM1QI0tXs.jpg","fr":"https://image.tmdb.org/t/p/w500/PgK9d0vegvPCx92b7c15sk4x8h.jpg"}'::jsonb WHERE id = 305;
UPDATE public.films SET tmdb_id = 27205, titoli_i18n = '{"it":"Inception","en":"Inception","fr":"Inception","es":"Origen","de":"Inception"}'::jsonb, trame_i18n = '{"it":"Dom Cobb possiede una qualifica speciale: è in grado di inserirsi nei sogni altrui per prelevare i segreti nascosti nel più profondo del subconscio. Viene contattato da Saito, un potentissimo industriale di origine giapponese, il quale gli chiede di tentare l''operazione opposta. Non deve prelevare pensieri celati ma inserire un''idea che si radichi nella mente di una persona. Costui è Robert Fischer Jr. il quale, alla morte dell''anziano e dittatoriale genitore, dovrà convincersi che l''unica cosa che può fare è distruggere l''impero ereditato. Saito avrà allora campo libero. In cambio offrirà a Cobb la possibilità di rientrare negli Stati Uniti dove è ricercato per omicidio. Cobb accetta e si fa affiancare da un team di cui entra a far parte la giovane Ariane, architetto abilissimo nella costruzione di spazi virtuali.","en":"Cobb, a skilled thief who commits corporate espionage by infiltrating the subconscious of his targets is offered a chance to regain his old life as payment for a task considered to be impossible: \"inception\", the implantation of another person''s idea into a target''s subconscious.","fr":"Dom Cobb est un voleur expérimenté, le meilleur dans l''art dangereux de l''extraction, voler les secrets les plus intimes enfouis au plus profond du subconscient durant une phase de rêve, lorsque l''esprit est le plus vulnérable. Les capacités de Cobb ont fait des envieux dans le monde tourmenté de l''espionnage industriel alors qu''il devient fugitif en perdant tout ce qu''il a un jour aimé. Une chance de se racheter lui est alors offerte. Une ultime mission grâce à laquelle il pourrait retrouver sa vie passée mais uniquement s''il parvient à accomplir l''impossible inception.","es":"Dom Cobb es un ladrón hábil, el mejor de todos, especializado en el peligroso arte de extracción: el robo de secretos valiosos desde las profundidades del subconsciente durante el estado de sueño cuando la mente está más vulnerable. Esta habilidad excepcional de Cobb le ha hecho un jugador codiciado en el traicionero nuevo mundo de espionaje corporativo, pero al mismo tiempo, le ha convertido en un fugitivo internacional y ha tenido que sacrificar todo que le importaba. Ahora a Cobb se le ofrece una oportunidad para redimirse. Con un último trabajo podría recuperar su vida anterior, pero solamente si logra lo imposible.","de":"Beim Versuch in das Unterbewusstsein des Industriellen Saito einzudringen, stoßen Cobb und seine Mitstreiter auf unerwartete Schwierigkeiten. Saito hatte Verteidigungsstrategien gegen den Gedankendiebstahl trainiert und baut nun einen Abwehrriegel auf, doch erst der Verrat eines Kollegen lässt den Versuch scheitern, dem Schlafenden Geheimnisse zu entlocken. Da seine Auftraggeber unbedingten Erfolg gefordert hatten, muss Cobb, der auf Grund einer drohenden Verurteilung nicht mehr in die USA zurück kann, fliehen, doch Saito kommt ihm zuvor. Allerdings nicht um ihn zu bestrafen, sondern um ihm einen Deal vorzuschlagen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/5QHWgqaBxZI1eM5e3YhyKzY5o3z.jpg","en":"https://image.tmdb.org/t/p/w500/xlaY2zyzMfkhk0HSC5VUwzoZPU1.jpg","fr":"https://image.tmdb.org/t/p/w500/aej3LRUga5rhgkmRP6XMFw3ejbl.jpg","es":"https://image.tmdb.org/t/p/w500/tXQvtRWfkUUnWJAn2tN3jERIUG.jpg","de":"https://image.tmdb.org/t/p/w500/t5WUY5ZSxwVIVExaMZmmIj88BKA.jpg"}'::jsonb WHERE id = 306;
UPDATE public.films SET tmdb_id = 11324, titoli_i18n = '{"it":"Shutter Island","en":"Shutter Island","es":"Shutter Island","de":"Shutter Island","fr":"Shutter Island"}'::jsonb, trame_i18n = '{"it":"Nel 1954, i due agenti federali Teddy Daniels e Chuck Aule vengono inviati all''istituto mentale Ashecliffe di Shutter Island, al largo della costa est, per indagare sull''improvvisa scomparsa di Rachel Solando, una pericolosa infanticida. Il direttore dell''istituto, il dottor Cawley, e i vari infermieri sostengono che la madre assassina si sia come dileguata dalla sua stanza senza lasciare alcuna traccia, ma l''agente Daniels nutre fin dal principio dei forti sospetti sullla gestione dell''ospedale da parte del dottor Cawley e del suo medico assistente, il dottor Naehring. Un uragano costringe i due agenti a protrarre il soggiorno sull''isola, durante il quale le indagini proseguono e particolari sempre più inquietanti emergono, mentre Daniels continua ad avere delle visioni che riguardano la moglie defunta e le sue esperienze di guerra contro gli ufficiali nazisti.","en":"World War II soldier-turned-U.S. Marshal Teddy Daniels investigates the disappearance of a patient from a hospital for the criminally insane, but his efforts are compromised by troubling visions and a mysterious doctor.","es":"Verano de 1954. Los agentes judiciales Teddy Daniels y Chuck Aule son destinados a una remota isla del puerto de Boston para investigar la desaparición de una peligrosa asesina recluida en el hospital psiquiátrico Ashecliffe, un centro penitenciario para criminales perturbados dirigido por el siniestro doctor John Cawley. Pronto descubrirán que el centro guarda muchos secretos, y que la isla esconde algo más peligroso que los pacientes.","de":"1954 soll der U.S. Marshall Teddy Daniels das Verschwinden eines Patienten aus dem Bostoner Shutter Island Ashecliffe Hospital aufklären. Er hat sich aus persönlichen Gründen um diesen Auftrag bemüht, aber schon bald muss er sich fragen, ob er nicht durch die Ärzte manipuliert wurde, deren Methoden von unethisch über illegal bis skrupellos gehen. Teddys scharfsinnige Ermittlungsmethoden führen rasch zu einer vielversprechenden Spur, aber das Hospital verweigert ihm Zugriff auf Informationen, die den Fall erhellen könnten. Als ein Hurrikan die Verbindung zum Festland unterbricht, \"entkommen\" weitere gefährliche Kriminelle in dem Chaos und die verwirrenden Hinweise mehren sich, so dass Teddy an allem zu zweifeln beginnt - seinem Gedächtnis, seinem Partner und sogar seinem eigenen Verstand.","fr":"En 1954, le marshal Teddy Daniels et son coéquipier Chuck Aule sont envoyés enquêter sur l’île de Shutter Island, dans un hôpital psychiatrique où sont internés de dangereux criminels. L’une des patientes, Rachel Solando, a inexplicablement disparu. Comment la meurtrière a‐t‐elle pu sortir d’une cellule fermée de l’extérieur ? Le seul indice retrouvé dans la pièce est une feuille de papier sur laquelle on peut lire une suite de chiffres et de lettres sans signification apparente. Œuvre cohérente d’une malade, ou cryptogramme ?"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/kgPRqDDr5RFkIly6CJrBPHYs2qS.jpg","en":"https://image.tmdb.org/t/p/w500/nrmXQ0zcZUL8jFLrakWc90IR8z9.jpg","es":"https://image.tmdb.org/t/p/w500/56utveUWJwmG12YU7c2zKw6pbRZ.jpg","de":"https://image.tmdb.org/t/p/w500/mm07ImVjMcrBFhcepmy63toBfax.jpg","fr":"https://image.tmdb.org/t/p/w500/fQ0vGVTtxjCdAJnxwPZ88O3Wzrh.jpg"}'::jsonb WHERE id = 307;
UPDATE public.films SET tmdb_id = 19995, titoli_i18n = '{"en":"Avatar","it":"Avatar","fr":"Avatar","de":"Avatar - Aufbruch nach Pandora","es":"Avatar"}'::jsonb, trame_i18n = '{"en":"In the 22nd century, a paraplegic Marine is dispatched to the moon Pandora on a unique mission, but becomes torn between following orders and protecting an alien civilization.","it":"Jake Sully è un marine costretto su una sedia a rotelle che accetta di trasferirsi sul pianeta Pandora in sostituzione del fratello morto, la cui missione era quella di esplorare il pianeta. Essendo l''atmosfera del pianeta tossica per gli umani sono stati creati degli esseri simili ai nativi Na''vi che possono essere ''guidati'' dagli umani. Pandora è un enorme giacimento di un minerale prezioso per la Terra dove le fonti di energia sono azzerate. Gli indigeni Na''vi non hanno intenzione di essere colonizzati. Il compito iniziale dell''avatar di Jake sarà quello di conoscerne usi e costumi e di farsi accettare all''interno delle comunità indigene. Jake conosce così Neytiri, una guerriera Na''vi figlia del capo tribù. Da lei impara a divenire un guerriero molto diverso dal marine che è stato e se ne innamora ricambiato.","fr":"Un marine paraplégique, envoyé sur la lune Pandora pour une mission unique, est tiraillé entre suivre ses ordres et protéger le monde qu''il considère dorénavant comme le sien.","de":"Ex-Marine Jake Sully nimmt auf dem Planeten Pandora an einem Experiment unter der Leitung der Wissenschaftlerin Dr. Grace Augustine teil. Als er sich im genetisch manipulierten Körper der Ureinwohner in die schöne Neytiri verliebt, gerät er zwischen die Fronten eines skrupellosen Konzerns und dem naturverbundenen Volk der Na''vi. Jake muss sich entscheiden, auf welcher Seite er steht - in einem ungleichen Kampf, in dem es um das Schicksal einer einzigartigen Welt geht ...","es":"Año 2154. Jake Sully, un exmarine en silla de ruedas, es enviado al planeta Pandora, donde se ha creado el programa Avatar, gracias al cual los seres humanos pueden controlar de forma remota un cuerpo biológico con apariencia y genética de la especie nativa. Pronto se encontrará con la encrucijada entre seguir las órdenes de sus superiores o defender al mundo que le ha acogido y siente como suyo."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/gKY6q7SjCkAU6FqvqWybDYgUKIF.jpg","it":"https://image.tmdb.org/t/p/w500/cu6CTvQqVvaTUmWNGWydpf7EzmV.jpg","fr":"https://image.tmdb.org/t/p/w500/7N8L80OaG8EBTDdRBjGqT8PBzCM.jpg","de":"https://image.tmdb.org/t/p/w500/8VV4YUwOGxgolFZTo2SgNwsfznR.jpg","es":"https://image.tmdb.org/t/p/w500/t5T3LPbLLgP2OP6kloM9p2PXpJL.jpg"}'::jsonb WHERE id = 308;
UPDATE public.films SET tmdb_id = 83533, titoli_i18n = '{"en":"Avatar: Fire and Ash","it":"Avatar: Fuoco e cenere","es":"Avatar: Fuego y ceniza","de":"Avatar: Fire and Ash","fr":"Avatar : De feu et de cendres"}'::jsonb, trame_i18n = '{"en":"In the wake of the devastating war against the RDA and the loss of their eldest son, Jake Sully and Neytiri face a new threat on Pandora: the Ash People, a violent and power-hungry Na''vi tribe led by the ruthless Varang. Jake''s family must fight for their survival and the future of Pandora in a conflict that pushes them to their emotional and physical limits.","it":"In seguito alla devastante guerra contro la RDA e alla perdita del loro figlio maggiore, Jake Sully e Neytiri affrontano una nuova minaccia su Pandora: il Popolo della Cenere, una tribù Na''vi violenta e assetata di potere guidata dagli spietati Varang. La famiglia di Jake deve lottare per la propria sopravvivenza e per il futuro di Pandora in un conflitto che li spinge ai loro limiti emotivi e fisici.","es":"Jake Sully y Neytiri enfrentan una nueva amenaza en Pandora: los Ash People, una tribu Na''vi violenta y sedienta de poder, liderada por la implacable Varang. Tras la devastadora guerra contra la RDA y la pérdida de su hijo mayor, la familia de Jake deberá luchar por su supervivencia y el futuro de Pandora en un conflicto que llevará a los personajes a sus límites emocionales y físicos. Con nuevos y antiguos aliados, esta épica visual y emocional redefine el destino de un mundo al borde del abismo.","de":"Nach dem verheerenden Krieg gegen die RDA und dem Verlust ihres ältesten Sohnes sehen sich Jake Sully und Neytiri mit einer neuen Bedrohung auf Pandora konfrontiert: dem Aschvolk, einem gewalttätigen und machthungrigen Na''vi-Stamm unter der Führung des skrupellosen Varang. Jakes Familie muss in einem Konflikt, der sie an ihre emotionalen und physischen Grenzen bringt, um ihr Überleben und die Zukunft von Pandora kämpfen.","fr":"Après la mort de Neteyam, Jake et Neytiri affrontent leur chagrin tout en faisant face au Peuple des Cendres, une tribu Na’vi redoutable menée par la fougueuse Varang, alors que le conflit sur Pandora s’intensifie et qu’une nouvelle quête morale s’amorce."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/bRBeSHfGHwkEpImlhxPmOcUsaeg.jpg","it":"https://image.tmdb.org/t/p/w500/kvivMhuEuzXuaj0UMjAAmrXVvWn.jpg","es":"https://image.tmdb.org/t/p/w500/4n1U0Mwn7djux6VKNYDRWPgS2x6.jpg","de":"https://image.tmdb.org/t/p/w500/nB8gjQdI6RPczGcJ5mzCgAdjdH8.jpg","fr":"https://image.tmdb.org/t/p/w500/kG3N8oQ10qiw2MsnSHFGJpQNyEy.jpg"}'::jsonb WHERE id = 309;
UPDATE public.films SET tmdb_id = 76600, titoli_i18n = '{"fr":"Avatar : La Voie de l''eau","it":"Avatar: La via dell''acqua","en":"Avatar: The Way of Water","de":"Avatar: The Way of Water","es":"Avatar: El sentido del agua"}'::jsonb, trame_i18n = '{"fr":"Une dizaine d''années s''est écoulée depuis les précédents évènements survenus sur Pandora. Jake Sully et Neytiri sont devenus parents. Leur vie idyllique, proche de la nature, est menacée lorsque la « Ressources Développement Administration », dangereuse organisation non-gouvernementale, est de retour sur Pandora. Contraints de quitter leur habitat naturel, Jake et sa famille se rendent sur les récifs, où ils pensent trouver asile. Mais ils tombent sur un clan, les Metkayina, aux mœurs différentes des leurs.","it":"Jake vive felicemente la sua vita insieme a Neytiri ma Pandora nasconde ancora numerosi misteri. Quando una vecchia, familiare minaccia torna ad affacciarsi per terminare quel che era stato iniziato un tempo, Jake dovrà nuovamente collaborare con l''esercito dei Na''vi per proteggere il loro incredibile pianeta. In veste di patriarca si ritroverà a dover combattere una dura guerra contro gli umani. Jake e Neytiri saranno pertanto costretti a lasciare la loro casa ed esplorare varie regioni di Pandora...","en":"Set more than a decade after the events of the first film, learn the story of the Sully family (Jake, Neytiri, and their kids), the trouble that follows them, the lengths they go to keep each other safe, the battles they fight to stay alive, and the tragedies they endure.","de":"Mehr als zehn Jahre nach den Ereignissen des ersten Films haben Jake und Neytiri eine Familie gegründet. Ihre Kinder sind Neteyam, Lo’ak und Tuktirey, der adoptierte Menschenjunge Miles “Spider” Socorro und die adoptierte Na’vi-Teenagerin Kiri. Doch ihre Heimat ist weiterhin nicht sicher - das müssen sie feststellen, als die Resources Development Administration (RDA) unter Führung von General Ardmore mit noch mehr Militär und einem alten Bekannten nach Pandora zurückkehrt, um den Planeten zur neuen Heimat der Menschheit zu machen. Bald sehen sich Neytiri, Jake und ihre Familie gezwungen, ihr Zuhause zu verlassen und beim Na’vi-Stamm der Metkayina Zuflucht zu suchen, der an den Küsten und Meeren des Mondes Pandora lebt und von der schwangeren Ronal und ihrem Mann Tonowari angeführt wird.","es":"Más de una década después de los acontecimientos de ''Avatar'', los Na''vi Jake Sully, Neytiri y sus hijos viven en paz en los bosques de Pandora hasta que regresan los hombres del cielo. Entonces comienzan los problemas que persiguen sin descanso a la familia Sully, que decide hacer un gran sacrificio para mantener a su pueblo a salvo y seguir ellos con vida."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/6WXn6RE1NAqcP2TfPcbVRawHUfE.jpg","it":"https://image.tmdb.org/t/p/w500/idul2fSUPkk0EHP92EzmES6KGW4.jpg","en":"https://image.tmdb.org/t/p/w500/t6HIqrRAclMCA60NsSmeqe9RmNV.jpg","de":"https://image.tmdb.org/t/p/w500/dsBpvG4m0uOerBOuNITL9rvaD0I.jpg","es":"https://image.tmdb.org/t/p/w500/ckeTumMS4G31UQ9NNkmtW2QhfMF.jpg"}'::jsonb WHERE id = 310;
UPDATE public.films SET tmdb_id = 14160, titoli_i18n = '{"en":"Up","de":"Oben","fr":"Là-haut","it":"Up","es":"Up"}'::jsonb, trame_i18n = '{"en":"Carl Fredricksen spent his entire life dreaming of exploring the globe and experiencing life to its fullest. But at age 78, life seems to have passed him by, until a twist of fate (and a persistent 8-year old Wilderness Explorer named Russell) gives him a new lease on life.","de":"Carl Fredricksen hat Zeit seines Lebens mit seiner Frau davon geträumt, die Welt zu bereisen, Abenteuer zu erleben und in Südamerika die Paradise-Fälle zu besuchen. Immer ist etwas dazwischen gekommen. Nach ihrem Tod will der 78-jährige die Pläne endlich in die Tat umsetzen, zumal sein Häuschen einer neuen Immobilie den Platz machen soll. Begleitet von dem hartnäckigen Pfadfinder Russell macht er sich auf den Weg – inklusive seines Häuschens, das sich, an zahllosen Ballons aufgehängt, in die Lüfte schwingt …","fr":"À 78 ans, Carl n''envisage plus qu''une chose : finir tranquillement sa vie dans la petite maison où il a passé toute une existence paisible auprès de son épouse Ellie. Veuf désormais, il reste, en effet, attaché à son passé en refusant les propositions mirobolantes d''un promoteur pour racheter son bien. Quand des circonstances exceptionnelles le contraignent d''intégrer une maison de retraite, il prend une ultime fois les choses en mains et, transformant sa demeure en dirigeable, s''envole pour l''aventure, vers la partie du monde où sa femme et lui s''étaient promis un jour de s''installer. Il ne se doute pas alors qu''il a emporté avec lui un jeune passager clandestin, Russell et que le voyage sera loin d''être de tout repos…","it":"Carl Fredricksen ha trascorso tutta la vita sognando di esplorare il mondo e di vivere appieno ogni istante. Ma a 78 anni, la vita sembra essergli sfuggita di mano, finché un colpo di fortuna (e un tenace esploratore di 8 anni di nome Russell) non gli regala una nuova prospettiva.","es":"Tras atar miles de globos a su casa, Carl Fredricksen, un vendedor de globos jubilado, se embarca en el mundo de los sueños de la infancia. Pero sin que Carl lo sepa, Russell, un explorador de 8 años, se encuentra en el lugar equivocado en el momento equivocado: el porche delantero de la casa. El dúo más improbable conoce a fantásticos amigos como Dug, un perro con un collar especial que le permite hablar, y Kevin, un pájaro de cuatro metros de altura que no vuela. Atrapados en la selva, Carl se da cuenta de que a veces las mayores aventuras de la vida son las que menos esperabas."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/mFvoEwSfLqbcWwFsDjQebn9bzFe.jpg","de":"https://image.tmdb.org/t/p/w500/gOOVHWgBmpoeYXG9tGFiNOLsSWl.jpg","fr":"https://image.tmdb.org/t/p/w500/k55kMEPkxGej70udPcVNqhTiwBz.jpg","it":"https://image.tmdb.org/t/p/w500/j3Ga41uc0y3W8KbKjSfPHQiZYVn.jpg","es":"https://image.tmdb.org/t/p/w500/1N0LtzUueXrlnpL466jQBJ6iAuj.jpg"}'::jsonb WHERE id = 311;
UPDATE public.films SET tmdb_id = 591, titoli_i18n = '{"en":"The Da Vinci Code","es":"El código Da Vinci","fr":"Da Vinci Code","de":"The Da Vinci Code - Sakrileg","it":"Il codice da Vinci"}'::jsonb, trame_i18n = '{"en":"A murder in Paris’ Louvre Museum and cryptic clues in some of Leonardo da Vinci’s most famous paintings lead to the discovery of a religious mystery. For 2,000 years a secret society closely guards information that — should it come to light — could rock the very foundations of Christianity.","es":"El catedrático y afamado simbologista Robert Langdon se ve obligado a acudir una noche al Museo del Louvre, cuando el asesinato de un restaurador deja tras de sí un misterioso rastro de símbolos y pistas. Con la ayuda de la criptógrafa de la policía Sophie Neveu y poniendo en juego su propia vida, Langdon descubre que la obra de Leonardo Da Vinci esconde una serie de misterios que apuntan a una sociedad secreta encargada de custodiar un antiguo secreto que ha permanecido oculto durante dos mil años...","fr":"Une nuit, le professeur Robert Langdon, éminent spécialiste de l''étude des symboles, est appelé d''urgence au Louvre : le conservateur du musée a été assassiné, mais avant de mourir, il a laissé de mystérieux symboles... Avec l''aide de la cryptologue Sophie Neveu, Langdon va mener l''enquête et découvrir des signes dissimulés dans les œuvres de Léonard de Vinci. Tous les indices convergent vers une organisation religieuse aussi mystérieuse que puissante, prête à tout pour protéger un secret capable de détruire un dogme deux fois millénaire... De Paris à Londres, puis en Écosse, Langdon et Sophie vont tout tenter pour déchiffrer le code et approcher les secrets qui remettent en cause les fondements mêmes de l''humanité...","de":"Mitten in der Nacht wird der renommierte Harvard-Symbologe Robert Langdon in den Pariser Louvre gerufen: Der Museumsdirektor wurde ermordet. Seine Leiche, die in einer Körperhaltung wie der des Vitruvischen Mannes von Leonardo da Vinci aufgefunden wird, ist der erste grausige Hinweis in einer mysteriösen Kette aus Codes und Symbolen. Unter Einsatz seines Lebens entschlüsselt Langdon mit Hilfe der Polizei- Kryptografin, Sophie Neveu versteckte Botschaften in den Kunstwerken Leonardo da Vincis. Alle verweisen auf eine sagenumwobene Bruderschaft, deren Mitglieder seit 2000 Jahren ein machtvolles Geheimnis bewahren. Die atemlose Schnitzeljagd führt Langdon und Sophie von Paris über London bis nach Schottland; währenddessen versuchen sie verzweifelt, den Code zu knacken, um mit ihm ein Geheimnis zu enthüllen, das die Menschheit in ihren Grundfesten erschüttern wird.","it":"Nel Museo del Louvre ha avuto luogo uno spettacolare omicidio e tutti gli indizi fanno pensare ad una setta religiosa che non si ferma davanti a niente pur di difendere una verità, la quale però non può essere nascosta ancora a lungo e il mistero rischia di essere decodificato. Per proteggere un segreto a volte basta chiedere a chi lo custodisce di non rivelarlo; tuttavia se può far crollare 2''000 anni di dogmi consolidati, bisogna mettere a tacere i suoi depositari, costasse anche la loro vita."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/9ejKfNk0LBhSI9AahH4f9NJNZNM.jpg","es":"https://image.tmdb.org/t/p/w500/r5DHVCB5AV7B7GLmXMyA71Y4Yu4.jpg","fr":"https://image.tmdb.org/t/p/w500/q6wt3HwGwRnzKbpgwNTeIZgHKkH.jpg","de":"https://image.tmdb.org/t/p/w500/99ef1uGXkiQU4h2wuN3xIBC2kCN.jpg","it":"https://image.tmdb.org/t/p/w500/sBqvvYq8PSNCJD3154Vdl5e7vAs.jpg"}'::jsonb WHERE id = 312;
UPDATE public.films SET tmdb_id = 13448, titoli_i18n = '{"it":"Angeli e demoni","en":"Angels & Demons","es":"Ángeles y demonios","de":"Illuminati","fr":"Anges et Démons"}'::jsonb, trame_i18n = '{"it":"Roma e il mondo sono in lutto per la morte del Santo Padre. Distrutto l''anello piscatorio, il camerlengo deve fare fronte al rapimento dei quattro cardinali favoriti alla successione pontificia e alla minaccia della distruzione della Città del Vaticano ad opera degli Illuminati, una confraternita venuta dal passato a rivendicare il primato della scienza sulla Chiesa e sullo Spirito. Riunito in Concistoro per eleggere il nuovo Papa, il collegio cardinalizio assolda Robert Langdon, docente di simbologia religiosa a Harvard. Nemico stimato della Chiesa, che non gli perdona la negazione dell''incarnazione del Verbo, il cavaliere accademico accetta l''investitura e parte alla volta della Capitale. Archiviati acredine e risentimento, il professore e gli uomini della Chiesa, armati di spirito e alabarda, collaboreranno alle indagini e alla risoluzione del mistero. Un mistero nascosto dentro le chiese e sotto le segrete della Città Eterna.","en":"Harvard symbologist Robert Langdon is recruited by the Vatican to investigate the apparent return of the Illuminati – a secret, underground organization – after four cardinals are kidnapped on the night of the papal conclave.","es":"Robert Langdon descubre la prueba de la reaparición de una antigua hermandad secreta conocida como los Illuminati: la más poderosa organización secreta en la historia, que a su vez también se enfrenta a una amenaza que hace que peligre su existencia: la Iglesia Católica. Cuando Langdon se entera de que los Illuminati conspiran en contra de la Iglesia intentando detonar una bomba de antimateria, él se dirige a Roma, donde une fuerzas con Vittoria Vetra.","de":"Die Gefahr lauert im Geheimen. Während in Rom die Papstwahlen Gläubige auf der ganzen Welt in Atem halten, plant der untergegangen geglaubte und einst herausragend mächtige Geheimbund „Die Illuminati“ den entscheidenden Schlag gegen seinen alten Erzfeind: die katholische Kirche. Das zumindest findet der amerikanische Wissenschaftler Robert Langdon heraus, der keine Zeit verliert und sich in Rom mit der italienischen Kollegin Vittoria Vetra verbündet. Ein Wettlauf mit der Zeit auf der Suche nach altertümlichen Symbolen und der Rettung für den Vatikan beginnt.","fr":"Une antique confrérie secrète parmi les plus puissantes de l''Histoire, les \"Illuminati\", qui s''était jurée autrefois d''anéantir l''Église catholique, est de retour. Cette fois, elle est sur le point de parvenir à son but : Robert Langdon, expert en religions d''Harvard, en a la certitude. Langdon a peu de temps pour comprendre ce qui se trame contre le Vatican et déjouer ces nouveaux crimes. Une course contre la montre et contre les tueurs qui démarre tel un jeu de piste : des églises romaines aux cryptes enfouies, des catacombes les plus profondes aux majestueuses cathédrales... Pour l''aider à comprendre toutes ces énigmes, Langdon va rencontrer Vittoria Vetra, une scientifique aussi belle que mystérieuse. Cette fois, il sait à qui il se confronte. Cette enquête diabolique est un piège, chaque secret est une clé, chaque révélation un danger..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/9Jc7YuiYVFpiJ7tbvXkRV7GTxTM.jpg","en":"https://image.tmdb.org/t/p/w500/tFZQAuulEOtFTp0gHbVdEXwGrYe.jpg","es":"https://image.tmdb.org/t/p/w500/kLTpEwwVyquJmWak9qKGc4icFMK.jpg","de":"https://image.tmdb.org/t/p/w500/yGVoQ7nFCDE1uuqiZL6ZVSLOZKf.jpg","fr":"https://image.tmdb.org/t/p/w500/yNrMIGy1eG0cjd2WSrHz2OcUWEy.jpg"}'::jsonb WHERE id = 313;
UPDATE public.films SET tmdb_id = 13223, titoli_i18n = '{"it":"Gran Torino","es":"Gran Torino","fr":"Gran Torino","de":"Gran Torino","en":"Gran Torino"}'::jsonb, trame_i18n = '{"it":"Walt Kowalski è un veterano della guerra in Corea e non sopporta che nell''abitazione di fianco alla sua viva una famiglia di asiatici. Le uniche sue passioni, oltre alla birra, sono il suo cane e un''auto modello Gran Torino, che viene sottoposta a continua manutenzione. La sua vita cambia il giorno in cui il giovane vicino Thao, spinto da una gang, si introduce nel suo garage. Walt lo fa fuggire, ma di lì a poco tempo assisterà a una violenta irruzione dei membri della gang con inatteso sconfinamento nella sua proprietà. In quell''occasione sottrarrà Thao alla violenza del branco, ottenendo la riconoscenza della sua famiglia.","es":"Walt Kowalski, un veterano de la guerra de Corea, es un obrero jubilado del sector del automóvil. Su máxima pasión es cuidar de su más preciado tesoro: un coche Gran Torino de 1972. Es un hombre inflexible y con una voluntad de hierro, al que le cuesta trabajo asimilar los cambios que se producen a su alrededor. Sin embargo, las circustancias harán que se vea obligado a replantearse sus ideas.","fr":"Walt Kowalski est un ancien de la guerre de Corée, un homme inflexible, amer et pétri de préjugés surannés. Après des années de travail à la chaîne, il vit replié sur lui-même, occupant ses journées à bricoler, traînasser et siroter des bières. Avant de mourir, sa femme exprima le vœu qu''il aille à confesse, mais Walt n''a rien à avouer, ni personne à qui parler. Hormis sa chienne Daisy, il ne fait confiance qu''à son M-1, toujours propre, toujours prêt à l''usage… Ses anciens voisins ont déménagé ou sont morts depuis longtemps. Son quartier est aujourd''hui peuplé d''immigrants asiatiques qu''il méprise, et Walt ressasse ses haines, innombrables - à l''encontre de ses voisins, des ados Hmong, latinos et afro-américains « qui croient faire la loi », de ses propres enfants, devenus pour lui des étrangers. Walt tue le temps comme il peut, en attendant le grand départ, jusqu''au jour où un ado Hmong du quartier tente de lui voler sa précieuse Ford Gran Torino…","de":"Der verwitwete Koreakrieg-Veteran Walt Kowalski ist ein verbitterter Misanthrop. Für die jüngere Generation hat er ob deren angeblicher Respektlosigkeit nur Verachtung übrig, das Verhältnis zu seinen eigenen Kindern ist eisig. Liebe und Zuneigung erfahren lediglich sein Hund Daisy, sein altes Sturmgewehr sowie sein pedantisch gepflegter Ford Gran Torino. Dass Kowalskis einst geliebtes Viertel zunehmend von Migranten vor allem aus Südostasien überschwemmt wird, ist dem pensionierten Fabrikarbeiter ein massiver Dorn im Auge. Beim Einzug einer koreanischen Familie ins Nachbarhaus, macht der rassistische Rentner auch keinen Hehl aus seiner Verachtung. Als deren halbwüchsiger Sohn Taoh im Zuge eines Initiationsrituals ausgerechnet Kowalskis geliebten Gran Torino stehlen soll, droht die angespannte Situation zu eskalieren ...","en":"Disgruntled Korean War veteran Walt Kowalski sets out to reform his neighbor, Thao Lor, a Hmong teenager who tried to steal Kowalski''s prized possession: a 1972 Gran Torino."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/eUepSGWIJjXeMAlSnk4CSZKOTfg.jpg","es":"https://image.tmdb.org/t/p/w500/7w54KRHdRokgXqxL59GKVau8e6l.jpg","fr":"https://image.tmdb.org/t/p/w500/sVmDIIFPzbyEz87dZYpLfetn4Lm.jpg","de":"https://image.tmdb.org/t/p/w500/rotZYrCliqDaqLWCyj6HEa8yHuT.jpg","en":"https://image.tmdb.org/t/p/w500/zUybYvxWdAJy5hhYovsXtHSWI1l.jpg"}'::jsonb WHERE id = 314;
UPDATE public.films SET tmdb_id = 12163, titoli_i18n = '{"it":"The Wrestler","es":"El luchador","en":"The Wrestler","fr":"The Wrestler","de":"The Wrestler"}'::jsonb, trame_i18n = '{"it":"Randy \"The Ram\" Robinson era un wrestler professionista di rinomata fama alla fine degli anni 80''. Vent''anni dopo tira avanti esibendosi per i fans del duro wrestling nelle palestre dei licei e nelle comunità del New Jersey. Allontanatosi dalla figlia, incapace di sostenere un vero rapporto, Randy vive per il brivido dello show, per l''adrenalina del combattimento e per l''adorazione dei fans che gli rimangono. Colto da un infarto durante un combattimento, il dottore gli dice di eliminare gli steroidi e di sospendere i combattimenti di wrestling. Costretto a lasciare lo show-business, Randy comincia a riflettere sulla sua vita. Prova a riallacciare i rapporti con sua figlia e inizia una relazione con una spogliarellista ormai non più giovanissima. Per un periodo le cose funzionano; tuttavia il richiamo della ribalta è troppo forte per lui e Randy si cimenta ancora una volta nel combattimento sul ring.","es":"Randy \"The Ram\" Robinson (Mickey Rourke) es un luchador profesional de wrestling que, tras haber sido una estrella en la década de los ochenta, trata de continuar su carrera en el circuito independiente, combatiendo en cuadriláteros de tercera categoría. Cuando se da cuenta de que los brutales golpes que ha recibido a lo largo de su carrera le empiezan a pasar factura, decide poner un poco de orden en su vida: intenta acercarse a Stephanie, la hija que abandonó (Evan Rachel Wood) y trata de superar la soledad con su amor por Cassidy, una streaper (Marisa Tomei).","en":"Aging wrestler Randy \"The Ram\" Robinson is long past his prime but still ready and rarin'' to go on the pro-wrestling circuit. After a particularly brutal beating, however, Randy hangs up his tights, pursues a serious relationship with a long-in-the-tooth stripper, and tries to reconnect with his estranged daughter. But he can''t resist the lure of the ring and readies himself for a comeback.","fr":"A la fin des années 80, Randy Robinson, dit The Ram (\"Le Bélier\"), était une star du catch. Vingt ans plus tard, il ne se produit plus que dans des salles de gym de lycées ou des maisons de quartier... Brouillé avec sa fille, il est incapable d''entretenir une relation durable avec quiconque : il ne vit que pour le plaisir du spectacle et l''adoration de ses fans. Mais lorsqu''il est foudroyé par une crise cardiaque au beau milieu d''un match, son médecin lui ordonne d''abandonner le catch : un autre combat pourrait lui être fatal. Contraint de se ranger, il tente de renouer avec sa fille et, dans le même temps, entame une liaison avec une strip-teaseuse vieillissante. Pourtant, son goût du spectacle et sa passion pour le catch risquent bien de reprendre le dessus et de le propulser de nouveau sur le ring...","de":"Randy „The Ram“ Robinson steht vor den Trümmern seines Lebens: Die große Zeit als Wrestling-Star in den 80er Jahren ist längst vorbei, finanziell ist es schlecht um ihn bestellt und seine Tochter Stephanie hat nicht mehr als Enttäuschung und Verachtung für ihn übrig. Während sich Randy an seine vergangenen Erfolge klammert, weiterhin auf miesen kleinen Kampf-Events auftritt und sich mit Steroiden in körperlicher Form hält, muss der abgewrackte Profi-Wrestler feststellen, wie weit seine Vereinsamung bereits fortgeschritten ist. Nur mit Stripperin Cassidy verbindet ihn eine tiefere Freundschaft. Zu seiner miserablen Gesamtsituation kommen erschwerend gesundheitliche Probleme hinzu, die ihren vorläufigen Höhepunkt in einem Herzanfall finden. Randy muss das Wrestling an den Nagel hängen um weitere Zusammenbrüche zu vermeiden – doch im Berufsleben kann der alternde Sportler nicht mehr Fuß fassen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/A0Uq6fZG9UVbaFZmwF593ESz8LE.jpg","es":"https://image.tmdb.org/t/p/w500/hQpBhEHCFNYgakxpP6pAVB2k3fp.jpg","en":"https://image.tmdb.org/t/p/w500/7QH5p5BF582k6qHufCKjftfkqWH.jpg","fr":"https://image.tmdb.org/t/p/w500/7QpX4fwxAG6F90dCp6TgXYX0YkI.jpg","de":"https://image.tmdb.org/t/p/w500/7QH5p5BF582k6qHufCKjftfkqWH.jpg"}'::jsonb WHERE id = 315;
UPDATE public.films SET tmdb_id = 12162, titoli_i18n = '{"it":"The Hurt Locker","en":"The Hurt Locker","fr":"Démineurs","de":"Tödliches Kommando - The Hurt Locker","es":"En tierra hostil"}'::jsonb, trame_i18n = '{"it":"I 40 giorni al fronte, in Iraq, di una squadra di artificieri e sminatori dell''esercito statunitense, unità speciale con elevatissimo tasso di mortalità. Quando tutto quel che resta del suo predecessore finisce in una \"cassetta del dolore\", pronta al rimpatrio, a capo della EOD (unità per la dismissione di esplosivi) arriva il biondo William James, un uomo che ha disinnescato un numero incredibile di bombe e sembra non conoscere la paura della morte. Uno che non conta i giorni, un volontario che ha scelto quel lavoro e da esso si è lasciato assorbire fino al punto di non ritorno.","en":"During the Iraq War, a Sergeant recently assigned to an army bomb squad is put at odds with his squad mates due to his maverick way of handling his work.","fr":"Bagdad. Le lieutenant James est à la tête de la meilleure unité de déminage de l''US Army. Leur mission: désamorcer des bombes dans des quartiers civils ou des théâtres de guerre, au péril de leur vie, alors que la situation locale est encore... explosive.","de":"Als wäre der Job der Bombenexperten im Irak nicht schon gefährlich genug, müssen Sanborn und Eldridge, beides Soldaten einer kleinen Elite-Einheit, feststellen, dass ihr neuer Sergeant lebensgefährliche Alleingänge unternimmt und den Tod herauszufordern scheint. Wenn sie den Krieg überleben wollen, müssen sie ihn schnellstmöglich unter Kontrolle bringen.","es":"En Irak, una unidad de élite de artificieros norteamericanos actúa en una caótica ciudad donde cualquier persona puede ser un enemigo y cualquier objeto, una bomba. El jefe del grupo, el sargento Thompson, muere en el transcurso de una misión y es sustituido por el impredecible y temerario sargento William James. Cuando falta poco para que la brigada sea relevada, el imprudente comportamiento de James hará que dos de sus subordinados, se planteen seriamente el riesgo que corren."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/9XaL18pWKcQO2M581832MjHlldD.jpg","en":"https://image.tmdb.org/t/p/w500/io2dfBJhasvGbgkCX9cCGVOiA99.jpg","fr":"https://image.tmdb.org/t/p/w500/mk9FGer03HxwLwFQeHkMiYtQi8o.jpg","de":"https://image.tmdb.org/t/p/w500/w1A4vVABxCyuLVjxuFFbMWcX4pC.jpg","es":"https://image.tmdb.org/t/p/w500/q57Kw9mCuqAa2cP2qHaU9zFxgdM.jpg"}'::jsonb WHERE id = 316;
UPDATE public.films SET tmdb_id = 6479, titoli_i18n = '{"it":"Io sono leggenda","en":"I Am Legend","fr":"Je suis une légende","es":"Soy leyenda","de":"I Am Legend"}'::jsonb, trame_i18n = '{"it":"New York, 2012. Un virus creato per curare il cancro, ha trasformato le persone in creature cannibali che temono la lice del sole. La città è deserta e l''unico sopravvissuto è il dottor Robert Neville, immune al virus che tenta di trovare un siero che potrebbe salvare l''umanità.","en":"Robert Neville is a scientist who was unable to stop the spread of the terrible virus that was incurable and man-made. Immune, Neville is now the last human survivor in what is left of New York City and perhaps the world. For three years, Neville has faithfully sent out daily radio messages, desperate to find any other survivors who might be out there. But he is not alone.","fr":"Des années après qu''une épidémie a anéanti presque tous les êtres humains et transformé le reste en monstres, le seul survivant à New York se bat vaillamment pour trouver un remède.","es":"Año 2012. Robert Neville es el último hombre vivo que hay sobre la Tierra, pero no está solo. Los demás seres humanos se han convertido en unos mutantes nocturnos llamados \"Darkseekers\" y todos ansían beber su sangre. Durante el día vive en estado de alerta, como un cazador, y busca a los muertos vivientes mientras duermen; pero durante la noche debe esconderse de ellos y esperar el amanecer. Esta pesadilla empezó hace tres años: Neville era un brillante científico, pero no pudo impedir la expansión de un terrible virus creado por el hombre. Él ha sobrevivido porque es inmune al virus; todos los días envía mensajes por radio con la esperanza de que haya otros supervivientes, pero es inútil. Lo único que puede hacer es buscar una fórmula que le permita utilizar su sangre inmune para devolverles a los hombres su naturaleza. Pero está en inferioridad de condiciones y el tiempo se acaba.","de":"Robert Neville war ein hervorragender Wissenschaftler, aber auch er konnte nicht verhindern, dass ein Virus vor 3 Jahren die gesamte Menschheit befiel. Nur er wurde aus unbekannten Gründen verschont und hat es sich inzwischen in einer immer mehr verwahrlosenden Umgebung eingerichtet. Tagsüber kann er sich verhältnismäßig frei bewegen, aber nachts lauern überall Gefahren durch vampirähnliche infizierte Gestalten, die nur das Sonnenlicht fern halten kann. Doch die Bedrohung wächst ständig und er versucht ein Gegenserum zu entwickeln..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/lrHsksAln0IxYFfZVgW6iRTaUsi.jpg","en":"https://image.tmdb.org/t/p/w500/fhbiz5BsGUVEZmzPP72SoPlbMz0.jpg","fr":"https://image.tmdb.org/t/p/w500/wCcC0oAsM1YHfO4sBFLSUtqCQZx.jpg","es":"https://image.tmdb.org/t/p/w500/pO1SrJgf5BumqcIRkYviSGIFdmX.jpg","de":"https://image.tmdb.org/t/p/w500/9rb7n00Q6KDsWH2jZOdeSHe0mvL.jpg"}'::jsonb WHERE id = 317;
UPDATE public.films SET tmdb_id = 7345, titoli_i18n = '{"it":"Il petroliere","es":"Pozos de ambición","en":"There Will Be Blood","fr":"There Will Be Blood","de":"There Will Be Blood"}'::jsonb, trame_i18n = '{"it":"Daniel Plainview è un cercatore d''argento che, alla fine dell''800 trova il petrolio nell''Ovest degli Stati Uniti. La sua ricchezza diventa considerevole, ma l''uomo, sempre più accecato da una misantropia assoluta, allontanerà da sé anche il figlio, precipitando sempre più nell''avidità del possesso.","es":"Texas, principios del siglo XX. Una historia sobre la familia, la avaricia y la religión. Daniel Plainview (Daniel Day-Lewis) se traslada a una miserable ciudad con el propósito de hacer fortuna, pero, a medida que se va enriqueciendo, sus principios y valores desaparecen y acaba dominado por la ambición. Tras encontrar un rico yacimiento de petróleo en 1902, se convierte en un acaudalado magnate. Cuando, años después, intenta apoderarse de un nuevo yacimiento, tiene que enfrentarse al predicador Eli Sunday (Paul Dano). Adaptación de la novela de Upton Sinclair \"Petróleo\", escrita en 1927.","en":"Ruthless silver miner, turned oil prospector, Daniel Plainview, moves to oil-rich California. Using his son to project a trustworthy, family-man image, Plainview cons local landowners into selling him their valuable properties for a pittance. However, local preacher Eli Sunday suspects Plainview''s motives and intentions, starting a slow-burning feud that threatens both their lives.","fr":"Lorsque Daniel Plainview entend parler d’une petite ville de Californie où l’on dit qu’un océan de pétrole coulerait littéralement du sol, il décide d’aller tenter sa chance et part avec son fils H.W. à Little Boston. Dans cet endroit perdu où chacun lutte pour survivre et où l’unique distraction est l’église animée par le charismatique prêtre Eli Sunday, Plainview et son fils voient le sort leur sourire. Même si le pétrole comble leurs attentes et fait leur fortune, plus rien ne sera comme avant : les tensions s’intensifient, les conflits éclatent et les valeurs humaines comme l’amour, l’espoir, le sens de la communauté, les croyances, l’ambition et même les liens entre père et fils sont mis en péril par la corruption, la trahison… et le pétrole.","de":"Daniel Plainview versucht Ende des 19. Jahrhunderts sein Glück als Schürfer auf der Suche nach Silber, doch er entdeckt bei der harten Arbeit eines Tages eine Ölquelle. Für den nur auf Profit eingestellten Einzelgänger erschließt sich eine neue Obsession und schon bald beginnt er seine Arbeit im Ölgeschäft. Schon früh kommt sein Partner zu Tode, woraufhin Daniel sich dessen Sohnes annimmt, der als Waise zurück blieb. Doch auch diesen Schritt wählt Daniel nur, um sich Vorteile zu erschleichen und so steigt er durch Rücksichtslosigkeit, Betrug und harte eigene Arbeit zu einem schwerreichen Ölbaron auf. Sein Ziehsohn H.W. dagegen verliert sein Gehör bei einem Unfall an der Ölpumpe. Im Laufe der Jahre wächst Daniels Vermögen und mit ihm sein grenzenloser Hass auf die Menschen …"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/2eH78Nz708yFVrcaZAE2bspY5q5.jpg","es":"https://image.tmdb.org/t/p/w500/fho18jHViMUC2Ax8xdkkGwimbTe.jpg","en":"https://image.tmdb.org/t/p/w500/fa0RDkAlCec0STeMNAhPaF89q6U.jpg","fr":"https://image.tmdb.org/t/p/w500/fa0RDkAlCec0STeMNAhPaF89q6U.jpg","de":"https://image.tmdb.org/t/p/w500/r3VUQ6prbQ7O96BYd8PiMWzdQcm.jpg"}'::jsonb WHERE id = 318;
UPDATE public.films SET tmdb_id = 4638, titoli_i18n = '{"it":"Hot Fuzz","en":"Hot Fuzz","es":"Arma fatal","de":"Hot Fuzz - Zwei abgewichste Profis","fr":"Hot Fuzz"}'::jsonb, trame_i18n = '{"it":"Vittima dell''invidia dei colleghi e dei superiori, l''agente Nicholas Angel, pluridecorato, viene considerato un esaltato. Con la scusa di una promozione, così, i suoi superiori cercano di allontanarlo il più possibile da Londra, spedendolo in un paesino a 250 km di distanza, dove non accade nulla di emozionante, almeno apparentemente... Seguendo la pista di alcune morti che sembrano casuali, Angel s''imbatte finalmente in un caso \"succulento\"...","en":"Former London constable Nicholas Angel finds it difficult to adapt to his new assignment in the sleepy British village of Sandford. Not only does he miss the excitement of the big city, but he also has a well-meaning oaf for a partner. However, when a series of grisly accidents rocks Sandford, Angel smells something rotten in the idyllic village.","es":"Nicholas Angel es, sin duda alguna, el mejor policía de Londres. Sus detenciones superan en un 400% al segundo mejor agente del Cuerpo. Es tan bueno que, comparado a él, cualquier poli es malo. Por eso sus superiores deciden trasladarle a un lugar en que su talento no ponga a nadie en evidencia, a Sandford, un aparentemente adormecido y pacífico pueblecito.","de":"Der Polizist Nicholas Angel wird von London in das Provinznest Sandford versetzt, weil er seine Kollegen immer in den Schatten stellte. Zunächst langweilt er sich - doch dann hat er mehr als nur Kleinstadtdelikte aufzudecken. Zwar gibt es an seinem neuen Einsatzort kaum Verbrechen, dafür aber jede Menge „Unfälle“.","fr":"À Londres, le policier Nicholas Angel est le meilleur de son équipe. Tellement bon qu''il fait passer ses collègues pour de simples gardiens de la paix. Le chef de la brigade décide donc de le « promouvoir » dans le petit village de Sandford, où il ne se passe rien. Aux côtés du policier local Danny Butterman qui rêve de devenir Mel Gibson, Nicholas règle quelques contraventions sans grand intérêt. Une série de crimes étranges va le remettre dans l''action…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/xY1DI4NJGgwbP5dqjPHgQWB4Elb.jpg","en":"https://image.tmdb.org/t/p/w500/zPib4ukTSdXvHP9pxGkFCe34f3y.jpg","es":"https://image.tmdb.org/t/p/w500/kO2Ez6xOf5CJiQywkMo27nHzBF4.jpg","de":"https://image.tmdb.org/t/p/w500/2XZ5B1yTAaRur9YW1sryHEkyx7E.jpg","fr":"https://image.tmdb.org/t/p/w500/tddbD3ETiKucVg15GKWkzveU7SI.jpg"}'::jsonb WHERE id = 319;
UPDATE public.films SET tmdb_id = 1579, titoli_i18n = '{"en":"Apocalypto","es":"Apocalypto","it":"Apocalypto","fr":"Apocalypto","de":"Apocalypto"}'::jsonb, trame_i18n = '{"en":"Set in the Mayan civilization, when a man''s idyllic presence is brutally disrupted by a violent invading force, he is taken on a perilous journey to a world ruled by fear and oppression where a harrowing end awaits him. Through a twist of fate and spurred by the power of his love for his woman and his family he will make a desperate break to return home and to ultimately save his way of life.","es":"Historia ambientada en la época del imperio maya. Cuando la idílica existencia de los mayas es brutalmente interrumpida por el ataque de una fuerza invasora, un hombre emprende un arriesgado viaje a un mundo regido por el miedo y la opresión en el que le espera un incierto final. Debido a un giro del destino y espoleado por el amor a su esposa y a su familia, emprenderá el regreso a su hogar en un desesperado esfuerzo por preservar su forma de vida...","it":"Negli anni del declino del regno Maya, i governanti sono convinti che per tornare a prosperare basterà costruire nuovi templi e fare numerosi sacrifici umani. Ma Zampa di giaguaro, un giovane selezionato essere ucciso sull''altare, decide di tentare di sfuggire al suo destino...","fr":"Dans les temps turbulents précédant la chute de la légendaire civilisation Maya. Jeune père porteur de grandes espérances, chef de son petit village, Patte de Jaguar vit une existence idyllique brusquement perturbée par une violente invasion. Capturé et emmené lors d''un périlleux voyage à travers la jungle pour être offert en sacrifice aux Dieux de la Cité Maya, il découvre un monde régi par la peur et l''oppression, dans lequel une fin déchirante l''attend inéluctablement. Poussé par l''amour qu''il porte à sa femme, à sa famille et à son peuple, il devra affronter ses plus grandes peurs en une tentative désespérée pour retourner chez lui et tenter de sauver ce qui lui tient le plus à cœur.","de":"Es ist die Zeit, in der der Niedergang einer der ältesten und geheimnisvollsten Hochkulturen aller Zeiten bevorsteht: der Maya. Bis heute birgt diese Zeit offene Fragen und ungeklärte Geheimnisse. In Apocalypto skizziert Mel Gibson die Geschichte eines Mannes aus dem Volk der Maya, der in dieser Zeit um sein Leben kämpft. Nur die Liebe zu seiner Familie und zu seiner Frau gibt ihm die Kraft und den Mut zu bestehen."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/cRY25Q32kDNPFDkFkxAs6bgCq3L.jpg","es":"https://image.tmdb.org/t/p/w500/yQ4uC13IYVerbxMMXeSogSQUkOT.jpg","it":"https://image.tmdb.org/t/p/w500/8z6coUJwLrM9akjheUeTTQ8Bgxx.jpg","fr":"https://image.tmdb.org/t/p/w500/5xR5OjvGQfaRZNL7GTuPAZy8tdr.jpg","de":"https://image.tmdb.org/t/p/w500/oCG3GYXIdwW1oQNz61a21xkVjuG.jpg"}'::jsonb WHERE id = 320;
UPDATE public.films SET tmdb_id = 1991, titoli_i18n = '{"it":"Grindhouse - A prova di morte","de":"Death Proof - Todsicher","es":"Death Proof","fr":"Boulevard de la mort","en":"Death Proof"}'::jsonb, trame_i18n = '{"it":"Tre ragazze Jungle Julia, Shanna e Arlene, tutte molto carine, si divertono a passare le serate tra due locali di Austin, Texas, il \"Guero''s\" e il \"Texas Chili Parlor\", dove attirano gli sguardi indiscreti degli avventori. Tra i tanti camionisti e motociclisti presenti al locale c''è Stuntman Mike un killer misogino schizofrenico che si diverte a uccidere le ragazze a bordo di una truccatissima vettura. Una sera, Mike prende di mira le tre amiche e, a loro insaputa, le seduce per poi condurle verso la sua arma, posteggiata vicino il Guero''s...","de":"Austin, Texas: Jungle Julia und ihre beiden Freundinnen Arlene und Shanna machen mal wieder ohne Männer in ihrer Lieblingsbar einen drauf. Männer kann man unterwegs ja immer noch aufreißen. Ausgerechnet an den harmlosen Stuntman Mike gerät die Truppe. Als die Damen ihn aber trotz eines Gewinns abblitzen lassen, zeigt der vernarbte Stuntman sein wahres Gesicht: Er kümmert sich auf seine Weise um das das Damentrio. Nicht zum erstenmal und nicht zum letztenmal beginnt für den Psychopathen ein tödliches Spiel auf der Straße. Ein knappes Jahr später in Lebanon, Tennessee: Wieder gerät eine Gruppe in die Schußbahn von Mike: Kim, Zoe, Abernathy und Lee. Doch diesmal hat er sich die Falschen für sein Spielchen ausgesucht, denn diese Damen haben offenbar nicht die Absicht in die Opferrolle zu schlüpfen ...","es":"\"Death Proof\", dirigida por Tarantino, gira en torno a un psicópata de la carretera llamado Especialista Mike, un asesino en serie que va aniquilando a sus víctimas, siempre chicas jóvenes, con su coche de especialista \"a prueba de muerte\".","fr":"C’est à la tombée du jour que Jungle Julia, la DJ la plus sexy d’Austin, peut enfin se détendre avec ses meilleures copines, Shanna et Arlene. Ce trio infernal, qui vit la nuit, attire les regards dans tous les bars et dancings du Texas. Mais l’attention dont ces trois jeunes femmes sont l’objet n’est pas forcément innocente. C’est ainsi que Mike, cascadeur au visage balafré et inquiétant, est sur leurs traces, tapi dans sa voiture indestructible. Tandis que Julia et ses copines sirotent leurs bières, Mike fait vrombir le moteur de son bolide menaçant…","en":"Austin''s hottest DJ, Jungle Julia, sets out into the night to unwind with her two friends Shanna and Arlene. Covertly tracking their moves is Stuntman Mike, a scarred rebel leering from behind the wheel of his muscle car, revving just feet away."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/kf493fwH6DM9sNZ798Qf9NnSsBG.jpg","de":"https://image.tmdb.org/t/p/w500/4RoeXMF9nvDoLyiAP696rJdAE07.jpg","es":"https://image.tmdb.org/t/p/w500/7AEMH73JTb0qqAZgMj5orBGLUrO.jpg","fr":"https://image.tmdb.org/t/p/w500/1cajesADv9jGJAMqC2peAnxh5ar.jpg","en":"https://image.tmdb.org/t/p/w500/vtu6H4NWnQVqEp3aanUq3hNeeot.jpg"}'::jsonb WHERE id = 321;
UPDATE public.films SET tmdb_id = 1124, titoli_i18n = '{"it":"The Prestige","de":"Prestige - Die Meister der Magie","en":"The Prestige","es":"El truco final (El prestigio)","fr":"Le Prestige"}'::jsonb, trame_i18n = '{"it":"Due giovani maghi apprendisti, Robert Angier e Alfred Borden, vengono istruiti e seguiti da Cutter, un ingegnere illusionista ed ex mago, ma durante un numero in cui una donna viene legata e messa in una cassa di vetro piena d''acqua, qualcosa va storto e Angier incolperà l''amico dell''accaduto, tentando di vendicarsi. Inizia così un crudele gioco tra i due uomini su chi sia il migliore e la rivalità si trasformerà pian piano in ossessione.","de":"Im viktorianischen Zeitalter, zur Zeit der Jahrhundertwende, lernen sich die konkurrierenden Magier Robert Angier und Alfred Borden kennen. Aus freundschaftlicher, jugendlicher Konkurrenz erwächst jedoch bald etwas wesentlich Schlimmeres, denn nicht nur neidet jeder dem Anderen das Talent, Roberts Frau stirbt auch bei einem von Alfreds risikobewehrten Tricks. Über Jahre belauern und bekämpfen sie sich gegenseitig und reißen damit ihr gesamtes Umfeld in die Tiefe, nur um hinter die Tricks des jeweils anderen zu kommen. Dabei schrecken die beiden am Ende nicht einmal vor Mord zurück, denn das \"Prestige\", der unglaubliche letzte Teil eines perfekten Zaubertricks, ist jeden Einsatz wert...","en":"A mysterious story of two magicians whose intense rivalry leads them on a life-long battle for supremacy -- full of obsession, deceit and jealousy with dangerous and deadly consequences.","es":"Robert Angier es un ilusionista respetado que se obsesiona con uno de los trucos de su rival Alfred Borden. Para conseguir el truco hará todo lo posible, sin saber hasta qué punto cambiará su vida...","fr":"Londres, au début du siècle dernier… Robert Angier et Alfred Borden sont deux magiciens surdoués, promis dès leur plus jeune âge à un glorieux avenir. Une compétition amicale les oppose d''abord l''un à l''autre, mais l''émulation tourne vite à la jalousie, puis à la haine. Devenus de farouches ennemis, les deux rivaux vont s''efforcer de se détruire l''un l''autre en usant des plus noirs secrets de leur art. Cette obsession aura pour leur entourage des conséquences dramatiques…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/1GjRCeZoE251tWkYc3erwjpdBpU.jpg","de":"https://image.tmdb.org/t/p/w500/rN2eGbRpbJw8ZFVDiQfDxsknirP.jpg","en":"https://image.tmdb.org/t/p/w500/Ag2B2KHKQPukjH7WutmgnnSNurZ.jpg","es":"https://image.tmdb.org/t/p/w500/lIl2CrnWohGrZSO9eyKRptxZ7Hs.jpg","fr":"https://image.tmdb.org/t/p/w500/37Fr7lY4QBHsuxlLJIfTNxW6nGW.jpg"}'::jsonb WHERE id = 322;
UPDATE public.films SET tmdb_id = 1422, titoli_i18n = '{"en":"The Departed","fr":"Les Infiltrés","es":"Infiltrados","de":"Departed - Unter Feinden","it":"The Departed - Il bene e il male"}'::jsonb, trame_i18n = '{"en":"To take down South Boston''s Irish Mafia, the police send in one of their own to infiltrate the underworld, not realizing the syndicate has done likewise. While an undercover cop curries favor with the mob kingpin, a career criminal rises through the police ranks. But both sides soon discover there''s a mole among them.","fr":"À Boston, une lutte sans merci oppose la police à la pègre irlandaise. Pour mettre fin au règne du parrain Frank Costello, la police infiltre son gang avec « un bleu » issu des bas quartiers, Billy Costigan. Tandis que Billy s’efforce de gagner la confiance du malfrat vieillissant, Colin Sullivan entre dans la police au sein de l’Unité des Enquêtes Spéciales, chargée d’éliminer Costello. Mais Colin fonctionne en « sous‑marin » et informe Costello des opérations qui se trament contre lui. Risquant à tout moment d’être démasqués, Billy et Colin sont contraints de mener une double vie qui leur fait perdre leurs repères et leur identité. Traquenards et contre‑offensives s’enchaînent jusqu’au jour où chaque camp réalise qu’il héberge une taupe. Une course contre la montre s’engage entre les deux hommes avec un seul objectif : découvrir l’identité de l’autre sous peine d’y laisser sa peau…","es":"El Departamento de Policía de Massachussets se enfrenta a la mayor banda de crimen organizado de la ciudad de Boston. La estrategia consiste en acabar desde dentro con Frank Costello, el poderoso jefe de la mafia irlandesa. El encargado de infiltrarse en la banda es un joven novato, Billy Costigan. Mientras Billy intenta ganarse la confianza de Costello, otro joven policía, Colin Sullivan, sube rápidamente de categoría y ocupa un puesto en la unidad de Investigaciones Especiales, grupo de élite cuya misión también es acabar con Costello. Lo que nadie sabe es que Colin es un topo infiltrado en la policía por el propio Costello.","de":"Der brutale Bostoner Mafiaboss Frank Costello hat es geschafft, mit Colin Sullivan einen seiner treuesten Männer bei der städtischen Polizei einzuschleusen, um stets auf dem Laufenden über die geplanten Aktivitäten der Cops zu bleiben. Und weil die Taktik, den Gegner mit Hilfe eines Maulwurfs auszuspionieren, zwar alt aber effektiv ist, hatten auch Polizeichef Queenan und Sergeant Digman diese Idee. Ihr Undercover-Ermittler Billy Costigan hat sich schnell zu einem der engsten Vertrauten von Pate Costello hochgearbeitet. Als sowohl die Mafia als auch das Police-Department erfahren, dass sich ein Falschspieler in ihren Reihen befindet, ohne aber dessen Identität zu kennen, müssen Sullivan und Costigan alles daran setzen, dass der jeweils andere zuerst auffliegt, um somit ihre eigene Tarnung aufrecht erhalten zu können.","it":"Boston. È in atto una guerra tra la polizia locale e una banda della malavita organizzata. Billy Costigan, giovane poliziotto in incognito, riceve l''incarico di infiltrarsi nella gang capeggiata dal boss Frank Costello. Mentre Billy guadagna rapidamente la fiducia di Costello, Colin Sullivan, giovane criminale incallito infiltrato nel dipartimento di polizia come informatore della gang, guadagna una posizione di rilievo nell''unità speciale di investigazione. Sia Billy che Colin vivono questa doppia vita come un''esperienza alienante, ma appena appare chiara l''esistenza di una talpa, sia all''interno della polizia che fra i gangster, entrambi dovranno, in una corsa contro il tempo, scoprire l''identità dell''altro per salvarsi."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/nT97ifVT2J1yMQmeq20Qblg61T.jpg","fr":"https://image.tmdb.org/t/p/w500/xHeuF5zzlx1YxkULiz0mx1TMBJ7.jpg","es":"https://image.tmdb.org/t/p/w500/hf0Hgw1snmBwinkHYLCxGIs6DgO.jpg","de":"https://image.tmdb.org/t/p/w500/zqGdG5pcK7WZFgP9ynXd8jM7Bic.jpg","it":"https://image.tmdb.org/t/p/w500/oTIEFn7Xf3bZ6HZP3yRF8CzzmYQ.jpg"}'::jsonb WHERE id = 323;
UPDATE public.films SET tmdb_id = 1083658, titoli_i18n = '{"de":"Scoop - Ein royales Interview","es":"La gran exclusiva","it":"Scoop","en":"Scoop","fr":"Scoop"}'::jsonb, trame_i18n = '{"de":"Dieses von wahren Ereignissen inspirierte fiktionale Drama illustriert, wie sich die Frauen von Newsnight das skandalöse Interview mit Prinz Andrew sichern konnten.","es":"Esta dramatización ficticia basada en hechos reales muestra cómo las periodistas de ''Newsnight'' consiguieron la famosa entrevista con el Príncipe Andrés.","it":"Questa drammatizzazione ispirata a eventi reali racconta come le donne di Newsnight hanno ottenuto la famigerata intervista con il principe Andrea.","en":"Inspired by real events, this fictional dramatization gives an insider account of how the women of Newsnight secured Prince Andrew''s infamous interview.","fr":"Inspirée de faits réels, cette fiction raconte comment les collaboratrices de Newsnight ont réussi à approcher le prince Andrew pour une interview qui s''est avérée désastreuse."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/5lLVcYBTenqwYYI4rLX10P0LtjQ.jpg","es":"https://image.tmdb.org/t/p/w500/qKCVf0em0cYHfnfiJ1EtMjWV78m.jpg","it":"https://image.tmdb.org/t/p/w500/ib3H2ZSeVRTAmd7EtGWV31LswaZ.jpg","en":"https://image.tmdb.org/t/p/w500/ib3H2ZSeVRTAmd7EtGWV31LswaZ.jpg","fr":"https://image.tmdb.org/t/p/w500/gXLnc7e7eIax0OqL7GmbJqzYCOP.jpg"}'::jsonb WHERE id = 324;
UPDATE public.films SET tmdb_id = 512, titoli_i18n = '{"en":"Scoop","it":"Scoop","fr":"Scoop","de":"Scoop - Der Knüller","es":"Scoop"}'::jsonb, trame_i18n = '{"en":"An American journalism student in London scoops a big story, and begins an affair with an aristocrat as the incident unfurls.","it":"Sondra è una giornalista in erba che riceve dal fantasma di un famoso reporter, appena morto, alcune informazioni su un serial killer ancora in libertà. Sebbene grazie a circostanze ben poco credibili, Sondra ha in mano l’occasione della sua vita e insieme al mago da avanspettacolo Sid Waterman inizia a seguire le tracce del presunto assassino, l’aristocratico e affascinante Peter Lyman.","fr":"L''enquête du célèbre journaliste d''investigation Joe Strombel, consacrée au \"Tueur au Tarot\" de Londres, tourne court quand il meurt de façon aussi soudaine qu''inexplicable. Mais rien, pas même la mort, ne peut arrêter Joe. À peine arrivé au purgatoire, il décide de transmettre ses toutes dernières informations à la plus charmante des étudiantes en journalisme : Sondra Pransky. De passage à Londres, Sondra entend le fantôme de Joe s''adresser à elle durant un numéro de magie de l''Américain Splendini, alias Sid Waterman. Bouleversée et folle de joie à l''idée d''avoir déniché le scoop du siècle, l''effervescente créature se lance avec Sid dans une enquête échevelée, qui les mène droit au fringant aristocrate et politicien Peter Lyman. Une idylle se noue en dépit de troublants indices semblant désigner le beau Peter comme le \"Tueur au Tarot\". Le scoop de Sondra lui sera-t-il fatal ?","de":"Ein echter Reporter tut alles für einen Knüller, notfalls kehrt er auch aus dem Reich der Toten zurück wie Joe Strombel, der auf dem Weg ins Jenseits einen Bombentip bekommt. Wie gut, daß gerade die aufstrebende Journalistin Sondra Pransky bei dem großen Magier Splendini im De-Materialisierer sitzt und von Strombel so von diesem Knüller erfährt: es geht um die Identität des Tarot-Killers, der überall gesucht wird. Gemeinsam mit Splendini, der in Wirklichkeit Sid Waterman heißt, reist Sondra nach London, um dem Killer auf die Spur zu kommen.Dabei könnte es sich um den Adeligen Peter Lyman handeln - nur ist der sehr charmant und schon bald verliebt sich Sondra in den Charmeur...","es":"Sondra Pransky (Scarlett Johansson), una estudiante americana de periodismo, se encuentra en Gran Bretaña visitando a unos amigos. Durante su estancia en Londres, acude a un espectáculo de magia, donde un ilusionista (Woody Allen) la invita a subir al escenario para hacerla desaparecer. Mientras espera que el mago ponga en práctica su truco, recibe la visita del fantasma de un prestigioso periodista muerto (Ian McShane), que ha venido desde el más allá para servirle en bandeja la exclusiva del año. El espíritu afirma que Peter Lyman (Hugh Jackman), el rico y atractivo hijo de un conocido aristócrata británico, es en realidad el famoso asesino en serie conocido como \"el asesino del tarot\"."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/1nF290EoEn2rs4W9VVercKa4S5o.jpg","it":"https://image.tmdb.org/t/p/w500/vyQD8AHtA3zK5ufHI5l6CQ4o4TD.jpg","fr":"https://image.tmdb.org/t/p/w500/1oX193DhmZplAZ2xSBcT3cEYuzl.jpg","de":"https://image.tmdb.org/t/p/w500/br9hS3DEjQguIMqoagxrqIHNafM.jpg","es":"https://image.tmdb.org/t/p/w500/r6HRh0NRuLWLmY4nabJCPLkqRX6.jpg"}'::jsonb WHERE id = 325;
UPDATE public.films SET tmdb_id = 1491, titoli_i18n = '{"it":"The Illusionist - L''illusionista","es":"El ilusionista","en":"The Illusionist","de":"The Illusionist - Nichts ist wie es scheint","fr":"L''Illusionniste"}'::jsonb, trame_i18n = '{"it":"Siamo all''inizio del XX secolo, in Austria. Eisenheim è un adolescente innamorato (e ricambiato) della bella Sophie: la ragazza però, è promessa sposa del Principe Leopoldo, erede al trono. I due sono costretti a separarsi ed Eisenheim scompare dalla circolazione. Quindici anni dopo, il ragazzo è cresciuto e strega Vienna con spettacoli nei quali mette in mostra le sue incredibili doti di illusionista: una sera incontra Sophie, e l''amore si riaccende, ma il Principe Leopoldo, aiutato dall''Ispettore Generale Uhl, capo della Polizia, fa di tutto per stroncare una volta per tutte la relazione.","es":"En la Viena de 1900, el misterioso Eisenheim cautiva al público con sus espectáculos de magia e ilusionismo. Sus poderes sobrenaturales llegan a los oídos del príncipe heredero Leopold, un hombre pragmático que acude a su espectáculo con incredulidad, acompañado de su prometida, la bella y sofisticada Sophie. Sospechando un fraude por parte de Eisenheim, el príncipe encarga al perspicaz inspector de policía Uhl que le vigile de cerca.","en":"With his eye on a lovely aristocrat, a gifted illusionist named Eisenheim uses his powers to win her away from her betrothed, a crown prince. But Eisenheim''s scheme creates tumult within the monarchy and ignites the suspicion of a dogged inspector.","de":"Wien um 1900: Mit seinen fantastischen Vorstellungen macht sich der Illusionist Eisenheim zur lebenden Legende. Auf der Höhe seiner Kunst beschwört er den Geist der gerade ermordeten Herzogin Sophie. Doch bevor die Erscheinung den Namen ihres Mörders nennen kann, wird Eisenheim von Inspektor Uhl verhaftet. Was niemand ahnt: Die Herzogin war zwar die Verlobte von Kronprinz Leopold, aber auch die heimliche Liebe des Magiers. Wurde sie das Opfer des Machtkampfes zwischen dem Thronfolger und dem rätselhaften Meister der Täuschung? Nichts ist wie es scheint, die Grenzen zwischen Magie und Wirklichkeit verschwimmen.","fr":"Vienne, dans les années 1900. Surgit un jour le charismatique et mystérieux illusionniste Eisenheim, qui ne tarda pas à devenir l''homme le plus célèbre de la ville, l''incarnation vivante d''une magie à laquelle personne n''osait plus croire... Mais la gloire d''Eisenheim est intolérable au Prince héritier Leopold, dont la popularité décroît à mesure que grandit celle de ce showman consommé. Rationaliste convaincu, avide de pouvoir, le Prince a une raison supplémentaire de jalouser Eisenheim : ce dernier fut le grand amour de jeunesse de sa fiancée, la belle Sophie von Teschen, qui nourrit encore pour lui de très tendres sentiments. Décidé à écarter ce rival, Leopold charge son homme de confiance, l''inspecteur Uhl, d''enquêter sur l''illusionniste et de dévoiler ses impostures. Une partie serrée s''engage entre les deux hommes..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/bGvkZZtWymiN3am617tpExQ0ow1.jpg","es":"https://image.tmdb.org/t/p/w500/30Bo0pvLcKYDbIHNzduumAdbS7j.jpg","en":"https://image.tmdb.org/t/p/w500/1O9jUvqkHaGBMVRyOJz1AlkmALW.jpg","de":"https://image.tmdb.org/t/p/w500/2o9Em0cLmVl7YUAt9p0FedoRbXW.jpg","fr":"https://image.tmdb.org/t/p/w500/9i9Y201WJuuYOtnTgPABauyKRYj.jpg"}'::jsonb WHERE id = 326;
UPDATE public.films SET tmdb_id = 612, titoli_i18n = '{"en":"Munich","es":"Munich","it":"Munich","de":"München","fr":"Munich"}'::jsonb, trame_i18n = '{"en":"During the 1972 Olympic Games in Munich, eleven Israeli athletes are taken hostage and murdered by a Palestinian terrorist group known as Black September. In retaliation, the Israeli government recruits a group of Mossad agents to track down and execute those responsible for the attack.","es":"Basada en hechos reales. Tras el asesinato de varios atletas israelíes por el grupo terrorista \"Septiembre negro\" en los Juegos Olímpicos de Múnich de 1972, un agente especial del Mossad tuvo que ejecutar una misión altamente secreta: asesinar a los responsables.","it":"Durante le Olimpiadi del 1972 di Monaco il commando di estremisti palestinesi Settembre Nero prende in ostaggio e poi uccide gli atleti israeliani. A seguito dell''attentato, una squadra di cinque uomini viene segretamente incaricata dal governo di stanare e uccidere i responsabili. Avner, ex ufficiale del Mossad, figlio di un patriota, accetta di essere a capo della missione: per un lungo periodo dovrà abbandonare la sua identità e i suoi affetti...","de":"Nach dem Geiseldrama um die israelische Mannschaft bei der Olympiade in München 1972 wird der Geheimdienstler Avner von der israelischen Regierung auf die Hintermänner angesetzt. Mit einem kleinen Team reist er quer durch Europa und exekutiert die Organisatoren des palästinensischen Terrors. Doch immer mehr regen sich Zweifel über die Legitimität ihrer Aufträge. Das dreckige, konspirative Leben fordert seinen Tribut – und schließlich gerät die Gruppe selbst auf die Abschussliste.","fr":"Jeux Olympiques de Munich, 5 septembre 1972. Un commando de terroristes palestiniens prend en otages puis exécute 11 membres de l''équipe sportive israélienne, sous l''œil des téléspectateurs du monde entier. Inspiré de faits réels, Munich retrace le parcours de 5 agents israéliens chargés de traquer les 11 palestiniens considérés comme les commanditaires de l''attentat. Pour mener à bien cette mission, les 5 hommes devront renoncer du jour au lendemain à leur identité, et s’exposer à tout moment à la vengeance de leurs cibles."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/iUekaw96QLInZpsNwRTlRKrZgwm.jpg","es":"https://image.tmdb.org/t/p/w500/6YTX9q7Rpjxwn8FxWaxAyHDbsmN.jpg","it":"https://image.tmdb.org/t/p/w500/5APB21LvvshIZFDtGBsNMOp6SJL.jpg","de":"https://image.tmdb.org/t/p/w500/rxzP6wJYqhALbXOuzrupILRpsft.jpg","fr":"https://image.tmdb.org/t/p/w500/mCWtxKSrdSjRWhFl4Mf3UDrkpdM.jpg"}'::jsonb WHERE id = 327;
UPDATE public.films SET tmdb_id = 74, titoli_i18n = '{"it":"La guerra dei mondi","fr":"La Guerre des mondes","es":"La guerra de los mundos","en":"War of the Worlds","de":"Krieg der Welten"}'::jsonb, trame_i18n = '{"it":"I marziani hanno deciso di invadere la Terra perché il loro pianeta è diventato invivibile e la razza umana è costretta ad affrontare una dura guerra per la sopravvivenza. Anche Ray Ferrier, ormai da tempo separato dalla sua famiglia, si trova coinvolto nella battaglia per difendere a tutti i costi i suoi figli dai violenti attacchi degli extra-terrestri...","fr":"Ray Ferrier est un docker divorcé et un père rien moins que parfait, qui n’entretient plus que des relations épisodiques avec son fils Robbie, 17 ans, et sa fille Rachel, 11 ans. Quelques minutes après que son ex‐femme et l’époux de cette dernière lui ont confié la garde des enfants, un puissant orage éclate. Ray assiste alors à un spectacle qui bouleversera à jamais sa vie…","es":"Ray Ferrier es un descargador de muelle, divorciado y padre nada modélico. Poco después de que su ex mujer y su nuevo marido se vayan después de dejar a Robbie, su hijo adolescente, y a su pequeña hija Rachel para una de sus contadas visitas, estalla una tremenda e inesperada tormenta eléctrica. Unos momentos después, en un cruce cerca de la casa, Ray es testigo de un acontecimiento que cambiará su vida y la de los suyos para siempre. Una enorme máquina de tres patas emerge del suelo y antes de que alguien pueda hacer algo, arrasa todo lo que está a su alcance. Un día como otro cualquiera acaba de convertirse en la fecha más extraordinaria de su vida: el primer ataque alienígena contra la Tierra.","en":"Ray Ferrier is a divorced dockworker and less-than-perfect father. Soon after his ex-wife and her new husband drop off his teenage son and young daughter for a rare weekend visit, a strange and powerful lightning storm touches down.","de":"Eines windigen herbstlichen Nachmittags wird der Erde der Krieg erklärt. Ray ein Kranführer, und seine zwei Kinder, stehen plötzlich mitten im Geschehen: der Boden reißt auf und stählerne Kolosse erheben sich aus den Asphaltbrocken. Alles was um sie herumsteht verwandeln sie zu Staub. Ray beschließt mit den Kindern zu fliehen. Doch es gibt kaum einen Ort an den sie gelangen, der nicht schon unter Beschuss der Invasoren steht."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/reQUXXUd0WeoIJiSvYjlGLRGpXR.jpg","fr":"https://image.tmdb.org/t/p/w500/o7PGnP8gSLjYdN2OQH4y45Ymi4i.jpg","es":"https://image.tmdb.org/t/p/w500/qlgvS2InG3oU8GixavRq3t3A9H7.jpg","en":"https://image.tmdb.org/t/p/w500/6Biy7R9LfumYshur3YKhpj56MpB.jpg","de":"https://image.tmdb.org/t/p/w500/5YaxrCqAQ482jCixgT3PIdvf7tg.jpg"}'::jsonb WHERE id = 328;
UPDATE public.films SET tmdb_id = 921, titoli_i18n = '{"en":"Cinderella Man","es":"Cinderella Man. El hombre que no se dejó tumbar","it":"Cinderella Man - Una ragione per lottare","de":"Das Comeback","fr":"De l''ombre à la lumière"}'::jsonb, trame_i18n = '{"en":"The true story of boxer Jim Braddock who, following his retirement in the 1930s, makes a surprise comeback in order to lift his family out of poverty.","es":"Basada en una historia real. Después de haberse retirado del boxeo, James J. Braddock decidió volver al cuadrilátero durante los años de la Gran Depresión para poder alimentar a su familia. No era un boxeador con talento, pero su coraje, sacrificio y dignidad lo llevaron hasta la cumbre.","it":"Ispirato alla vera storia del pugile Jim Braddock che, nel periodo della Grande Depressione, per sfamare la famiglia tentò la fortuna con la boxe. Braddock passò velocemente dalla miseria alla gloria quando, nel 1935, riuscì a battere in un combattimento epico di 15 riprese il campione del mondo dei pesi massimi Max Baer.","de":"Nachdem er etliche Kämpfe hintereinander verloren hat, sieht der Halbschwergewicht-Boxer Jim Braddock keinen anderen Ausweg mehr: Er hört auf, in den Ring zu steigen und muss sich von nun an mit mickrigen Jobs begnügen, damit er, seine Frau Mae und seine Kinder über die Runden kommen.Eines Tages allerdings hat er die Chance zu seinem großen Comeback, als ein anderer Boxer einen Kampf absagen muss und Jim für ihn den Ring zurückkehrt. Hingegen aller Erwartungen gewinnt er den Kampf und wird so zum Held. Doch sein nächster Gegner wird nicht so einfach zu besiegen sein. Das Schwergewicht Max Baer stieg nämlich schon zweimal als einziger Überlebender aus dem Ring...","fr":"Autrefois boxeur prometteur, Jim Braddock s''est vu contraint d''abandonner la compétition après une série de défaites. Alors que l''Amérique sombre dans la `Grande Dépression'', Jim accepte n''importe quel petit boulot pour faire vivre sa femme Mae et leurs enfants. Il n''abandonne pourtant pas l''espoir de remonter un jour sur le ring. Grâce à une annulation de dernière minute, Jim est appelé à combattre le deuxième challenger mondial, à la stupéfaction générale il gagne au troisième round."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/wkeOjIcpuqLMW4GnVowlM9VI0JE.jpg","es":"https://image.tmdb.org/t/p/w500/9qJlfL3fB5d8MotO4kUtDgH4Yr8.jpg","it":"https://image.tmdb.org/t/p/w500/6TeNVIUGkCh9ZaTysb94Blhbram.jpg","de":"https://image.tmdb.org/t/p/w500/fUfgrFi5qBVDIHsntX1E3TAehzq.jpg","fr":"https://image.tmdb.org/t/p/w500/3WFqefpOIBmj6kqZ5zvnZw8Dy6M.jpg"}'::jsonb WHERE id = 329;
UPDATE public.films SET tmdb_id = 59, titoli_i18n = '{"it":"A History of Violence","en":"A History of Violence","fr":"A History of Violence","de":"A History of Violence","es":"Una historia de violencia"}'::jsonb, trame_i18n = '{"it":"Tom Stall è il proprietario di un piccolo ristorante in una cittadina di provincia. Conduce una vita normale con la moglie e i figli fin quando un giorno si difende dall''aggressione di due feroci criminali uccidendo entrambi. La sua immagine finisce su tutti i media e spinge Carl Fogarty, un boss della mafia irlandese di Philadelpia ad andarlo a cercare.","en":"An average family is thrust into the spotlight after the father commits a seemingly self-defense murder at his diner.","fr":"Père de famille dans une petite ville tranquille, Tom Stall est un jour contraint de tuer deux malfrats qui menaçaient la vie des employés et des clients de son restaurant. Proclamé héros par la presse locale, Tom essaie peu à peu de revenir à une vie normale. Mais un certain Carl Fogarty débarque, convaincu de reconnaître en Tom celui avec qui il a autrefois eu de violents démêlés.","de":"Tom Stall, seine Frau Edie und seine zwei Kinder leben ein normales Leben in ihrem Kleinstadthaus in Millbrock, Indiana. Eines Tages jedoch wird die Familie auf eine harte Belastungsprobe gestellt.Alles beginnt mit zwei Männern, die in den Coffeeshop von Tom kommen und den Laden überfallen wollen. Damit keine unschuldige Person verletzt wird, erschießt Tom die beiden in Notwehr und wird durch diese Tat zu einem Helden in der Stadt. Auch die Presse feiert ihn, was er selbst aber eigentlich nicht möchte, sondern lieber, dass alle ihn sein geregeltes Leben weiterführen lassen. Als sich die Schlagzeilen wieder etwas legen, steht der undurchschaubare Carl Fogarty vor seiner Tür. Carl macht ihm unmissverständlich klar, dass seine letzte Stunde geschlagen hat, da er schon lange mit einem gewissen \"Joey\", für den er ihn hält, abrechnen will. Tom setzt nun alles daran, Carl davon zu überzeugen, dass er nicht Joey ist...","es":"Tom Stall lleva una vida feliz y tranquila con su mujer –abogada– y sus dos hijos en la pequeña ciudad de Millbrook (Indiana) hasta que una noche su existencia idílica se ve destrozada cuando frustra un violento intento de robo en su restaurante. Tom percibe el peligro y salva a sus clientes y amigos matando en defensa propia a dos criminales buscados por la justicia. Aplaudido como un héroe, la vida de Tom cambia de la noche a la mañana y de repente se encuentra convertido en el centro de atención de todos los medios de comunicación. Incómodo con esta fama no buscada, intenta volver a su vida normal, pero un hombre amenazante y misterioso llega a la ciudad para enfrentarse a él porque cree que Tom es el hombre con quien tiene una cuenta pendiente del pasado."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/hZRFgghyOvYkFZ6dtPtPQ97KXLg.jpg","en":"https://image.tmdb.org/t/p/w500/ptJKY9WGDUUL064ge3jW78zBX0t.jpg","fr":"https://image.tmdb.org/t/p/w500/A26rcvipOqptVs7i5uRmKicXRxE.jpg","de":"https://image.tmdb.org/t/p/w500/tYn6WVRwTyvK7B6LA6n1aU74LnB.jpg","es":"https://image.tmdb.org/t/p/w500/rZLpsfxj2qKbJzSzXiKFYrRIeB1.jpg"}'::jsonb WHERE id = 330;
UPDATE public.films SET tmdb_id = 116, titoli_i18n = '{"en":"Match Point","it":"Match Point","es":"Match Point","fr":"Match Point","de":"Match Point"}'::jsonb, trame_i18n = '{"en":"Chris, a former tennis pro, takes a job as an instructor and befriends his wealthy young student, Tom. After being introduced to his family, Chris is soon engaged to Tom''s sister, Chloe. Despite the professional and financial advantages that this relationship affords him, Chris becomes obsessed with Tom''s fiancee, American actress Nola.","it":"L''ascesa al successo del giovane e ambizioso istruttore di tennis Chris Wilton sembra inarrestabile, grazie anche alla conquista di due donne belle e potenti che se lo contenderanno.","es":"Chris Wilton es un ambicioso y joven profesor de tenis con escasos recursos económicos. Gracias a su amistad con Tom Hewett, consigue entrar en la alta sociedad londinense y enamorar a su hermana Chloe. Tom, por su parte, sale con Nola Rice, una atractiva americana, de la que Chris se encapricha nada más verla. El azar, la pasión y, sobre todo, la ambición llevarán a Chris a cometer acciones que determinarán su vida y la de los demás para siempre.","fr":"Jeune professeur de tennis issu d''un milieu modeste, Chris Wilton se fait embaucher dans un club huppé des beaux quartiers de Londres. Il ne tarde pas à sympathiser avec Tom Hewett, un jeune homme de la haute société avec qui il partage sa passion pour l''opéra. Très vite, Chris fréquente régulièrement les Hewett et séduit Chloe, la sœur de Tom. Alors qu''il s''apprête à l''épouser et qu''il voit sa situation sociale se métamorphoser, il fait la connaissance de la ravissante fiancée de Tom, Nola Rice, une jeune Américaine venue tenter sa chance comme comédienne en Angleterre...","de":"Chris Wilton ist jung, gut aussehend und ehrgeizig. Mit der ganz großen Tenniskarriere hat es nicht geklappt, und so verdient er sich jetzt seine Brötchen als Tennislehrer in einem feinen Londoner Club. Als er hier die Bekanntschaft des reichen Snobs Tom und dessen schüchternen Schwester Chloe macht, sieht er seine ganz große Chance gekommen, seinem Leben doch noch die entscheidende Wendung nach oben zu geben."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/vHjEVTD8ucuwKSFOZJeyAnTZYli.jpg","it":"https://image.tmdb.org/t/p/w500/vHjEVTD8ucuwKSFOZJeyAnTZYli.jpg","es":"https://image.tmdb.org/t/p/w500/4JJr9zvDxys2f7dOlDdDgEsw9Yy.jpg","fr":"https://image.tmdb.org/t/p/w500/vHjEVTD8ucuwKSFOZJeyAnTZYli.jpg","de":"https://image.tmdb.org/t/p/w500/bOK3J1TMfYZjlM86jBoVTgcIeVz.jpg"}'::jsonb WHERE id = 331;
UPDATE public.films SET tmdb_id = 866, titoli_i18n = '{"es":"Descubriendo Nunca Jamás","it":"Neverland - Un sogno per la vita","de":"Wenn Träume fliegen lernen","fr":"Neverland","en":"Finding Neverland"}'::jsonb, trame_i18n = '{"es":"Basada en la vida de James Barrie, el autor \"Peter Pan\". La historia comienza en Londres en 1904 y muestra el proceso que desembocó en la creación de Peter Pan, desde que a Barrie se le ocurrió la idea hasta el estreno de la obra en el teatro Duke de Nueva York, una noche en la que no sólo cambió la vida del autor, sino la de todos los que estaban con él.","it":"L’affermato drammaturgo scozzese James M. Barrie è un genio letterario dei suoi tempi ma non ne può più dei soliti vecchi temi. Inaspettatamente, trova ispirazione durante la passeggiata che fa ogni giorno per i giardini di Kensington. Lì incontra la famiglia Llewelyn Davies, quattro bambini orfani di padre e la loro bella madre. Nonostante la disapprovazione della nonna dei bambini e il risentimento di sua moglie, Barrie fa amicizia con la famiglia. Trasforma i ragazzi nei “ragazzi perduti dell’isola che non c’è”. Dalle avventure elettrizzanti dell’infanzia scaturisce il capolavoro di Barrie, Peter Pan. Al principio, la sua compagnia teatrale è scettica ma Barrie scioccherà gli attori facendoli provare con delle richieste mai sentite. Una tragica piega del destino, però, costringerà lo scrittore e le persone che ama a capire cosa davvero significa credere...","de":"London, Anfang des 19. Jahrhunderts. Auf der Suche nach Inspiration stolpert der schottische Bühnenautor J.M. Barrie im Park über eine vierköpfige Jungen-Bande, die von ihrer bezaubernden Mutter Sylvia begleitet wird. Auf Anhieb findet Barrie einen Draht zu den wilden, abenteuerlustigen Buben; Peter, der jüngste Spross, wird gar das Vorbild zu Peter Pan. Doch während beruflich alles nach Plan läuft - \"Peter Pan\" wird ein sensationeller Erfolg -, geht Barries Ehe in die Brüche, und Sylvia erkrankt unheilbar an Krebs.","fr":"Londres au début du XXe siècle, J. M. Barrie auteur de pièces de théâtre est en manque d’inspiration. Son mariage ne va pas bien, sa dernière pièce est un désastre. Mais alors qu’il est dans le parc avec son chien Porthos, il rencontre Mme Sylvia Llewelyn Davies, qui est veuve, et ses 4 garçons. Une amitié très forte naît entre J. M. Barrie, les 4 enfants et leur mère.","en":"During a writing slump, playwright J.M. Barrie meets a widow and her four children, all young boys—who soon become an important part of Barrie’s life and the inspiration that lead him to create his masterpiece. Peter Pan."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/ibdzSgStiFFXXnQc3WsMrNqv0wt.jpg","it":"https://image.tmdb.org/t/p/w500/fqfx3dcYzfK6sQVRQYn9siNzBuX.jpg","de":"https://image.tmdb.org/t/p/w500/3ErdhYRrDl7uQ9xFOvP97LzHZ3D.jpg","fr":"https://image.tmdb.org/t/p/w500/z1DKo16vog6RAlwqV7ERqiYMCUU.jpg","en":"https://image.tmdb.org/t/p/w500/A9jgLICNCEb3lvWdNaIKAG9pRdp.jpg"}'::jsonb WHERE id = 332;
UPDATE public.films SET tmdb_id = 70, titoli_i18n = '{"es":"Million Dollar Baby","it":"Million Dollar Baby","en":"Million Dollar Baby","fr":"Million Dollar Baby","de":"Million Dollar Baby"}'::jsonb, trame_i18n = '{"es":"Frankie Dunn, después de haber entrenado y representado a los mejores púgiles, regenta un gimnasio con la ayuda de Scrap, un ex-boxeador que, además, es su único amigo. Frankie es un hombre solitario y adusto que se refugia desde hace años en la religión buscando una redención que no llega. Un día, entra en su gimnasio Maggie Fitzgerald, una voluntariosa chica que quiere boxear y que está dispuesta a luchar denodadamente para conseguirlo. Pero lo que más desea y necesita es que alguien crea en ella. Frankie la rechaza alegando que es demasiado mayor y que, además, él no entrena a chicas. Pero Maggie no se rinde y se machaca cada día en el gimnasio, con el único apoyo de Scrap. Finalmente, convencido de la inquebrantable determinación de Maggie, Frankie decide entrenarla.","it":"Maggie Fitzgerald fa la cameriera, ha passato i trent''anni ma ancora sogna di affermarsi come boxeuse, e ha anche incontrato l''allenatore che fa al caso suo. Peccato che Frankie Dunn non voglia saperne di allenare una donna...","en":"Despondent over a painful estrangement from his daughter, trainer Frankie Dunn isn''t prepared for boxer Maggie Fitzgerald to enter his life. But Maggie''s determined to go pro and to convince Dunn and his cohort to help her.","fr":"Rejeté depuis longtemps par sa fille, l’entraîneur Frankie Dunn s’est replié sur lui‐même et vit dans un désert affectif, en évitant toute relation qui pourrait accroître sa douleur et sa culpabilité. Le jour où Maggie Fitzgerald, 31 ans, pousse la porte de son gymnase à la recherche d’un coach, elle n’amène pas seulement avec elle sa jeunesse et sa force, mais aussi une histoire jalonnée d’épreuves et une exigence, vitale et urgente : monter sur le ring, entraînée par Frankie, et enfin concrétiser le rêve d’une vie. Après avoir repoussé plusieurs fois sa demande, Frankie se laisse convaincre par l’inflexible détermination de la jeune femme. Une relation mouvementée, tour à tour stimulante et exaspérante, se noue entre eux, au fil de laquelle Maggie et l’entraîneur se découvrent une communauté d’esprit et une complicité inattendues…","de":"Frankie Dunn hat sein Leben lang viele unglaubliche Kämpfer im Ring trainiert. Die wichtigste Regel, die er seine Boxer lehrt, ist die, die sein eigenes Leben bestimmt: Vor allem andere, schütze dich selbst! Im Zuge einer schmerzvollen Entfremdung von seiner Tochter hat Frankie niemanden mehr an sich herangelassen. Sein einziger Freund ist Scrap, ein ehemaliger Boxer, der sich um das Studio kümmert und weiß, dass unter Frankies rauher Schale ein warmherziger Kerl steckt."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/3mNb5EaO5HfgrxZGx917c8kNp6E.jpg","it":"https://image.tmdb.org/t/p/w500/3ehWHEKe54gTpYoTZ19q2qRCCyH.jpg","en":"https://image.tmdb.org/t/p/w500/jcfEqKdWF1zeyvECPqp3mkWLct2.jpg","fr":"https://image.tmdb.org/t/p/w500/7yWwlgq12qZ4nMLQHhEf8ITaggn.jpg","de":"https://image.tmdb.org/t/p/w500/h91jhpl63wxNGNl18adInAsn3YV.jpg"}'::jsonb WHERE id = 333;
UPDATE public.films SET tmdb_id = 652, titoli_i18n = '{"en":"Troy","it":"Troy","fr":"Troie","de":"Troja","es":"Troya"}'::jsonb, trame_i18n = '{"en":"In year 1250 B.C. during the late Bronze age, two emerging nations begin to clash. Paris, the Trojan prince, convinces Helen, Queen of Sparta, to leave her husband Menelaus, and sail with him back to Troy. After Menelaus finds out that his wife was taken by the Trojans, he asks his brother Agamemnon to help him get her back. Agamemnon sees this as an opportunity for power. They set off with 1,000 ships holding 50,000 Greeks to Troy.","it":"Nel 1193 A.C., Paride, principe di Troia, rapisce Elena, regina di Sparta e moglie di Menelao. Questo sarŕ l''evento che scatenerŕ la guerra tra la Grecia micenea e Troia, una guerra lunga dieci anni che vedrà protagonisti due eroi contrapposti: Achille per i greci ed Ettore per i troiani.","fr":"Dans la Grèce antique, l''enlèvement d''Hélène, reine de Sparte, par Pâris, prince de Troie, est une insulte que le roi Ménélas ne peut supporter. L''honneur familial étant en jeu, Agamemnon, frère de Ménélas et puissant roi de Mycènes, réunit toutes les armées grecques afin de faire sortir Hélène de Troie. Mais en réalité, la sauvegarde de l''honneur familial n''est qu''un prétexte pris par Agamemnon pour cacher sa terrible avidité. Celui-ci cherche en fait à contrôler Troie et à agrandir son vaste empire. Aucune armée n''a jamais réussi à pénétrer dans la cité fortifiée, sur laquelle veillent le roi Priam et le prince Hector. L''issue de la guerre de Troie dépendra notamment d''un homme, Achille, connu comme le plus grand guerrier de son époque. Arrogant, rebelle, et réputé invincible, celui-ci n''a d''attache pour rien ni personne si ce n''est sa propre gloire…","de":"Paris, der schwer verliebte Prinz von Troja, verschleppt die spartanische Königsgemahlin Helena in seine Heimat. Der spartanische König Menelaos kann diese Beleidigung nicht hinnehmen. Unter der Leitung seines Bruders Agamemnon, dem mächtigen König von Mykene, schließen sich weitere griechische Könige zusammen, um Troja zu vernichten, darunter auch der berühmteste Krieger Achilles. Das Hauptmotiv von Agamemnon ist nicht die Ehre seines Bruders wiederherzustellen, sondern seine Habgier: der Fall von Troja würde für ihn einen großen Sieg bedeuten und die Vorherrschaft seines bereits riesigen Reiches sichern. Unter der Führung des gewaltigen Prinz Hektor halten aber Trojas Mauern besser stand als von den Griechen geplant…","es":"A lo largo de los tiempos, los hombres han hecho la guerra. Unos por poder, otros por gloria o por honor, y algunos por amor. En la antigua Grecia, la pasión de dos de los amantes más legendarios de la historia, Paris, príncipe de Troya y Helena, reina de Esparta, desencadena una guerra que asolará una civilización. El rapto de Helena por Paris, separándola de su esposo, el rey Menelao, es un insulto que El orgullo familiar establece que una afrenta a Menelao es una afrenta a su hermano Agamenón, el poderoso rey de Micenas, que no tarda en reunir a todas las grandes tribus de Grecia para recuperar a Helena de manos de los troyanos y defender el honor de su hermano. La verdad es que la lucha por el honor por parte de Agamenón está corrompida por su incontenible codicia ya que necesita conquistar Troya para asumir el control del mar Egeo."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/a07wLy4ONfpsjnBqMwhlWTJTcm.jpg","it":"https://image.tmdb.org/t/p/w500/6n8BiphW9fvqC6biB0RMfblqi43.jpg","fr":"https://image.tmdb.org/t/p/w500/pkKBYrihVm5kuBgOH04KagSids0.jpg","de":"https://image.tmdb.org/t/p/w500/3Mt64xsMF88cRz08ysJLLV2Qhws.jpg","es":"https://image.tmdb.org/t/p/w500/mBiDQT28DnuYaJSL4nDD43ORE6p.jpg"}'::jsonb WHERE id = 334;
UPDATE public.films SET tmdb_id = 1586, titoli_i18n = '{"it":"Secret Window","es":"La ventana secreta","en":"Secret Window","de":"Das geheime Fenster","fr":"Fenêtre secrète"}'::jsonb, trame_i18n = '{"it":"Da quando la moglie lo ha lasciato il famoso romanziere Mort Rainey è in preda ad una forte depressione e trascorre le giornate a dormire anziché a scrivere. A peggiorare le cose arriva uno psicopatico che lo accusa di aver plagiato un suo racconto. Per vendicarsi è disposto a tutto. Persino ad uccidere.","es":"Thriller basado en una novela de Stephen King. Depp es un escritor que atraviesa un mal momento: a la sequía creativa se une el proceso de separación de su esposa. En tales circunstancias, aparece en su vida un extraño personaje que lo acusa de haber plagiado uno de sus relatos.","en":"Mort Rainey, a writer just emerging from a painful divorce with his ex-wife, is stalked at his remote lake house by a psychotic stranger and would-be scribe who claims Rainey swiped his best story idea. But as Rainey endeavors to prove his innocence, he begins to question his own sanity.","de":"Der Schriftsteller Mort Rainey hatte auch schon einmal bessere Zeiten. Erst erwischt er seine Frau Amy beim Seitensprung, dann taucht der mysteriöse Shooter auf und bezichtigt Mort des Plagiats. Shooter behauptet, dass Mort seinen Roman „Das geheime Fenster“ abgeschrieben hat. Was Mort zunächst für einen Witz hält, den er schnell aufklären kann, wird nach und nach durch unheimliche Ereignisse zur Realität. Denn so sehr Mort auch versucht, eine Kopie seines Buches zu beschaffen, welches seine Unschuld beweisen könnte, es misslingt ihm ständig. Und Shooter hat ihm ein Ultimatum von drei Tagen gestellt.","fr":"Mort Rainey, un écrivain frappé du syndrome de la page blanche, est harcelé par un dangereux psychopathe. Ce dernier l''accuse d''avoir plagié son histoire et demande réparation. Malgré les efforts de Rainey pour le calmer, l''individu devient de plus en plus vindicatif."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/5NpdcGLZuk6AgpVrAN2f4Vmw0Yr.jpg","es":"https://image.tmdb.org/t/p/w500/tNPnEp91xKShOIGh1VJgAIXIGT9.jpg","en":"https://image.tmdb.org/t/p/w500/hvzw4wufKZkDCTPVeG71Z7pGfZh.jpg","de":"https://image.tmdb.org/t/p/w500/5dc63yS1CIKyMWrlTlqDqx4pja9.jpg","fr":"https://image.tmdb.org/t/p/w500/mOLEDcCD3qh4jWeuwPxCEZWRW7J.jpg"}'::jsonb WHERE id = 335;
UPDATE public.films SET tmdb_id = 322, titoli_i18n = '{"it":"Mystic River","en":"Mystic River","fr":"Mystic River","es":"Mystic River","de":"Mystic River"}'::jsonb, trame_i18n = '{"it":"Da ragazzini Jimmy Marcus, Sean Devine e Dave Boyle erano inseparabili. Ora, a distanza di molto tempo, i tre si ritrovano in occasione di un tragico evento: la morte della prima figlia di Jimmy. Sean, che fa il poliziotto, indaga sul fatto...","en":"The lives of three men who were childhood friends are shattered when one of them suffers a family tragedy.","fr":"Jimmy Markum, Dave Boyle et Sean Devine ont grandi ensemble dans les rues de Boston. Rien ne semblait devoir altérer le cours de leur amitié jusqu''au jour où Dave se fit enlever par un inconnu sous les yeux de ses amis. Leur complicité juvénile ne résista pas à un tel événement et leurs chemins se séparèrent inéluctablement. Jimmy sombra pendant quelque temps dans la délinquance, Sean s''engagea dans la police, Dave se replia sur lui-même, se contenta de petits boulots et vécut durant plusieurs années avec sa mère avant d''épouser Celeste. Une nouvelle tragédie rapproche soudain les trois hommes : Katie, la fille de Jimmy, est retrouvée morte au fond d''un fossé. Le père endeuillé ne rêve plus que d''une chose : se venger. Et Sean, affecté à l''enquête, croit connaître le coupable : Dave Boyle...","es":"Cuando Jimmy Markum, Dave Boyle y Sean Devine eran unos niños que crecían juntos en un peligroso barrio obrero de Boston, pasaban los días jugando al hockey en la calle. Pero, un día, a Dave le ocurrió algo que marcó para siempre su vida y las de sus amigos. Veinticinco años más tarde, otra tragedia los vuelve a unir: el asesinato de Katie, la hija de 19 años de Jimmy. A Sean, que es policía, le asignan el caso; pero también tiene que estar muy pendiente de Jimmy porque, en su desesperación, está intentando tomarse la justicia por su mano.","de":"Einst waren sie Jugendfreunde, Jimmy, Sean und Davey, bis ein Verbrechen alles zerstörte. Zwei Männer, die sich als Polizisten ausgeben, entführen eines Tages Davey und missbrauchen ihn daraufhin tagelang, bis er schließlich entkommen kann.30 Jahre später ist nichts davon vergessen, die Wunden sind vernarbt, aber sie schmerzen noch. Jimmy ist nach einer Gefängnisstrafe jetzt ruhiger geworden, verheiratet und Vater zweier Töchter. Davey leidet, trotz glücklicher Ehe immer noch unter den Ereignissen von damals, während Sean inzwischen Polizist geworden ist.Als Jimmys ältere Tochter Opfer eines brutalen Verbrechens wird, nutzt Sean seine beruflichen Kompetenzen für einen privaten Rachefeldzug, in den auch seine immer noch mit ihm verbundenen Freunde mit hineingezogen werden..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/3D5VS7oWduCmwNLNmRClqGKOgZa.jpg","en":"https://image.tmdb.org/t/p/w500/hCHVDbo6XJGj3r2i4hVjKhE0GKF.jpg","fr":"https://image.tmdb.org/t/p/w500/1z7IwJBQSKVY7BPLYOOS3ZNWM53.jpg","es":"https://image.tmdb.org/t/p/w500/b6j7T4uBjXdG8FBMuDFsHttgIK2.jpg","de":"https://image.tmdb.org/t/p/w500/e2VNohx5jb7I6HUamCuGhKvzXDR.jpg"}'::jsonb WHERE id = 336;
UPDATE public.films SET tmdb_id = 615, titoli_i18n = '{"de":"Die Passion Christi","it":"La passione di Cristo","fr":"La Passion du Christ","es":"La pasión de Cristo","en":"The Passion of the Christ"}'::jsonb, trame_i18n = '{"de":"In \"Die Passion Christi\" werden die letzten zwölf Stunden im Leben von Jesus von Nazareth erzählt. Judas, einer seiner Jünger, verrät Jesus nach dem letzten Abendmahl an die pharisäischen Hohepriester, die den Prediger daraufhin gefangen nehmen. Die Hohepriester - allen voran deren Anführer Kaiphas - fürchten durch Jesus ihren gesellschaftlichen Status zu verlieren, beschuldigen ihn daher der Gotteslästerung und verlangen seinen Tod. Doch weder der römische Statthalter Pontius Pilatus, der erkennt, dass es sich bei den Anschuldigungen um eine politische Intrige handelt, noch König Herodes sind gewillt, das Todesurteil zu besiegeln...","it":"Le ultime dodici ore di vita di Gesù, dall''orto degli ulivi, all''arresto e la condanna a morte. La decisione di Ponzio Pilato di affidare la scelta alla folla, la flagellazione e, infine, la crocifissione.","fr":"Les douze dernières heures de la vie du Christ. Rendu au Mont des Oliviers, Jésus prie après avoir partagé un dernier repas avec ses apôtres. Il résiste maintenant aux tentations de Satan. Trahi par Judas, Jésus est arrêté et emmené à Jérusalem, où les chefs des Pharisiens l''accusent de blasphème et lui font un procès qui a pour issue sa condamnation à mort…","es":"Año 33 de nuestra era. En la provincia romana de Judea, un misterioso carpintero llamado Jesús de Nazareth comienza a anunciar la llegada del \"reino de Dios\" y se rodea de un grupo de humildes pescadores: los Apóstoles. Durante siglos, el pueblo judío había esperado la llegada del Mesías - personaje providencial que liberaría su sagrada patria e instauraría un nuevo orden basado en la justicia-. Las enseñanzas de Jesús atraen a una gran multitud de seguidores que lo reconocen como el Mesías. Alarmado por la situación, el Sanedrín, con la ayuda de Judas Iscariote, uno de los doce Apóstoles, arresta a Jesús. Acusado de traición a Roma, Cristo es entregado a Poncio Pilato, quien, para evitar un motín, lo condena a a morir en la cruz como un vulgar criminal.","en":"A graphic portrayal of the last twelve hours of Jesus of Nazareth''s life."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/4vtMNmeBHrxFMlV39HyLW6jOrhn.jpg","it":"https://image.tmdb.org/t/p/w500/arQvRafRtfyEQqBZ4qAjuYuYsyo.jpg","fr":"https://image.tmdb.org/t/p/w500/nVjopQNIWFGQ4Kk73QxAeIw6xov.jpg","es":"https://image.tmdb.org/t/p/w500/qPSyfz3yzTHXh1s8KRNy5YMNQJL.jpg","en":"https://image.tmdb.org/t/p/w500/rBM5o2HpmCfDejuIPybI09tkY3V.jpg"}'::jsonb WHERE id = 337;
UPDATE public.films SET tmdb_id = 640, titoli_i18n = '{"it":"Prova a prendermi","en":"Catch Me If You Can","de":"Catch Me If You Can","fr":"Arrête-moi si tu peux","es":"Atrápame si puedes"}'::jsonb, trame_i18n = '{"it":"Frank W. Abagnale Jr. è il tipico ragazzo americano di buona famiglia degli anni ''60. Ma l''improvviso dissesto finanziario del padre e il divorzio dei genitori lo costringono ad andarsene di casa. Ma come sbarcare il lunario? Ad esempio ottenendo una divisa da pilota Pan Am, falsificando assegni della compagnia aerea e comprandosi una macchina marcatrice per alterare i numeri degli stessi. In poco tempo Frank, che cambia identità più velocemente dei propri abiti, diventa una delle priorità dell''Fbi ed in particolare dell''agente Hanratty, esperto in frodi bancarie e come il suo antagonista solo al mondo.","en":"A true story about Frank Abagnale Jr. who, before his 19th birthday, successfully conned millions of dollars worth of checks as a Pan Am pilot, doctor, and legal prosecutor. An FBI agent makes it his mission to put him behind bars. But Frank not only eludes capture, he revels in the pursuit.","de":"Frank W. Abagnale war nicht nur als Arzt und Rechtsanwalt erfolgreich, sondern auch als Copilot einer großen Fluglinie. Das alles erreichte er vor seinem 21. Geburtstag. Er ist ein Meister der Täuschung, aber auch ein brillanter Fälscher. Durch geschickte Scheckbetrügereien ist er zu einem Vermögen von mehreren Millionen Dollar gekommen. FBI-Agent Carl Hanratty hat ihn schon länger im Visier und macht sich zur Aufgabe, Frank zu fassen und vor Gericht zu bringen. Frank ist ihm jedoch immer einen Schritt voraus und macht sich einen Spaß daraus, seinem Verfolger kleine Köder vorzuwerfen, damit die Jagd weiter geht…","fr":"Dans les années soixante, le jeune Frank Abagnale Jr. est passé maître dans l’art de l’escroquerie, allant jusqu’à détourner 2,5 millions de dollars et à figurer sur les listes du FBI comme l’un des dix individus les plus recherchés des États‐Unis. Véritable caméléon, Frank revêt des identités aussi diverses que celles de pilote de ligne, de médecin, de professeur d’université ou encore d’assistant du procureur. Carl Hanratty, agent du FBI à l’apparence stricte, fait de la traque de Frank Abagnale Jr. sa mission prioritaire, mais ce dernier reste pendant longtemps insaisissable…","es":"Frank Abagnale Jr. trabajó como médico, abogado y copiloto de una de las grandes líneas aéreas, todo ello antes de cumplir los dieciocho años. También fue un genial falsificador y sus habilidades le otorgaron una plaza en la historia. A la edad de 17 años, Frank Abagnale Jr. se convirtió en el ladrón de bancos de más éxito en la historia de Estados Unidos. El agente del FBI Carl Hanratty dedicó la mayor parte de su tiempo a perseguir a Frank para llevarle ante la justicia, pero Frank siempre estaba un paso por delante, retándole a continuar la caza."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/j0Ab2kETKLFISnddShJA6LffxuO.jpg","en":"https://image.tmdb.org/t/p/w500/ctjEj2xM32OvBXCq8zAdK3ZrsAj.jpg","de":"https://image.tmdb.org/t/p/w500/bJLrws4RmIw6UdXQJ6Ok4UOvKo0.jpg","fr":"https://image.tmdb.org/t/p/w500/nafyoqVGi87AwaV51GSJ0pk97gs.jpg","es":"https://image.tmdb.org/t/p/w500/WboEhiMlCsy4l2u2BweerHCLFa.jpg"}'::jsonb WHERE id = 338;
UPDATE public.films SET tmdb_id = 3131, titoli_i18n = '{"it":"Gangs of New York","es":"Gangs of New York","fr":"Gangs of New York","de":"Gangs of New York","en":"Gangs of New York"}'::jsonb, trame_i18n = '{"it":"New York, 1846. Nel quartiere di Five Points una cruenta battaglia tra gang sancisce il trionfo di William Cutting - detto Billy the Butcher, capo dei nativi americani - e la morte di Padre Vallon, protettore degli emigranti. Sedici anni dopo il figlio di questi, Amsterdam, esce dal riformatorio fermamente deciso a ingraziarsi l’assassino di suo padre per poi ottenere vendetta. Conosciuto Billy, Amsterdam ne viene in pratica adottato e arriva a salvargli la vita. Una volta scoperto e sfigurato, si risolverà a combattere apertamente contro di lui, ma sono gli anni della Guerra Civile: l’ultimo scontro tra le gang sarà decisamente superato in violenza e ferocia dall’intervento delle truppe inviate a far rispettare la coscrizione obbligatoria.","es":"New York City, 1863. Antes de la ciudad que conocemos hoy, llena de riqueza, poder y sueños infinitos, New York era un lugar diferente, una ciudad naciente donde el deseo por una vida mejor enfurecía a su gente y generaba violencia en las calles. Mientras la superviviencia del país se debatía en la Guerra Civil, un vasto y peligroso grupo de personas crecía en el bajo mundo. Pero en la joven y naciente ciudad, llegaba el momento de luchar contra los despiadados, contra la intolerancia y el miedo. Había llegado el momento del extraordinario valor de aquellos que impulsaron al borde de la lucha la libertad de futuras generaciones.","fr":"En 1846, le quartier de Five Points, un faubourg pauvre de New York, est le théâtre d''une guerre des gangs entre émigrants irlandais d''un côté, les Dead Rabbits menés par Père Vallon, et les Native Americans de l''autre, dirigés par le sanguinaire Bill le Boucher. Ce dernier met rapidement en déroute les Dead Rabbits en assassinant leur chef, et prend par la même occasion le contrôle exclusif des rues de la \"grosse pomme\". Afin de renforcer ses pouvoirs, Bill s''allie avec Boss Tweed, un politicien influent. Seize ans plus tard, le gang des Native Americans règne toujours en maître dans New York. Devenu adulte, Amsterdam Vallon souhaite venger la mort de son père en éliminant Bill. Mais sa rencontre avec Jenny Everdeane, une énigmatique pickpocket dont l''indépendance et la beauté le fascinent, va compliquer les choses...","de":"1846, New York, das Viertel Five Points: immer wieder kommt es zu blutigen Unruhen zwischen den „Gangs“ des Viertels, zwischen irisch-katholischen Immigranten und den übrigen protestantischen Einwohnern. In einem mörderischen Zweikampf ermordet „Bill The Butcher“ Cutting seinen Gegenüber Vallon. Sein Sohn Amsterdam taucht unter, um 1862 wieder im Viertel zu erscheinen, das inzwischen unter Bills Kontrolle steht. Cutting beginnt ein Vater-Sohn-Verhältnis mit Amsterdam, der Rache für seinen Vater will. Doch in Bills Nähe findet er auch eine ganz besondere Frau, Jenny Everdeane…","en":"In early 1860s New York, Irish immigrant Amsterdam Vallon is released from prison and returns to the Five Points, seeking revenge against his father''s killer, William Cutting, a powerful anti-immigrant gang leader. He knows that revenge can only be attained by infiltrating Cutting''s inner circle. Vallon''s journey becomes a fight for personal survival and to find a place for the Irish people."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/zaUzyruncix1oAQLlaG0Q8WQBbY.jpg","es":"https://image.tmdb.org/t/p/w500/gB7aaHAT1yEj49beaII6pudpode.jpg","fr":"https://image.tmdb.org/t/p/w500/UYbOQyJkfHWejmIq0k10hPb7w8.jpg","de":"https://image.tmdb.org/t/p/w500/2zJnUob8XfVxuZUFDsZF3bkPvuk.jpg","en":"https://image.tmdb.org/t/p/w500/lemqKtcCuAano5aqrzxYiKC8kkn.jpg"}'::jsonb WHERE id = 339;
UPDATE public.films SET tmdb_id = 2675, titoli_i18n = '{"it":"Signs","en":"Signs","es":"Señales","fr":"Signes","de":"Signs - Zeichen"}'::jsonb, trame_i18n = '{"it":"Il reverendo Graham Hess vive a Bucks County in Pennsylvania con i suoi due figlioletti e il fratello un po’ svanito. Sua moglie è morta in un incidente e da quel momento l’uomo ha perso la fede. Un giorno scopre degli ampi cerchi tracciati nei campi intorno alla sua fattoria. Il fenomeno si manifesta anche in India e, successivamente, in tutto il mondo. E’ opera di alieni particolarmente pericolosi e abili nel non farsi individuare. Qualcuno di loro si muove anche nei pressi della fattoria. Graham riuscirà a venire a capo del mistero. M. Night Shyamalan si muove con sicurezza nel territorio del paranormale e del contatto con gli alieni.","en":"A family living on a farm finds mysterious crop circles in their fields which suggests something more frightening to come.","es":"Graham Hess es un pastor protestante que vive con sus dos hijos y con su hermano, Merrill, una antigua estrella del béisbol que trabaja en una gasolinera. Tras la muerte de su esposa en un accidente de tráfico, Graham pierde la fe y, en consecuencia, abandona a sus feligreses. Una mañana, al despertarse, se encuentra con que sus hijos han hecho un descubrimiento escalofriante en los campos de maíz que rodean su granja.","fr":"À Bucks County, en Pennsylvanie. Après la perte de sa femme, Graham Hess a rendu sa charge de pasteur. Tout en s''occupant de sa ferme, il tente d''élever de son mieux ses deux enfants, Morgan et Bo. Son jeune frère Merrill, une ancienne gloire du base-ball, est revenu vivre avec lui pour l''aider. Un matin, la petite famille découvre l''apparition dans ses champs de gigantesques signes et cercles étranges. Des extra-terrestres seraient-ils à l''origine de tels phénomènes surnaturels ? Graham et Merrill vont s''efforcer de percer le mystère qui entoure ces dessins.","de":"Eine Familie, die auf einem Bauernhof lebt, findet auf ihren Feldern mysteriöse Kornkreise, die auf etwas noch Beängstigenderes hindeuten."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/4Jv4RWBvi0F3DIXNfVF1Ldooy86.jpg","en":"https://image.tmdb.org/t/p/w500/YtrIdrTxpRhvCnlw43dwOjfLqx.jpg","es":"https://image.tmdb.org/t/p/w500/r4q93grfe8xO28bY6MFMOZdffoo.jpg","fr":"https://image.tmdb.org/t/p/w500/A5JFVANRBrNbkraAerHjF8h8aLI.jpg","de":"https://image.tmdb.org/t/p/w500/53puwcLb51AW5iKkMwS528VMlhX.jpg"}'::jsonb WHERE id = 340;
UPDATE public.films SET tmdb_id = 180, titoli_i18n = '{"en":"Minority Report","fr":"Minority Report","it":"Minority Report","de":"Minority Report","es":"Minority Report"}'::jsonb, trame_i18n = '{"en":"John Anderton is a top ''Precrime'' cop in the late-21st century, when technology can predict crimes before they''re committed. But Anderton becomes the quarry when another investigator targets him for a murder charge.","fr":"Washington, 2054. Plus aucun meurtre ne se produit grâce au « pré-crime », l’unité policière dirigée par John Anderton. Cette unité dispose d''un système lui permettant de visualiser les meurtres avant qu''ils ne se produisent. Mais quand John découvre qu''il est lui-même accusé d''un meurtre à venir, il n''a que 36 heures pour comprendre le véritable fonctionnement de ce système.","it":"Siamo nel 2054, a Washington, dove è stato messo a punto un sistema capace di prevedere i crimini, dunque prevenirli. Niente di particolarmente tecnologico: semplicemente tre umani dotati di capacità paranormali. Si chiamano pre-cog, da precognitives. Vivono in una piscina e hanno visioni che poi trasmettono a un secondo livello, a un''unità di pronto intervento, il cui eroe è John Anderton. Ma ecco che i veggenti a un certo punto indicano proprio John come futuro omicida di un tale che non conosce. Dunque il detective comincia la caccia a se stesso, naturalmente c''è la possibilità di qualche trucco, qualcuno per esempio potrebbe fabbricare non false prove, ma false visioni. Da qui una corsa contro il tempo, che è breve","de":"Im Washington, D.C., des Jahres 2054 gibt es keine Morde mehr. Die Zukunft ist bekannt und Mörder werden gefasst, bevor sie ihr Verbrechen begehen können. Dafür sorgt Pre-Crime, eine Elite-Einheit der Polizei, die die Visionen der Pre-Cogs, drei Wesen mit hellseherischen Fähigkeiten, auswertet und zur Tat schreitet. Das System ist perfekt. Und John Anderton ist sein perfekter Chef: Seit einem tragischen Verlust sechs Jahre zuvor widmet er sein Leben mit vollkommener Leidenschaft der Verbrecherjagd. Es gibt keinen Grund für ihn, am System zu zweifeln bis er in einer Vision selbst als Mörder zu sehen ist. 36 Stunden bleiben ihm bis zu dem Verbrechen. 36 Stunden, um zu beweisen, dass er unschuldig ist und das perfekte System fehlbar. Die Flucht kann beginnen.","es":"Washington DC, año 2054. La policía utiliza tecnología psíquica para arrestar y enjuiciar a los asesinos antes de que cometan un crimen. El futuro se puede predecir y los culpables son detenidos por la unidad de élite Precrime antes de que puedan delinquir. Las pruebas se basan en los \"precogs\", tres seres psíquicos cuyas visiones sobre los asesinatos nunca han fallado."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/qtgFcnwh9dAFLocsDk2ySDVS8UF.jpg","fr":"https://image.tmdb.org/t/p/w500/91dfWOkpjlqPkbZDjAjrReFqXQP.jpg","it":"https://image.tmdb.org/t/p/w500/8EUnGlnPlleaNHt5dLGPK5GubQT.jpg","de":"https://image.tmdb.org/t/p/w500/pW1k71rXEZoXESdg9OTuorEDfvV.jpg","es":"https://image.tmdb.org/t/p/w500/q5qipy536mgsejg6AWPP9lmkGkG.jpg"}'::jsonb WHERE id = 341;
UPDATE public.films SET tmdb_id = 423, titoli_i18n = '{"es":"El pianista","it":"Il pianista","fr":"Le Pianiste","de":"Der Pianist","en":"The Pianist"}'::jsonb, trame_i18n = '{"es":"Varsovia, 1939. El pianista polaco de origen judío Wladyslaw Szpilman (Adrien Brody) interpreta un tema de Chopin en la radio nacional de Polonia mientras la aviación alemana bombardea la capital. El régimen nazi ha invadido el país, y como hace en otros países invadidos, lleva a cabo la misma política con respecto a los judíos. Así Szpilman y toda su familia -sus padres, su hermano y sus dos hermanas- se ven obligados a dejar su casa y todo lo que les pertenece para trasladarse con miles de personas de origen judío al ghetto de Varsovia. Mientras Wladyslaw trabaja como pianista en un restaurante propiedad de un judío que colabora con los nazis, su hermano Henryk (Ed Stoppard) prefiere luchar contra los nazis. Pero tres años más tarde, los habitantes del ghetto son trasladados en trenes hacia campos de concentración.","it":"È la storia di Wladyslaw Szpilman, pianista ebreo polacco, attraverso la Seconda Guerra Mondiale, dall’occupazione di Varsavia all’arrivo dell’Armata Rossa. Il film è diviso in due parti: la prima è incentrata sulla famiglia Szpilman, dall’iniziale mix di stupore e indignazione per le leggi razziali alla reclusione nel ghetto, infine alla deportazione; col treno che parte, e Wladyslaw che rimane giù, inizia la seconda parte, la fuga del pianista, il suo continuo cambiar nascondiglio, sempre a un passo dalla cattura, a mezzo dalla morte, a nessuno dall’orrore che in quegli anni ha avvolto Varsavia – non solo Varsavia.","fr":"Varsovie, au mois d’octobre 1939. Un jeune pianiste juif, Wladyslaw Szpilman, est enfermé dans le ghetto avec sa famille. Il assiste, impuissant, aux humiliations que subissent quotidiennement les siens. Grâce à une aide extérieure, il échappe de justesse à la déportation mais voit partir toute sa famille. Le jeune homme se cache alors dans les maisons vides et observe passivement les derniers habitants se révolter contre l’occupation allemande. Après avoir réussi à s’échapper miraculeusement, il se terre dans des quartiers détruits et tente de survivre, ce qui s’avère de plus en plus dur. C’est alors qu’il rencontre un nazi mélomane…","de":"Warschau, 1939. Die Besetzung Polens durch die Deutschen bedeutet für den gefeierten polnisch-jüdischen Pianisten Wladyslaw Szpilman den Beginn eines langen Leidenswegs. Durch einen Glücksfall entgeht er dem Transport ins KZ, in dem seine gesamte Familie ums Leben kommt. Von nun an fristet er ein Dasein im Untergrund. Hungrig, krank und psychisch vor dem Kollaps stehend, wird er gegen Kriegsende schließlich von einem deutschen Offizier aufgespürt. Doch anstatt ihn auszuliefern, bittet er ihn, Klavier zu spielen. Szpilmans Rettung.  Der Pianist ist eine Filmadaption der Biographie „Das wunderbare Überleben“ von Wladyslaw Szpilman. Das Filmdrama des Regisseurs Roman Polanski hat mit dem Film auch ein Stück eigene Geschichte aufgearbeitet.","en":"The true story of pianist Władysław Szpilman''s experiences in Warsaw during the Nazi occupation. When the Jews of the city find themselves forced into a ghetto, Szpilman finds work playing in a café; and when his family is deported in 1942, he stays behind, works for a while as a laborer, and eventually goes into hiding in the ruins of the war-torn city."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/mxfLOWnHnSlbdraKfzRn5mqoqk7.jpg","it":"https://image.tmdb.org/t/p/w500/zK3KyPLAQl0IRIToIaQsMxm0aR3.jpg","fr":"https://image.tmdb.org/t/p/w500/vI05JxU356MciaQeYHjXlqfjQe0.jpg","de":"https://image.tmdb.org/t/p/w500/eLWN41bCnCshV3fPqe5cuwqYCeK.jpg","en":"https://image.tmdb.org/t/p/w500/2hFvxCCWrTmCYwfy7yum0GKRi3Y.jpg"}'::jsonb WHERE id = 342;
UPDATE public.films SET tmdb_id = 245, titoli_i18n = '{"es":"Un niño grande","it":"About A Boy - Un ragazzo","de":"About a Boy oder: Der Tag der toten Ente","fr":"Pour un garçon","en":"About a Boy"}'::jsonb, trame_i18n = '{"es":"Will Lightman (Hugh Grant) es un soltero de 38 años que vive de los derechos de autor de una canción compuesta hace años por su padre. Su miedo al compromiso es tal que sólo se relaciona con madres solteras, porque piensa que es más fácil romper con ellas. Sin embargo, sus convicciones se tambalean cuando se convierte en el mejor amigo de Marcus, un niño de 12 años al que conoce en una de sus citas.","it":"Will è un single, vicino ai quarant’anni: vive di rendita e il suo unico scopo nella vita sembra essere continuare a non fare niente, impiegando la maggior parte del suo tempo a cercare nuove conquiste femminili. Infatti un giorno si reca ad un incontro di genitori single, fingendosi “ragazzo-padre” solo per conquistare qualche donna sola: invece si troverà suo malgrado coinvolto nella vita di una di queste, e soprattutto di suo figlio, Marcus.","de":"Will Freeman wird von all seinen Geschlechtsgenossen beneidet – er fährt ein schnelles Auto, genießt seine Affären und kann mit 38 ohne jede Verantwortung in den Tag hinein leben… Seine neue Taktik für den Frauenfang ist der Besuch von Selbsthilfegruppen für allein erziehende Mütter und Väter, denn das ist genau der richtige Ort um auf einsame Frauen zu treffen. Doch dann begegnet Will Marcus. Dieser ungewöhnliche Zwölfjährige bringt sein Leben völlig durcheinander – mit äußerst amüsanten Folgen.","fr":"Will Freeman est un trentenaire londonien et un célibataire endurci. Vivant allègrement grâce aux droits d''auteur qu''il perçoit sur une chanson de Noël écrite par son père, il s''invente un fils pour draguer des mères célibataires. Un jour, il fait la connaissance de Marcus, un garçon de douze ans, fils de Fiona, hippie et végétarienne, et tête de Turc de l''école. Will et Marcus deviennent amis, et pendant que Will apprend à Marcus l''art d''être cool, Marcus apprend à Will l''art d''être adulte.","en":"Will Freeman is a good-looking, smooth-talking bachelor whose primary goal in life is avoiding any kind of responsibility. But when he invents an imaginary son in order to meet attractive single moms, Will gets a hilarious lesson about life from a bright, but hopelessly geeky 12-year-old named Marcus. Now, as Will struggles to teach Marcus the art of being cool, Marcus teaches Will that you''re never too old to grow up."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/6AQlj4fIeZoDO74xhBKsEVPUa8m.jpg","it":"https://image.tmdb.org/t/p/w500/hEzs1OAhc9djI69fRUHVRgXrin.jpg","de":"https://image.tmdb.org/t/p/w500/5GxorcCulCJhcOjNGRUdkZWY2qN.jpg","fr":"https://image.tmdb.org/t/p/w500/b5uCL8EzOXe0DD2PZJjuF34eLy7.jpg","en":"https://image.tmdb.org/t/p/w500/qoZ1bD0q9EFqcNiEYbEigsRcNCt.jpg"}'::jsonb WHERE id = 343;
UPDATE public.films SET tmdb_id = 1011082, titoli_i18n = '{"es":"The Greatest Hits","de":"The Greatest Hits","fr":"The Greatest Hits","it":"The Greatest Hits","en":"The Greatest Hits"}'::jsonb, trame_i18n = '{"es":"Harriet descubre que ciertas canciones la hacen viajar atrás en el tiempo y revive un romance del pasado mientras conoce a un nuevo interés amoroso en el presente. Durante el viaje a través de la hipnótica conexión entre música y recuerdos, Harriet se pregunta si cambiaría el pasado a pesar de tener el poder de hacerlo.","de":"Harriet entdeckt, dass bestimmte Lieder sie in der Zeit zurückversetzen - im wahrsten Sinne des Wortes. Als sie eine vergangene Romanze wiedererlebt, während sie in der Gegenwart durch die Verbindung zwischen Musik und Erinnerung eine neue Liebe findet, stellt sie sich die Frage - selbst wenn sie die Vergangenheit ändern könnte, sollte sie es tun?","fr":"Harriet réalise que certaines chansons peuvent littéralement la ramener dans le passé. Elle revit une histoire d''amour passée tout en découvrant un nouvel amour dans le présent, à travers le lien entre la musique et la mémoire, et se demande si, même si cela est impossible, elle pourrait changer le passé...","it":"Harriet scopre che alcune canzoni la riportano indietro nel tempo, letteralmente. Mentre rivive una storia romantica del passato e, nel frattempo, scopre un nuovo amore nel presente attraverso il legame tra musica e memoria, si pone una domanda: cambierebbe il passato, se potesse?","en":"Harriet finds art imitating life when she discovers certain songs can transport her back in time – literally. While she relives the past through romantic memories of her former boyfriend, her time travelling collides with a burgeoning new love interest in the present. As she takes her journey through the hypnotic connection between music and memory, she wonders – even if she could change the past, should she?"}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/cve12HkI9psBUfmkx7FeBciaQN7.jpg","de":"https://image.tmdb.org/t/p/w500/cve12HkI9psBUfmkx7FeBciaQN7.jpg","fr":"https://image.tmdb.org/t/p/w500/cve12HkI9psBUfmkx7FeBciaQN7.jpg","it":"https://image.tmdb.org/t/p/w500/cve12HkI9psBUfmkx7FeBciaQN7.jpg","en":"https://image.tmdb.org/t/p/w500/cve12HkI9psBUfmkx7FeBciaQN7.jpg"}'::jsonb WHERE id = 344;
UPDATE public.films SET tmdb_id = 64036, titoli_i18n = '{"it":"L''Esorciccio","en":"The Exorciccio","es":"L''Esorciccio","de":"L''Esorciccio","fr":"L''Esorciccio"}'::jsonb, trame_i18n = '{"it":"Durante scavi archeologici in Iran viene rinvenuto un amuleto che finisce tra le mani del figlio decenne del sindaco di un paesino del Lazio. Il ragazzino diventa un focosissimo amatore, e ricorre quindi allo stregone Esorciccio. E come lui tutti coloro che, a turno, posseggono l''amuleto si scatenano in inverecode stranezze. Ogni tanto compare addirittura il Demonio in persona, finché Esorciccio ingoia l''oggetto diabolico.","en":"A satire on the American film \"The Exorcist,\" but with an Italian twist."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/2SWLoIVmadfNNcFnILglliTQaTN.jpg","en":"https://image.tmdb.org/t/p/w500/2SWLoIVmadfNNcFnILglliTQaTN.jpg","es":"https://image.tmdb.org/t/p/w500/2SWLoIVmadfNNcFnILglliTQaTN.jpg","de":"https://image.tmdb.org/t/p/w500/2SWLoIVmadfNNcFnILglliTQaTN.jpg","fr":"https://image.tmdb.org/t/p/w500/2SWLoIVmadfNNcFnILglliTQaTN.jpg"}'::jsonb WHERE id = 345;
UPDATE public.films SET tmdb_id = 807, titoli_i18n = '{"en":"Se7en","fr":"Seven","de":"Sieben","it":"Seven","es":"Seven"}'::jsonb, trame_i18n = '{"en":"Two homicide detectives are on a desperate hunt for a serial killer whose crimes are based on the \"seven deadly sins\" in this dark and haunting film that takes viewers from the tortured remains of one victim to the next. The seasoned Det. Somerset researches each sin in an effort to get inside the killer''s mind, while his novice partner, Mills, scoffs at his efforts to unravel the case.","fr":"À New York, un criminel anonyme a décidé de commettre 7 meurtres basés sur les 7 pêchés capitaux énoncés dans la Bible : gourmandise, avarice, paresse, orgueil, luxure, envie et colère. Vieux flic blasé à 7 jours de la retraite, l''inspecteur Somerset mène l''enquête tout en formant son remplaçant, l''ambitieux inspecteur David Mills…","de":"Der besonnene Detective Somerset ist ein Kriminologe der „alten Schule“. Zusammen mit seinem neuen Kollegen, dem Heißsporn Mills, wird er auf den ungewöhnlichsten und erschreckendsten Fall seiner Laufbahn angesetzt. Ein unbekannter Serienkiller versucht scheinbar, die Stadt von allen Sünden zu befreien. Er tut dies, indem er auf bestialische Weise für jede der sieben Todsünden einen symbolischen Ritualmord begeht.","it":"Un killer astuto e spietato sta uccidendo a raffica, nei modi più raccapriccianti, personaggi scelti con cura. Sulle sue tracce ci sono il giovane e ambizioso Mills, alla prima missione, e l''esperto Somerset, ormai prossimo alla pensione; personalità opposte che mal si tollerano a vicenda. Imparano a \"convivere\" man mano che la caccia all''assassino si fa più serrata e il mistero comincia a districarsi.","es":"El teniente Somerset, del departamento de homicidios, está a punto de jubilarse y ser reemplazado por el ambicioso y brillante detective David Mills. Ambos tendrán que colaborar en la resolución de una serie de asesinatos cometidos por un psicópata que toma como base la relación de los siete pecados capitales: gula, pereza, soberbia, avaricia, envidia, lujuria e ira. Los cuerpos de las víctimas, sobre los que el asesino se ensaña de manera impúdica, se convertirán para los policías en un enigma que les obligará a viajar al horror y la barbarie más absoluta."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/191nKfP0ehp3uIvWqgPbFmI4lv9.jpg","fr":"https://image.tmdb.org/t/p/w500/to6jUaLJonMuKW2YovtWfQKtLYP.jpg","de":"https://image.tmdb.org/t/p/w500/79tFIrbMweqs52PxForIRJRFCIW.jpg","it":"https://image.tmdb.org/t/p/w500/1XHq0Z7BkjeQ9J5CLmWD0xX0DuB.jpg","es":"https://image.tmdb.org/t/p/w500/uVPcVz4b2hnSGrXYLdIGRXwcivs.jpg"}'::jsonb WHERE id = 346;
UPDATE public.films SET tmdb_id = 453, titoli_i18n = '{"en":"A Beautiful Mind","it":"A Beautiful Mind","es":"Una mente maravillosa","de":"A Beautiful Mind - Genie und Wahnsinn","fr":"Un homme d''exception"}'::jsonb, trame_i18n = '{"en":"From the heights of notoriety to the depths of depravity, John Forbes Nash Jr. experiences it all. As a brilliant but socially awkward mathematician, he made a groundbreaking discovery early in his career and stands on the brink of international acclaim. But as the handsome and arrogant Nash accepts secret work in cryptography, he becomes entangled in a mysterious conspiracy. His life takes a nightmarish turn and he soon finds himself on a painful and harrowing journey of self-discovery.","it":"Il film si ispira alla vita di John Forbes Nash Jr. Di origini medio borghesi, Forbes nacque in una piccola città della Virginia occidentale il 13 giugno 1928 e, per oltre cinquant''anni è stato considerato un mito negli ambienti della ricerca matematica. Grazie al suo studio della teoria dei giochi, negli anni 50 diventò l''astro nascente della \"nuova matematica\". Poco a poco, vittima di una grave forma di schizofrenia, Nash sprofondò in un mondo tutto suo, convinto che le sue allucinazioni fossero realtà. Passò diversi anni in ospedali psichiatrici, ma durante la sua assenza, la teoria dei giochi acquistò un ruolo di importanza fondamentale nei campi dell''economia e degli affari. Nel 1994, Nash aveva riacquistato il pieno controllo della sua vita e ripreso le ricerche. In quello stesso anno venne insignito del Premio Nobel per l''economia.","es":"Obsesionado con la búsqueda de una idea matemática original, el brillante estudiante John Forbes Nash llega a Princeton para realizar sus estudios de postgrado. Es un muchacho extraño y solitario, al que sólo comprende su compañero de cuarto. Por fin, Nash esboza una revolucionaria teoría y consigue una plaza de profesor en el MIT. Alicia Lardé, una de sus alumnas, lo deja fascinado al mostrarle que las leyes del amor están por encima de las de las matemáticas. Gracias a su prodigiosa habilidad para descifrar códigos es reclutado por Parcher William, del departamento de Defensa, para ayudar a los Estados Unidos en la Guerra Fría contra la Unión Soviética.","de":"Princeton Universität, 1947: Der hoch begabte, aber äußerst exzentrische John Nash sucht fieberhaft, fast krankhaft besessen, nach einer revolutionierenden Theorie in der Mathematik. Er schert sich wenig um seine Kommilitonen und die Konventionen der Universität. Und tatsächlich macht er eines Tages die alles entscheidende Entdeckung. Mit seiner Karriere geht es fortan steil bergauf, und Nash bekommt eine Stelle als Forscher und Dozent. Da er zudem die außergewöhnliche Fähigkeit besitzt, innerhalb weniger Sekunden komplexe Codes zu knacken, übernimmt er immer häufiger Decodier-Aufgaben für den amerikanischen Geheimdienst. Doch der Stress, die Gefahr und die Heimlichkeiten seiner Tätigkeit fordern ihren Tribut: John leidet zunehmend unter Verfolgungswahn und wittert ständig Verschwörungen. Die erschütternde Diagnose: paranoide Schizophrenie. John droht alles zu verlieren: seine geliebte Frau, seinen Job und seinen Verstand…","fr":"En 1947, étudiant les mathématiques à l''université de Princeton, John Forbes Nash Jr., un brillant élève, élabore sa théorie économique des jeux. Pour lui, les fluctuations des marchés financiers peuvent être calculées très précisément. Au début des années cinquante, ses travaux et son enseignement au Massachusetts Institute of Technology ne passent pas inaperçus et un représentant du Département de la Défense, William Parcher, se présente à lui pour lui proposer d''aider secrètement les États‐Unis. La mission de John consiste à décrypter dans la presse les messages secrets d’espions russes, censés préparer un attentat nucléaire sur le territoire américain. Celui‐ci y consacre rapidement tout son temps, et ce au détriment de sa vie de couple avec Alicia. Ce job n''est toutefois pas sans risques : des agents ennemis surveillent ses moindres faits et gestes. Mais personne ne le croit."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/rEIg5yJdNOt9fmX4P8gU9LeNoTQ.jpg","it":"https://image.tmdb.org/t/p/w500/bsVAjDLllFLEkuS1HwU96bbvkw5.jpg","es":"https://image.tmdb.org/t/p/w500/6zyZ6cauEgSbfii9I7gOvGNyPGv.jpg","de":"https://image.tmdb.org/t/p/w500/slNnHqV7xeXuqCfHFlqGOj9MJjK.jpg","fr":"https://image.tmdb.org/t/p/w500/AjoFwrErCHZYCx4pYqH1F0CjrcA.jpg"}'::jsonb WHERE id = 347;
UPDATE public.films SET tmdb_id = 1903, titoli_i18n = '{"it":"Vanilla Sky","en":"Vanilla Sky","es":"Vanilla Sky","fr":"Vanilla Sky","de":"Vanilla Sky"}'::jsonb, trame_i18n = '{"it":"David Aames è un uomo davvero fortunato. È giovane, è bello ed è ricco, essendo l''erede di un impero editoriale. È abituato a ottenere ciò che vuole quando vuole, finché un giorno non incontra Sofia, che scompare quando lui comprende che è la donna dei suoi sogni. La vita di David non sarà più la stessa e la cercherà in modo ossessivo a rischio di perdere tutto.","en":"David Aames has it all: wealth, good looks and gorgeous women on his arm. But just as he begins falling for the warmhearted Sofia, his face is horribly disfigured in a car accident. That''s just the beginning of his troubles as the lines between illusion and reality, between life and death, are blurred.","es":"Re-boot. David Aames lo tiene todo: es apuesto, tiene dinero y una hermosa mujer a su lado. Pero justo cuando ha encontrado el verdadero amor en Sofía, sufre un accidente de automóvil que le deja la cara horriblemente desfigurada y lo pierde todo.","fr":"David Aames est un jeune et brillant éditeur new-yorkais qui a tout pour lui : l''argent, la réussite professionnelle et les femmes. Son ami Pelayo commet l''erreur de lui présenter Sofia, sa nouvelle compagne. Au premier regard, David succombe au charme de celle-ci. Tous les deux filent bientôt le parfait amour. Alors que David se dispute en voiture avec Julie, une ex folle de jalousie, la jeune femme accélère et c''est l''accident. Julie décède. Atrocement défiguré, David est transporté d''urgence à l''hôpital où les médecins ne peuvent réaliser de miracle. Sa vie bascule. Les gens ont dorénavant peur de lui et Sofia l''évite. Mais un matin, David se fait gentiment réveiller par celle-ci, qui lui déclare son amour. Les médecins lui annoncent même qu''il pourra retrouver son ancien visage. Réalité ou hallucination ?","de":"Der New Yorker Geschäftsmann David Aames stand bislang auf der Sonnenseite des Lebens. Eines Abends jedoch verliebt er sich in die bezaubernde Sofia. Doch seine langjährige Affäre Julie hat etwas dagegen. Nach einem heftigen Streit kommt es zu einem Autounfall, bei dem Julie stirbt und Davids Gesicht aufs Grausamste entstellt wird. Etliche Operationen später scheint Aames genesen, da läuft ihm Sofia erneut über den Weg, nur um kurz darauf spurlos zu verschwinden. Stattdessen taucht Julie wieder auf und behauptet felsenfest, sie sei Sofia..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/aV9cwAmpNhxlX8l64RXULc9jrqN.jpg","en":"https://image.tmdb.org/t/p/w500/cAh2pCiNPftsY3aSqJuIOde7uWr.jpg","es":"https://image.tmdb.org/t/p/w500/nphloW8RV0agLvy6iXYaITFmbuJ.jpg","fr":"https://image.tmdb.org/t/p/w500/rP5pOnQ7kZrPOOCGay2Vc1O84Z0.jpg","de":"https://image.tmdb.org/t/p/w500/gXYUq0mqzlJV0Le0N2xG7E5QkLU.jpg"}'::jsonb WHERE id = 348;
UPDATE public.films SET tmdb_id = 676, titoli_i18n = '{"it":"Pearl Harbor","en":"Pearl Harbor","es":"Pearl Harbor","de":"Pearl Harbor","fr":"Pearl Harbor"}'::jsonb, trame_i18n = '{"it":"In una tranquilla domenica mattina di dicembre, mentre i bambini sono intenti nei loro giochi e le famiglie raccolte in preghiera, squadroni di aerei da guerra giapponesi sfrecciano roboanti nei cieli del paradiso hawaiano un attacco a sorpresa contro le forze armate statunitensi di base a Pearl Harbor. Pearl Harbor è la storia di un intenso amore nato sullo sfondo degli eventi del 7 dicembre 1941. Descrive le vicende di due giovani e audaci piloti e della bella e sensibile infermiera di cui sono entrambi innamorati. E'' un imponente film sulla forza dell''amore e sul coraggio del singolo messi a dura prova da un drammatico momento storico.","en":"The lifelong friendship between Rafe McCawley and Danny Walker is put to the ultimate test when the two ace fighter pilots become entangled in a love triangle with beautiful Naval nurse Evelyn Johnson. But the rivalry between the friends-turned-foes is immediately put on hold when they find themselves at the center of Japan''s devastating attack on Pearl Harbor on Dec. 7, 1941.","es":"Rafe y Danny crecieron juntos en una zona rural estadounidense y su amistad se ha prolongado a lo largo de los años hasta las filas del ejercito del aire, donde los dos son pilotos de combate. Rafe encontró en Evelyn, una valiente enfermera, al amor de su vida, pero pronto es llamado a servir en la fuerza aérea británica para combatir a los nazis como representante del ejército estadounidense. Mientras tanto, Danny y Evelyn son enviados a la base aérea de Pearl Harbor en Hawai. Una vez allí, ambos se enamoran mientras Rafe es derribado en combate. Para sorpresa de ambos, Rafe sobrevive y regresa a Pearl Harbor pero todo se complica cuando se produce un mortal bombardeo por parte del ejercito japonés.","de":"New Jersey 1941. Rafe McCawley und Danny Walker sind seit ihren Kindertagen beste Freunde. Wie Brüder sind sie aufgewachsen und das Fliegen war schon immer ihre große Leidenschaft. Inzwischen sind sie waghalsige junge Piloten im U.S. Army Air Corps. Bis eine eigenmächtige Entscheidung Rafes ihre Freundschaft auf die Probe stellt: Er hat sich als Freiwilliger zum \"Eagle Squadron\" gemeldet, einer Gruppe amerikanischer Soldaten, die auf Seiten der Engländer kämpft. Rafe lässt nicht nur seinen besten Freund zurück, sondern auch seine große Liebe Evelyn. Sie ist eine mutige junge Frau, die Rafe im Militärkrankenhaus kennenlernte, in dem sie als Krankenschwester arbeitet. Während Rafe in England sein Leben aufs Spiel setzt, werden Evelyn und Danny nach Pearl Harbor auf Hawaii versetzt ...","fr":"Amis depuis la plus tendre enfance, Rafe McCawley et Danny Walker sont deux brillants pilotes de l''armée de l''air américaine. La Seconde Guerre mondiale a commencé, mais les États-Unis n''ont pas encore engagé les hostilités. Rafe succombe bientôt au charme d''Evelyn Johnson, une jeune infirmière. C''est le coup de foudre. Mais ce dernier part combattre aux côtés des Britanniques. Evelyn et Danny sont, quant à eux, transférés sur la base américaine de Pearl Harbor. La paisible existence de ces deux jeunes gens bascule lorsqu''ils apprennent la mort de Rafe. Evelyn partage son chagrin avec Danny et un amour naît de leurs confidences. Rafe est pourtant vivant. En cette journée du 7 décembre 1941, les retrouvailles et les explications vont devoir être reportées à plus tard : au même moment, près de 200 bombardiers japonais surgissent dans le ciel de Hawaï pour une attaque surprise."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/rU08tMQ381BRMjKSwDKiR00TNeq.jpg","en":"https://image.tmdb.org/t/p/w500/y8A0Cvp8WQmZ3bjbnsL53lY0dsC.jpg","es":"https://image.tmdb.org/t/p/w500/ftkKVbk4sQEcekuaGJvpvXcNs32.jpg","de":"https://image.tmdb.org/t/p/w500/1XCLbbuhN2wFjURcY046RMTCaO.jpg","fr":"https://image.tmdb.org/t/p/w500/3oae9FJMWfvobqbl0CvXqqCftvU.jpg"}'::jsonb WHERE id = 349;
UPDATE public.films SET tmdb_id = 1018, titoli_i18n = '{"fr":"Mulholland Drive","en":"Mulholland Drive","es":"Mulholland Drive","de":"Mulholland Drive - Straße der Finsternis","it":"Mulholland Drive"}'::jsonb, trame_i18n = '{"fr":"À Hollywood, durant la nuit, Rita, une jeune femme, devient amnésique suite à un accident de voiture sur la route de Mulholland Drive. Elle fait la rencontre de Betty Elms, une actrice en devenir qui vient juste de débarquer à Los Angeles. Aidée par celle-ci, Rita tente de retrouver la mémoire ainsi que son identité.","en":"Blonde Betty Elms has only just arrived in Hollywood to become a movie star when she meets an enigmatic brunette with amnesia. Meanwhile, as the two set off to solve the second woman''s identity, filmmaker Adam Kesher runs into ominous trouble while casting his latest project.","es":"Betty, una joven aspirante a actriz, llega a Los Ángeles para convertirse en estrella de cine y se aloja en el apartamento de su tía. Allí conoce a Rita, una mujer que padece amnesia a causa de un accidente en Mulholland Drive. Las dos juntas deciden investigar quién es Rita y cómo llegó hasta allí.","de":"Nach einem Unfall irrt eine junge Frau, die ihr Gedächtnis verloren hat, durch das nächtliche Hollywood und findet Unterschlupf in einem Appartement, das von der jungen Schauspielerin Betty bewohnt wird. Diese will in Hollywood Karriere machen, erklärt sich aber bereit, der verstörten Schönheit bei der Suche nach ihrem düsteren Geheimnis zu helfen.","it":"In tarda notte, una limousine percorre Mulholland Drive (una strada che attraversa le colline attorno a Los Angeles, California); al suo interno c''è una donna dai capelli scuri (interpretata da Laura Elena Harring) e due uomini; improvvisamente, l''auto si ferma ed uno dei due uomini punta una pistola contro la donna; subito dopo, però, dei pirati della strada si schiantano contro la limousine. La donna resta miracolosamente illesa, ma ha un''amnesia. Abbandona la scena dell''incidente e scende la collina che porta a Los Angeles, stendendosi nel giardino di un appartamento e mettendosi a dormire. Il giorno successivo, si sveglia e vede la proprietaria dell''appartamento, una donna di mezza età dai capelli rossi, che sta per partire."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/d5gefer4mHnL5kOmlOP5rGumdM7.jpg","en":"https://image.tmdb.org/t/p/w500/x7A59t6ySylr1L7aubOQEA480vM.jpg","es":"https://image.tmdb.org/t/p/w500/kLpwkbimTwTbsYixCO3eAdNCQJ8.jpg","de":"https://image.tmdb.org/t/p/w500/6XpAFxwhVZ2t30Qtn8Wz8koKlaN.jpg","it":"https://image.tmdb.org/t/p/w500/zQKnbazscP54i6iKHfdgYdmDsLv.jpg"}'::jsonb WHERE id = 350;
UPDATE public.films SET tmdb_id = 768, titoli_i18n = '{"fr":"From Hell","de":"From Hell","en":"From Hell","es":"Desde el infierno","it":"La vera storia di Jack lo Squartatore"}'::jsonb, trame_i18n = '{"fr":"En 1888, à Londres, dans les rues mal famées du quartier de Whitechapel, un tueur en série, surnommé Jack l''Éventreur, rôde. D''une étonnante précision, ce mystérieux personnage éventre, la nuit tombée, des prostituées. C''est ici qu''entre en scène l''inspecteur Fred Abberline. Cet agent de Scotland Yard comprend rapidement que ces crimes procèdent d''une mise en scène élaborée et supposent un \"doigté\" d''artiste, un sang-froid à toute épreuve et de solides connaissances en anatomie. Le policier, intuitif et visionnaire, dresse patiemment le profil de ce meurtrier hors normes et parvient à gagner la confiance de Mary Kelly, une jeune prostituée. Celle-ci va l''aider à résoudre cette périlleuse enquête.","de":"Der Tod seiner Frau und seines Kindes hat den Scotland-Yard-Inspektor Fred Abberline endgültig aus der Bahn geworfen. Nun sucht er Vergessen in Drogen, doch was er im Opium- und Absinth-Rausch findet, sind Visionen von grausigen Verbrechen und düstere Vorahnungen, die ihn zu einem Besessenen werden lassen. Sie sind es auch, die eine Verbindung herstellen zwischen ihm und dem Prostituiertenmörder Jack the Ripper, dessen Taten das Slum-ähnliche Londoner Arbeiterviertel Whitechapel in Aufruhr versetzen. Bei seinen Nachforschungen begegnet Abberline der engelsgleichen irischen Prostituierten Mary Kelly, die mit allen Opfern des brutalen Serienmörders befreundet war.","en":"Frederick Abberline is an opium-huffing inspector from Scotland Yard who falls for one of Jack the Ripper''s prostitute targets in this Hughes brothers adaption of a graphic novel that posits the Ripper''s true identity.","es":"Basada en la historia de Jack el Destripador y el cómic de Alan Moore. Amanece en Whitechapel, el barrio más sórdido de Londres, donde las drogas, la enfermedad y la miseria campan a sus anchas. Cinco chicas dedicadas a la prostitución se encuentran amenazadas por un terrible monstruo que podría robarles su única posesión: la vida. El único que se toma la molestia por protegerlas es el Inspector Fred Abberline que con la ayuda de su amigo el sargento Godley, trata de desentrañar una espeluznante conspiración. A medida que los salvajes asesinatos se suceden, los dos hombres ven obstaculizado su trabajo por unos superiores más interesados en esconder los crímenes bajo la alfombra que en encontrar al verdadero asesino, un sádico loco destinado a pasar a la historia.","it":"Londra, 1888. Nelle strade del quartiere di Whitechapel, Jack lo Squartatore si aggira di notte uccidendo e sventrando le prostitute. Sulle sue tracce, oltre all''intera polizia londinese, c''è l''ispettore Frederick George Abberline, l''unico che capisce subito che i delitti sono preceduti da una meticolosa e scrupolosa messa in scena. Il poliziotto, intuitivo e visionario, cerca di ricostruire il profilo di Jack anche grazie all''aiuto della prostituta Mary Kelly."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/yqNsZZQF4khKyCZ13yfnT4ov6uI.jpg","de":"https://image.tmdb.org/t/p/w500/uxWh7kHpeDTsiYELdw4H33ACNyM.jpg","en":"https://image.tmdb.org/t/p/w500/t2WpWM8nBO4sULXr2bDfNEt4qgr.jpg","es":"https://image.tmdb.org/t/p/w500/fv29GwNS1NOgsr4NAdghOlQXkup.jpg","it":"https://image.tmdb.org/t/p/w500/pvgnEmCPie99MOZFrkEpA73QHgg.jpg"}'::jsonb WHERE id = 351;
UPDATE public.films SET tmdb_id = 392, titoli_i18n = '{"es":"Chocolat","en":"Chocolat","it":"Chocolat","de":"Chocolat","fr":"Le Chocolat"}'::jsonb, trame_i18n = '{"es":"A Lansquenet, un pueblo francés muy tradicional, donde nada ha cambiado en los últimos cien años, el Viento del Norte lleva consigo a dos forasteras: Vianne Rocher y su hija Anouk. Vianne inaugura una chocolatería repleta de dulces capaces de despertar los ocultos apetitos de los habitantes del pueblo. Posee, además, un don especial que le permite percibir los deseos de los demás y satisfacerlos con el dulce exacto.","en":"In the winter of 1959, a single mother and her young daughter arrive in a rural French town, where they open an unusual chocolate shop that disrupts the moral fiber of the strictly Catholic townsfolk and mayor.","it":"L''apertura di un peccaminoso negozio di cioccolata da parte della giovane Vianne Rocher nel minuscolo villaggio di Lansquenet, scatena una vera e propria guerra all''interno della cittŕ, tra quelli che non vedono di buon occhio il negozio e quelli che desiderano assaporare la libertà che hanno appena scoperto.","de":"Ein verschlafenes Dorf in Frankreich im Jahre 1959. Hier glauben die Bewohner an „Tranquillité“, an die Ruhe und Stille. Man ist ordentlich und gottesfürchtig, wie es sich gehört. Da kommt Vianne Rocher mit ihrer minderjährigen Tochter in die Stadt, mietet die leerstehende Patisserie an und eröffnet einen Schokoladenladen. Da sie nicht verheiratet ist, nicht in die Kirche geht und den Laden in der Fastenzeit öffnet, eckt sie bei vielen Leuten, besonders dem Bürgermeister an. Doch ihre Spezialitäten zeigen ihre Wirkung bei den ersten Leuten, die wie nach einem langen Winter allmählich auftauen. Vianne nimmt sich Zeit, redet mit den Leuten und gewinnt das Vertrauen einiger. Doch es gibt immer wieder Probleme, vor allem, als sie sich mit dem Zigeuner Roux anfreundet, ein Nomade wie sie selbst …","fr":"Durant l''hiver 1959, Vianne Rocher s''installe avec Anouk, sa petite fille, à Lansquenet, une petite bourgade française. En quelques jours, elle ouvre une confiserie à proximité de l''église. C''est une chocolatière hors pair: elle devine la gourmandise cachée de chacun et adapte ses recettes raffinées pour combler ses clients. De nombreux villageois s''abandonnent rapidement à ses irrésistibles friandises et succombent à ses délices sucrés. Mais la bourgeoisie huppée de la ville ainsi que le Comte de Reynaud sont outrés de voir les habitants envoûtés par les chocolats de Vianne. Craignant que ses friandises n''amènent les gens au péché et à l''oisiveté, le Comte s''oppose vivement au commerce de Vianne et, afin de causer sa faillite, interdit à quiconque de s''y rendre. La venue d''un autre étranger, le beau Roux, va bouleverser la donne. Il aide Vianne à tenir tête à ses détracteurs."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/yxaZCSXfUlkBY8WVYoeWeE8nvej.jpg","en":"https://image.tmdb.org/t/p/w500/lnwPvyj8UR7MetG2pQ92453IIoR.jpg","it":"https://image.tmdb.org/t/p/w500/ym4zIlPCAoD0UqOBf6NmHcK0YIi.jpg","de":"https://image.tmdb.org/t/p/w500/meGDfWXgwbN63RJ5mhaogqLQiM8.jpg","fr":"https://image.tmdb.org/t/p/w500/7RBG3RzAqQvF6XtTsQqLzdsyAvR.jpg"}'::jsonb WHERE id = 352;
UPDATE public.films SET tmdb_id = 8358, titoli_i18n = '{"en":"Cast Away","de":"Cast Away - Verschollen","it":"Cast Away","fr":"Seul au monde","es":"Náufrago"}'::jsonb, trame_i18n = '{"en":"Chuck Noland, a top international manager for FedEx, and Kelly, a Ph.D. student, are in love and heading towards marriage. Then Chuck''s plane to Malaysia crashes at sea during a terrible storm. He''s the only survivor, and finds himself marooned on a desolate island. With no way to escape, Chuck must find ways to survive in his new home.","de":"Als gestresster Inspektor eines Transportunternehmens reist Chuck Noland um die ganze Welt. Dann passiert das Unerwartete: Nach einem Unfall kann er sich als einziger Überlebender auf eine einsame Insel retten. Gefangen im Paradies kämpft er vier Jahre lang ums Überleben um dann, zurück in der Zivilisation, eine für ihn fremd gewordene Welt vorzufinden.","it":"È la vigilia di Natale e Chuck Noland, funzionario della Federal Express, scambia i regali con la sua fidanzata Kelly in macchina prima di salire a bordo dell''aereo per l''ennesimo viaggio di lavoro. A causa di una tempesta l''aereo si inabissa nel Pacifico. Chuck, unico sopravvissuto, naufraga su di un isola deserta dove si rende conto, poco alla volta, che dovrà restarci per molto molto tempo.","fr":"Chuck Noland, gestionnaire au service d’un transporteur international, ne vit que par son travail. Il sillonne le monde pour améliorer les performances de son entreprise et la productivité de ses équipes. Il ne voit sa compagne Kelly que quelques jours par an. Lors de l’un de ses déplacements, Chuck est victime d’un accident d''avion qui coule en plein Pacifique. Agrippé à un radeau de sauvetage, Chuck s’échoue sur un îlot désert. Seul au monde, privé de tous ses repères habituels, le naufragé doit apprendre les gestes élémentaires pour sa survie.","es":"Chuck Noland, un ejecutivo de la empresa multinacional de mensajería FedEx, se ve apartado de su cómoda vida y de su prometida a causa de un accidente de avión por el que queda aislado de la civilización en una remota isla tropical. Único superviviente y solo en la isla, tras cuatro años de subsistencia Chuck aprende todas las técnicas de supervivencia mientras sufre la tortura de la soledad. La solución: arriesgar la vida adentrándose mar adentro."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/7lLJgKnAicAcR5UEuo8xhSMj18w.jpg","de":"https://image.tmdb.org/t/p/w500/4GHtillFPlz9DApJov5P5WMz6r4.jpg","it":"https://image.tmdb.org/t/p/w500/WOTDhrel5R6hDhfDhFhHmExxjO.jpg","fr":"https://image.tmdb.org/t/p/w500/w1bnhSkcT4pa2KQZzRoq0BHBn8T.jpg","es":"https://image.tmdb.org/t/p/w500/BlxcYMoHMXsgf3sXcHAjLOuQ1y.jpg"}'::jsonb WHERE id = 353;
UPDATE public.films SET tmdb_id = 11983, titoli_i18n = '{"en":"Proof of Life","de":"Lebenszeichen - Proof of Life","fr":"L''Échange","es":"Prueba de vida","it":"Rapimento e riscatto"}'::jsonb, trame_i18n = '{"en":"When Peter Bowman, an American engineer working in a South American country, is captured by anti-government forces, the rebels learn his identity and demand $5 million for his safe return. However, his US employer is on the verge of insolvency and will not provide the ransom. Peter''s wife Alice is forced to deal with the matter on her own and she retains the services of freelance professional hostage negotiator Terry Thorne.","de":"In Tecala entführen Mitglieder einer Terrororganisation mehrere Menschen, darunter auch den Ingenieur Peter Bowman. Sie verschleppen ihn in die Berge, während seine sich ebenfalls in Tecala befindliche Frau Alice mit dieser Situation kaum klar kommt. Zu allem Überfluss erfährt Alice auch noch, dass Peter''s Firma von einem anderen Konzern übernommen wird; dieser neue Arbeitgeber will Peter''s neuestes Projekt, den Bau eines Staudamms zu wohltätigen Zwecken, nicht finanzieren und hätte ihn sowieso entlassen. So zieht auch der zuerst zu Rate gezogene, dem Konzern unterstellte Kidnappingexperte Terry Thorne trotz Flehens von Alice` Seite seiner Wege. Alice hat nicht nur Schwierigkeiten das geforderte Lösegeld aufzutreiben, sondern der ortsansässige Vermittler entpuppt sich auch noch als Betrüger. Doch die Rettung naht: Terry entscheidet sich aufgrund seines schlechten Gewissens, die Verhandlungen doch noch zu übernehmen.","fr":"Peter Bowman, ingénieur américain en Amérique latine est kidnappé par les rebelles qui réclament une rançon de 3 milliards de dollars. Ne pouvant compter sur le soutien de l’employeur de son mari, sa femme Alice fait alors appel à Terry Thorne, un ancien membre des services secrets britanniques, expert en \" kidnapping et rançon \", qui a mis ses compétences au service de la compagnie d’assurance Luthan Risk International et sauvé depuis la vie de nombreux otages. Les pourparlers s’engagent dans un climat tendu. Les ravisseurs menacent périodiquement d’exécuter leur prisonnier, qu’ils transfèrent de camp et camp à travers les montagnes et la jungle, lui faisant endurer d’incessantes souffrances physiques et psychologiques. Avec l’aide d’un autre négociateur Dino et un trio de mercenaires parfaitement entraînés, Terry s’engage dans une opération commando à hauts risques pour libérer Peter Bowman.","es":"Mientras construye una presa en Tecala, en el corazón de los Andes, el ingeniero norteamericano Peter Bowman es capturado por fuerzas antigubernamentales durante una incursión en la capital. Cuando los rebeldes descubren su identidad exigen tres millones de dólares de rescate. El problema es que la empresa de Peter, con sede en Houston, está al borde de la bancarrota y ha cancelado la póliza de seguros contra secuestros, así que no dispone del dinero del rescate. Viéndose abandonada por la compañía, la esposa de Peter contrata los servicios de Terry Thorne, un negociador profesional que en los últimos años ha resuelto numerosos casos de secuestro.","it":"Per liberare un importante manager americano, preso in ostaggio da alcuni guerriglieri colombiani, un negoziatore si reca in America Latina. Ed innamorandosi della moglie del prigioniero non fa che complicare la sua missione..."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/yw8x2i3vaHZZzpvqvF75E8q2N6M.jpg","de":"https://image.tmdb.org/t/p/w500/4OiduBCxGNZgl3KBY2fN2uoXhcN.jpg","fr":"https://image.tmdb.org/t/p/w500/r5i4CvMAyOQ0h7A2mfHCg5OZjke.jpg","es":"https://image.tmdb.org/t/p/w500/1YoW4LJpl559Bcs8ToyFRR249R1.jpg","it":"https://image.tmdb.org/t/p/w500/4v6lGQKphnHNz3AYb72M7xfVs0a.jpg"}'::jsonb WHERE id = 354;
UPDATE public.films SET tmdb_id = 9741, titoli_i18n = '{"it":"Unbreakable - Il predestinato","en":"Unbreakable","de":"Unbreakable - Unzerbrechlich","fr":"Incassable","es":"El protegido"}'::jsonb, trame_i18n = '{"it":"David Dunn è l''unico superstite di un disastroso incidente ferroviario; non solo è stato l''unico a salvarsi su 132 passeggeri, ma non ha riportato nemmeno un graffio. Forse soltanto la folle teoria di Elijah Price, un esperto di fumetti che si è messo in contatto con David, può spiegare la sua miracolosa invulnerabilità.","en":"An ordinary man makes an extraordinary discovery when a train accident leaves his fellow passengers dead — and him unscathed. The answer to this mystery could lie with the mysterious Elijah Price, a man who suffers from a disease that renders his bones as fragile as glass.","de":"Ein verheerender Zugunfall vor den Toren von Philadelphia. 131 Tote. Nur ein Mann hat die Katastrophe überlebt – völlig unverletzt, ganz ohne Schrammen. Hatte David Dunn nur Glück? Oder gibt es einen tieferen Grund für sein Überleben? Er hat keine Antworten auf seine Fragen. Doch dann tritt Elijah Price in sein Leben. Er behauptet, David Dunn sei unzerbrechlich und er wüsste, warum …","fr":"Unique survivant d''une catastrophe ferroviaire à la périphérie de Philadelphie, David Dunn, un agent de sécurité à la vie des plus banales, s''interroge sur les raisons qui lui ont permis d''échapper à la mort et de sortir de ce cauchemar sans la moindre égratignure. Quelque temps plus tard, Elijah Price, un étrange personnage féru de bandes dessinées, prend contact avec David. Il souffre d''une fragilité du squelette qui l''oblige à rester au lit, le moindre choc pouvant lui causer une fracture. Price soumet à Dunn une théorie pour le moins surprenante. Cet homme aux os de verre serait inextricablement lié à Dunn qui, lui, n''a jamais contracté la moindre maladie de sa vie...","es":"Philadelphia. Año 1961. Un niño negro acaba de nacer en unos grandes almacenes. Un médico acude a ver como se encuentran tanto la madre como el bebé, y horrorizado le pregunta a la mujer si se le ha caído el niño, ya que tiene tanto los brazos como las piernas fracturadas. Philadelphia. Año 2000. Un hombre llamado David Dunn está en el expreso que va de Nueva York a Philadelphia camino de su casa después de una entrevista de trabajo en la ciudad de los rascacielos. En el tren entabla conversación con una atractiva mujer, pero ésta cree que quiere ligar y se cambia de asiento. Un momento después se produce un dramático accidente."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/4bbHcTViomdM0j7dM0Tm0CYQF1m.jpg","en":"https://image.tmdb.org/t/p/w500/mLuehrGLiK5zFCyRmDDOH6gbfPf.jpg","de":"https://image.tmdb.org/t/p/w500/8sVi8I2GS2b1xVxgXnMobKCjcNs.jpg","fr":"https://image.tmdb.org/t/p/w500/ykeSbrFsTa24jVGW6QDDb6W7SEo.jpg","es":"https://image.tmdb.org/t/p/w500/5SlS9jMrLRB4ZhoWUmLnC5GK7aC.jpg"}'::jsonb WHERE id = 355;
UPDATE public.films SET tmdb_id = 77, titoli_i18n = '{"it":"Memento","en":"Memento","de":"Memento","fr":"Memento","es":"Memento"}'::jsonb, trame_i18n = '{"it":"Leonard Shelby è affetto da una particolare forma di amnesia che lascia intatti i vecchi ricordi ma comporta la perdita della memoria breve. Attraverso un''affannosa ricerca compiuta per mezzo dell''azione e della scrittura, che serve a registrare ciò di cui la percezione non può farsi sicuro garante, Leonard cerca l''assassino della moglie, l''ultimo ricordo che \"non riesce a ricordare di dimenticare\".","en":"Leonard Shelby is tracking down the man who raped and murdered his wife. The difficulty of locating his wife''s killer, however, is compounded by the fact that he suffers from a rare, untreatable form of short-term memory loss. Although he can recall details of life before his accident, Leonard cannot remember what happened fifteen minutes ago, where he''s going, or why.","de":"Leonard Shelby hat bei einem Unfall sein Kurzeitgedächtnis verloren. Zwar weiß er, wer er ist, doch er kann sich keine Namen, keine Begegnungen länger als ein paar Minuten merken. Sein Leben besteht aus einem Berg Notizen, Fotos und Tätowierungen, mit denen sein Körper übersät ist. Der Film beginnt mit einem Mord, festgehalten auf einem Polaroid. Der einzige Hinweis, dass Shelby den Mord begangen hat. Ein Mann ohne Gedächtnis kann von seiner Umwelt leicht missbraucht werden. Shelby versucht aus dem Wirrwarr von Notizen und Fotos das Geschehen zu entschlüsseln. Wenn er vor dem Spiegel steht, sieht er die Tätowierung: Finde den Mörder deiner Frau. Töte ihn.","fr":"Leonard Shelby ne porte que des costumes de grands couturiers et ne se déplace qu’au volant de sa Jaguar. En revanche, il habite dans des motels miteux et règle ses notes avec d’épaisses liasses de billets. Leonard n’a qu’une idée en tête: traquer l’homme qui a violé et assassiné sa femme afin de se venger. Sa recherche du meurtrier est rendue plus difficile par le fait qu’il souffre d’une forme rare et incurable d’amnésie. Bien qu’il puisse se souvenir de détails de son passé, il est incapable de savoir ce qu’il a fait dans le quart d’heure précédent, où il se trouve, où il va et pourquoi. Pour ne jamais perdre son objectif de vue, il a structuré sa vie à l’aide de fiches, de notes, de photos, de tatouages sur le corps. C’est ce qui l’aide à garder contact avec sa mission, à retenir les informations et à garder une trace, une notion de l’espace et du temps.","es":"Leonard Shelby sigue la pista del hombre que violó y asesinó a su mujer. Sin embargo, la dificultad de localizar al asesino de su esposa se ve agravada por el hecho de que padece una forma rara e intratable de pérdida de memoria a corto plazo. Aunque puede recordar detalles de la vida antes de su accidente, Leonard no puede recordar qué ha pasado hace quince minutos, adónde va o por qué."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/eyVdGf0QUnw1SBr1IMvZJj5kk6M.jpg","en":"https://image.tmdb.org/t/p/w500/nzlv62aC0octS5AklAiWpXLX9Z0.jpg","de":"https://image.tmdb.org/t/p/w500/qaXfDrZCdd3wix2XYor5HDDpFrT.jpg","fr":"https://image.tmdb.org/t/p/w500/nK3cJaUWx1iaQ9Cs08JPtZqVzQ6.jpg","es":"https://image.tmdb.org/t/p/w500/fKTPH2WvH8nHTXeBYBVhawtRqtR.jpg"}'::jsonb WHERE id = 356;
UPDATE public.films SET tmdb_id = 2133, titoli_i18n = '{"it":"La tempesta perfetta","es":"La tormenta perfecta","fr":"En pleine tempête","de":"Der Sturm","en":"The Perfect Storm"}'::jsonb, trame_i18n = '{"it":"Gloucester, Massachusetts: un gruppo di pescatori, guidati dal determinato capitano Billy Tyne, dopo un periodo di magra, si dirigono al largo in cerca di maggiore fortuna; l''equipaggio del peschereccio \"Andrea Gail\" naviga oltre le normali rotte di pesca del New England, fino al Flemish Cap, noto per i ricchi banchi di pesce spada. Mentre si trova già in alto mare, la barca riceve l''allarme riguardo ad una tempesta che sta montando alle loro spalle, ma, decisi a non rinunciare alla ricca battuta di pesca ed ai guadagni che con essa ne ricaveranno, ignorano l''avvertimento e procedono nel loro intento. Sfortunatamente la situazione meteoreologica peggiora e l''uragano Grace è in rotta di collisione con altre due aree di bassa pressione, una proveniente da Sud, l''altra da Nord, dalla cui unione scaturisce la cosiddetta tempesta perfetta, un evento che, secondo gli esperti meteo, si verifica molto raramente.","es":"Gloucester (Massachussetts), octubre de 1991. El Andrea Gail es un barco de pesca capitaneado por Billy Tyne, un veterano pescador cuyas últimas salidas se han saldado con paupérrimas capturas. Buscando un golpe de suerte que haga cambiar esta mala racha, se interna en el Flemish Cap, un lugar más allá de las zonas frecuentadas por los pescadores. Lo que ignora es que, a la zona donde faena, se está aproximando la tormenta más aterradora, violenta y destructiva que se pueda concebir.","fr":"Gloucester fut pendant près de quatre siècles le premier port d''Amérique. Mais l''âge d''or est révolu et les temps difficiles obligent les marins à s''aventurer dans des zones dépressionnaires à hauts risques. Aussi, après une saison décevante, Billy Tyne, capitaine de l''Andrea Gail, décide-t-il de tenter sa chance dans la zone du Cap Flemish. Mais les éléments semblent s''acharner contre lui et son équipage: une terrible tempête se lève.","de":"Die Gefahr von Sturm und Wellen auf hoher See ist ihr Alltag, für einen erfolgreichen Fischzug geben sie alles – die Schwertfischer von Gloucester riskieren täglich ihr Leben und sind stolz darauf! Aber als Captain Tyne und seine Crew dieses Mal auslaufen, um den letzten Fang der Saison einzuholen, ahnen sie nicht, welcher Macht sie sich stellen müssen.","en":"In October 1991, a confluence of weather conditions combined to form a killer storm in the North Atlantic. Caught in the storm was the sword-fishing boat Andrea Gail."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/kpQ8X4WAQJ032CYlta81B6OrZcg.jpg","es":"https://image.tmdb.org/t/p/w500/75aRoXgG74D5wbSqEQAYFpFFJ0V.jpg","fr":"https://image.tmdb.org/t/p/w500/nwbMqUD9RsJDwa9XD3n9FhU2R8l.jpg","de":"https://image.tmdb.org/t/p/w500/rTSPQuj7ufQxNhdJxa4m89WsXZt.jpg","en":"https://image.tmdb.org/t/p/w500/vJPoxqgpfFNbGi0HyoNsjFeLCio.jpg"}'::jsonb WHERE id = 357;
UPDATE public.films SET tmdb_id = 1213, titoli_i18n = '{"es":"El talento de Mr. Ripley","it":"Il talento di Mr. Ripley","en":"The Talented Mr. Ripley","de":"Der talentierte Mr. Ripley","fr":"Le Talentueux M. Ripley"}'::jsonb, trame_i18n = '{"es":"Ser joven y despreocupado en medio de un paisaje idílico de la Italia bañada por el sol de finales de los 50: esa es la dolce vita que Tom Ripley (Matt Damon) anhela, y que Dickie Greeleaf (Jude Law) disfruta. Cuando el padre de Dickie, un adinerado constructor de barcos, pide a Tom que traiga de vuelta a casa, a América, a su hijo, éste y su bella y expatriada compañera, Marge Sherwood (Gwyneth Paltrow), nunca hubieran sospechado a qué peligrosos extremos llegaría Ripley con tal de convertir el estilo de vida de la pareja en el suyo propio. Al fin y al cabo, es mejor ser una falsa persona importante que un don nadie auténtico.","it":"1958: Tom Ripley è un giovane americano educato di modesta estrazione. Cede il posto alle signore e ascolta rispettosamente i consigli dei più anziani. Con gli amici è allegro, non ha eguali nell''imitare i personaggi celebri, nel cantare e suonare il piano. Soprattutto tende spesso a mentire pur di mascherare la propria condizione. Un giorno durante un party la grande occasione: un ricco industriale gli chiede, dietro un cospicuo compenso, di riportare negli Stati Uniti suo figlio Dickie, che vive un esilio dorato in Italia. Tom infatti, si è sentito di spacciarsi per un suo compagno di università, avendo indossato un blazer dell''istituto fattosi prestare da un amico per l''occasione. Il giovane entra in una gigantesca avventura, raggiunge quindi Ischia, dove vive Dick Greenleaf; ne diventa amico, e conosce anche la sua bella ragazza, Marge.","en":"Tom Ripley is a calculating young man who believes it''s better to be a fake somebody than a real nobody. Opportunity knocks in the form of a wealthy U.S. shipbuilder who hires Tom to travel to Italy to bring back his playboy son, Dickie. Ripley worms his way into the idyllic lives of Dickie and his girlfriend, plunging into a daring scheme of duplicity, lies and murder.","de":"Der mittellose Tom Ripley erhält den Auftrag, nach Italien zu reisen, um seinen Altersgenossen, den jungen amerikanischen Playboy Dickie Greenleaf zu überreden, in die USA zurückzukehren. Dickie aber bleibt hartnäckig und zieht es vor, weiterhin das Dolce Vita mit seiner reizenden Verlobten Marge zu genießen. Tom beneidet Dickie um das Leben, das er führt. Eines Tages, während einer gemeinsamen Reise zum Jazzfestival von San Remo, kommt es zu einer Rauferei, die fast aus Versehen beginnt, sich aber zum todernsten Kampf ausweitet. Mit viel Talent schlüpft Tom Ripley von nun an in die Haut des getöteten Dickie Greenleaf, eignet sich seinen Lebensstil an und will alles hinter sich lassen. Er genießt sein Leben am Abgrund, denn einige Menschen, die Dickie Greenleaf nahe standen, stellen sich natürlich Fragen: Ist es möglich, dass jemand, selbst wenn er so extrem launisch ist wie Dickie, einfach verschwindet?","fr":"Tom Ripley, jeune homme désargenté mais ambitieux, attire l’attention d’un riche vieillard, Herbert Greenleaf, qui le charge de convaincre son fils Dickie, exilé en Italie, de rentrer aux États‐Unis. Sur place, Tom se laisse fasciner par l’existence insouciante et dorée que mène le jeune oisif. Il adopte ses goûts, imite son comportement, désire sa compagne, et va jusqu’à s’éprendre de Dickie lui‐même. Celui‐ci, dans un premier temps, traite Tom comme un ami mais, très vite, il commence à le trouver encombrant, pour ne pas dire énervant. Un jour, alors qu’ils sont seuls en mer, Tom avoue son amour à Dickie, qui le repousse violemment. Le conflit qui s’ensuit se termine par la mort de Dickie…"}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/idVOOIQGbf22TF58amdYvHBL9Ua.jpg","it":"https://image.tmdb.org/t/p/w500/g7GOx0foFBSdrzzpNGKKeoKwdqA.jpg","en":"https://image.tmdb.org/t/p/w500/6ojHgqtIR41O2qLKa7LFUVj0cZa.jpg","de":"https://image.tmdb.org/t/p/w500/8YlmaxQTBiqVSAbW6Vc8VKPBdYg.jpg","fr":"https://image.tmdb.org/t/p/w500/vU4qTwtFpYF5EDsQwxqn4B83hzk.jpg"}'::jsonb WHERE id = 358;
UPDATE public.films SET tmdb_id = 2668, titoli_i18n = '{"it":"Il mistero di Sleepy Hollow","en":"Sleepy Hollow","fr":"Sleepy Hollow, la légende du cavalier sans tête","de":"Sleepy Hollow","es":"Sleepy Hollow"}'::jsonb, trame_i18n = '{"it":"1799, il poliziotto Ichabod Crane viene inviato nel piccolo paese di Sleepy Hollow per indagare su una serie di omicidi commessi da un presunto cavaliere senza testa.","en":"Skeptical young detective Ichabod Crane gets transferred to the hamlet of Sleepy Hollow, New York, where he is tasked with investigating the decapitations of three people – murders the townsfolk attribute to a legendary specter, The Headless Horseman.","fr":"En 1799, dans une bourgade de la Nouvelle-Angleterre, plusieurs cadavres sont successivement retrouvés décapités. Les têtes ont disparu. Terrifiés, les habitants sont persuadés que ces meurtres sont commis par un étrange et furieux cavalier, dont la rumeur prétend qu''il est lui-même sans tête. Les autorités new-yorkaises envoient alors leur plus fin limier pour éclaircir ce mystère. Ichabod Crane ne croit ni aux légendes, ni aux vengeances post-mortem. Mais, à peine arrivé, il succombe au charme étrange et vénéneux de la belle Katrina Van Tassel.","de":"Der Ermittler Ichabod Crane aus New York ist auf mehrere mysteriöse Todesfälle angesetzt worden, die sich in dem unscheinbaren Städtchen Sleepy Hollow zugetragen haben. Crane ist ein Mann des Verstandes und der Vernunft und gibt sich an die Aufklärung der Verbrechen mit neuartigen kriminalistischen Methoden. Doch schon bald muss er feststellen, dass in Sleepy Hollow der Wissenschaft schnell Grenzen gesetzt sind; spätestens dann, wenn sich Ichabod Crane dem leibhaftigen Hessen ohne Kopf persönlich gegenüber stehen sieht.","es":"Durante la Guerra de Secesión Americana, un policía de Nueva York que utiliza avanzados métodos de investigación es enviado al pueblo de Sleepy Hollow para descubrir qué hay de verdad en la leyenda de un jinete sin cabeza que aterroriza a los habitantes del lugar. Una vez allí adopta la identidad de un profesor de escuela y se enamora de Katrina, que mantiene relaciones con uno de los hombres más conocidos del pueblo. Realidad y ficción se darán la mano en el momento menos pensado."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/eX61VBYV1mh4AARjogZ4WIZeGaQ.jpg","en":"https://image.tmdb.org/t/p/w500/1GuK965FLJxqUw9fd1pmvjbFAlv.jpg","fr":"https://image.tmdb.org/t/p/w500/gBVKVccVx7mwMeAF8VChefNpXl3.jpg","de":"https://image.tmdb.org/t/p/w500/5r5qM47DQP2BGatpMzt8Jyuk8Ta.jpg","es":"https://image.tmdb.org/t/p/w500/sEsDyXI4LTjS0RmlUehHUGI7Xny.jpg"}'::jsonb WHERE id = 359;
UPDATE public.films SET tmdb_id = 745, titoli_i18n = '{"it":"The Sixth Sense - Il sesto senso","en":"The Sixth Sense","es":"El sexto sentido","fr":"Sixième Sens","de":"The Sixth Sense"}'::jsonb, trame_i18n = '{"it":"Un famoso psichiatra infantile in un momento difficile della propria vita fa amicizia con un bambino che sembra avere dei problemi. Presosi a cuore il caso, l''uomo riesce a entrarvi in confidenza e a scoprire che è disturbato da visioni: il piccolo asserisce infatti di poter vedere la gente morta.","en":"Following an unexpected tragedy, child psychologist Malcolm Crowe meets a nine year old boy named Cole Sear, who is hiding a dark secret.","es":"El Dr. Malcom Crowe es un conocido psicólogo infantil obsesionado con el doloroso recuerdo de un joven paciente desequilibrado al que fue incapaz de ayudar. Cole Sear es un aterrorizado y confuso niño de ocho años que necesita tratamiento, y Crowe ve la oportunidad de redimirse haciendo todo lo posible por ayudarle. Sin embargo, el psicólogo infantil no está preparado para conocer la terrible verdad acerca del don sobrenatural de su paciente: recibe visitas no deseadas de espíritus atormentados.","fr":"Cole Sear, garçonnet de huit ans est hanté par un terrible secret. Son imaginaire est visité par des esprits menaçants. Trop jeune pour comprendre le pourquoi de ces apparitions et traumatisé par ces pouvoirs paranormaux, Cole s''enferme dans une peur maladive et ne veut révéler à personne la cause de son enfermement, à l''exception d''un psychologue pour enfants. La recherche d''une explication rationnelle guidera l''enfant et le thérapeute vers une vérité foudroyante et inexplicable.","de":"Der Kinderpsychologe Dr. Malcolm Crowe feiert mit seiner Frau eine für ihn bedeutsame Auszeichnung. An diesem Abend wird er von Vincent Grey überrascht, einem ehemaligen Patienten, dem Crowe nicht helfen konnte. Sichtlich verzweifelt schießt er auf Dr. Crowe und begeht daraufhin Selbstmord. Im darauf folgenden Jahr betreut Dr. Crowe den neunjährigen Cole. Er erinnert ihn an seinen früheren Patienten Grey. Der Junge scheint von großen Ängsten geplagt, die er niemandem anvertraut. Von seinen Klassenkameraden wird er mit „Psycho“ angesprochen und gemieden. Sogar sein Lehrer bezeichnet ihn nach einem Streit so. Coles Mutter ist verzweifelt, und Dr. Crowe scheint dem Jungen nicht helfen zu können. Nach und nach gewinnt er schließlich das Vertrauen des Jungen; Cole verrät ihm sein Geheimnis: „Ich sehe tote Menschen. Die sind wütend. Die wissen nicht, dass sie tot sind.“ Zunächst glaubt Dr. Crowe ihm nicht."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/1Dth4Jbh7FzPguUIddmK43deTCy.jpg","en":"https://image.tmdb.org/t/p/w500/vOyfUXNFSnaTk7Vk5AjpsKTUWsu.jpg","es":"https://image.tmdb.org/t/p/w500/pvjph7FouToPBY3PhTvTyOYoJDX.jpg","fr":"https://image.tmdb.org/t/p/w500/7s3ekiDpic8NxDjwdLdOYDIX8Pe.jpg","de":"https://image.tmdb.org/t/p/w500/mItbnCncatYHCwV2w7gXUw3xmxB.jpg"}'::jsonb WHERE id = 360;
UPDATE public.films SET tmdb_id = 30497, titoli_i18n = '{"it":"Non aprite quella porta","es":"La matanza de Texas","fr":"Massacre à la tronçonneuse","en":"The Texas Chain Saw Massacre","de":"Blutgericht in Texas"}'::jsonb, trame_i18n = '{"it":"Mentre è in corso una serie di misteriose razzie nei cimiteri della zona, Sally (Marilyn Burns), assieme al fratello paraplegico Franklin (Paul A. Partain) e a un gruppo di amici, parte per una vacanza in camper alla vecchia casa abbandonata del nonno. Prima di arrivarci, i ragazzi danno un passaggio a uno strano autostoppista con cui hanno un alterco prima di sbatterlo fuori. Dopo aver dato un’occhiata alla casa, i ragazzi si separano e due di loro, Pam (Teri McMinn) e Kirk (William Vail), si imbattono in un’altra casa apparentemente abbandonata che vogliono visitare. Ma Kirk viene ucciso e Pam viene trascinata dentro la casa e impalata in un gancio da macellaio da un essere gigantesco con una maschera di cuoio in faccia (Gunnar Hansen). E gli altri dovranno cercare di salvarsi lottando contro una famiglia di cannibali.","es":"Cinco adolescentes visitan la tumba, supuestamente profanada, del abuelo de uno de ellos. Cuando llegan al lugar, donde hay un siniestro matadero, toman una deliciosa carne en una gasolinera. A partir de ese momento, los jóvenes vivirán la peor pesadilla de toda su vida.","fr":"Au fin fond du Texas, des habitants font une découverte macabre : leur cimetière vient d''être profané et les cadavres exposés sous forme de trophées. Pendant ce temps, cinq amis traversent la région à bord d''un minibus. Ils croisent en chemin la route d''un auto-stoppeur et décident de le prendre à bord. Mais lorsque les jeunes gens s''aperçoivent que l''individu a un comportement inquiétant et menaçant, ils finissent par s''en débarrasser. Bientôt à court d''essence, le groupe décide d''aller visiter une vieille maison abandonnée, appartenant aux grands-parents de deux d''entre eux. Chacun leur tour, les cinq amis vont être attirés par la maison voisine. La rencontre avec ses étranges habitants va leur être fatale…","en":"Five friends head out to rural Texas to visit the grave of a grandfather. On the way, they stumble across what appears to be a deserted house, only to discover something sinister within. Something armed with a chainsaw.","de":"Eine Gruppe junger Leute unternimmt einen Ausflug in die texanische Prärie, während der Wetterbericht von atmosphärischen Störungen kündet, welche nicht ohne Folgen auf die menschliche Psyche bleiben sollen. Als die Kids an einer scheinbar verlassenen Villa rasten, werden sie nacheinander von Mitgliedern einer in der Gegend ansässigen Metzgerfamilie attackiert, entführt oder ermordet. Lediglich einer der fünf Reisenden gelingt in letzter Sekunde die Flucht."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/8giqGVVX5UaQbmXM7ZEpGR9Xp8.jpg","es":"https://image.tmdb.org/t/p/w500/dDuWWq9VpBK0PFCDytlBpZhV6ca.jpg","fr":"https://image.tmdb.org/t/p/w500/u61noSAr4IGVostCNbVApRXC4FZ.jpg","en":"https://image.tmdb.org/t/p/w500/mpgkRPH1GNkMCgdPk2OMyHzAks7.jpg","de":"https://image.tmdb.org/t/p/w500/8yvocJK9DVChrdupZ7c4w87aP2U.jpg"}'::jsonb WHERE id = 361;
UPDATE public.films SET tmdb_id = 43539, titoli_i18n = '{"en":"The Next Three Days","de":"72 Stunden - The Next Three Days","it":"The Next Three Days","fr":"Les Trois Prochains Jours","es":"Los próximos tres días"}'::jsonb, trame_i18n = '{"en":"Life seems perfect for John Brennan until his wife, Lara, is arrested for a murder she says she didn’t commit. Three years into her sentence, John is struggling to hold his family together, raising their son and teaching at college while he pursues every means available to prove her innocence. With the rejection of their final appeal, Lara becomes suicidal and John decides there is only one possible, bearable solution: to break his wife out of prison.","de":"Lara Brennan, die Frau von College-Professor John Brennan wird aus heiterem Himmel wegen Mordes verhaftet. Der schockierten Familienmutter wird vorgeworfen ihre Chefin ermordet zu haben. Alle Indizien sprechen eindeutig gegen sie, doch John glaubt an seine Frau. Obwohl er alles daran setzt ihre Unschuld zu beweisen, wird Lara vor Gericht schuldig gesprochen. Gemeinsam mit einem ehemaligen Gefängnisinsassen entwickelt John den scheinbar perfekten Ausbruchsplan. Dann soll seine Ehefrau jedoch in ein anderes Gefängnis verlegt werden – John bleiben nur noch 72 Stunden um Lara zu befreien.","it":"John Brennan, la moglie Lara e il loro piccolo Luke fanno colazione con amore e con gioia, quando la polizia irrompe con un mandato d''arresto per omicidio a carico della donna. Per tre anni, il marito le fa visita quotidianamente, certo che sia tutto un abbaglio, che la giustizia le ridarà la sua casa e la sua vita. Persino più certo della moglie, che lei quell''atto non l''abbia commesso, che non avrebbe mai potuto. Quando anche l''ultimo appello viene respinto e Lara tenta il sudicio, John, tranquillo insegnante di letteratura e padre di famiglia, decide che se non sarà la legge a fare uscire sua moglie di prigione, sarà lui.","fr":"John Brennan, sa femme Lara et leur enfant vivent un bonheur sans nuage, jusqu''au jour où elle est arrêtée pour un meurtre qu''elle nie avoir commis. Trois ans après sa condamnation, John se débat pour préserver l''unité de sa famille, élevant seul leur fils, tout en se démenant pour prouver l''innocence de sa femme. Lorsque leur dernière tentative d''appel échoue, Lara s''enfonce dans la dépression au risque de mettre fin à ses jours. John n''a plus qu''une seule solution pour sauver sa femme : la faire évader. Malgré son inexpérience, John plonge dans les eaux troubles et dangereuses de l''illégalité et se lance dans l''opération de la dernière chance.","es":"La vida es perfecta para el profesor John Brennan hasta que su esposa, Laura, es acusada de un asesinato que no ha cometido. Durante tres largos años, John se ve condenado a sacar adelante a su hijo sin ninguna ayuda, a seguir dando clase en el colegio como si nada hubiera ocurrido y a reunir las pruebas necesarias para probar la inocencia de Laura.Pero su esposa está tan desesperada que intenta suicidarse. Después de esta traumática experiencia, a John no le queda otro remedio que idear un plan para ayudarle a escapar de la cárcel. Está dispuesto a dejar de ser quien es con tal de salvar a la mujer que ama."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/wBaRZ3aHa7qoYTSY0ONbXrXYk4B.jpg","de":"https://image.tmdb.org/t/p/w500/gmzSUgycQcTcxLjuDSGD0Pnrnz4.jpg","it":"https://image.tmdb.org/t/p/w500/nCl2I0yGwKop0qBIpwXWJA7zQPP.jpg","fr":"https://image.tmdb.org/t/p/w500/iGR71fLxh2fQpgsPN2WDtUEYYZS.jpg","es":"https://image.tmdb.org/t/p/w500/t9hzEgM3KJRFLHwEBbz4YZjpV6y.jpg"}'::jsonb WHERE id = 362;
UPDATE public.films SET tmdb_id = 696506, titoli_i18n = '{"it":"Mickey 17","en":"Mickey 17","fr":"Mickey 17","es":"Mickey 17","de":"Mickey 17"}'::jsonb, trame_i18n = '{"it":"Mickey 17 è un \"sacrificabile\", un impiegato usa e getta, in una spedizione umana inviata a colonizzare il mondo ghiacciato Niflheim. Dopo la morte di un''iterazione, un nuovo corpo viene rigenerato con la maggior parte dei suoi ricordi intatti.","en":"Unlikely hero Mickey Barnes finds himself in the extraordinary circumstance of working for an employer who demands the ultimate commitment to the job… to die, for a living.","fr":"En 2054, afin de fuir son cruel créancier, le naïf Mickey se porte volontaire pour une mission de colonisation sur Niflheim, une planète de glace. Devenu sans trop le savoir un ouvrier \"consommable\", il est régénéré chaque fois qu''il meurt lors des missions les plus dangereuses imposées par l''ex-sénateur Kenneth Marshall, dirigeant mégalomane de la colonie. Après quatre ans, Mickey en est à sa 17e incarnation. Grièvement blessé, il est laissé pour mort par son coéquipier au fond d''une crevasse. Mais contre toute attente, il est sauvé par la mère des créatures qui habitent Niflheim. Pendant son absence, un Mickey 18 est créé.","es":"Mickey 17, un miembro de la tripulación ''expendable'' (prescindible) enviado a un planeta helado para colonizarlo, se niega a dejar que su clon de reemplazo, Mickey 18, tome su lugar... Adaptación del libro original de Edward Ashton.","de":"Mickey Barnes, der unvermutete Held der Geschichte, befindet sich in einer außergewöhnlichen Situation, denn sein Arbeitgeber verlangt von ihm die ultimative Hingabe an den Job: Mickey verdient sich seinen Lebensunterhalt, indem er stirbt ..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/2JQBZs01ahsOiANQ7Fs8MN9zBY4.jpg","en":"https://image.tmdb.org/t/p/w500/edKpE9B5qN3e559OuMCLZdW1iBZ.jpg","fr":"https://image.tmdb.org/t/p/w500/on60ASUpGg1xfiFucuMCv9wVqtq.jpg","es":"https://image.tmdb.org/t/p/w500/iOKu6Hf5atv3DuXBS0jBF3OYYdu.jpg","de":"https://image.tmdb.org/t/p/w500/belnJtEppRZPMSvbMPAUWDm9ps7.jpg"}'::jsonb WHERE id = 363;
UPDATE public.films SET tmdb_id = 1375441, titoli_i18n = '{"it":"Primetime","es":"Primetime","en":"Primetime","fr":"Primetime","de":"Primetime"}'::jsonb, trame_i18n = '{"it":"Nel 2006 il giornalista Chris Hansen si prepara a fare la storia della televisione con To Catch a Predator, il controverso format che, attraverso operazioni sotto copertura e telecamere nascoste, smaschera in diretta tv predatori sessuali colti sul fatto. Mentre il programma diventa un fenomeno nazionale e il suo conduttore un’icona del pubblico, il confine tra informazione, giustizia e spettacolo si fa sempre più ambiguo e il cortocircuito fra cronaca, intrattenimento e voyeurismo televisivo sempre più insostenibile.","es":"En 2006, Chris Hansen, presentador de *To Catch a Predator*, se propone hacer historia en la televisión.","en":"In 2006, To Catch a Predator host Chris Hansen sets out to make television history. When a high stakes operation goes fatally wrong, his veneered dream of fame curdles into a nightmare of performative justice.","fr":"Chris Hansen présente l''émission policière « To Catch a Predator ». Diffusée sur NBC Dateline, cette émission tente de filmer des pédophiles présumés avec l''aide des forces de l''ordre et d''une équipe d''appâts se faisant passer pour des mineurs sur Internet. En 2006, Hansen est sur le point de révolutionner le monde de la télévision.","de":"Im Jahr 2006 macht sich Chris Hansen, der Moderator von „To Catch a Predator“, daran, Fernsehgeschichte zu schreiben."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/sqArsDFYFryd5iKuoxLvr4y5NZv.jpg","es":"https://image.tmdb.org/t/p/w500/lmrulvLbmaejTix1YaMxo1oGhH1.jpg","en":"https://image.tmdb.org/t/p/w500/lmrulvLbmaejTix1YaMxo1oGhH1.jpg","fr":"https://image.tmdb.org/t/p/w500/8W69bkus937B2OzJapRmw2uY42s.jpg","de":"https://image.tmdb.org/t/p/w500/iVtbZFH8QwcPB3U1xYDi9s9laOn.jpg"}'::jsonb WHERE id = 364;
UPDATE public.films SET tmdb_id = 856, titoli_i18n = '{"en":"Who Framed Roger Rabbit","fr":"Qui veut la peau de Roger Rabbit ?","de":"Falsches Spiel mit Roger Rabbit","es":"¿Quién engañó a Roger Rabbit?","it":"Chi ha incastrato Roger Rabbit"}'::jsonb, trame_i18n = '{"en":"Toon star Roger is worried that his wife Jessica is playing pattycake with someone else, so the studio hires detective Eddie Valiant to snoop on her. But the stakes are quickly raised when Marvin Acme is found dead and Roger is the prime suspect.","fr":"En 1947, à Hollywood, les grandes vedettes du cinéma partagent l''affiche avec les Toons, personnages animés. Roger Rabbit est amoureux transi de sa sublime femme Jessica, et son amour l''empêche de travailler correctement. Le producteur R.K. Maroon, le patron des Studios, tente de le ramener sur le droit chemin et engage Eddie Valiant, un détective privé humain et alcoolique, pour prouver à Roger Rabbit l''infidélité de Jessica. Des photos compromettantes sont prises et le présumé amant est retrouvé assassiné. Roger Rabbit est accusé du meurtre et recherché par l''ignoble juge Demort qui voue une haine féroce aux Toons.","de":"Roger Rabbit, einer der größten Stars Toontowns, wird gesucht: Er soll Marvin Acme ermordet haben, weil der angeblich ein Verhältnis mit Rogers Frau Jessica hatte. Richter Doom will ihn in seine berüchtigte “Suppe” stecken, das Einzige, was einen Toon töten kann. Roger fällt nichts anderes ein, als ausgerechnet den heruntergekommenen Privatdetektiv Eddie Valliant um Hilfe zu bitten, dessen Bruder von einem Toon getötet wurde. Seither hasst Valliant alle Zeichentrickfiguren, lässt sich aber doch dazu überreden, diesen Job anzunehmen.","es":"Hollywood, 1947. Eddie Valiant, un detective de poca monta, ha sido contratado para encontrar pruebas que demuestren que Marvin Acme, magnate del negocio de los artículos de broma y dueño de Toontown, está rondando a Jessica Rabbit, mujer fatal y esposa de la superestrella del Marron Cartoon, Roger Rabbit. Cuando Acme aparece asesinado, todas las pruebas apuntan a Roger, y el siniestro y ambicioso Juez Doom está decidido a condenarlo como sea. Roger suplica a Valiant que le ayude a encontrar al verdadero culpable, pero el asunto se irá complicando a medida que Eddie va descubriendo, escándalo tras escándalo, que la propia existencia de Toontown corre peligro.","it":"In uno studio cinematografico due cartoon stanno recitando una scena: Baby Herman, un poppante tutto pepe e pieno di trovate, e il suo baby-sitter, il coniglio Roger, che per togliere il piccolo da situazioni rischiose si mette in grossi guai. Nonostante l''impegno Roger non soddisfa il regista con la sua interpretazione: egli infatti è assillato da preoccupazioni familiari, teme che la sua bellissima moglie Jessica lo tradisca col padrone di Cartoonia, Marvin Acme. Viene incaricato di trovare le prove del tradimento il detective privato Eddie Valiant, sempre senza soldi e mezzo alcolizzato da quando suo fratello Teddy fu ucciso cinque anni prima da un cartoon. Eddie riesce a trovare ciò che cercava e per Roger è la disperazione: questi lascia l''ufficio del produttore Mr. Maroon in preda ad una nera desolazione e nulla può fare per consolarlo Valiant che ne ha compassione. La polizia trova il cadavere di Acme e dà subito la colpa a Roger..."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/lYfRc57Kx9VgLZ48iulu0HKnM15.jpg","fr":"https://image.tmdb.org/t/p/w500/fJ1wJ9avrGj9VViC94CcRKL8N7w.jpg","de":"https://image.tmdb.org/t/p/w500/cn0VQ9vKhdk6fr45HyOIptJOPwt.jpg","es":"https://image.tmdb.org/t/p/w500/nXqhkF0tJ1K2fglVMgimVZd5kMH.jpg","it":"https://image.tmdb.org/t/p/w500/5KZOkoKzj5wfJOGdWZYy4O4LLY2.jpg"}'::jsonb WHERE id = 365;
UPDATE public.films SET tmdb_id = 274, titoli_i18n = '{"es":"El silencio de los corderos","it":"Il silenzio degli innocenti","en":"The Silence of the Lambs","fr":"Le Silence des agneaux","de":"Das Schweigen der Lämmer"}'::jsonb, trame_i18n = '{"es":"Clarice Starling, del FBI, se aventura a una prisión de máxima seguridad para analizar el cerebro enfermo de Hannibal Lecter, un psiquiatra convertido en caníbal.","it":"Dal romanzo omonimo di Thomas Harris. Una giovane recluta dell''FBI è incaricata di far visita in carcere a Hannibal Lecter, psichiatra pluriomicida, per ottenere informazioni su un assassino psicopatico che ha ucciso e scuoiato cinque donne.","en":"Clarice Starling is a top student at the FBI''s training academy.  Jack Crawford wants Clarice to interview Dr. Hannibal Lecter, a brilliant psychiatrist who is also a violent psychopath, serving life behind bars for various acts of murder and cannibalism.  Crawford believes that Lecter may have insight into a case and that Starling, as an attractive young woman, may be just the bait to draw him out.","fr":"Un psychopathe connu sous le nom de Buffalo Bill sème la terreur dans le Middle West en kidnappant et en assassinant de jeunes femmes. Clarice Starling, une jeune stagiaire du FBI, est chargée d’interroger l’ex‐psychiatre Hannibal Lecter. Psychopathe redoutablement intelligent et porté sur le cannibalisme, Lecter est capable de lui fournir des informations concernant Buffalo Bill ainsi que son portrait psychologique. Mais il n’accepte de l’aider qu’en échange d’informations sur la vie privée de la jeune femme. Entre eux s’établit un lien de fascination et de répulsion.","de":"Clarice Starling, Auszubildende beim FBI, bekommt von einem ihrer Lehrer den Auftrag, sich im Gefängnis mit Dr. Hannibal Lecter, einem Massenmörder und Psychiater, zu befassen. Durch ihre Unbefangenheit hoffen sie, daß Lecter ihnen bei der Suche nach einem anderen Serienkiller hilft, aber es ist nicht leicht, an Lecter heranzukommen."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/8FdQQ3cUCs9goEOr1qUFaHackoJ.jpg","it":"https://image.tmdb.org/t/p/w500/jCS4Iw1bGGhSEdzFeUq8CX8UoiC.jpg","en":"https://image.tmdb.org/t/p/w500/uS9m8OBk1A8eM9I042bx8XXpqAq.jpg","fr":"https://image.tmdb.org/t/p/w500/sSQDxwm4r28YpJSQVyVOtpYVs0E.jpg","de":"https://image.tmdb.org/t/p/w500/yyW5OFz5r8S81R2Afj9ILiEa70w.jpg"}'::jsonb WHERE id = 366;
UPDATE public.films SET tmdb_id = 1292695, titoli_i18n = '{"it":"Ti uccideranno","en":"They Will Kill You","es":"Te van a matar","fr":"They Will Kill You","de":"They Will Kill You"}'::jsonb, trame_i18n = '{"it":"\"Ti uccideranno\" porta sul grande schermo un horror-action-comedy ad alto tasso di adrenalina e intriso di sangue, in cui una giovane donna deve sopravvivere alla notte al Virgil, dove è stata da poco assunta come domestica, senza sapere che quell’edificio nasconde un passato inquietante fatto di inspiegabili sparizioni.  Ne nasce uno scontro cinematografico audace e senza freni, tra uccisioni efferate e un umorismo nerissimo.","en":"A woman answers a help wanted ad to be a housekeeper in a mysterious New York City high-rise, unaware that she is entering a community that has seen a number of disappearances over the years and may be under the grip of a Satanic cult.","es":"Una mujer acepta un trabajo como ama de llaves en un rascacielos de Nueva York, sin conocer el historial de desapariciones del edificio. Pronto se da cuenta de que la comunidad está rodeada de misterio.","fr":"Une jeune femme doit survivre toute une nuit, enfermée dans le mystérieux et sordide repaire d''une secte démoniaque, et tout faire pour ne pas devenir leur prochain sacrifice. Une lutte acharnée, des combats saisissants et un humour profondément noir vous attendent.","de":"Eine Frau antwortet auf eine Stellenanzeige als Haushälterin in einem mysteriösen Hochhaus in New York City, ohne zu ahnen, dass sie damit in eine Gemeinschaft eintritt, in der es im Laufe der Jahre zu einer Reihe von Verschwinden gekommen ist und die möglicherweise unter dem Einfluss einer satanistischen Sekte steht."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/jCe5etBmMuTf2TXgYvv0EDUj4BZ.jpg","en":"https://image.tmdb.org/t/p/w500/6oI4oQKTWMVUlr8Ivqydp28Ruu6.jpg","es":"https://image.tmdb.org/t/p/w500/9dEn8a12dqkQw48zxQhPcpQ7D5W.jpg","fr":"https://image.tmdb.org/t/p/w500/gyc0CMzFS91ZtXyhPcw7mE60v6Y.jpg","de":"https://image.tmdb.org/t/p/w500/ywrFHscZl86wM0a32SR8PniIf9B.jpg"}'::jsonb WHERE id = 367;
UPDATE public.films SET tmdb_id = 1242898, titoli_i18n = '{"en":"Predator: Badlands","de":"Predator: Badlands","es":"Predator: Badlands","fr":"Predator : Badlands","it":"Predator: Badlands"}'::jsonb, trame_i18n = '{"en":"Cast out from his clan, a young Predator finds an unlikely ally in a damaged android and embarks on a treacherous journey in search of the ultimate adversary.","de":"Ein noch junger Predator namens Dek wird von seinem eigenen Clan verstoßen. Die anderen sehen in ihm keinen starken, furchtlosen Krieger heranwachsen. Damit ist er für die Gemeinschaft wertlos, da niemand glaubt, dass Dek eine glorreiche Zukunft bei der Jagd bevorsteht. Fortan muss er also alleine auf einem abgelegenen Planeten klarkommen. Doch dort bleibt er nicht lange alleine. Dek stößt auf Thia mit der er eine unverhoffte Verbündete findet. Von nun an gehen die beiden also gemeinsam auf die Jagd und treffen einen weiteren Weggefährten. Zu dritt müssen sie sich schließlich auch einer scheinbar übermächtigen Bedrohung stellen. Im Laufe ihres gemeinsamen Abenteuers werden sie beste Freunde und lernen, einander auch in ausweglosen Situationen zu vertrauen. Dek wächst dabei als Jäger über sich hinaus und lernt, richtig gut zu jagen.","es":"Un joven Predator rechazado por su clan encuentra un aliado inesperado en Thia y emprende un peligroso viaje en busca del adversario definitivo.","fr":"Jugé trop faible et indigne par son père, chef de la tribu des Yautja, Dek est sur le point de se faire exécuter par son frère Kwei. Mais au dernier moment, celui-ci préfère se sacrifier pour favoriser sa fuite. Décidé à prouver son courage, le jeune paria se rend sur la planète Genna pour y capturer le Kalisk, un monstre réputé invincible. Confronté à une nature hostile et imprévisible, le guerrier inexpérimenté doit sa survie à Thia, une androïde privée de la partie inférieure de son corps depuis son affrontement avec le Kalisk. Avec l''aide de celle-ci, Dek amorce sa traque de la terrible créature, convoitée par des scientifiques pour ses formidables dons de régénération.","it":"Nel futuro, su un pianeta remoto, un giovane Predatore, emarginato dal suo clan, trova un alleato improbabile in Thia e intraprende un viaggio pericoloso alla ricerca del nemico supremo."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/pHpq9yNUIo6aDoCXEBzjSolywgz.jpg","de":"https://image.tmdb.org/t/p/w500/lxw9cD6g5Ccfml1PthmO6YT2aMp.jpg","es":"https://image.tmdb.org/t/p/w500/8nCEJ5hFJt0h8FhXafHGhEhT8d7.jpg","fr":"https://image.tmdb.org/t/p/w500/empQGO0pCVTndCpihyVpNfaLebl.jpg","it":"https://image.tmdb.org/t/p/w500/zn14Felr0VlFg6A86IUx4PDt2E7.jpg"}'::jsonb WHERE id = 368;
UPDATE public.films SET tmdb_id = 972533, titoli_i18n = '{"en":"Last Breath","it":"Last Breath","es":"Sin oxígeno","de":"Last Breath","fr":"Last Breath"}'::jsonb, trame_i18n = '{"en":"Seasoned deep-sea divers battle the raging elements to rescue their crewmate trapped hundreds of feet below the ocean''s surface.","it":"Last Breath segue un esperto sommozzatore delle profondità marine mentre combatte gli elementi furiosi per salvare il suo compagno di equipaggio intrappolato a centinaia di metri sotto la superficie dell''oceano.","es":"La increíble historia real de Chris Lemons (Finn Cole), un buzo profesional que, tras un extraño accidente, queda atrapado en el fondo del Mar del Norte. Con tan solo 10 minutos de oxígeno de emergencia y a más de media hora de cualquier esperanza de rescate, esta es la lucha imposible de un hombre por sobrevivir a 90 metros de profundidad. Mientras tanto, en la superficie, sus compañeros Duncan (Woody Harrelson) y Dave (Simu Liu) lucharán contra una feroz tormenta y harán todo lo posible por rescatarlo con vida.","de":"Erfahrene Tiefseetaucher kämpfen gegen die tobenden Elemente, um ihren Mannschaftskameraden zu retten, der Hunderte von Metern unter der Meeresoberfläche gefangen ist.","fr":"Lorsqu''un plongeur reste piégé à des centaines de mètres sous la surface de l''océan, une course contre la montre s''amorce afin de le ramener à la surface."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/uB8yTnF6YLIIVKuRJAK8LNk8C6w.jpg","it":"https://image.tmdb.org/t/p/w500/mKP5zZ8NjUf68D0qte9LyIA0C6k.jpg","es":"https://image.tmdb.org/t/p/w500/bgcf7lci3pwWSMgHNBlqDDQbyJJ.jpg","de":"https://image.tmdb.org/t/p/w500/7qk3yuoVqL52miBRL6iKNWGzi6c.jpg","fr":"https://image.tmdb.org/t/p/w500/dhwOAQ9gSdiKeuVn8XT9tqok8mO.jpg"}'::jsonb WHERE id = 369;
UPDATE public.films SET tmdb_id = 1083968, titoli_i18n = '{"en":"Locked","it":"Locked - In trappola","fr":"Piégé","de":"Locked","es":"Blindado"}'::jsonb, trame_i18n = '{"en":"When Eddie breaks into a luxury SUV, he steps into a deadly trap set by William, a self-proclaimed vigilante delivering his own brand of twisted justice. With no means of escape, Eddie must fight to survive in a ride where escape is an illusion, survival is a nightmare, and justice shifts into high gear.","it":"Un ladruncolo riesce a forzare la serratura di un SUV di lusso, ma quando è dentro all''abitacolo si rende conto di essere incappato in una trappola complessa e mortale, tesagli da una figura misteriosa.","fr":"Les ennuis commencent pour Eddie, un jeune voleur, lorsqu''il s''introduit dans un SUV de luxe. Il découvre rapidement qu''il est pris au piège dans un jeu mortel orchestré par William, un justicier autoproclamé. Alors qu''Eddie tente désespérément de s''échapper, il se rend compte que sa situation est bien plus dangereuse qu''il ne l''imaginait...","de":"Als Eddie in einen luxuriösen Geländewagen einbricht, tappt er in eine tödliche Falle, die ihm William gestellt hat, ein Selbstjustizler, der seine eigene Art von verdrehter Gerechtigkeit ausübt. Ohne Fluchtmöglichkeit muss Eddie um sein Überleben kämpfen - in einer Welt, in der die Flucht eine Illusion, das Überleben ein Albtraum und die Gerechtigkeit ein hohes Tempo hat.","es":"Un ladrón irrumpe en un todoterreno de lujo y se da cuenta de que ha tropezado con una trampa compleja y mortal tendida por una misteriosa figura."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/hhkiqXpfpufwxVrdSftzeKIANl3.jpg","it":"https://image.tmdb.org/t/p/w500/nn2TyHzFpOszdqgAQuAmS2WSxYe.jpg","fr":"https://image.tmdb.org/t/p/w500/w620DtlHR14olwvXiVdQK0TGN1D.jpg","de":"https://image.tmdb.org/t/p/w500/ql35bug5dlqT3aMlxoPKhuYyUs1.jpg","es":"https://image.tmdb.org/t/p/w500/xIyIiJCss0HpychoUKFQYKiZiBH.jpg"}'::jsonb WHERE id = 370;
UPDATE public.films SET tmdb_id = 1137350, titoli_i18n = '{"it":"La trama fenicia","en":"The Phoenician Scheme","es":"La trama fenicia","fr":"The Phoenician Scheme","de":"Der phönizische Meisterstreich"}'::jsonb, trame_i18n = '{"it":"Sopravvissuto ad un incidente aereo per la sesta volta in tutta la sua vita, il magnate internazionale Zsa-zsa Korda tenta di ricucire i rapporti con sua figlia Liesl, nel frattempo diventata suora, che non vede da troppo tempo.","en":"Wealthy businessman Zsa-zsa Korda appoints his only daughter, a nun, as sole heir to his estate. As Korda embarks on a new enterprise, they soon become the target of scheming tycoons, foreign terrorists, and determined assassins.","es":"El magnate Zsa-zsa Korda es un rico empresario europeo que se ve envuelto en una trama de espionaje junto a su hija Liesl, una monja con la que mantiene una relación difícil y a la quiere dejar el negocio familiar.","fr":"Le riche homme d''affaires Zsa-zsa Korda désigne sa fille unique, une religieuse, comme seule héritière de son patrimoine. Alors que les Korda se lancent dans une nouvelle entreprise, ils deviennent rapidement la cible de magnats intrigants, de terroristes étrangers et d''assassins déterminés.","de":"Düstere Spionagegeschichte über eine angespannte Vater-Tochter-Beziehung in einem Familienunternehmen. Die Wendungen drehen sich um Verrat und moralisch graue Entscheidungen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/90yhkAmFHypazSdnR0LXSf5e6h0.jpg","en":"https://image.tmdb.org/t/p/w500/iXxIUVqpQAlyy98UjUlzjkMYuj6.jpg","es":"https://image.tmdb.org/t/p/w500/ts8IjoVDPH4wTlhZOm8owNlPhs4.jpg","fr":"https://image.tmdb.org/t/p/w500/aWucFFSKSo5k6dKn4WQXCQiu6MP.jpg","de":"https://image.tmdb.org/t/p/w500/9EhvxOvEUGTzHUJEnF2A3dWXB46.jpg"}'::jsonb WHERE id = 371;
UPDATE public.films SET tmdb_id = 1035259, titoli_i18n = '{"it":"Una pallottola spuntata","en":"The Naked Gun","es":"Agárralo como puedas","fr":"Y a-t-il un flic pour sauver le monde ?","de":"Die nackte Kanone"}'::jsonb, trame_i18n = '{"it":"Solo un uomo ha le pall....ottole giuste per guidare la squadra di polizia e salvare il mondo. Il tenente Frank Drebin Jr. (Liam Neeson) è pronto a raccogliere l''eredità del padre","en":"Only one man has the particular set of skills... to lead Police Squad and save the world: Lt. Frank Drebin Jr. Following in his father''s footsteps, he must solve a murder case to prevent Police Squad from closure.","es":"El torpe teniente Frank Drebin Jr. intenta resolver un asesinato vinculado a un magnate tecnológico. Mientras investiga, su unidad policial corre peligro de ser cerrada. Con la ayuda de una escritora de crímenes, Frank se verá envuelto en situaciones tan absurdas como explosivas. Película reboot basada en la popular franquicia de comedia \"Agárralo como puedas\" y la serie de televisión \"Police Squad!\".","fr":"Frank Drebin est le fils du légendaire inspecteur gaffeur du même nom. Son enquête sur un accident d’auto mortel l’amène à rencontrer la séduisante Beth Davenport, sœur de l’infortunée victime. Leur investigation les conduit à Richard Cane, le richissime et génial inventeur d’une automobile électrique révolutionnaire. Au fil de son enquête, Frank découvre que Cane fomente un sombre complot : utiliser une fréquence sonore inaudible pour renvoyer l''humanité à l''état sauvage.","de":"Nur ein einziger Mann verfügt über diese ganz besonderen Fähigkeiten … die Spezialeinheit der Polizei zu leiten und die Welt zu retten! Lt. Frank Drebin Jr. tritt in die Fußstapfen seines Vaters."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/tL8WM2MW87Sf48QctGHIpnnNSWK.jpg","en":"https://image.tmdb.org/t/p/w500/rwla9vqzrKVVKVKiOuROTIXGsxj.jpg","es":"https://image.tmdb.org/t/p/w500/v8FpKw8mOsHxC0YElkgNNSCzGMl.jpg","fr":"https://image.tmdb.org/t/p/w500/dIOzuzx0CLYpNLx1Yf44cykyYX5.jpg","de":"https://image.tmdb.org/t/p/w500/gFByp0Ent85Wrks1U8p14BQe6Gu.jpg"}'::jsonb WHERE id = 372;
UPDATE public.films SET tmdb_id = 1153714, titoli_i18n = '{"es":"La muerte del unicornio","en":"Death of a Unicorn","de":"Death of a Unicorn","fr":"La Mort d''une licorne","it":"Death of a Unicorn"}'::jsonb, trame_i18n = '{"es":"Padre e hija, Ridley y Elliot, atropellan a un unicornio con su coche y lo llevan al refugio, en medio de la naturaleza, de un multimillonario director de una farmacéutica.","en":"A father and daughter accidentally hit and kill a unicorn while en route to a weekend retreat, where his billionaire boss seeks to exploit the creature’s miraculous curative properties.","de":"Ridley begleitet ihren Vater Elliot und dessen Chef Dell Leopold zu einem Geschäftstermin, als sie bei einer Fahrt durch die Natur versehentlich ein Einhorn überfahren. Leopold beschließt, das magische Wesen in sein Labor zu bringen, um dort Experimente durchzuführen. Schnell entdeckt er die heilenden Kräfte der Einhorn-Körperteile, die das Potenzial haben, die Medizin grundlegend zu verändern. Doch getrieben von grenzenloser Profitgier beginnt Leopold, immer riskantere Entscheidungen zu treffen. Währenddessen häufen sich mysteriöse Ereignisse, die eine dunkle Wendung andeuten und die Beteiligten mit den Konsequenzen ihres Handelns konfrontieren.","fr":"Un père et sa fille percutent et tuent accidentellement une licorne, alors qu''ils sont en route pour rejoindre le patron milliardaire de ce dernier, qui cherche à exploiter les incroyables propriétés médicinales de la créature.","it":"Elliot, dirigente vedovo di un''azienda farmaceutica, si reca con la figlia Ridley nella fastosa tenuta del suo capo, Odell Leopold. Guidando a gran velocità per il grave ritardo accumulato, Elliot finisce per investire un animale che si era fermato in mezzo alla strada: solo che non si tratta di un animale qualsiasi, ma di un unicorno. Quando la famiglia Leopold comprende che il sangue degli animali magici ha delle proprietà curative, pensa di sfruttare la scoperta a scopo commerciale. Nessuno però ha fatto i conti con l''ira di mamma e papà unicorno, assetati di vendetta."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/7ONypZBnKXAAzr1zCNDo88AD6qf.jpg","en":"https://image.tmdb.org/t/p/w500/xWlF2i51zUq7BUq4iJte1g9NyIM.jpg","de":"https://image.tmdb.org/t/p/w500/tbomnwkXAOF6jGalOytrk2qRy2p.jpg","fr":"https://image.tmdb.org/t/p/w500/9unIGgBrHsIuvaYhsB88oVZhVBh.jpg","it":"https://image.tmdb.org/t/p/w500/k3Nuu7Z5PuC6UxVIl2xbGhFvIjj.jpg"}'::jsonb WHERE id = 373;
UPDATE public.films SET tmdb_id = 37136, titoli_i18n = '{"de":"Die nackte Kanone","en":"The Naked Gun: From the Files of Police Squad!","es":"Agárralo como puedas","fr":"Y a-t-il un flic pour sauver la reine ?","it":"Una pallottola spuntata"}'::jsonb, trame_i18n = '{"de":"Ihre Majestät Elizabeth II. von England will die Stadt Los Angeles mit einem Besuch beglücken. Da kommt es natürlich einer Katastrophe gleich, wenn ausgerechnet der Vorsitzende des Empfangskomitees verdächtig wird, ein Rauschgifthändler und Killer zu sein. Ein solch heikler Fall verlangt einfach nach Leutnant Frank Drebin vom L.A. Police Squad. Temperamentvoll stürzt er sich in die Ermittlungen und hinterlässt dabei eine breite Spur von Chaos und Verwüstung...","en":"When the bumbling Lieutenant Frank Drebin investigates events following the shooting of his partner, he stumbles upon an attempt to assassinate Queen Elizabeth II.","es":"Después de que su compañero Nordberg fuera tiroteado por una banda de narcotraficantes, el incompetente teniente Frank Drebin busca al jefe de la organización para vengarse. Sospecha del magnate naviero Vincent Ludwig, pero no tiene pruebas para inculparlo. Tendrá incluso que enfrentarse a una alcaldesa, que trata de obstaculizar su investigación. Sin embargo, Drebin consigue la inesperada ayuda de Jane Spencer, una antigua novia de Ludwig.","fr":"Le lieutenant Frank Drebin est le monsieur catastrophes de la police de Los Angeles. Il est l’auteur de tant de bourdes et de scandales que ses supérieurs hiérarchiques s’apprêtent à le licencier. C’est ce moment que choisit la reine d’Angleterre pour arriver à Los Angeles. Drebin apprend que Ludwig est en train d’ourdir un diabolique complot contre la reine. Il persuade son supérieur de lui donner une dernière chance de se réhabiliter en sauvant la reine…","it":"Il cattivo Vincent Ludwig organizza un attentato contro la Regina Elisabetta, in visita in città. L''imbranato tenente di polizia Frank Drebin sospetta fin dall''inizio che ci sia qualcosa di losco in quel Ludwig e, avendo capito cosa sta tramando, cerca di mettergli i bastoni fra le ruote e salvare la regina."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/2EjR99blDO7dEkMfaGrMPYeIFpN.jpg","en":"https://image.tmdb.org/t/p/w500/zT0mhZqZQJE1gSY5Eg9qcGP4NYo.jpg","es":"https://image.tmdb.org/t/p/w500/eykTYCLnPW4quK6rqOHtc5PR8qy.jpg","fr":"https://image.tmdb.org/t/p/w500/bQsieGMAodtLhVP13JznizC553.jpg","it":"https://image.tmdb.org/t/p/w500/psaW7ECMBTmBjI83FhLgIyhCG6e.jpg"}'::jsonb WHERE id = 374;
UPDATE public.films SET tmdb_id = 38251, titoli_i18n = '{"it":"Mediterraneo","es":"Mediterráneo","en":"Mediterraneo","fr":"Mediterraneo","de":"Mediterraneo"}'::jsonb, trame_i18n = '{"it":"Avventure, amori e tribolazioni di otto soldati del Regio Esercito Italiano che nel giugno 1941 sono mandati a presidiare un''isoletta greca dell''Egeo dove rimangono sino all''inverno del 1943, dimenticandosi degli avvenimenti bellici in corso. Uno degli otto non tornerà. Senza ambizioni storiche, è una favola, un racconto di formazione, un apologo sull''amicizia virile, sul desiderio di fuga (è dedicato “a tutti quelli che stanno scappando”), sulle difficoltà di crescere. Chiude un''ideale trilogia sul viaggio e su una generazione, quella del regista, formata da Marrakech Express e Turné. Un bel gioco di squadra attoriale e un''accattivante mistura di buffo e patetico con molti stereotipi e qualche leziosaggine ruffiana. Girato nell''isola di Kastellorizo (Megisti in greco). Oscar per il film straniero.","es":"Segunda Guerra Mundial. Ocho soldados han recibido la orden de desembarcar en una pequeña e insignificante isla griega. Su misión es custodiarla, dado que tiene un alto valor estratégico. Cuando consiguen llegar a tierra, su nave se ha hundido y la radio se ha roto. El lugar, que al principio parecía desierto, en realidad está habitado por mujeres, ancianos y niños. Los ocho hombres, aislados del frente y de la realidad, empiezan a integrarse rápidamente entre los vecinos, llegando incluso a olvidarse de que son soldados y están en guerra.","en":"Greek Sea, World War II. An Italian ship leaves a handful of soldiers in a little island; their mission is to spot enemy ships and to hold the island in case of attack. The village of the island seems abandoned and there isn''t a single enemy in sight, so the soldiers begin to relax a little. Things change when their ship is hit and destroyed by the enemy, and the soldiers find themselves abandoned there.","fr":"En 1941, huit soldats italiens débarquent sur une ile de la mer Égée et vont, a la suite de plusieurs quiproquos, être coupés de la guerre et du reste du monde.","de":"Abenteuer, Liebesgeschichten und Leiden von acht Soldaten der Königlichen Italienischen Armee, die im Juni 1941 zur Bewachung einer kleinen griechischen Insel in der Ägäis entsandt werden, wo sie bis zum Winter 1943 verbleiben und die laufenden Kriegsereignisse vergessen. Einer der acht wird nicht zurückkehren. Ohne historische Ambitionen ist es ein Märchen, eine Coming-of-Age-Geschichte, eine Fabel über männliche Freundschaft, über den Wunsch nach Flucht (der Film ist „allen gewidmet, die auf der Flucht sind“) und über die Schwierigkeiten des Erwachsenwerdens. Er bildet den Abschluss einer idealen Trilogie über das Reisen und über eine Generation - die des Regisseurs -, bestehend aus „Marrakech Express“ und „Turné“. Ein schönes Zusammenspiel der Schauspieler und eine fesselnde Mischung aus Komik und Pathos mit vielen Klischees und etwas schmeichlerischer Affektiertheit."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/wfJ2flMchZPQCSdt8h3ZQNSW7Ym.jpg","es":"https://image.tmdb.org/t/p/w500/xspcpzfsFSRQZPL80QOHQheVvhB.jpg","en":"https://image.tmdb.org/t/p/w500/omFU47TZSR7xAAZcDHKM48SmVwe.jpg","fr":"https://image.tmdb.org/t/p/w500/wfJ2flMchZPQCSdt8h3ZQNSW7Ym.jpg","de":"https://image.tmdb.org/t/p/w500/wfJ2flMchZPQCSdt8h3ZQNSW7Ym.jpg"}'::jsonb WHERE id = 375;
UPDATE public.films SET tmdb_id = 120467, titoli_i18n = '{"it":"Grand Budapest Hotel","en":"The Grand Budapest Hotel","fr":"The Grand Budapest Hotel","es":"El gran hotel Budapest","de":"Grand Budapest Hotel"}'::jsonb, trame_i18n = '{"it":"Una ragazza depone una chiave di una stanza d''hotel ai piedi del busto dedicato a uno scrittore scomparso. Lo stesso scrittore racconta delle origini del suo romanzo. Un uomo oramai anziano e stanco racconta in un albergo semi deserto ad un giovane scrittore la storia di Gustave H., il leggendario concierge del Grand Budapest Hotel, e del suo giovane protetto Zero, alle prese con il furto e il recupero di un dipinto rinascimentale inestimabile e la battaglia per un enorme patrimonio di famiglia.","en":"The Grand Budapest Hotel tells of a legendary concierge at a famous European hotel between the wars and his friendship with a young employee who becomes his trusted protégé. The story involves the theft and recovery of a priceless Renaissance painting, the battle for an enormous family fortune and the slow and then sudden upheavals that transformed Europe during the first half of the 20th century.","fr":"Pendant l’entre‐deux guerres, le légendaire concierge d’un grand hôtel et son jeune protégé se retrouvent impliqués dans une histoire mêlant le vol d’un tableau de la Renaissance, la bataille pour une énorme fortune familiale, et le lent puis soudain bouleversement qui transforme l’Europe en cette première moitié de XXème siècle.","es":"El Sr. Gustave H., un legendario conserje de un famoso hotel europeo de entreguerras, entabla amistad con Zero Moustafa, un joven empleado al que convierte en su protegido. La historia trata sobre el robo y la recuperación de una pintura renacentista de valor incalculable y sobre la batalla que enfrenta a los miembros de una familia por una inmensa fortuna. Como telón de fondo, los levantamientos que transformaron Europa durante la primera mitad del siglo XX.","de":"Gustave H. ist der legendäre Concierge eines Luxushotels in Europa. In den 20er Jahren des 20. Jahrhunderts baut er eine enge Freundschaft zu einem jungen Hotelangestellten namens Zero Moustafa auf, der mit der Zeit sein engster Vertrauter und Protégé wird. In der Zwischenzeit geht ein atemberaubender Kunstdiebstahl vonstatten, bei dem ein unschätzbar wertvolles Gemälde aus der Renaissance entwendet wird, Leute werden des Mordes an Madame D. beschuldigt und Gustave H. ist in den Kampf um ein Familienerbe verwickelt, während in Europa langsam die ersten Anzeichen eines drohenden Krieges nicht mehr zu übersehen sind. Außerdem machen noch das Konkurrenzhotel des Grand Budapest – das Excelsior''s Palace – und dessen Manager M. Ivan Probleme …"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/tY8gmrOOzhJxfBLQNOxjbuSR52b.jpg","en":"https://image.tmdb.org/t/p/w500/eWdyYQreja6JGCzqHWXpWHDrrPo.jpg","fr":"https://image.tmdb.org/t/p/w500/qcWTuWPu6x6t2MKt0MTfbResJiV.jpg","es":"https://image.tmdb.org/t/p/w500/1wk0vpNCX5T40KsGQKjfoDAhmJw.jpg","de":"https://image.tmdb.org/t/p/w500/cnYv3px6xOUryhCvasKO40v3fPD.jpg"}'::jsonb WHERE id = 376;
